# =====================================================================
#  OptiLauncher v7.7  -  Kompleksowa Optymalizacja Komputerowa
#  by Jerremi
#
#  Nowe w 7.7  (interfejs):
#    - GESTOSC WIDOKU: tryb zwarty sciaga marginesy i wysokosci pozycji
#    - TLO MICA: okno przejmuje rozmyte tlo pulpitu (tylko Windows 11)
#    - SZKIELETY: migoczace placeholdery zamiast pustego obszaru
#      podczas zbierania listy
#    - ujednolicone zaokraglenia (6 male / 10 kontrolki / 14 karty
#      / 16 okno) i grubosci ramek
#    - wiecej ruchu: kaskada pozycji w menu przy starcie, plynne
#      przejscie koloru pierscieni, gasniecie kart przy filtrowaniu,
#      mrugniecie licznika zaznaczonych
#
#  7.6.1: poprawka - kolor poswiaty w mapie motywu byl skladany bez
#  znaku '#', przez co XamlReader nie budowal okna w zadnym motywie
#  poza domyslnym; doszedl bezpiecznik ignorujacy bledny wpis w mapie
#
#  Nowe w 7.6:
#    - WYGLAD: nowa zakladka z siedmioma motywami kolorystycznymi
#      (cyjan, fiolet, mieta, bursztyn, karmin, grafit, blekit, roz, jasny)
#    - kolory nie sa juz wpisane na sztywno: paleta bazowa idzie przez
#      mape motywu jednym przebiegiem - i w tekscie XAML, i w wywolaniach
#      Br w kodzie, wiec nie zostaje nigdzie stary odcien
#    - zielen, zolc i czerwien zostaja takie same w kazdym motywie,
#      bo niosa znaczenie (zastosowane / ostroznie / nie weszlo)
#    - wybor siedzi w motyw.json obok reszty danych programu
#
#  Z 7.5  (interfejs):
#    - FILTR ZADAN: pole u gory zwija karty, ktore nie pasuja do wpisanej
#      frazy; zwinieta karta nie liczy sie do zaznaczenia
#    - WYKRES OBCIAZENIA: historia procesora i pamieci z ostatnich
#      dwoch minut na Pulpicie
#    - SKROTY: Ctrl+F szukaj, Ctrl+K konsola, F5 / Ctrl+R odswiez,
#      Ctrl+1..9 zakladki, Esc czysci filtr
#    - POSTEP NA PASKU ZADAN: ikona programu wypelnia sie w trakcie pracy
#    - PASEK POWIADOMIEN nad paskiem akcji - widac koniec zadania
#      nawet przy zwinietej konsoli
#    - okno bez ramki da sie powiekszyc do obszaru roboczego
#      (przycisk na pasku tytulu albo dwuklik)
#
#  Z 7.4  (interfejs):
#    - caly interfejs przepisany na animacje: wejscie okna, zmiana
#      zakladki (karty wjezdzaja kolejno), najazd na karte, przyciski
#      z poswiata i wcisnieciem, pasek postepu dojezdza plynnie
#    - liczniki na Pulpicie dojezdzaja do wartosci zamiast skakac
#    - SZYBKIE AKCJE na Pulpicie: trzy szerokie kafle zamiast waskiej
#      kolumny przyciskow przy wyniku
#    - przyciski zakladek przeniesione pod opis, w jeden pasek narzedzi
#      (wczesniej pionowa kolumna po prawej stronie karty)
#    - konsole mozna zwinac przyciskiem na pasku tytulu
#    - dwa przyciski na dole menu obok siebie, z ikonami
#
#  Z 7.3:
#    - USLUGI: nowa zakladka, 9 grup uslug Windows do wylaczenia,
#      kazda z zapisem poprzedniego trybu startu do kopii
#    - PROCESY W TLE: co teraz zajmuje pamiec, z mozliwoscia zamkniecia;
#      procesy systemowe zablokowane przed ubiciem
#    - APLIKACJE WBUDOWANE: usuwanie preinstalowanych aplikacji
#      z zamknietej listy dozwolonych (nie czarnej listy!)
#    - czytelniejsze naglowki sekcji i sciezki na kartach
#
#  Z 7.2:
#    - AUTOSTART: pelna zakladka - lista programow startujacych z Windows
#      z wlaczaniem i wylaczaniem przez StartupApproved (jak Menedzer zadan,
#      wpis nie jest kasowany, wiec zmiana jest w pelni odwracalna)
#    - POMIAR PRZED/PO: punkt odniesienia + porownanie (czas rozruchu
#      z Dziennika zdarzen, procesy, uslugi, pamiec, autostart)
#    - ETYKIETY ZYSKU: kazde zadanie mowi wprost, czy efekt jest mierzalny,
#      zalezny od sprzetu, czy tylko kosmetyczny
#    - liczniki na pulpicie liczone przez kernel32 zamiast WMI
#      (bylo kilkaset ms co 3 s i licznik CPU sam obciazal procesor)
#    - skan diagnostyczny szybszy: autostart z rejestru zamiast
#      Win32_StartupCommand, timeout na odczyt temperatur
#
#  Z 7.1: weryfikacja kazdej zmiany po zastosowaniu, poprawki w svchost,
#  hibernacji, telemetrii, czyszczeniu katalogow i planie zasilania
#
#  Z 7.0: interfejs, pulpit z licznikami na zywo, biblioteka gier
#
#  Wymaga: Windows 10/11, Windows PowerShell 5.1+, admin
#  Plik zapisany w UTF-8 z BOM
# =====================================================================

param([string]$Tryb = '')

# =====================================================================
#  TRYBY URUCHOMIENIA
#
#  Bez parametru: normalne okno programu.
#  Z parametrem -Tryb: zadania pomocnicze, ktore kiedys byly osobnymi
#  plikami (Instalator.ps1, Build-EXE.ps1, SPRAWDZ-LACZE.ps1, README.txt).
#  Wszystko siedzi teraz w tym jednym pliku, lacznie z ikona.
# =====================================================================

$AppNazwa   = 'OptiLauncher'
$AppWersja  = '8.6.0'
$AppAutor   = 'Jerremi'

