$ReadmeTekst = @'
OptiLauncher 7.9
Kompleksowa Optymalizacja Komputerowa  |  by Jerremi
====================================================

Czym ten program rozni sie od reszty
------------------------------------
Wiekszosc darmowych "optymalizatorow" wrzuca kilkadziesiat przelacznikow,
nie sprawdza, czy cokolwiek zadzialalo, i nie pozwala tego cofnac.
OptiLauncher robi trzy rzeczy, ktorych one nie robia:

  1. SPRAWDZA SWOJA WLASNA ROBOTE
     Po kazdym zastosowaniu zmiany program ponownie odczytuje stan systemu
     i mowi wprost: "potwierdzone" albo "NIE WESZLO". Nie ufa temu, ze
     zapis do rejestru sie powiodl - weryfikuje wynik.

  2. POKAZUJE EFEKT W LICZBACH
     Punkt odniesienia przed zmianami, pomiar po restarcie, roznica na
     ekranie. Zamiast wierzyc na slowo, widzisz czas rozruchu.

  3. MOWI, KIEDY COS NIC NIE DA
     Kazde zadanie ma etykiete: mierzalny zysk, zalezny od sprzetu albo
     kosmetyczny. Niektore zadania same siebie odradzaja - i tak ma byc.


NOWE W WERSJI 7.9
-----------------

Zakladka "Siec i naprawa" dostala przycisk "Aktualizacje sterownikow
(Windows Update)" - otwiera oficjalny ekran opcjonalnych aktualizacji
Windows, ten sam co w Ustawieniach. Program NIE instaluje sterownikow
sam ani nic nie wybiera za Ciebie - zly sterownik, zwlaszcza karty
graficznej, potrafi zawiesic system, wiec liste i decyzje zawsze
zostawiamy Tobie.

Doszly tez trzy wczesniej niedopisane tu zadania: "Zamknij nakladki
nagrywania" (zabija procesy Xbox Game Bar / NVIDIA Overlay, gdy
przeszkadzaja w grze), "Wylacz Szybki rozruch" oraz "Planowanie
procesora -> Programy".

NOWE W WERSJI 7.8
-----------------

Czwarta tura zmian w wygladzie, plus ikona w zasobniku i szybszy start.
Zadania optymalizacyjne bez zmian.

* PRZEJSCIE MIEDZY ZAKLADKAMI
  Stara zakladka gasnie i lekko zjezdza w dol, zamiast znikac w jednej
  klatce. Nowa wjezdza tak jak dotychczas - calosc czyta sie jak
  przenikanie, nie przelaczanie.

* PRZYCISKI ODPOWIADAJA NA KLIKNIECIE
  Przyciski obrysowe i wypelnione dostaly krotki blysk pod kursorem
  w momencie kliknieca, nie tylko przy najechaniu.

* PRZELACZNIKI W AUTOSTARCIE
  Kolumna Wlacz/Wylacz w zakladce Autostart to teraz przelacznik,
  ktory faktycznie sie przesuwa i zmienia kolor, zamiast tekstowego
  przycisku.

* ANIMACJA PRZY SUKCESIE
  Karta zadania dostaje krotki, zielonkawy "oddech" w momencie
  potwierdzonej zmiany - latwiej zlapac wzrokiem, ktore zadanie
  wlasnie sie skonczylo.

* IKONA W ZASOBNIKU SYSTEMOWYM
  Program jest dostepny z zasobnika, dopoki dziala - dwuklik albo
  pozycja w menu przywraca okno, bez szukania go na pasku zadan.

* SZYBSZY START
  Odczyt sprzetu (CPU/GPU/RAM z WMI) przeniesiony na chwile po
  pokazaniu okna, zamiast przed nim. Okno pojawia sie od razu,
  dane w rogu dochodza ulamek sekundy pozniej.


CO PRZYSZLO W 7.7
-----------------

Trzecia tura zmian w wygladzie. Zadania optymalizacyjne bez zmian.

* GESTOSC WIDOKU  (zakladka Wyglad)
  Tryb zwarty sciaga marginesy kart i wysokosci pozycji w menu - na
  ekranie miesci sie wtedy o kilka kart wiecej. Rozmiary liter zostaja
  bez zmian: zmniejszanie tekstu to prosta droga do interfejsu, ktorego
  nie da sie czytac.

* TLO MICA  (Windows 11)
  Okno przejmuje rozmyte tlo pulpitu, tak jak Ustawienia Windows 11.
  Rysuje je menedzer okien, nie program.

  DLACZEGO WYMAGA RESTARTU I CO SIE ZMIENIA
  Backdrop nie ma sie gdzie narysowac, dopoki okno jest warstwowe -
  a takie wlasnie bylo, bo z tego bral sie zaokraglony ksztalt. Przy
  wlaczonej Mice okno przechodzi na zwykly tryb, ramka zostaje
  rozciagnieta na cala powierzchnie, a zaokraglenie rysuje juz system.
  Na Windows 10 ustawienie jest wyszarzone - i tak by nie zadzialalo.

* SZKIELETY LADOWANIA
  Zanim lista sie zbierze, w jej miejscu migocza placeholdery
  w ksztalcie kart. Pusty obszar czyta sie jak "nic tu nie ma",
  a placeholder jak "zaraz bedzie".

* JEDNA SKALA ZAOKRAGLEN
  Bylo 9, 10, 11, 12, 13 i 14 pikseli, zaleznie od tego, w ktorej turze
  dopisywalem dany fragment. Teraz sa cztery wartosci: 6 dla drobiazgow,
  10 dla kontrolek, 14 dla kart, 16 dla okna. Grubosci ramek zejsciowo
  ujednolicone do jednego piksela.

* WIECEJ RUCHU
  - pozycje menu wjezdzaja kaskada przy starcie programu
  - pierscienie na Pulpicie przechodza kolorem plynnie, zamiast
    przeskakiwac z zielonego w zolty
  - karty odsiane filtrem gasna, zanim sie zwina (skok o pol ekranu
    przy kazdej wpisanej literze byl nie do czytania)
  - licznik zaznaczonych mruga, gdy sie zmieni


CO PRZYSZLO W 7.6
-----------------

* WYGLAD  (nowa zakladka)
  Siedem motywow kolorystycznych do wyboru: Nocny cyjan (domyslny),
  Fiolet, Mieta, Bursztyn, Karmin, Grafit i Jasny. Kazdy z podgladem
  palety obok nazwy.

  Wybor dotyczy wylacznie wygladu programu - zadne ustawienie systemu
  nie jest zmieniane, nic nie trafia do kopii zapasowej.

  JAK TO DZIALA
  Kolory nie sa juz wpisane na sztywno w kilku tysiacach linii.
  Kazdy odcien palety bazowej ma swoj odpowiednik w mapie motywu,
  a podmiana idzie JEDNYM przebiegiem - i przez tekst interfejsu,
  i przez kolory tworzone w kodzie. Gdyby lecial petla po parach,
  druga podmiana lapalaby wynik pierwszej.

  CO SIE NIE ZMIENIA
  Zielony, zolty i czerwony zostaja identyczne w kazdym motywie,
  bo nie sa ozdoba: znacza "zastosowane", "ostroznie" i "NIE WESZLO".
  Motyw, ktory by je przemalowal, odbieralby programowi to, co
  odroznia go od darmowych optymalizatorow.

  Dwa motywy sa oznaczone uwaga wprost na karcie: Bursztyn gryzie sie
  z zoltym ostrzezeniem, a Karmin z czerwonym. Nadal mozna je wybrac -
  ale wiadomo, na co sie idzie.

  RESTART
  Zmiana motywu wymaga ponownego uruchomienia programu, bo kolory sa
  wtapiane w interfejs przy jego budowaniu. Program uruchamia sie sam,
  po potwierdzeniu.


CO PRZYSZLO W 7.5
-----------------

Druga tura zmian w interfejsie. Zadania optymalizacyjne bez zmian.

* FILTR ZADAN  (Ctrl+F)
  Pole u gory zakladki zwija wszystkie karty, ktore nie pasuja do
  wpisanej frazy - szuka po tytule, opisie i etykiecie. Przy ponad
  piecdziesieciu zadaniach to szybsze niz przewijanie oczami.

  Wazny szczegol: karta zwinieta filtrem NIE liczy sie do zaznaczenia.
  Inaczej "Uruchom zaznaczone" odpalaloby rzeczy, ktorych w tej chwili
  nie widzisz na ekranie.

* WYKRES OBCIAZENIA
  Na Pulpicie, pod pierscieniami: historia procesora i pamieci
  z ostatnich okolo dwoch minut. Probka co 1,2 s, nowe punkty wchodza
  z prawej strony. Licznik zbiera dane caly czas, wiec po powrocie
  na Pulpit wykres nie ma dziury.

* SKROTY KLAWISZOWE
  Ctrl+F    pole szukania
  Ctrl+K    zwin lub rozwin konsole
  F5, Ctrl+R  odswiez stan
  Ctrl+1..9 skok do zakladki w kolejnosci z menu
  Esc       czysci filtr

* POSTEP NA PASKU ZADAN
  Ikona programu na pasku zadan Windows wypelnia sie razem z paskiem
  w konsoli. Widac postep dlugiego zadania, nie trzymajac okna
  na wierzchu.

* PASEK POWIADOMIEN
  Krotki komunikat nad paskiem akcji po skonczonym zadaniu. Log
  w konsoli zostaje bez zmian, ale przy zwinietej konsoli nie bylo
  wczesniej widac, ze cokolwiek sie skonczylo.

* POWIEKSZANIE OKNA
  Okno nie ma systemowej ramki, wiec nie mialo tez maksymalizacji.
  Teraz rozciaga sie do obszaru roboczego przyciskiem na pasku tytulu
  albo dwuklikiem - i nie wchodzi pod pasek zadan.


CO PRZYSZLO W 7.4
-----------------

Wersja 7.4 nie dodaje zadnego nowego zadania optymalizacyjnego -
w calosci dotyczy interfejsu.

* RUCH ZAMIAST PRZESKOKOW
  Okno wjezdza przy starcie, zakladki zmieniaja sie plynnie, a karty
  pojawiaja sie jedna po drugiej. Najazd kursorem podswietla karte
  i unosi ja o dwa piksele. Przyciski maja poswiate przy najezdzie
  i wciskaja sie pod kliknieciem.

  Kazda karta ma wlasny pedzel i wlasna transformacje - dlatego
  animacja jednej nie rusza pozostalych stu.

* LICZNIKI DOJEZDZAJA
  Pierscienie na Pulpicie plynnie doganiaja nowa wartosc zamiast
  przeskakiwac co pomiar. Osobny zegar 45 ms robi tylko to i zatrzymuje
  sie, gdy wartosci sa juz na miejscu albo Pulpit nie jest widoczny.
  Pedzle pierscieni sa zamrozone i buforowane, wiec klatki nie tworza
  nowych obiektow.

* PRZYCISKI POUKLADANE OD NOWA
  - Pulpit: trzy szerokie kafle SZYBKIE AKCJE pod wynikiem zamiast
    waskiej kolumny przy pasku postepu
  - Moje gry, Autostart, Procesy, Lacze, Aplikacje, Diagnostyka:
    przyciski zeszly z prawej krawedzi pod opis, w jeden pasek
    oddzielony cienka linia - opis dostal cala szerokosc karty
  - pasek akcji na dole: Restart odsuniety separatorem od dwoch
    przyciskow uruchamiajacych zadania
  - menu: "Punkt przywracania" i "Przywroc wszystko" obok siebie,
    z ikonami, zamiast dwoch pasow jeden pod drugim

* KONSOLA DO ZWINIECIA
  Przycisk na pasku tytulu chowa prawa kolumne. Przy pracy przy
  waskim ekranie zostaje wiecej miejsca na tresc.

* DROBIAZGI
  Kropka przy naglowku konsoli pulsuje w trakcie pracy, pasek postepu
  dojezdza zamiast przeskakiwac, pigulka stanu miga przy zmianie,
  a zaznaczenie w polu wyboru rozwija sie zamiast pojawiac.


CO PRZYSZLO W 7.3
-----------------

* USLUGI  (nowa zakladka)
  Dziewiec grup uslug Windows, ktore na domowym komputerze zwykle nie
  sa potrzebne: telemetria, uslugi Xbox, zdalny rejestr, faks, mapy
  offline, udostepnianie WMP, tryb demo sklepu, indeksowanie
  wyszukiwania i bufor wydruku.

  Przed wylaczeniem program zapisuje do kopii poprzedni tryb startu
  KAZDEJ uslugi i to, czy dzialala. "Przywroc wszystko" ustawia je
  dokladnie tak, jak byly - nie "na automatyczny", jak robi wiekszosc
  narzedzi. Dwie grupy sa oznaczone "Ostroznie" i celowo NIE sa
  zaznaczone domyslnie: indeksowanie (wyszukiwanie plikow zwolni)
  i bufor wydruku (bez niego nic nie wydrukujesz).

* PROCESY W TLE  (nowa zakladka)
  Co zajmuje pamiec w tej chwili - procesy zgrupowane po nazwie,
  posortowane od najbardziej pamieciozernych, z liczba instancji
  i tytulem okna. Kolor pigulki: powyzej 1 GB czerwony, powyzej
  300 MB zolty.

  Zamkniecie niczego nie zmienia w systemie - przy nastepnym
  uruchomieniu program wroci. Zeby nie wracal, trzeba go wylaczyc
  w zakladce Autostart. Procesy systemowe sa zablokowane: ubicie
  ktoregokolwiek konczy sie zawieszeniem pulpitu albo restartem.

* APLIKACJE WBUDOWANE  (nowa zakladka)
  Usuwanie preinstalowanych aplikacji Windows. Program pokazuje
  WYLACZNIE pozycje z wlasnej, recznie sprawdzonej listy dozwolonych -
  to celowo odwrotnosc typowych debloaterow, ktore kasuja wszystko
  poza czarna lista i przy okazji wywalaja ludziom Sklep, kalkulator
  albo komponenty systemowe.

  Usuniecie dotyczy biezacego uzytkownika, a kazda aplikacje mozna
  zainstalowac z powrotem ze Sklepu Microsoft.


CO PRZYSZLO W 7.2
-----------------
* AUTOSTART  (nowa zakladka)
  Lista wszystkich programow startujacych z Windows: cztery klucze Run
  plus dwa foldery Autostart. Dla kazdej pozycji nazwa, zrodlo, pelne
  polecenie i stan. Wlaczone na gorze, bo to one kosztuja czas rozruchu.

  Wylaczanie dziala dokladnie jak w Menedzerze zadan: wpis NIE jest
  kasowany, zmienia sie tylko jego stan w StartupApproved. Dzieki temu
  operacja jest odwracalna tym samym przyciskiem, a stan zgadza sie
  z Menedzerem zadan w obie strony.

  To zwykle najwiekszy realny zysk w calym programie - wiecej niz
  wszystkie ustawienia rejestru razem wziete.

* POMIAR WYDAJNOSCI  (panel Diagnostyka)
  "Zapisz punkt odniesienia"  - PRZED zmianami
  "Zmierz teraz"              - po zmianach i restarcie

  Mierzone: czas rozruchu i czas do pulpitu (Dziennik zdarzen,
  Diagnostics-Performance, zdarzenie 100), liczba procesow, liczba
  dzialajacych uslug, zajetosc pamieci, liczba pozycji autostartu.

  UWAGA: czas rozruchu aktualizuje sie wylacznie po ponownym
  uruchomieniu komputera. Program to wykrywa i mowi o tym wprost
  zamiast pokazywac "bez zmian".

* MOJE GRY - widac, ktore sa faktycznie zoptymalizowane
  Nad lista licznik "Zoptymalizowanych: X z Y", a same gry sa
  podzielone na grupy: z pelna optymalizacja, zoptymalizowane
  czesciowo, bez zmian i brak pliku na dysku. Przycisk "Pokaz tylko
  zoptymalizowane" ukrywa reszte. Stan jest odczytywany z rejestru
  przy kazdym odswiezeniu, wiec pokazuje rzeczywistosc, a nie to,
  co program kiedys zapisal u siebie.

* ETYKIETY REALNEGO ZYSKU
  Pod opisem kazdego zadania:
    ZYSK MIERZALNY      - widac w liczbach
    ZALEZY OD SPRZETU   - pomoze albo nie, zaleznie od konfiguracji
    KOSMETYCZNY         - zmienia odczucie, wydajnosci nie rusza

* SZYBSZY PROGRAM
  Pulpit liczy obciazenie przez GetSystemTimes i GlobalMemoryStatusEx
  zamiast odpytywac WMI co 3 sekundy - wczesniej licznik procesora
  sam podbijal wartosc, ktora pokazywal. Diagnostyka czyta autostart
  z rejestru zamiast z Win32_StartupCommand, a odczyt temperatur ma
  twardy timeout. Skan schodzi z okolo 10 sekund do 2-3.


Z WERSJI 7.1
------------
Weryfikacja po zastosowaniu. Naprawione: falszywe wykrywanie stanu
svchost, wykrywanie planu zasilania (powercfg -duplicatescheme tworzy
plan z nowym GUID-em, wiec kazde uruchomienie robilo kolejna kopie),
cofanie hibernacji, zadania harmonogramu przy telemetrii (TaskPath bez
konczacego ukosnika powodowal, ze cala petla po cichu nic nie robila),
czyszczenie katalogow w jednym przebiegu, natychmiastowe wylaczenie
akceleracji myszy, ostrzezenia dla laptopow i maszyn z malym RAM.


TRZY SPOSOBY URUCHOMIENIA
=========================
1) INSTALACJA     - dwuklik ZAINSTALUJ.bat  (zalecane)
2) TRYB PRZENOSNY - dwuklik URUCHOM.bat
                    (sam znajduje plik OptiLauncher_v*.ps1)
3) WLASNY .EXE    - prawy klik na Build-EXE.ps1 > Uruchom w PowerShell
                    (niepodpisany exe bywa blokowany przez Inteligentna
                     kontrole aplikacji - sposoby 1 i 2 tego problemu
                     nie maja)


ZALECANA KOLEJNOSC PRZY PIERWSZYM URUCHOMIENIU
----------------------------------------------
1. "Punkt przywracania" w lewym dolnym rogu
2. Diagnostyka > "Zapisz punkt odniesienia"
3. Autostart > wylacz to, czego nie potrzebujesz przy starcie
4. Optymalizacje > zaznacz i uruchom (sprawdz etykiety zysku)
5. Restart komputera
6. Diagnostyka > "Zmierz teraz"


BAZA OPISOW
-----------
Autostart i Procesy w tle pokazuja nazwy plikow. Przy kazdej znanej
pozycji program dopisuje, co to jest, kto to wstawil i czy wolno to
wylaczyc - w trzech stanach: mozna wylaczyc / zalezy od Ciebie /
zostaw wlaczone.

Baza jedzie kanalem aktualizacji osobno od programu, bo to dane, a nie
kod. Nowe opisy przychodza w tle i wchodza od razu, bez restartu.

Zadania optymalizacyjne ta droga nie ida i nie beda szly - pisza do
rejestru, wiec sciaganie ich z sieci byloby zdalnym wykonywaniem kodu
na koncie administratora.


AKTUALIZACJE
------------
Program sprawdza raz na dobe, czy jest nowsza wersja. Sprawdzanie idzie
w tle, po pokazaniu okna - brak sieci niczego nie opoznia.

Nic nie pobiera sie samo. Po znalezieniu nowej wersji pojawia sie okno
z lista zmian: aktualizuj / pomin te wersje / pozniej.

Zanim cokolwiek zostanie podmienione, pobrany plik przechodzi dwa
sprawdzenia - suma kontrolna SHA256 i test skladni. Stara wersja
zostaje obok jako OptiLauncher.ps1.bak; jesli nowa nie wstanie
w ciagu kilku sekund, wraca poprzednia.

Recznie: START.bat > [8], albo -Tryb aktualizuj z wiersza polecen.


DANE PROGRAMU
-------------
%LOCALAPPDATA%\OptiLauncher\
  backup.json  - kopia wartosci sprzed zmian (do cofania)
  games.json   - twoja lista gier
  pomiar.json  - punkt odniesienia do porownan
  aktualizacje.json - ustawienia sprawdzania wersji
  baza.json    - pobrane opisy autostartu i procesow
  raporty\     - raporty HTML
  log_*.txt    - logi sesji

Autostart nie zapisuje sie do backup.json i nie musi - wylaczenie
pozycji jest odwracalne tym samym przyciskiem.


WYMAGANIA
---------
Windows 10 lub 11, Windows PowerShell 5.1, uprawnienia administratora.
Program sam prosi o podniesienie uprawnien przy starcie.
'@

function Zapisz-Ikone {
    param([string]$Sciezka)
    try {
        [System.IO.File]::WriteAllBytes($Sciezka, [Convert]::FromBase64String(($IkonaB64 -replace '\s', '')))
        return $true
    } catch { return $false }
}

# =====================================================================
#  AKTUALIZACJE  -  silnik
#
#  Wariant hybrydowy: instalacja z Inno aktualizuje sie instalatorem,
#  instalacja z .bat i wersja przenosna - podmiana samego .ps1.
#
#  Blok stoi przed sekcja trybow, bo korzysta z niego i tryb konsolowy
#  (-Tryb aktualizuj), i okno programu.
# =====================================================================

# ---------------------------------------------------------------------
#  KONFIGURACJA  -  jedyne miejsce zalezne od hostingu
# ---------------------------------------------------------------------
# Manifest to zwykly plik JSON. Moze lezec na GitHubie (link "raw"),
# na wlasnym serwerze, wszedzie gdzie da sie go pobrac po HTTPS.
# Dopoki w adresie siedzi UZYTKOWNIK/REPO, sprawdzanie jest wylaczone
# i program nie probuje odpytywac nieistniejacego serwera.
$UrlManifest = 'https://raw.githubusercontent.com/jerrykacper/OptiPakiet/main/wersja.json'

# Ile godzin czekac miedzy sprawdzeniami. Pytanie serwera przy kazdym
# uruchomieniu nic nie wnosi, a generuje ruch i logi.
$AktOdstepH = 20

# AppId z OptiPakiet.iss - po nim poznajemy instalacje z instalatora.
$AktAppId = '{9C4A1F52-7E63-4B8D-AE21-5D0F3C6B8A17}'

$KluczApp = 'HKCU:\Software\OptiLauncher'

# $DataDir powstaje nizej, przy starcie okna - a tu jest potrzebny juz
# teraz, bo tryb konsolowy nie dochodzi tak daleko.
if (-not $DataDir) {
    $DataDir = Join-Path $env:LOCALAPPDATA 'OptiLauncher'
    if (-not (Test-Path $DataDir)) { New-Item -ItemType Directory -Path $DataDir -Force | Out-Null }
}
$AktFile = Join-Path $DataDir 'aktualizacje.json'

function Akt-Skonfigurowane {
    return ($UrlManifest -notmatch 'UZYTKOWNIK/REPO')
}


# ---------------------------------------------------------------------
#  USTAWIENIA
# ---------------------------------------------------------------------
function Load-UstAkt {
    # poWersja / poZmiany: slad po wlasnie zainstalowanej aktualizacji.
    # Zapisujemy je tuz przed podmiana pliku, bo lista zmian przychodzi
    # z manifestu i po restarcie program juz jej nie ma skad wziac.
    # czeka: wersja juz znaleziona, ktorej uzytkownik jeszcze nie
    # zainstalowal. Dopoki tam siedzi, limit raz na dobe nie obowiazuje -
    # inaczej "Później" znaczyloby "za dwadziescia godzin", a nie
    # "przy nastepnym uruchomieniu", jak mowi przycisk.
    $u = @{ auto = $true; pomin = ''; ostatnie = ''; poWersja = ''; poZmiany = @(); czeka = '' }
    try {
        if (Test-Path $AktFile) {
            $j = Get-Content $AktFile -Raw -Encoding UTF8 | ConvertFrom-Json
            if ($null -ne $j.auto) { $u.auto = [bool]$j.auto }
            if ($j.pomin)          { $u.pomin = "$($j.pomin)" }
            if ($j.ostatnie)       { $u.ostatnie = "$($j.ostatnie)" }
            if ($j.poWersja)       { $u.poWersja = "$($j.poWersja)" }
            if ($j.poZmiany)       { $u.poZmiany = @($j.poZmiany) }
            if ($j.czeka)          { $u.czeka = "$($j.czeka)" }
        }
    } catch { }
    return $u
}

function Save-UstAkt {
    param($U)
    try {
        $poz = @()
        if ($U.poZmiany) { $poz = @($U.poZmiany) }
        @{ auto     = [bool]$U.auto
           pomin    = "$($U.pomin)"
           ostatnie = "$($U.ostatnie)"
           poWersja = "$($U.poWersja)"
           poZmiany = $poz
           czeka    = "$($U.czeka)" } |
            ConvertTo-Json | Set-Content $AktFile -Encoding UTF8
    } catch { }
}


# ---------------------------------------------------------------------
#  TRYB INSTALACJI
# ---------------------------------------------------------------------
# Trzy drogi, ktorymi program moze trafic na dysk, i kazda wymaga
# innej aktualizacji:
#   inno     - instalator .exe, wpis w rejestrze Inno Setup
#   bat      - ZAINSTALUJ.bat, katalog %LOCALAPPDATA%\Programs\OptiLauncher
#   portable - odpalony z folderu z paczki, nic nie jest zarejestrowane
#
# Znacznik zapisuje instalacja. Heurystyka po sciezce jest zapasem dla
# osob, ktore zainstalowaly wersje sprzed tego mechanizmu.
function Get-TrybInstalacji {
    $z = $null
    try { $z = (Get-ItemProperty -LiteralPath $KluczApp -Name 'InstallMode' -ErrorAction Stop).InstallMode } catch { }
    if ($z -eq 'inno' -or $z -eq 'bat' -or $z -eq 'portable') { return $z }

    $sciezka = $PSCommandPath
    if (-not $sciezka) { $sciezka = $MyInvocation.MyCommand.Path }
    $kat = ''
    if ($sciezka) { $kat = Split-Path -Parent $sciezka }

    $uni = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\$($AktAppId)_is1"
    if (Test-Path $uni) {
        try {
            $loc = (Get-ItemProperty -LiteralPath $uni -Name 'InstallLocation' -ErrorAction Stop).InstallLocation
            if ($loc -and $kat -and ($kat.TrimEnd('\') -eq $loc.TrimEnd('\'))) { return 'inno' }
        } catch { }
    }

    try {
        $katBat = Join-Path $env:LOCALAPPDATA 'Programs\OptiLauncher'
        if ($kat -and $katBat -and ($kat.TrimEnd('\') -eq $katBat.TrimEnd('\'))) { return 'bat' }
    } catch { }

    return 'portable'
}


# ---------------------------------------------------------------------
#  SIEC
# ---------------------------------------------------------------------
# PowerShell 5.1 na czesci buildow startuje ze starym protokolem i
# polaczenie konczy sie bledem, ktory nie mowi o co chodzi.
function Ustaw-TLS {
    try {
        [Net.ServicePointManager]::SecurityProtocol =
            [Net.SecurityProtocolType]::Tls12 -bor [Net.SecurityProtocolType]::Tls11
    } catch { }
}

function Pobierz-Manifest {
    param([int]$Timeout = 6)
    if (-not (Akt-Skonfigurowane)) { return $null }
    Ustaw-TLS
    try {
        # Cache-buster: raw.githubusercontent trzyma plik kilka minut,
        # a niejeden firmowy proxy znacznie dluzej.
        $url = $UrlManifest
        if ($url -notmatch '\?') { $url = $url + '?t=' + [DateTime]::UtcNow.Ticks }

        $r = Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec $Timeout `
                               -Headers @{ 'Cache-Control' = 'no-cache' }
        if ($r.StatusCode -ne 200) { return $null }
        return ($r.Content | ConvertFrom-Json)
    } catch { return $null }
}


# ---------------------------------------------------------------------
#  PORTOWNANIE WERSJI
# ---------------------------------------------------------------------
# Numery ida przez [version], nie przez porownanie tekstu - inaczej
# "7.10" wyszloby starsze od "7.9".
function Na-Wersje {
    param([string]$T)
    if (-not $T) { return $null }
    $t = ($T -replace '[^0-9\.]', '')
    while (($t.Split('.')).Count -lt 2) { $t = $t + '.0' }
    try { return [version]$t } catch { return $null }
}

function Nowsza-Wersja {
    param([string]$Zdalna, [string]$Lokalna)
    $a = Na-Wersje $Zdalna
    $b = Na-Wersje $Lokalna
    if (-not $a -or -not $b) { return $false }
    return ($a -gt $b)
}


# ---------------------------------------------------------------------
#  SPRAWDZENIE
# ---------------------------------------------------------------------
# Zwraca opis aktualizacji albo $null. Sam niczego nie pokazuje ani nie
# pobiera - decyzje podejmuje wywolujacy.
function Ocen-Manifest {
    param($m, $u, [switch]$Wymuszone)

    if (-not $m -or -not $m.opti) { return $null }

    $zdalna = "$($m.opti.wersja)"
    if (-not (Nowsza-Wersja $zdalna $AppWersja)) { return $null }
    if (-not $Wymuszone -and $u.pomin -eq $zdalna) { return $null }

    # Ponizej wersji minimalnej podmiana samego pliku moze nie wystarczyc
    # (zmieniony format danych, nowe pliki w paczce) - wtedy kierujemy na
    # pelna instalacje zamiast udawac, ze wszystko sie uda.
    $pelna = $false
    if ($m.opti.minimalna -and (Nowsza-Wersja "$($m.opti.minimalna)" $AppWersja)) { $pelna = $true }

    $zmiany = @()
    if ($m.opti.zmiany) { $zmiany = @($m.opti.zmiany) }

    return @{
        Wersja     = $zdalna
        Zmiany     = $zmiany
        PelnaWymag = $pelna
        Ps1Url     = "$($m.opti.ps1.url)"
        Ps1Sha     = "$($m.opti.ps1.sha256)"
        Ps1Rozm    = $(if ($m.opti.ps1.rozmiar)   { [int64]$m.opti.ps1.rozmiar }   else { [int64]0 })
        SetupUrl   = "$($m.opti.setup.url)"
        SetupSha   = "$($m.opti.setup.sha256)"
        SetupRozm  = $(if ($m.opti.setup.rozmiar) { [int64]$m.opti.setup.rozmiar } else { [int64]0 })
        Strona     = "$($m.opti.strona)"
    }
}

# Jedno zapytanie do serwera obsluguje dwie rzeczy: nowa wersje programu
# i nowa baze opisow. Baza schodzi od razu, bo to dane - nowa wersja
# czeka na klikniecie, bo to kod.
function Sprawdz-Wszystko {
    param([switch]$Wymuszone)

    if (-not (Akt-Skonfigurowane)) { return $null }

    $u = Load-UstAkt

    # Znaleziona, a jeszcze niezainstalowana wersja omija limit czasowy.
    $czekaJuz = $false
    try { $czekaJuz = ($u.czeka -and (Nowsza-Wersja "$($u.czeka)" $AppWersja) -and ($u.pomin -ne $u.czeka)) } catch { }

    if (-not $Wymuszone -and -not $czekaJuz) {
        if (-not $u.auto) { return $null }
        if ($u.ostatnie) {
            try {
                $last = [DateTime]::Parse($u.ostatnie, [Globalization.CultureInfo]::InvariantCulture)
                if (((Get-Date) - $last).TotalHours -lt $AktOdstepH) { return $null }
            } catch { }
        }
    }

    $m = Pobierz-Manifest
    $u.ostatnie = (Get-Date).ToString('o')
    Save-UstAkt $u

    # Przy sprawdzeniu recznym oddajemy wynik zawsze - takze pusty.
    # Inaczej wskaznik w pasku tytulu nie mialby jak odrozniec "nie ma
    # nowszej wersji" od "nie udalo sie polaczyc" i utknalby na napisie
    # "Sprawdzam...".
    if (-not $m) {
        if ($Wymuszone) { return @{ Akt = $null; BazaOdswiezona = $false; Polaczono = $false } }
        return $null
    }

    $baza = $false
    try { $baza = [bool](Zaktualizuj-Baze $m) } catch { }

    $akt = Ocen-Manifest $m $u -Wymuszone:$Wymuszone

    # Zapamietujemy, ze cos czeka - albo kasujemy slad, gdy juz nie czeka
    # (zainstalowane albo pominiete).
    try {
        $nowyCzeka = ''
        if ($akt) { $nowyCzeka = "$($akt.Wersja)" }
        if ("$($u.czeka)" -ne $nowyCzeka) {
            $u.czeka = $nowyCzeka
            Save-UstAkt $u
        }
    } catch { }

    if (-not $akt -and -not $baza -and -not $Wymuszone) { return $null }

    return @{ Akt = $akt; BazaOdswiezona = $baza; Polaczono = $true }
}

function Sprawdz-Aktualizacje {
    param([switch]$Wymuszone)
    $w = Sprawdz-Wszystko -Wymuszone:$Wymuszone
    if (-not $w) { return $null }
    return $w.Akt
}

# Wersja dla okna: leci w osobnym runspace, zeby nie zatrzymac startu
# programu na czas odpowiedzi serwera. Wynik wraca do UI przez
# Dispatcher, bo watek w tle nie ma prawa dotknac kontrolek.
#
# Nowy runspace nie widzi funkcji z glownej sesji, wiec przepisujemy je
# tam po nazwie - zamiast trzymac druga kopie tego samego kodu.
$FunkcjeDoTla = @('Akt-Skonfigurowane','Load-UstAkt','Save-UstAkt','Ustaw-TLS',
                  'Pobierz-Manifest','Na-Wersje','Nowsza-Wersja','Pobierz-Plik',
                  'Zaktualizuj-Baze','Ocen-Manifest','Sprawdz-Wszystko','Sprawdz-Aktualizacje')

function Sprawdz-AktualizacjeWTle {
    param($Okno, [scriptblock]$PoZnalezieniu, [switch]$Wymuszone)

    if (-not (Akt-Skonfigurowane)) { return }

    $kod = ''
    foreach ($n in $FunkcjeDoTla) {
        $f = Get-Command $n -CommandType Function -ErrorAction SilentlyContinue
        if ($f) { $kod += "function $n {`n" + $f.Definition + "`n}`n" }
    }

    # Wynik NIE wraca przez wywolanie zwrotne z runspace'u w tle.
    # Scriptblock przekazany tam i wywolany przez Dispatcher wykonuje sie
    # w obcym runspace, a kazde dotkniecie kontrolki konczy sie wtedy
    # bledem "watek wywolujacy nie moze uzyskac dostepu do tego obiektu".
    # Zamiast tego tlo zapisuje wynik do wspolnej tablicy, a okno odbiera
    # go zegarem - czyli juz na swoim wlasnym watku i w swoim runspace.
    $wspolne = [hashtable]::Synchronized(@{ Gotowe = $false; Wynik = $null })

    try {
        $rs = [runspacefactory]::CreateRunspace()
        $rs.ApartmentState = 'STA'
        $rs.ThreadOptions  = 'ReuseThread'
        $rs.Open()
        $rs.SessionStateProxy.SetVariable('Kod',           $kod)
        $rs.SessionStateProxy.SetVariable('UrlManifest',   $UrlManifest)
        $rs.SessionStateProxy.SetVariable('AktFile',       $AktFile)
        $rs.SessionStateProxy.SetVariable('AppWersja',     $AppWersja)
        $rs.SessionStateProxy.SetVariable('AktOdstepH',    $AktOdstepH)
        $rs.SessionStateProxy.SetVariable('BazaFile',      $BazaFile)
        $rs.SessionStateProxy.SetVariable('BazaWbudowana', $BazaWbudowana)
        $rs.SessionStateProxy.SetVariable('Wymus',         [bool]$Wymuszone)
        $rs.SessionStateProxy.SetVariable('S',             $wspolne)

        $ps = [powershell]::Create()
        $ps.Runspace = $rs
        $null = $ps.AddScript({
            try {
                . ([scriptblock]::Create($Kod))
                $S.Wynik = Sprawdz-Wszystko -Wymuszone:$Wymus
            } catch { }
            $S.Gotowe = $true
        })
        $uchwyt = $ps.BeginInvoke()
    } catch { return }

    $zegar = New-Object System.Windows.Threading.DispatcherTimer
    $zegar.Interval = [TimeSpan]::FromMilliseconds(250)
    $zegar.Add_Tick({
        if (-not $wspolne.Gotowe) { return }
        $zegar.Stop()
        try { $null = $ps.EndInvoke($uchwyt) } catch { }
        try { $ps.Dispose(); $rs.Close(); $rs.Dispose() } catch { }
        if ($wspolne.Wynik) {
            try { & $PoZnalezieniu $wspolne.Wynik } catch { }
        }
    }.GetNewClosure())
    $zegar.Start()
}


# ---------------------------------------------------------------------
#  POBIERANIE
# ---------------------------------------------------------------------
# Bez zgodnej sumy kontrolnej nie ruszamy dalej. Program chodzi z
# prawami administratora - plik, ktory tu wejdzie, dostanie je razem
# z nim.
function Pobierz-Plik {
    param([string]$Url, [string]$Cel, [string]$Sha256)

    Ustaw-TLS
    try {
        $wc = New-Object System.Net.WebClient
        $wc.Headers.Add('User-Agent', 'OptiLauncher')
        $wc.DownloadFile($Url, $Cel)
    } catch {
        return @{ Ok = $false; Blad = "Nie udalo sie pobrac pliku: $($_.Exception.Message)" }
    }

    if (-not (Test-Path $Cel)) { return @{ Ok = $false; Blad = 'Plik nie zostal zapisany.' } }

    if ($Sha256) {
        $h = ''
        try { $h = (Get-FileHash -LiteralPath $Cel -Algorithm SHA256).Hash } catch { }
        if ($h -ne $Sha256.ToUpper()) {
            Remove-Item -LiteralPath $Cel -Force -ErrorAction SilentlyContinue
            return @{ Ok = $false; Blad = 'Suma kontrolna sie nie zgadza - plik odrzucony.' }
        }
    }
    return @{ Ok = $true }
}

# Przed podmiana sprawdzamy, czy pobrany skrypt w ogole da sie
# sparsowac. Jeden bledny znak w wydanej wersji zabilby program
# u kazdego, kto ja pobierze.
function Test-SkladniPliku {
    param([string]$Sciezka)
    try {
        $err = $null
        $null = [System.Management.Automation.Language.Parser]::ParseFile($Sciezka, [ref]$null, [ref]$err)
        return (-not $err -or $err.Count -eq 0)
    } catch { return $false }
}


# ---------------------------------------------------------------------
#  PODMIANA .PS1   (tryb bat i portable)
# ---------------------------------------------------------------------
# Nie da sie nadpisac pliku, ktory wlasnie jest uruchomiony, i liczyc na
# to, ze nic sie nie stanie. Zapisujemy maly skrypt-posrednik: czeka az
# proces zniknie, robi kopie starej wersji, podmienia, uruchamia
# ponownie, a gdy start sie nie uda - przywraca kopie.
$SzablonPodmiany = @'
param([int]$ProcId, [string]$Stary, [string]$Nowy, [string]$Kopia)

$i = 0
while ($i -lt 60) {
    if (-not (Get-Process -Id $ProcId -ErrorAction SilentlyContinue)) { break }
    Start-Sleep -Milliseconds 500
    $i++
}
Start-Sleep -Milliseconds 400

try {
    Copy-Item -LiteralPath $Stary -Destination $Kopia -Force
    Copy-Item -LiteralPath $Nowy  -Destination $Stary -Force
    Unblock-File -LiteralPath $Stary -ErrorAction SilentlyContinue
} catch {
    if (Test-Path $Kopia) { Copy-Item -LiteralPath $Kopia -Destination $Stary -Force }
    exit 1
}

$psexe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
$p = Start-Process $psexe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',"`"$Stary`"") -PassThru

# Jesli nowa wersja wywali sie w pierwszych sekundach, wracamy do
# poprzedniej - lepiej starszy dzialajacy program niz zaden.
Start-Sleep -Seconds 6
if ($p.HasExited -and $p.ExitCode -ne 0) {
    Copy-Item -LiteralPath $Kopia -Destination $Stary -Force
    Start-Process $psexe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',"`"$Stary`"")
}

Remove-Item -LiteralPath $Nowy -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $MyInvocation.MyCommand.Path -Force -ErrorAction SilentlyContinue
'@

# Sciezka docelowa wlasnego pliku - potrzebna i przy pobieraniu,
# i przy podmianie.
function Sciezka-Wlasna {
    $x = $PSCommandPath
    if (-not $x) { $x = $MyInvocation.MyCommand.Path }
    return $x
}

function Plik-TymczasowyPs1 {
    param($Info)
    return (Join-Path $env:TEMP ("OptiLauncher_{0}.ps1" -f $Info.Wersja))
}

function Plik-TymczasowySetup {
    param($Info)
    return (Join-Path $env:TEMP ("OptiPakiet-{0}-Setup.exe" -f $Info.Wersja))
}

# Czesc po pobraniu, wspolna dla trybu konsolowego i okna z paskiem
# postepu: sprawdzenie skladni, kopia zapasowa, posrednik, restart.
function Zakoncz-PodmianePs1 {
    param($Info, [string]$Tmp, [scriptblock]$Postep)

    $mojaSciezka = Sciezka-Wlasna
    if (-not $mojaSciezka) { return @{ Ok = $false; Blad = 'Nie wiem, gdzie lezy wlasny plik.' } }

    if ($Postep) { & $Postep 'Sprawdzam pobrany plik...' }
    if (-not (Test-SkladniPliku $Tmp)) {
        Remove-Item -LiteralPath $Tmp -Force -ErrorAction SilentlyContinue
        return @{ Ok = $false; Blad = 'Pobrany plik ma blad skladni - aktualizacja przerwana.' }
    }

    Zapamietaj-Aktualizacje $Info

    $kopia = "$mojaSciezka.bak"
    $swap  = Join-Path $env:TEMP ("OptiPodmiana_{0}.ps1" -f [guid]::NewGuid().ToString('N'))
    Set-Content -LiteralPath $swap -Value $SzablonPodmiany -Encoding UTF8

    # Wpis w Ustawieniach Windows tez musi poznac nowy numer - inaczej
    # lista zainstalowanych programow zostanie przy starej wersji.
    # Dwa mozliwe klucze: wlasny (instalacja .batem) i Inno Setup.
    foreach ($reg in @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\OptiLauncher',
                       "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\$($AktAppId)_is1")) {
        try {
            if (Test-Path $reg) {
                New-ItemProperty -Path $reg -Name 'DisplayVersion' -Value $Info.Wersja `
                                 -PropertyType String -Force | Out-Null
            }
        } catch { }
    }

    $psexe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $argumenty = @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File', "`"$swap`"",
                   '-ProcId', $PID, '-Stary', "`"$mojaSciezka`"", '-Nowy', "`"$Tmp`"", '-Kopia', "`"$kopia`"")
    Start-Process $psexe -ArgumentList $argumenty -WindowStyle Hidden | Out-Null

    return @{ Ok = $true; Zamknij = $true }
}

# Wersja synchroniczna - uzywa jej tryb konsolowy, gdzie zamrozenie
# niczego nie psuje, bo i tak nie ma okna.
function Start-AktualizacjaPs1 {
    param($Info, [scriptblock]$Postep)

    if (-not (Sciezka-Wlasna)) { return @{ Ok = $false; Blad = 'Nie wiem, gdzie lezy wlasny plik.' } }
    if ($Postep) { & $Postep 'Pobieram nowa wersje...' }

    $tmp = Plik-TymczasowyPs1 $Info
    $p = Pobierz-Plik $Info.Ps1Url $tmp $Info.Ps1Sha
    if (-not $p.Ok) { return $p }

    return (Zakoncz-PodmianePs1 $Info $tmp $Postep)
}


# ---------------------------------------------------------------------
#  AKTUALIZACJA INSTALATOREM   (tryb inno)
# ---------------------------------------------------------------------
# Inno z tym samym AppId nadpisze instalacje w miejscu, zachowa skroty
# i podniesie wersje w Ustawieniach Windows. /SILENT zostawia pasek
# postepu - /VERYSILENT nie pokazuje nic, co przy kilkudziesieciu
# sekundach ciszy wyglada jak zawieszony program.
function Zakoncz-Instalator {
    param($Info, [string]$Tmp, [scriptblock]$Postep)

    Zapamietaj-Aktualizacje $Info

    if ($Postep) { & $Postep 'Uruchamiam instalator...' }
    try {
        Start-Process -FilePath $Tmp `
            -ArgumentList '/SILENT','/NOCANCEL','/SUPPRESSMSGBOXES','/RESTARTAPPLICATIONS' | Out-Null
    } catch {
        return @{ Ok = $false; Blad = "Nie udalo sie uruchomic instalatora: $($_.Exception.Message)" }
    }

    return @{ Ok = $true; Zamknij = $true }
}

function Start-AktualizacjaInno {
    param($Info, [scriptblock]$Postep)

    if (-not $Info.SetupUrl) { return @{ Ok = $false; Blad = 'Manifest nie podaje instalatora.' } }

    if ($Postep) { & $Postep 'Pobieram instalator...' }
    $tmp = Plik-TymczasowySetup $Info
    $p = Pobierz-Plik $Info.SetupUrl $tmp $Info.SetupSha
    if (-not $p.Ok) { return $p }

    return (Zakoncz-Instalator $Info $tmp $Postep)
}


# ---------------------------------------------------------------------
#  WEJSCIE GLOWNE
# ---------------------------------------------------------------------
# Zapisujemy numer i liste zmian, zeby nowa wersja miala co pokazac
# przy pierwszym uruchomieniu. Bez tego uzytkownik widzi tylko to, ze
# program sie zrestartowal.
function Zapamietaj-Aktualizacje {
    param($Info)
    try {
        $u = Load-UstAkt
        $u.poWersja = "$($Info.Wersja)"
        $u.poZmiany = @($Info.Zmiany)
        Save-UstAkt $u
    } catch { }
}

# Pobieranie pliku aktualizacji.
#
# Historia tego miejsca jest pouczajaca: cztery razy przepisywalem sposob
# pobierania, a zepsute bylo raportowanie postepu. Scriptblocki tworzone
# w uchwycie klikniecia nie przechwytywaly $bar ani $stan, bo
# GetNewClosure() bierze tylko zmienne z BIEZACEGO zakresu lokalnego -
# leciał wyjatek "IsIndeterminate cannot be found", po cichu polkniety
# przez catch. Stad wrazenie, ze pobieranie stoi.
#
# Dlatego teraz: droga glowna czyta odpowiedz kawalkami, zeby byly
# prawdziwe procenty, a gdy cokolwiek na niej zawiedzie - wracamy do
# jednego wywolania Invoke-WebRequest, tego samego, ktorym schodzi
# manifest i ktore przeszlo aktualizacje 8.4. Kazdy krok idzie do konsoli.
function Pobierz-Prosto {
    param([string]$Url, [string]$Cel)
    try {
        Invoke-WebRequest -Uri $Url -OutFile $Cel -UseBasicParsing -TimeoutSec 90 -ErrorAction Stop
        return ''
    } catch {
        return "$($_.Exception.Message)"
    }
}

function Pobierz-ZPostepem {
    param([string]$Url, [string]$Cel, [int64]$Rozmiar, $Okno, [scriptblock]$Postep, [scriptblock]$Koniec)

    Add-Log 'Aktualizacja: start pobierania.' 'info'

    try { Remove-Item -LiteralPath $Cel -Force -ErrorAction SilentlyContinue } catch { }
    try {
        [Net.ServicePointManager]::SecurityProtocol =
            [Net.SecurityProtocolType]::Tls12 -bor [Net.SecurityProtocolType]::Tls11
    } catch { }

    $blad = ''
    $udaloSieZPostepem = $false
    $we = $null; $wy = $null; $odp = $null

    try {
        $req = [System.Net.HttpWebRequest]::Create($Url)
        $req.UserAgent        = 'OptiLauncher'
        $req.Timeout          = 20000
        $req.ReadWriteTimeout = 20000

        $odp  = $req.GetResponse()
        $caly = [int64]$odp.ContentLength
        if ($caly -le 0) { $caly = $Rozmiar }

        $we  = $odp.GetResponseStream()
        $wy  = [System.IO.File]::Create($Cel)
        $buf = New-Object byte[] 32768
        $ile = [int64]0
        $ostatnie = [Environment]::TickCount

        while (($n = $we.Read($buf, 0, $buf.Length)) -gt 0) {
            $wy.Write($buf, 0, $n)
            $ile = $ile + $n
            if (([Environment]::TickCount - $ostatnie) -ge 120) {
                $ostatnie = [Environment]::TickCount
                $proc = 0
                if ($caly -gt 0) { $proc = [int][Math]::Min(99, (100 * $ile / $caly)) }
                & $Postep $proc $ile $caly
                $Okno.Dispatcher.Invoke([action]{}, [Windows.Threading.DispatcherPriority]::Render)
            }
        }

        $wy.Close(); $wy = $null
        $we.Close(); $we = $null
        $odp.Close(); $odp = $null
        $udaloSieZPostepem = $true
        Add-Log 'Aktualizacja: pobieranie zakonczone.' 'info'
    } catch {
        Add-Log "Aktualizacja: postep niedostepny ($($_.Exception.Message)) - pobieram bez niego." 'warn'
        if ($wy)  { try { $wy.Close() }  catch { } }
        if ($we)  { try { $we.Close() }  catch { } }
        if ($odp) { try { $odp.Close() } catch { } }
    }

    if (-not $udaloSieZPostepem) {
        # Droga zapasowa - bez procentow, ale sprawdzona.
        try { & $Postep -1 0 0 } catch { }
        try { $Okno.Dispatcher.Invoke([action]{}, [Windows.Threading.DispatcherPriority]::Render) } catch { }
        try { Remove-Item -LiteralPath $Cel -Force -ErrorAction SilentlyContinue } catch { }
        $blad = Pobierz-Prosto $Url $Cel
        if ($blad) { Add-Log "Aktualizacja: blad pobierania - $blad" 'err' }
        else       { Add-Log 'Aktualizacja: pobieranie zakonczone (bez postepu).' 'info' }
    }

    if (-not $blad) {
        $ile = [int64]0
        try { $ile = [int64](Get-Item -LiteralPath $Cel -ErrorAction Stop).Length } catch { $ile = 0 }
        Add-Log ("Aktualizacja: zapisano {0:N0} bajtow." -f $ile) 'info'
        if ($ile -le 0) { $blad = 'Pobrany plik jest pusty.' }
        else {
            try {
                & $Postep 100 $ile $ile
                $Okno.Dispatcher.Invoke([action]{}, [Windows.Threading.DispatcherPriority]::Render)
            } catch { }
        }
    }

    try { & $Koniec $blad } catch {
        Add-Log "Aktualizacja: blad po pobraniu - $($_.Exception.Message)" 'err'
    }
    return @{ Ok = $true }
}

function Sprawdz-Sume {
    param([string]$Plik, [string]$Sha256)
    if (-not $Sha256) { return $true }
    $h = ''
    try { $h = (Get-FileHash -LiteralPath $Plik -Algorithm SHA256).Hash } catch { }
    return ($h -eq $Sha256.ToUpper())
}

# Ktora droga aktualizacji ma sens przy tej instalacji i tym manifescie.
# Instalacja z instalatora woli instalator, bo ten utrzymuje spojnosc
# skrotow i wpisu w Ustawieniach Windows - ale gdy manifest go nie
# podaje, podmiana samego pliku jest lepsza niz komunikat o bledzie.
# Numer wersji w rejestrze i tak zostaje poprawiony.
function Wybierz-DrogeAktualizacji {
    param($Info)
    $tryb = Get-TrybInstalacji
    if ($tryb -eq 'inno' -and $Info.SetupUrl) { return 'inno' }
    return 'ps1'
}

function Zainstaluj-Aktualizacje {
    param($Info, [scriptblock]$Postep)

    $droga = Wybierz-DrogeAktualizacji $Info

    if ($Info.PelnaWymag -and $droga -ne 'inno') {
        return @{ Ok = $false
                  Blad = 'Ta wersja wymaga pelnej instalacji - pobierz instalator ze strony programu.' }
    }

    if ($droga -eq 'inno') { return (Start-AktualizacjaInno $Info $Postep) }
    return (Start-AktualizacjaPs1 $Info $Postep)
}


# =====================================================================
#  BAZA OPISOW
#
#  Autostart i lista procesow pokazuja nazwy plikow. To jedyne miejsce
#  w programie, gdzie uzytkownik naprawde nie wie, na co patrzy:
#  "RtkAudUService64" nic mu nie mowi, a decyzja nalezy do niego.
#
#  Baza to dane, nie kod - i dlatego moze isc kanalem aktualizacji
#  osobno od programu. Nowe opisy nie wymagaja wydawania nowej wersji.
#  Zadania optymalizacyjne swiadomie NIE ida ta droga: one pisza do
#  rejestru i wylaczaja uslugi, wiec plik z zadaniami pobierany z sieci
#  bylby zdalnym wykonywaniem kodu na koncie administratora.
# =====================================================================

$BazaFile = Join-Path $DataDir 'baza.json'

# Kopia dostarczona z programem - dziala od pierwszego uruchomienia,
# bez sieci. Pobrana wersja lezy w katalogu danych i ma pierwszenstwo.
$BazaWbudowana = ''
try {
    $sc = $PSCommandPath
    if (-not $sc) { $sc = $MyInvocation.MyCommand.Path }
    if ($sc) { $BazaWbudowana = Join-Path (Split-Path -Parent $sc) 'baza.json' }
} catch { }

$script:Baza        = $null
$script:BazaWersja  = 0
$script:BazaZrodlo  = ''

function Load-Baza {
    $script:Baza       = $null
    $script:BazaWersja = 0
    $script:BazaZrodlo = ''

    foreach ($p in @($BazaFile, $BazaWbudowana)) {
        if (-not $p -or -not (Test-Path $p)) { continue }
        try {
            $j = Get-Content -LiteralPath $p -Raw -Encoding UTF8 | ConvertFrom-Json
            if ($j.wpisy) {
                $script:Baza       = $j
                $script:BazaWersja = [int]$j.wersja
                $script:BazaZrodlo = $p
                return $true
            }
        } catch { }
    }
    return $false
}

# Nazwy w bazie sa malymi literami, bez rozszerzenia.
function Klucz-Nazwy {
    param([string]$N)
    if (-not $N) { return '' }
    $k = "$N".Trim().ToLower()
    if ($k.EndsWith('.exe')) { $k = $k.Substring(0, $k.Length - 4) }
    return $k
}

# Z polecenia autostartu ("C:\Program Files\...\Steam.exe" -silent)
# zostaje sama nazwa pliku.
function Klucz-Polecenia {
    param([string]$Cmd)
    if (-not $Cmd) { return '' }
    try {
        $m = [regex]::Match("$Cmd", '(?i)"?([A-Za-z]:\\[^"]*?\.exe)"?')
        if ($m.Success) { return (Klucz-Nazwy (Split-Path $m.Groups[1].Value -Leaf)) }
    } catch { }
    return ''
}

# Kolejnosc dopasowania: najpierw alias po nazwie wpisu (producenci
# nazywaja wpisy w rejestrze inaczej niz pliki), potem plik z polecenia,
# na koncu sama nazwa.
function Opis-Dla {
    param([string]$Nazwa, [string]$Cmd = '')

    if (-not $script:Baza) { return $null }

    $kandydaci = New-Object System.Collections.ArrayList
    $kn = Klucz-Nazwy $Nazwa
    $kc = Klucz-Polecenia $Cmd

    if ($kn -and $script:Baza.aliasy -and $script:Baza.aliasy.PSObject.Properties[$kn]) {
        [void]$kandydaci.Add("$($script:Baza.aliasy.$kn)")
    }
    if ($kc) { [void]$kandydaci.Add($kc) }
    if ($kn) { [void]$kandydaci.Add($kn) }

    foreach ($k in $kandydaci) {
        if (-not $k) { continue }
        if ($script:Baza.wpisy.PSObject.Properties[$k]) {
            $w = $script:Baza.wpisy.$k
            return @{
                nazwa  = "$($w.nazwa)"
                zrodlo = "$($w.zrodlo)"
                ocena  = "$($w.ocena)"
                opis   = "$($w.opis)"
            }
        }
    }
    return $null
}

# Pobranie nowej bazy kanalem aktualizacji. Dane, nie kod - wiec moze
# zejsc w tle bez pytania. Suma kontrolna i tak jest sprawdzana, a plik
# laduje na miejscu dopiero wtedy, gdy da sie go sparsowac.
function Zaktualizuj-Baze {
    param($M)

    if (-not $M -or -not $M.baza -or -not $M.baza.url) { return $false }

    $lokalna = 0
    foreach ($p in @($BazaFile, $BazaWbudowana)) {
        if (-not $p -or -not (Test-Path $p)) { continue }
        try {
            $j = Get-Content -LiteralPath $p -Raw -Encoding UTF8 | ConvertFrom-Json
            if ([int]$j.wersja -gt $lokalna) { $lokalna = [int]$j.wersja }
        } catch { }
        break
    }
    if ([int]$M.baza.wersja -le $lokalna) { return $false }

    $tmp = Join-Path $env:TEMP ("OptiBaza_{0}.json" -f [guid]::NewGuid().ToString('N'))
    $p = Pobierz-Plik "$($M.baza.url)" $tmp "$($M.baza.sha256)"
    if (-not $p.Ok) { return $false }

    try {
        $j = Get-Content -LiteralPath $tmp -Raw -Encoding UTF8 | ConvertFrom-Json
        if (-not $j.wpisy) { throw 'brak sekcji wpisy' }
        Copy-Item -LiteralPath $tmp -Destination $BazaFile -Force
        Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
        return $true
    } catch {
        Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
        return $false
    }
}

Load-Baza | Out-Null


if ($Tryb -ne '') {

    function Info { param($m) Write-Host "  $m" -ForegroundColor Gray }
    function Ok   { param($m) Write-Host "  $m" -ForegroundColor Green }
    function Uwaga{ param($m) Write-Host "  $m" -ForegroundColor Yellow }
    function Blad { param($m) Write-Host "  $m" -ForegroundColor Red }

    switch ($Tryb.ToLower()) {

    # =================================================================
    #  INSTALACJA
    # =================================================================
    'instaluj' {
        $ErrorActionPreference = 'Stop'
        Write-Host ''
        Write-Host '  ==============================================' -ForegroundColor Cyan
        Write-Host "     Instalacja $AppNazwa $AppWersja"             -ForegroundColor Cyan
        Write-Host '  ==============================================' -ForegroundColor Cyan
        Write-Host ''

        $Zrodlo = $PSCommandPath
        if (-not $Zrodlo) { $Zrodlo = $MyInvocation.MyCommand.Path }
        Info "Zrodlo: $Zrodlo"

        $KatInst = Join-Path $env:LOCALAPPDATA "Programs\$AppNazwa"
        $DstPs1  = Join-Path $KatInst 'OptiLauncher.ps1'
        $DstIco  = Join-Path $KatInst 'OptiLauncher.ico'
        $DstTxt  = Join-Path $KatInst 'README.txt'
        $DstUni  = Join-Path $KatInst 'Odinstaluj.ps1'

        Write-Host ''
        Write-Host '  [1/4] Kopiowanie plikow...' -ForegroundColor Cyan
        Info "Katalog: $KatInst"
        if (-not (Test-Path $KatInst)) { New-Item -ItemType Directory -Path $KatInst -Force | Out-Null }

        Copy-Item -LiteralPath $Zrodlo -Destination $DstPs1 -Force
        Unblock-File -LiteralPath $DstPs1 -ErrorAction SilentlyContinue
        Set-Content -LiteralPath $DstTxt -Value $ReadmeTekst -Encoding UTF8

        $MaIkone = Zapisz-Ikone $DstIco
        if (-not $MaIkone) { Uwaga 'Nie udalo sie zapisac ikony - skroty dostana ikone PowerShella.' }
        Ok 'Pliki na miejscu.'

        # ---------------- deinstalator ----------------
        $UninstallBody = @'
Add-Type -AssemblyName System.Windows.Forms
$AppName = 'OptiLauncher'
$Dir     = Split-Path -Parent $MyInvocation.MyCommand.Path

$answer = [System.Windows.Forms.MessageBox]::Show(
    "Usunac $AppName z tego komputera?`n`nZmiany wprowadzone w systemie NIE zostana cofniete - do tego sluzy przycisk Przywroc wszystko w programie.",
    "Deinstalacja $AppName", 'YesNo', 'Question')
if ($answer -ne 'Yes') { exit }

$paths = @(
    (Join-Path ([Environment]::GetFolderPath('Desktop')) "$AppName.lnk"),
    (Join-Path $env:APPDATA "Microsoft\Windows\Start Menu\Programs\$AppName.lnk")
)
foreach ($p in $paths) { Remove-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue }

Remove-Item -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\$AppName" `
            -Recurse -Force -ErrorAction SilentlyContinue

Start-Process cmd.exe -ArgumentList '/c','timeout /t 2 /nobreak >nul & rmdir /s /q',"`"$Dir`"" `
              -WindowStyle Hidden

[System.Windows.Forms.MessageBox]::Show("$AppName zostal usuniety.", "Deinstalacja") | Out-Null
'@
        Set-Content -LiteralPath $DstUni -Value $UninstallBody -Encoding UTF8

        # ---------------- skroty ----------------
        Write-Host ''
        Write-Host '  [2/4] Tworzenie skrotow...' -ForegroundColor Cyan

        $PsExe   = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
        $LnkArgs = "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$DstPs1`""

        function Nowy-Skrot {
            param([string]$Sciezka)
            $ws  = New-Object -ComObject WScript.Shell
            $lnk = $ws.CreateShortcut($Sciezka)
            $lnk.TargetPath       = $PsExe
            $lnk.Arguments        = $LnkArgs
            $lnk.WorkingDirectory = $KatInst
            $lnk.Description      = "Kompleksowa Optymalizacja Komputerowa by $AppAutor"
            if ($MaIkone) { $lnk.IconLocation = "$DstIco,0" }
            $lnk.Save()
            # bit 0x20 w bajcie 0x15 pliku .lnk = "Uruchom jako administrator"
            try {
                $b = [System.IO.File]::ReadAllBytes($Sciezka)
                $b[0x15] = $b[0x15] -bor 0x20
                [System.IO.File]::WriteAllBytes($Sciezka, $b)
            } catch { }
        }

        Nowy-Skrot (Join-Path $env:APPDATA "Microsoft\Windows\Start Menu\Programs\$AppNazwa.lnk")
        Ok 'Menu Start: gotowe.'

        Write-Host ''
        $mk = Read-Host '  Utworzyc skrot na pulpicie? [T/n]'
        if ($mk -eq '' -or $mk -match '^[tTyY]') {
            Nowy-Skrot (Join-Path ([Environment]::GetFolderPath('Desktop')) "$AppNazwa.lnk")
            Ok 'Pulpit: gotowe.'
        } else { Info 'Pominieto skrot na pulpicie.' }

        # ---------------- rejestracja ----------------
        Write-Host ''
        Write-Host "  [3/4] Rejestracja w 'Aplikacje i funkcje'..." -ForegroundColor Cyan

        $RegPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\$AppNazwa"
        if (-not (Test-Path $RegPath)) { New-Item -Path $RegPath -Force | Out-Null }

        $rozmiar = 0
        try {
            $rozmiar = [int][math]::Round(((Get-ChildItem $KatInst -Recurse -File |
                       Measure-Object Length -Sum).Sum / 1KB), 0)
        } catch { }

        $props = @{
            DisplayName     = $AppNazwa
            DisplayVersion  = $AppWersja
            Publisher       = $AppAutor
            InstallLocation = $KatInst
            UninstallString = "`"$PsExe`" -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$DstUni`""
            NoModify        = 1
            NoRepair        = 1
            EstimatedSize   = $rozmiar
        }
        if ($MaIkone) { $props['DisplayIcon'] = $DstIco }
        foreach ($k in $props.Keys) {
            $typ = 'String'
            if ($props[$k] -is [int]) { $typ = 'DWord' }
            New-ItemProperty -Path $RegPath -Name $k -Value $props[$k] -PropertyType $typ -Force | Out-Null
        }
        Ok 'Zarejestrowano - program widoczny w Ustawieniach Windows.'

        # Znacznik dla systemu aktualizacji: po nim program wie, ze
        # zostal zainstalowany .batem, a nie instalatorem - i ze wolno
        # mu podmienic wlasny plik zamiast pobierac caly setup.
        try {
            if (-not (Test-Path $KluczApp)) { New-Item -Path $KluczApp -Force | Out-Null }
            New-ItemProperty -Path $KluczApp -Name 'InstallMode' -Value 'bat' `
                             -PropertyType String -Force | Out-Null
        } catch { }

        # ---------------- srodowisko ----------------
        Write-Host ''
        Write-Host '  [4/4] Sprawdzanie srodowiska...' -ForegroundColor Cyan
        $mode = $ExecutionContext.SessionState.LanguageMode
        if ($mode -ne 'FullLanguage') {
            Uwaga "PowerShell dziala w trybie: $mode"
            Uwaga 'To zwykle oznacza wlaczona Inteligentna kontrole aplikacji (SAC).'
            Uwaga 'W tym trybie okno programu sie nie otworzy.'
        } else { Ok 'Tryb PowerShell: FullLanguage - wszystko gra.' }

        $sac = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\CI\Policy' `
                -Name VerifiedAndReputablePolicyState -ErrorAction SilentlyContinue).VerifiedAndReputablePolicyState
        switch ($sac) {
            0       { Info 'Smart App Control: wylaczony.' }
            1       { Uwaga 'Smart App Control: WYMUSZANIE.' }
            2       { Info 'Smart App Control: tryb ewaluacji.' }
            default { Info 'Smart App Control: niedostepny na tym systemie.' }
        }

        Write-Host ''
        Write-Host '  ==============================================' -ForegroundColor Green
        Write-Host '     ZAINSTALOWANO'                               -ForegroundColor Green
        Write-Host '  ==============================================' -ForegroundColor Green
        Write-Host ''
        Info 'Uruchamiasz z Menu Start albo ikony na pulpicie.'
        Info 'Odinstalujesz z: Ustawienia > Aplikacje > Zainstalowane aplikacje.'
        Write-Host ''
        Read-Host '  Enter konczy'
        exit 0
    }

    # =================================================================
    #  README
    # =================================================================
    'readme' {
        $cel = Join-Path (Split-Path -Parent $PSCommandPath) 'README.txt'
        Set-Content -LiteralPath $cel -Value $ReadmeTekst -Encoding UTF8
        Write-Host ''
        Ok "Zapisano: $cel"
        Write-Host ''
        Read-Host '  Enter konczy'
        exit 0
    }

    # =================================================================
    #  IKONA
    # =================================================================
    'ikona' {
        $cel = Join-Path (Split-Path -Parent $PSCommandPath) 'OptiLauncher.ico'
        if (Zapisz-Ikone $cel) { Ok "Zapisano: $cel" } else { Blad 'Nie udalo sie zapisac ikony.' }
        Write-Host ''
        Read-Host '  Enter konczy'
        exit 0
    }

    # =================================================================
    #  AKTUALIZACJA Z KONSOLI
    # =================================================================
    'aktualizuj' {
        Write-Host ''
        Write-Host "  Sprawdzam aktualizacje ($AppNazwa $AppWersja)..." -ForegroundColor Cyan
        Write-Host ''

        if (-not (Akt-Skonfigurowane)) {
            Uwaga 'Adres manifestu nie jest jeszcze ustawiony.'
            Info  'Wpisz go w zmiennej $UrlManifest na gorze OptiLauncher.ps1'
            Info  'i wygeneruj wersja.json przez Build-Manifest.ps1.'
            Write-Host ''
            Read-Host '  Enter konczy'
            exit 0
        }

        # Tryb reczny rozroznia trzy rzeczy, ktore w tle wygladaja tak samo:
        # brak polaczenia, brak nowszej wersji i sama odswiezona baze.
        $m = Pobierz-Manifest
        if (-not $m) {
            Blad 'Nie udalo sie pobrac informacji o wersjach.'
            Info 'Sprawdz polaczenie z internetem. Jesli dziala, sprawdz adres:'
            Info "  $UrlManifest"
            Info 'Repozytorium musi byc publiczne - z prywatnego plik nie wyjdzie.'
            Write-Host ''
            Read-Host '  Enter konczy'
            exit 0
        }

        $u = Load-UstAkt
        $u.ostatnie = (Get-Date).ToString('o')
        Save-UstAkt $u

        if (Zaktualizuj-Baze $m) { Ok 'Baza opisow zaktualizowana.' }

        $info = Ocen-Manifest $m $u -Wymuszone
        if (-not $info) {
            Ok "Masz najnowsza wersje ($AppWersja)."
            Write-Host ''
            Read-Host '  Enter konczy'
            exit 0
        }

        Ok "Dostepna wersja $($info.Wersja)"
        foreach ($z in $info.Zmiany) { Info "  - $z" }
        Write-Host ''
        Info ("Tryb instalacji: " + (Get-TrybInstalacji))
        Write-Host ''

        $t = Read-Host '  Zaktualizowac teraz? [T/n]'
        if ($t -ne '' -and $t -notmatch '^[tTyY]') {
            Info 'Anulowane.'
            Write-Host ''
            exit 0
        }

        Write-Host ''
        $w = Zainstaluj-Aktualizacje $info { param($x) Info $x }
        Write-Host ''
        if ($w.Ok) { Ok 'Aktualizacja w toku - program uruchomi sie sam.' }
        else       { Blad $w.Blad }
        Write-Host ''
        Read-Host '  Enter konczy'
        exit 0
    }

    # =================================================================
    #  POMIAR LACZA W KONSOLI
    # =================================================================
    'lacze' {
        function Naglowek {
            param([string]$T)
            Write-Host ''
            Write-Host ("  " + $T) -ForegroundColor Cyan
            Write-Host ("  " + ('-' * $T.Length)) -ForegroundColor DarkGray
        }
        function Wiersz {
            param([string]$Etykieta, [string]$Wartosc, [string]$Stan = '')
            $kolor = 'Gray'
            if ($Stan -eq 'ok')   { $kolor = 'Green' }
            if ($Stan -eq 'warn') { $kolor = 'Yellow' }
            if ($Stan -eq 'err')  { $kolor = 'Red' }
            Write-Host ("  {0,-24}" -f $Etykieta) -NoNewline -ForegroundColor DarkGray
            Write-Host $Wartosc -ForegroundColor $kolor
        }
        function Karta {
            try {
                $r = Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction Stop |
                     Sort-Object RouteMetric | Select-Object -First 1
                if ($r) {
                    $a = Get-NetAdapter -InterfaceIndex $r.InterfaceIndex -ErrorAction Stop
                    if ($a) { return $a }
                }
            } catch { }
            try {
                return (Get-NetAdapter -Physical -ErrorAction Stop |
                        Where-Object { $_.Status -eq 'Up' } | Select-Object -First 1)
            } catch { }
            return $null
        }
        function Pomiar {
            param([string]$Cel, [int]$Ile = 10)
            $czasy = New-Object System.Collections.ArrayList
            $zgub = 0
            $ping = New-Object System.Net.NetworkInformation.Ping
            for ($i = 0; $i -lt $Ile; $i++) {
                try {
                    $r = $ping.Send($Cel, 1200)
                    if ($r -and $r.Status -eq 'Success') { [void]$czasy.Add([double]$r.RoundtripTime) }
                    else { $zgub++ }
                } catch { $zgub++ }
                Write-Host '.' -NoNewline -ForegroundColor DarkGray
                Start-Sleep -Milliseconds 120
            }
            Write-Host ''
            if ($czasy.Count -eq 0) { return @{ ok=$false; avg=0; min=0; max=0; jitter=0; loss=100 } }
            $sj = 0.0; $n = 0
            for ($i = 1; $i -lt $czasy.Count; $i++) { $sj += [math]::Abs($czasy[$i] - $czasy[$i-1]); $n++ }
            $jit = 0.0
            if ($n -gt 0) { $jit = $sj / $n }
            $st = ($czasy | Measure-Object -Average -Minimum -Maximum)
            return @{
                ok=$true
                avg=[math]::Round($st.Average,1); min=[math]::Round($st.Minimum,1); max=[math]::Round($st.Maximum,1)
                jitter=[math]::Round($jit,1); loss=[math]::Round(($zgub/[double]$Ile)*100,0)
            }
        }

        Clear-Host
        Write-Host ''
        Write-Host '  SPRAWDZANIE LACZA' -ForegroundColor White
        Write-Host "  $AppNazwa by $AppAutor - modul diagnostyczny" -ForegroundColor DarkGray

        Naglowek 'KARTA SIECIOWA'
        $ad = Karta
        if (-not $ad) {
            Wiersz 'Stan' 'nie wykryto aktywnego polaczenia' 'err'
            Write-Host ''
            Read-Host '  Enter konczy'
            exit 1
        }
        Wiersz 'Karta' "$($ad.InterfaceDescription)"
        Wiersz 'Predkosc linku' "$($ad.LinkSpeed)"

        $wifi = $false
        try { $wifi = ("$($ad.PhysicalMediaType)" -match '802.11') } catch { }
        Wiersz 'Typ' $(if ($wifi) { 'Wi-Fi' } else { 'kabel' })

        if ($wifi) {
            try {
                $txt = netsh wlan show interfaces 2>&1 | Out-String
                $sygnal = $null
                foreach ($line in ($txt -split "`r?`n")) {
                    if (-not $sygnal -and $line -match '(\d+)\s*%') { $sygnal = [int]$Matches[1] }
                    if ($line -match '(?i)radio type\s*:\s*(.+)$') { Wiersz 'Standard' $Matches[1].Trim() }
                }
                if ($sygnal) {
                    $s = 'ok'
                    if ($sygnal -lt 50) { $s = 'err' } elseif ($sygnal -lt 70) { $s = 'warn' }
                    Wiersz 'Sila sygnalu' "$sygnal %" $s
                }
            } catch { }
        }

        try {
            $mtu = (Get-NetIPInterface -InterfaceIndex $ad.InterfaceIndex -AddressFamily IPv4 -ErrorAction Stop).NlMtu
            if ($mtu) { Wiersz 'MTU' $mtu $(if ($mtu -lt 1400) { 'warn' } else { '' }) }
        } catch { }
        try {
            $dns = (Get-DnsClientServerAddress -InterfaceIndex $ad.InterfaceIndex -AddressFamily IPv4 -ErrorAction Stop).ServerAddresses
            if ($dns) { Wiersz 'Serwery DNS' ($dns -join ', ') }
        } catch { }

        $brama = $null
        try {
            $brama = (Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction Stop |
                      Sort-Object RouteMetric | Select-Object -First 1).NextHop
        } catch { }
        if ($brama) { Wiersz 'Brama' $brama }

        $g = @{ ok=$false; jitter=0; loss=0 }
        if ($brama) {
            Naglowek 'PING DO ROUTERA'
            Write-Host '  ' -NoNewline
            $g = Pomiar $brama 10
            if ($g.ok) {
                $s = 'ok'
                if ($g.jitter -gt 5 -or $g.loss -gt 0) { $s = 'err' } elseif ($g.jitter -gt 2) { $s = 'warn' }
                Wiersz 'Srednia' "$($g.avg) ms"
                Wiersz 'Min / max' "$($g.min) / $($g.max) ms"
                Wiersz 'Jitter' "$($g.jitter) ms" $s
                Wiersz 'Straty' "$($g.loss) %" $(if ($g.loss -gt 0) { 'err' } else { 'ok' })
            } else { Wiersz 'Wynik' 'brak odpowiedzi' 'err' }
        }

        Naglowek 'PING DO INTERNETU (1.1.1.1)'
        Write-Host '  ' -NoNewline
        $c = Pomiar '1.1.1.1' 10
        if ($c.ok) {
            $s = 'ok'
            if ($c.avg -gt 80) { $s = 'err' } elseif ($c.avg -gt 40) { $s = 'warn' }
            Wiersz 'Srednia' "$($c.avg) ms" $s
            Wiersz 'Min / max' "$($c.min) / $($c.max) ms"
            Wiersz 'Jitter' "$($c.jitter) ms" $(if ($c.jitter -gt 10) { 'warn' } else { 'ok' })
            Wiersz 'Straty' "$($c.loss) %" $(if ($c.loss -gt 0) { 'err' } else { 'ok' })
        } else { Wiersz 'Wynik' 'brak odpowiedzi' 'err' }

        Naglowek 'WNIOSEK'
        if ($brama -and $g.ok -and ($g.jitter -gt 5 -or $g.loss -gt 0)) {
            Wiersz 'Diagnoza' 'Problem MIEDZY komputerem a routerem.' 'err'
            Write-Host '  Kabel, Wi-Fi albo sam router. Zadne ustawienie Windows tego nie naprawi.' -ForegroundColor DarkGray
        } elseif ($c.ok -and $c.loss -gt 0) {
            Wiersz 'Diagnoza' 'Do routera stabilnie, pakiety gina dalej.' 'warn'
            Write-Host '  To strona operatora - warto zglosic.' -ForegroundColor DarkGray
        } elseif ($wifi -and $c.ok -and $c.jitter -gt 10) {
            Wiersz 'Diagnoza' 'Jitter wysoki jak na Wi-Fi.' 'warn'
            Write-Host '  Kabel rozwiazalby to od reki.' -ForegroundColor DarkGray
        } elseif ($c.ok) {
            Wiersz 'Diagnoza' 'Lacze zachowuje sie prawidlowo.' 'ok'
            Write-Host '  Nie ma tu czego optymalizowac.' -ForegroundColor DarkGray
        } else {
            Wiersz 'Diagnoza' 'Brak polaczenia z internetem.' 'err'
        }

        Naglowek 'USTAWIENIA STEROWNIKA KARTY'
        $props = @(
            @{ kw='*EEE';                 nazwa='Energy Efficient Ethernet' }
            @{ kw='EnableGreenEthernet';  nazwa='Green Ethernet' }
            @{ kw='*InterruptModeration'; nazwa='Interrupt Moderation' }
            @{ kw='*FlowControl';         nazwa='Flow Control' }
            @{ kw='*SelectiveSuspend';    nazwa='Selective Suspend' }
            @{ kw='WakeOnMagicPacket';    nazwa='Wybudzanie pakietem' }
        )
        # gwiazdka w nazwie klucza NDIS jest czescia nazwy, ale -RegistryKeyword
        # traktuje ja jak wieloznacznik - dlatego pobieramy wszystko raz
        $wszystkie = @()
        try { $wszystkie = @(Get-NetAdapterAdvancedProperty -Name $ad.Name -ErrorAction Stop) } catch { }
        $zn = 0
        foreach ($p in $props) {
            $cur = $wszystkie | Where-Object { "$($_.RegistryKeyword)" -eq $p.kw } | Select-Object -First 1
            if ($cur) {
                $zn++
                $val = "$(@($cur.RegistryValue)[0])"
                $wyl = ($val -eq '0')
                Wiersz $p.nazwa $(if ($wyl) { 'wylaczone' } else { "wlaczone  (wartosc: $val)" }) $(if ($wyl) { 'ok' } else { 'warn' })
            }
        }
        if ($zn -eq 0) { Write-Host '  Sterownik tej karty nie udostepnia zadnej z tych wlasciwosci.' -ForegroundColor DarkGray }

        Write-Host ''
        Write-Host '  Gotowe. Nic nie zostalo zmienione - to byl wylacznie odczyt.' -ForegroundColor DarkGray
        Write-Host ''
        Read-Host '  Enter konczy'
        exit 0
    }

    default {
        Blad "Nieznany tryb: $Tryb"
        Info 'Dostepne: instaluj, lacze, readme, ikona'
        exit 1
    }
    }
}

# =====================================================================
#  Ponizej normalny program - okno uruchamia sie, gdy nie podano -Tryb
# =====================================================================
$ErrorActionPreference = 'Continue'

$HostExe = $null
try { $HostExe = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName } catch { }
$IsCompiled = ($HostExe -and ($HostExe -notmatch '\\(powershell|pwsh|powershell_ise)\.exe$'))

$ScriptPath = $PSCommandPath
if (-not $ScriptPath) { $ScriptPath = $MyInvocation.MyCommand.Path }
if ($ScriptPath -and $ScriptPath -like '*.ps1') {
    Unblock-File -LiteralPath $ScriptPath -ErrorAction SilentlyContinue
}

$IsAdmin = ([Security.Principal.WindowsPrincipal] `
    [Security.Principal.WindowsIdentity]::GetCurrent()
    ).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

if (-not $IsAdmin) {
    try {
        if ($IsCompiled) { Start-Process -FilePath $HostExe -Verb RunAs }
        elseif ($ScriptPath) {
            Start-Process -FilePath $HostExe -Verb RunAs `
                -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',"`"$ScriptPath`"")
        }
    } catch { }
    exit
}

if ($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage') {
    Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
    [System.Windows.Forms.MessageBox]::Show(
        "PowerShell dziala w trybie $($ExecutionContext.SessionState.LanguageMode).`n`n" +
        "To zwykle skutek wlaczonej Inteligentnej kontroli aplikacji (Smart App Control), " +
        "ktora blokuje budowanie okien WPF.`n`n" +
        "Rozwiazanie: Zabezpieczenia Windows > Kontrola aplikacji i przegladarki > " +
        "Inteligentna kontrola aplikacji > Wylacz.",
        "OptiLauncher - nie moge wystartowac", 'OK', 'Warning') | Out-Null
    exit 1
}

Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName PresentationCore
Add-Type -AssemblyName WindowsBase
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

$AppVersion = '8.6'
$DataDir    = Join-Path $env:LOCALAPPDATA 'OptiLauncher'
if (-not (Test-Path $DataDir)) { New-Item -ItemType Directory -Path $DataDir -Force | Out-Null }
$LogFile    = Join-Path $DataDir ("log_{0}.txt" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
$BackupFile = Join-Path $DataDir 'backup.json'
$GamesFile  = Join-Path $DataDir 'games.json'
$ReportDir  = Join-Path $DataDir 'raporty'
$BenchFile  = Join-Path $DataDir 'pomiar.json'
if (-not (Test-Path $ReportDir)) { New-Item -ItemType Directory -Path $ReportDir -Force | Out-Null }

