$MotywFile = Join-Path $DataDir 'motyw.json'

# W motyw.json siedza wszystkie ustawienia wygladu: motyw, gestosc widoku
# i tlo Mica. Jeden plik, zeby nie mnozyc smieci w katalogu danych.
function Load-Wyglad {
    $w = @{ id = 'cyjan'; gestosc = 'komfort'; mica = $false }
    try {
        if (Test-Path $MotywFile) {
            $j = Get-Content $MotywFile -Raw -Encoding UTF8 | ConvertFrom-Json
            if ($j.id)      { $w.id = "$($j.id)" }
            if ($j.gestosc) { $w.gestosc = "$($j.gestosc)" }
            if ($null -ne $j.mica) { $w.mica = [bool]$j.mica }
        }
    } catch { }
    return $w
}

function Save-Wyglad {
    try {
        @{ id = $script:MotywId; gestosc = $script:Gestosc; mica = $script:Mica } |
            ConvertTo-Json | Set-Content $MotywFile -Encoding UTF8
    } catch { }
}

$script:Wyglad  = Load-Wyglad
$script:MotywId = $script:Wyglad.id
$script:Gestosc = $script:Wyglad.gestosc
$script:Mica    = $script:Wyglad.mica
$script:Motyw   = @($Motywy | Where-Object { $_.Id -eq $script:MotywId })[0]
if (-not $script:Motyw) { $script:Motyw = $Motywy[0]; $script:MotywId = 'cyjan' }

# Tryb zageszczony sciaga marginesy i wysokosci, zeby na ekranie miescilo
# sie wiecej kart. Rozmiary tekstu zostaja - zmniejszanie liter to droga
# do interfejsu, ktorego nie da sie czytac.
$Zwarty = ($script:Gestosc -eq 'zwarty')
$G = @{ NavH = 42; RowH = 38 }
$G.CardPad = New-Object Windows.Thickness 18,15,18,15
$G.CardMar = New-Object Windows.Thickness 0,0,0,11
if ($Zwarty) {
    $G.NavH = 36
    $G.RowH = 34
    $G.CardPad = New-Object Windows.Thickness 14,10,14,10
    $G.CardMar = New-Object Windows.Thickness 0,0,0,7
}

function Zageszcz {
    param($Border)
    if (-not $Zwarty -or -not $Border) { return }
    $Border.Padding = $G.CardPad
    $Border.Margin  = $G.CardMar
}

# Podmiana idzie JEDNYM przebiegiem przez wyrazenie regularne. Gdyby lecial
# petla po parach, druga podmiana lapalaby wynik pierwszej: cyjan -> fiolet,
# a potem ten fiolet znowu na cos innego.
function Przemaluj {
    param([string]$Tekst)
    if (-not $script:Motyw -or $script:Motyw.Mapa.Count -eq 0) { return $Tekst }
    $mapa = $script:Motyw.Mapa
    $ocena = [System.Text.RegularExpressions.MatchEvaluator]{
        param($m)
        $k = $m.Value.ToUpper()
        # Bezpiecznik: wartosc bez '#' albo o zlej dlugosci jest ignorowana.
        # Bez tego jeden zly wpis w mapie wywala cale okno przy budowaniu.
        if ($mapa.ContainsKey($k)) {
            $w = "$($mapa[$k])"
            if ($w -match '^#([0-9A-Fa-f]{6}|[0-9A-Fa-f]{8})$') { return $w }
        }
        return $m.Value
    }
    return [regex]::Replace($Tekst, '#(?:[0-9A-Fa-f]{8}|[0-9A-Fa-f]{6})\b', $ocena)
}

$XamlText = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="OptiLauncher" Height="880" Width="1400"
        MinHeight="740" MinWidth="1220"
        WindowStyle="None" AllowsTransparency="True" Background="Transparent"
        WindowStartupLocation="CenterScreen" Opacity="0"
        FontFamily="Segoe UI" FontSize="13" TextOptions.TextFormattingMode="Display"
        UseLayoutRounding="True" SnapsToDevicePixels="True"
        RenderOptions.BitmapScalingMode="HighQuality">

  <Window.Resources>

    <SolidColorBrush x:Key="Bg"       Color="#070A10"/>
