    <SolidColorBrush x:Key="Warn"     Color="#FBBF24"/>
    <SolidColorBrush x:Key="Bad"      Color="#FB7185"/>

    <CubicEase   x:Key="EaseOut"  EasingMode="EaseOut"/>
    <CubicEase   x:Key="EaseIn"   EasingMode="EaseIn"/>
    <QuadraticEase x:Key="EaseSoft" EasingMode="EaseOut"/>
    <BackEase    x:Key="EasePop"  EasingMode="EaseOut" Amplitude="0.45"/>

    <LinearGradientBrush x:Key="AccentGrad" StartPoint="0,0" EndPoint="1,1">
      <GradientStop Color="#22D3EE" Offset="0"/>
      <GradientStop Color="#818CF8" Offset="1"/>
    </LinearGradientBrush>
    <LinearGradientBrush x:Key="AccentGradHot" StartPoint="0,0" EndPoint="1,1">
      <GradientStop Color="#67E8F9" Offset="0"/>
      <GradientStop Color="#A5B4FC" Offset="1"/>
    </LinearGradientBrush>
    <LinearGradientBrush x:Key="NavGlow" StartPoint="0,0" EndPoint="1,0">
      <GradientStop Color="#1B3450" Offset="0"/>
      <GradientStop Color="#101826" Offset="1"/>
    </LinearGradientBrush>
    <LinearGradientBrush x:Key="HeaderGrad" StartPoint="0,0" EndPoint="1,0">
      <GradientStop Color="#0B101A" Offset="0"/>
      <GradientStop Color="#111C2C" Offset="0.55"/>
      <GradientStop Color="#0B101A" Offset="1"/>
    </LinearGradientBrush>
    <LinearGradientBrush x:Key="Sheen" StartPoint="0,0" EndPoint="0,1">
      <GradientStop Color="#38FFFFFF" Offset="0"/>
      <GradientStop Color="#00FFFFFF" Offset="0.55"/>
    </LinearGradientBrush>
    <RadialGradientBrush x:Key="Aura" GradientOrigin="0.5,0.5" Center="0.5,0.5" RadiusX="0.75" RadiusY="0.75">
      <GradientStop Color="#2622D3EE" Offset="0"/>
      <GradientStop Color="#00000000" Offset="1"/>
    </RadialGradientBrush>

    <!-- Kafelki (Pulpit, Diagnostyka, Wyglad) - "szklany" panel: lekko
         przezroczyste tlo (Opacity na calym pedzlu, nie na kolorze - dzieki
         temu kolory nizej to wciaz te same, potwierdzone wartosci co w
         kazdej z dziewieciu map motywu, wiec dalej dzialaja wszedzie) i jasna,
         biala obwodka jako odbicie swiatla na krawedzi - ten sam patent,
         co juz uzywany w "Sheen" na glownym przycisku, tylko tutaj na
         calej ramce. -->
    <LinearGradientBrush x:Key="TileGrad" StartPoint="0,0" EndPoint="0,1" Opacity="0.86">
      <GradientStop Color="#141D2C" Offset="0"/>
      <GradientStop Color="#111826" Offset="1"/>
    </LinearGradientBrush>
    <LinearGradientBrush x:Key="TileBorderGrad" StartPoint="0,0" EndPoint="0,1">
      <GradientStop Color="#4DFFFFFF" Offset="0"/>
      <GradientStop Color="#12FFFFFF" Offset="1"/>
    </LinearGradientBrush>

    <!-- ============ PASEK PRZEWIJANIA ============ -->
    <Style TargetType="ScrollBar">
      <Setter Property="Width" Value="8"/>
      <Setter Property="Background" Value="Transparent"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ScrollBar">
            <Grid x:Name="root" Background="Transparent">
              <Track x:Name="PART_Track" IsDirectionReversed="True">
                <Track.Thumb>
                  <Thumb x:Name="th">
                    <Thumb.Template>
                      <ControlTemplate TargetType="Thumb">
                        <Border x:Name="tb" CornerRadius="4" Background="#26364C" Margin="2,0" Opacity="0.75"/>
                      </ControlTemplate>
                    </Thumb.Template>
                  </Thumb>
                </Track.Thumb>
                <Track.IncreaseRepeatButton>
                  <RepeatButton Command="ScrollBar.PageDownCommand" Opacity="0" Focusable="False"/>
                </Track.IncreaseRepeatButton>
                <Track.DecreaseRepeatButton>
                  <RepeatButton Command="ScrollBar.PageUpCommand" Opacity="0" Focusable="False"/>
                </Track.DecreaseRepeatButton>
              </Track>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="th" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.15"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="th" Storyboard.TargetProperty="Opacity"
                                       To="0.75" Duration="0:0:0.25"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <!-- ============ PRZYCISKI OKNA ============ -->
    <Style x:Key="Chrome" TargetType="Button">
      <Setter Property="Foreground" Value="#7E8DA1"/>
      <Setter Property="Background" Value="Transparent"/>
      <Setter Property="FontFamily" Value="Segoe MDL2 Assets"/>
      <Setter Property="FontSize" Value="10"/>
      <Setter Property="Width" Value="46"/>
      <Setter Property="Height" Value="42"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Grid>
              <Border x:Name="hov" Background="#1A2434" Opacity="0"/>
              <ContentPresenter x:Name="cp" HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Foreground" Value="#EAF2F8"/>
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hov" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.14"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hov" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.22"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
                <Setter TargetName="cp" Property="Opacity" Value="0.6"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <Style x:Key="ChromeClose" TargetType="Button" BasedOn="{StaticResource Chrome}">
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Grid>
              <Border x:Name="hov" Background="#D32B48" Opacity="0"/>
              <ContentPresenter x:Name="cp" HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Foreground" Value="White"/>
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hov" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.14"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hov" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.22"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <!-- ============ NAWIGACJA ============ -->
    <Style x:Key="Nav" TargetType="RadioButton">
      <Setter Property="Foreground" Value="{StaticResource Muted}"/>
      <Setter Property="Height" Value="36"/>
      <Setter Property="Margin" Value="12,1"/>
      <Setter Property="FontSize" Value="13"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="RadioButton">
            <Grid>
              <Border x:Name="hov" CornerRadius="10" Background="#121B29" Opacity="0"/>
              <Border x:Name="sel" CornerRadius="10" Background="{StaticResource NavGlow}" Opacity="0"/>
              <Border x:Name="bar" Width="3" Height="10" CornerRadius="0,2,2,0"
                      HorizontalAlignment="Left" VerticalAlignment="Center"
                      Background="{StaticResource AccentGrad}" Opacity="0"/>
              <StackPanel x:Name="row" Orientation="Horizontal" VerticalAlignment="Center" Margin="17,0">
                <TextBlock x:Name="ic" Text="{TemplateBinding Tag}" FontFamily="Segoe MDL2 Assets"
                           FontSize="14" VerticalAlignment="Center" Margin="0,0,13,0"/>
                <ContentPresenter VerticalAlignment="Center"/>
              </StackPanel>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Foreground" Value="{StaticResource Txt}"/>
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hov" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.15"/>
                      <ThicknessAnimation Storyboard.TargetName="row" Storyboard.TargetProperty="Margin"
                                          To="21,0,0,0" Duration="0:0:0.22"
                                          EasingFunction="{StaticResource EaseOut}"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hov" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.25"/>
                      <ThicknessAnimation Storyboard.TargetName="row" Storyboard.TargetProperty="Margin"
                                          To="17,0,0,0" Duration="0:0:0.25"
                                          EasingFunction="{StaticResource EaseOut}"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsChecked" Value="True">
                <Setter TargetName="ic" Property="Foreground" Value="{StaticResource Accent}"/>
                <Setter Property="Foreground" Value="{StaticResource Txt}"/>
                <Setter Property="FontWeight" Value="SemiBold"/>
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="sel" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.28" EasingFunction="{StaticResource EaseOut}"/>
                      <DoubleAnimation Storyboard.TargetName="bar" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.18"/>
                      <DoubleAnimation Storyboard.TargetName="bar" Storyboard.TargetProperty="Height"
                                       To="22" Duration="0:0:0.34" EasingFunction="{StaticResource EasePop}"/>
                      <DoubleAnimation Storyboard.TargetName="ic" Storyboard.TargetProperty="FontSize"
                                       From="11" To="14" Duration="0:0:0.3" EasingFunction="{StaticResource EasePop}"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="sel" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.25"/>
                      <DoubleAnimation Storyboard.TargetName="bar" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.2"/>
                      <DoubleAnimation Storyboard.TargetName="bar" Storyboard.TargetProperty="Height"
                                       To="10" Duration="0:0:0.2"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <!-- ============ KARTY ============ -->
    <Style x:Key="Card" TargetType="Border">
      <Setter Property="Background" Value="#111826"/>
      <Setter Property="BorderBrush" Value="#1E2A3D"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="CornerRadius" Value="16"/>
      <Setter Property="Padding" Value="17,16"/>
      <Setter Property="Margin" Value="0,0,0,12"/>
      <!-- Lekki cien - WPF renderuje go raz na karte i trzyma w pamieci
           podrecznej, wiec przy liscie kilkudziesieciu zadan nie kosztuje
           tyle, ile mogloby sie wydawac (odswieza sie tylko ta karta,
           ktora sie akurat animuje pod kursorem). -->
      <Setter Property="Effect">
        <Setter.Value>
          <DropShadowEffect Color="#000000" Opacity="0.26" BlurRadius="14" ShadowDepth="3" Direction="270"/>
        </Setter.Value>
      </Setter>
    </Style>

    <Style x:Key="PlainCard" TargetType="Border">
      <Setter Property="Background" Value="{StaticResource TileGrad}"/>
      <Setter Property="BorderBrush" Value="{StaticResource TileBorderGrad}"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="CornerRadius" Value="14"/>
      <Setter Property="Padding" Value="18,16"/>
      <!-- delikatny cien: te panele stoja na stale (nie w liscie na sto sztuk),
           wiec staly efekt cienia nic nie kosztuje, a daje uczucie uniesienia
           nad tlem zamiast plaskiej plamy koloru -->
      <Setter Property="Effect">
        <Setter.Value>
          <DropShadowEffect Color="#000000" Opacity="0.30" BlurRadius="16" ShadowDepth="3" Direction="270"/>
        </Setter.Value>
      </Setter>
    </Style>

    <!-- ============ CHECKBOX ============ -->
    <Style x:Key="Chk" TargetType="CheckBox">
      <Setter Property="VerticalAlignment" Value="Center"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="CheckBox">
            <Grid Width="20" Height="20">
              <Border x:Name="box" CornerRadius="6" Background="#0A0F19"
                      BorderBrush="#2C3D55" BorderThickness="1"/>
              <Border x:Name="ring" CornerRadius="6" BorderBrush="{StaticResource Accent}"
                      BorderThickness="1" Opacity="0"/>
              <Border x:Name="fill" CornerRadius="6" Background="{StaticResource AccentGrad}"
                      Opacity="0" Margin="7"/>
              <TextBlock x:Name="tick" Text="&#xE73E;" FontFamily="Segoe MDL2 Assets"
                         FontSize="10" Foreground="#06121A" Opacity="0"
                         HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsChecked" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="fill" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.12"/>
                      <ThicknessAnimation Storyboard.TargetName="fill" Storyboard.TargetProperty="Margin"
                                          To="0" Duration="0:0:0.26" EasingFunction="{StaticResource EasePop}"/>
                      <DoubleAnimation Storyboard.TargetName="tick" Storyboard.TargetProperty="Opacity"
                                       To="1" BeginTime="0:0:0.08" Duration="0:0:0.14"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="tick" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.1"/>
                      <ThicknessAnimation Storyboard.TargetName="fill" Storyboard.TargetProperty="Margin"
                                          To="7" Duration="0:0:0.18" EasingFunction="{StaticResource EaseOut}"/>
                      <DoubleAnimation Storyboard.TargetName="fill" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.18"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsMouseOver" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="ring" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.14"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="ring" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.2"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter TargetName="box" Property="Opacity" Value="0.25"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <!-- ============ PRZELACZNIK (WLACZ/WYLACZ) ============ -->
    <Style x:Key="Switch" TargetType="ToggleButton">
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Focusable" Value="False"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ToggleButton">
            <Grid x:Name="wrap" Width="46" Height="25" Cursor="Hand">
              <Border x:Name="track" CornerRadius="13" Background="#1A2432"
                      BorderBrush="#2C3D55" BorderThickness="1"/>
              <Border x:Name="trackOn" CornerRadius="13" Background="{StaticResource Good}" Opacity="0"/>
              <Border x:Name="thumb" Width="19" Height="19" CornerRadius="10" Background="#D7E0EC"
                      HorizontalAlignment="Left" VerticalAlignment="Center" Margin="3,0,0,0">
                <Border.Effect>
                  <DropShadowEffect Color="#000000" Opacity="0.35" BlurRadius="4" ShadowDepth="1"/>
                </Border.Effect>
              </Border>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsChecked" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="trackOn" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.18"/>
                      <ThicknessAnimation Storyboard.TargetName="thumb" Storyboard.TargetProperty="Margin"
                                          To="24,0,0,0" Duration="0:0:0.24" EasingFunction="{StaticResource EasePop}"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="trackOn" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.22"/>
                      <ThicknessAnimation Storyboard.TargetName="thumb" Storyboard.TargetProperty="Margin"
                                          To="3,0,0,0" Duration="0:0:0.2" EasingFunction="{StaticResource EaseOut}"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="track" Property="BorderBrush" Value="{StaticResource Accent}"/>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter TargetName="wrap" Property="Opacity" Value="0.35"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <!-- ============ PRZYCISK OBRYSOWY ============ -->
    <Style x:Key="Ghost" TargetType="Button">
      <Setter Property="Foreground" Value="{StaticResource Accent}"/>
      <Setter Property="Background" Value="Transparent"/>
      <Setter Property="Height" Value="33"/>
      <Setter Property="MinWidth" Value="86"/>
      <Setter Property="FontSize" Value="12"/>
      <Setter Property="FontWeight" Value="SemiBold"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Grid x:Name="wrap">
              <Border x:Name="base" CornerRadius="10" Background="#0D1420"
                      BorderBrush="#26384F" BorderThickness="1"/>
              <Border x:Name="hov" CornerRadius="10" Background="#123243"
                      BorderBrush="{StaticResource Accent}" BorderThickness="1" Opacity="0"/>
              <Border x:Name="pulse" CornerRadius="10" Background="{StaticResource Accent}"
                      Opacity="0" IsHitTestVisible="False"/>
              <ContentPresenter x:Name="cp" HorizontalAlignment="Center" VerticalAlignment="Center"
                                Margin="14,0"/>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hov" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.16"/>
                      <ThicknessAnimation Storyboard.TargetName="wrap" Storyboard.TargetProperty="Margin"
                                          To="-1" Duration="0:0:0.18" EasingFunction="{StaticResource EaseOut}"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hov" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.24"/>
                      <ThicknessAnimation Storyboard.TargetName="wrap" Storyboard.TargetProperty="Margin"
                                          To="0" Duration="0:0:0.24" EasingFunction="{StaticResource EaseOut}"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <ThicknessAnimation Storyboard.TargetName="wrap" Storyboard.TargetProperty="Margin"
                                          To="2" Duration="0:0:0.07"/>
                      <DoubleAnimation Storyboard.TargetName="pulse" Storyboard.TargetProperty="Opacity"
                                       To="0.24" Duration="0:0:0.05"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <ThicknessAnimation Storyboard.TargetName="wrap" Storyboard.TargetProperty="Margin"
                                          To="-1" Duration="0:0:0.16" EasingFunction="{StaticResource EaseOut}"/>
                      <DoubleAnimation Storyboard.TargetName="pulse" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.3"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Opacity" Value="0.26"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style x:Key="GhostWarn" TargetType="Button" BasedOn="{StaticResource Ghost}">
      <Setter Property="Foreground" Value="{StaticResource Warn}"/>
    </Style>
    <Style x:Key="GhostDim" TargetType="Button" BasedOn="{StaticResource Ghost}">
      <Setter Property="Foreground" Value="{StaticResource Muted}"/>
    </Style>

    <!-- ============ PRZYCISK GLOWNY ============ -->
    <Style x:Key="Primary" TargetType="Button">
      <Setter Property="Foreground" Value="#04121A"/>
      <Setter Property="Background" Value="{StaticResource AccentGrad}"/>
      <Setter Property="Height" Value="43"/>
      <Setter Property="FontSize" Value="13.5"/>
      <Setter Property="FontWeight" Value="Bold"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Grid x:Name="wrap">
              <Border x:Name="glow" CornerRadius="14" Margin="-2"
                      Background="{StaticResource AccentGrad}" Opacity="0">
                <Border.Effect>
                  <BlurEffect Radius="14"/>
                </Border.Effect>
              </Border>
              <Border x:Name="bg" CornerRadius="10" Background="{TemplateBinding Background}">
                <Grid>
                  <Border x:Name="hot" CornerRadius="10" Background="{StaticResource AccentGradHot}" Opacity="0"/>
                  <Border x:Name="sheen" CornerRadius="10" Background="{StaticResource Sheen}" Opacity="0.55"/>
                  <ContentPresenter x:Name="cp" HorizontalAlignment="Center" VerticalAlignment="Center"
                                    Margin="20,0"/>
                </Grid>
              </Border>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="glow" Storyboard.TargetProperty="Opacity"
                                       To="0.55" Duration="0:0:0.2"/>
                      <DoubleAnimation Storyboard.TargetName="hot" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.2"/>
                      <ThicknessAnimation Storyboard.TargetName="wrap" Storyboard.TargetProperty="Margin"
                                          To="-1.5" Duration="0:0:0.2" EasingFunction="{StaticResource EaseOut}"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="glow" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.3"/>
                      <DoubleAnimation Storyboard.TargetName="hot" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.3"/>
                      <ThicknessAnimation Storyboard.TargetName="wrap" Storyboard.TargetProperty="Margin"
                                          To="0" Duration="0:0:0.28" EasingFunction="{StaticResource EaseOut}"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <ThicknessAnimation Storyboard.TargetName="wrap" Storyboard.TargetProperty="Margin"
                                          To="2.5" Duration="0:0:0.07"/>
                      <DoubleAnimation Storyboard.TargetName="sheen" Storyboard.TargetProperty="Opacity"
                                       To="0.1" Duration="0:0:0.07"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <ThicknessAnimation Storyboard.TargetName="wrap" Storyboard.TargetProperty="Margin"
                                          To="-1.5" Duration="0:0:0.18" EasingFunction="{StaticResource EaseOut}"/>
                      <DoubleAnimation Storyboard.TargetName="sheen" Storyboard.TargetProperty="Opacity"
                                       To="0.55" Duration="0:0:0.18"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Opacity" Value="0.28"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <Style x:Key="Secondary" TargetType="Button">
      <Setter Property="Foreground" Value="{StaticResource Txt}"/>
      <Setter Property="Background" Value="#182233"/>
      <Setter Property="Height" Value="43"/>
      <Setter Property="FontSize" Value="13"/>
      <Setter Property="FontWeight" Value="SemiBold"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Grid x:Name="wrap">
              <Border x:Name="bg" CornerRadius="10" Background="{TemplateBinding Background}"
                      BorderBrush="#26364C" BorderThickness="1">
                <Grid>
                  <Border x:Name="hov" CornerRadius="10" Background="#22304A"
                          BorderBrush="#3C5A80" BorderThickness="1" Opacity="0"/>
                  <Border x:Name="pulse" CornerRadius="10" Background="{StaticResource Accent}"
                          Opacity="0" IsHitTestVisible="False"/>
                  <ContentPresenter x:Name="cp" HorizontalAlignment="Center" VerticalAlignment="Center"
                                    Margin="18,0"/>
                </Grid>
              </Border>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hov" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.16"/>
                      <ThicknessAnimation Storyboard.TargetName="wrap" Storyboard.TargetProperty="Margin"
                                          To="-1.5" Duration="0:0:0.2" EasingFunction="{StaticResource EaseOut}"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hov" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.26"/>
                      <ThicknessAnimation Storyboard.TargetName="wrap" Storyboard.TargetProperty="Margin"
                                          To="0" Duration="0:0:0.26" EasingFunction="{StaticResource EaseOut}"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <ThicknessAnimation Storyboard.TargetName="wrap" Storyboard.TargetProperty="Margin"
                                          To="2.5" Duration="0:0:0.07"/>
                      <DoubleAnimation Storyboard.TargetName="pulse" Storyboard.TargetProperty="Opacity"
                                       To="0.2" Duration="0:0:0.05"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <ThicknessAnimation Storyboard.TargetName="wrap" Storyboard.TargetProperty="Margin"
                                          To="-1.5" Duration="0:0:0.18" EasingFunction="{StaticResource EaseOut}"/>
                      <DoubleAnimation Storyboard.TargetName="pulse" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.3"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Opacity" Value="0.28"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <Style x:Key="Danger" TargetType="Button" BasedOn="{StaticResource Secondary}">
      <Setter Property="Background" Value="#6E1A2C"/>
      <Setter Property="Foreground" Value="#FFE4E9"/>
    </Style>

    <!-- ============ PASEK POSTEPU ============ -->
    <Style TargetType="ProgressBar">
      <Setter Property="Height" Value="6"/>
      <Setter Property="Foreground" Value="{StaticResource AccentGrad}"/>
      <Setter Property="Background" Value="#141D2C"/>
      <Setter Property="BorderThickness" Value="0"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ProgressBar">
            <Border CornerRadius="3" Background="{TemplateBinding Background}" ClipToBounds="True">
              <Border x:Name="PART_Track">
                <Border x:Name="PART_Indicator" HorizontalAlignment="Left"
                        Background="{TemplateBinding Foreground}" CornerRadius="3">
                  <Border x:Name="pulse" CornerRadius="3" Background="#FFFFFF" Opacity="0"/>
                </Border>
              </Border>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="Tag" Value="busy">
                <Trigger.EnterActions>
                  <BeginStoryboard x:Name="sbPulse">
                    <Storyboard RepeatBehavior="Forever" AutoReverse="True">
                      <DoubleAnimation Storyboard.TargetName="pulse" Storyboard.TargetProperty="Opacity"
                                       From="0" To="0.45" Duration="0:0:0.75"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <StopStoryboard BeginStoryboardName="sbPulse"/>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="pulse" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.2"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <Style x:Key="MiniIcon" TargetType="Button">
      <Setter Property="Foreground" Value="{StaticResource Dim}"/>
      <Setter Property="FontFamily" Value="Segoe MDL2 Assets"/>
      <Setter Property="FontSize" Value="9"/>
      <Setter Property="Width" Value="22"/>
      <Setter Property="Height" Value="22"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Grid>
              <Border x:Name="hov" CornerRadius="6" Background="#22304A" Opacity="0"/>
              <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Foreground" Value="{StaticResource Txt}"/>
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hov" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.14"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hov" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.22"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <Style x:Key="Search" TargetType="TextBox">
      <Setter Property="Foreground" Value="{StaticResource Txt}"/>
      <Setter Property="CaretBrush" Value="{StaticResource Accent}"/>
      <Setter Property="SelectionBrush" Value="{StaticResource Accent}"/>
      <Setter Property="FontSize" Value="12"/>
      <Setter Property="Height" Value="33"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="TextBox">
            <Grid>
              <Border x:Name="base" CornerRadius="10" Background="#0D1420"
                      BorderBrush="#26384F" BorderThickness="1"/>
              <Border x:Name="foc" CornerRadius="10" BorderBrush="{StaticResource Accent}"
                      BorderThickness="1" Opacity="0"/>
              <Grid Margin="11,0,32,0">
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="Auto"/>
                  <ColumnDefinition Width="*"/>
                </Grid.ColumnDefinitions>
                <TextBlock x:Name="lupa" Grid.Column="0" Text="&#xE721;" FontFamily="Segoe MDL2 Assets"
                           FontSize="11" Foreground="{StaticResource Dim}" VerticalAlignment="Center"/>
                <ScrollViewer x:Name="PART_ContentHost" Grid.Column="1" VerticalAlignment="Center"
                              Margin="8,0,0,0" Focusable="False" HorizontalScrollBarVisibility="Hidden"/>
              </Grid>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsKeyboardFocusWithin" Value="True">
                <Setter TargetName="lupa" Property="Foreground" Value="{StaticResource Accent}"/>
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="foc" Storyboard.TargetProperty="Opacity"
                                       To="1" Duration="0:0:0.16"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="foc" Storyboard.TargetProperty="Opacity"
                                       To="0" Duration="0:0:0.24"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <Style x:Key="H1" TargetType="TextBlock">
      <Setter Property="Foreground" Value="{StaticResource Txt}"/>
      <Setter Property="FontSize" Value="23"/>
      <Setter Property="FontWeight" Value="Bold"/>
    </Style>
    <Style x:Key="Label" TargetType="TextBlock">
      <Setter Property="Foreground" Value="{StaticResource Dim}"/>
      <Setter Property="FontSize" Value="10.5"/>
      <Setter Property="FontWeight" Value="Bold"/>
    </Style>
    <Style x:Key="CardHead" TargetType="TextBlock">
      <Setter Property="Foreground" Value="{StaticResource Txt}"/>
      <Setter Property="FontSize" Value="14.5"/>
      <Setter Property="FontWeight" Value="SemiBold"/>
    </Style>
    <Style x:Key="Body" TargetType="TextBlock">
      <Setter Property="Foreground" Value="{StaticResource Muted}"/>
      <Setter Property="FontSize" Value="11.5"/>
      <Setter Property="TextWrapping" Value="Wrap"/>
      <Setter Property="LineHeight" Value="18"/>
    </Style>
    <Style x:Key="Fine" TargetType="TextBlock">
      <Setter Property="Foreground" Value="{StaticResource Dim}"/>
      <Setter Property="FontSize" Value="11"/>
      <Setter Property="TextWrapping" Value="Wrap"/>
      <Setter Property="LineHeight" Value="16"/>
    </Style>
    <Style x:Key="Hair" TargetType="Border">
      <Setter Property="Height" Value="1"/>
      <Setter Property="Background" Value="#1A2536"/>
      <Setter Property="Margin" Value="0,14,0,13"/>
    </Style>
  </Window.Resources>

  <Border x:Name="Root" CornerRadius="16" Background="{StaticResource Bg}"
          BorderBrush="#1B2637" BorderThickness="1" RenderTransformOrigin="0.5,0.5">
    <Border.RenderTransform>
      <ScaleTransform x:Name="RootScale" ScaleX="0.985" ScaleY="0.985"/>
    </Border.RenderTransform>
    <Grid>
      <Grid.RowDefinitions>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="*"/>
      </Grid.RowDefinitions>

      <!-- ================= PASEK TYTULU ================= -->
      <Border x:Name="TitleBar" Grid.Row="0" Height="52" Background="{StaticResource HeaderGrad}"
              CornerRadius="16,16,0,0">
        <Grid>
          <Border Height="1" VerticalAlignment="Bottom" Background="#16202F"/>
          <StackPanel Orientation="Horizontal" VerticalAlignment="Center" Margin="20,0">
            <Grid Width="28" Height="28">
              <!-- pierscien "pukniecia" przy starcie - rozszerza sie i gasnie raz -->
              <Ellipse x:Name="LogoRing" Width="28" Height="28" Stroke="{StaticResource Accent}"
                       StrokeThickness="1.4" Opacity="0" RenderTransformOrigin="0.5,0.5">
                <Ellipse.RenderTransform>
                  <ScaleTransform x:Name="LogoRingScale" ScaleX="0.6" ScaleY="0.6"/>
                </Ellipse.RenderTransform>
              </Ellipse>
              <Border x:Name="LogoMark" Width="28" Height="28" CornerRadius="10" Background="{StaticResource AccentGrad}"
                      RenderTransformOrigin="0.5,0.5">
                <Border.RenderTransform>
                  <ScaleTransform x:Name="LogoMarkScale" ScaleX="0.3" ScaleY="0.3"/>
                </Border.RenderTransform>
                <TextBlock Text="&#xE945;" FontFamily="Segoe MDL2 Assets" FontSize="13"
                           Foreground="#04121A" HorizontalAlignment="Center" VerticalAlignment="Center"/>
              </Border>
            </Grid>
            <TextBlock Text="OptiLauncher" Foreground="{StaticResource Txt}" FontWeight="Bold"
                       FontSize="14.5" VerticalAlignment="Center" Margin="11,0,0,0"/>
            <Border Background="#141E2E" CornerRadius="6" Padding="7,1,7,2" Margin="9,1,0,0"
                    VerticalAlignment="Center">
              <TextBlock x:Name="VerLabel" Text="v7.4" Foreground="{StaticResource Muted}" FontSize="10.5"/>
            </Border>
            <Border Background="#0F2E24" CornerRadius="6" Padding="9,2" Margin="14,0,0,0" VerticalAlignment="Center">
              <StackPanel Orientation="Horizontal">
                <TextBlock Text="&#xE72E;" FontFamily="Segoe MDL2 Assets" FontSize="9.5"
                           Foreground="{StaticResource Good}" VerticalAlignment="Center" Margin="0,0,5,0"/>
                <TextBlock Text="Administrator" FontSize="11" Foreground="{StaticResource Good}"/>
              </StackPanel>
            </Border>
            <Border x:Name="AktPill" Background="#141E2E" CornerRadius="6" Padding="9,2" Margin="9,0,0,0"
                    VerticalAlignment="Center" Cursor="Hand" Visibility="Collapsed"
                    ToolTip="Kliknij, żeby sprawdzić aktualizacje">
              <StackPanel Orientation="Horizontal">
                <TextBlock x:Name="AktPillIcon" Text="&#xE895;" FontFamily="Segoe MDL2 Assets" FontSize="9.5"
                           Foreground="{StaticResource Muted}" VerticalAlignment="Center" Margin="0,0,5,0"/>
                <TextBlock x:Name="AktPillText" Text="" FontSize="11" Foreground="{StaticResource Muted}"/>
              </StackPanel>
            </Border>
          </StackPanel>
          <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
            <Button x:Name="BtnHardware" Content="&#xE770;" Style="{StaticResource Chrome}"
                    ToolTip="Sprzęt (CPU / GPU / RAM / dysk)"/>
            <Button x:Name="BtnConsole" Content="&#xE756;" Style="{StaticResource Chrome}"
                    ToolTip="Pokaż lub ukryj konsolę   (Ctrl+K)"/>
            <Button x:Name="BtnMin"   Content="&#xE921;" Style="{StaticResource Chrome}"/>
            <Button x:Name="BtnMax"   Content="&#xE922;" Style="{StaticResource Chrome}"
                    ToolTip="Powiększ na cały obszar roboczy   (dwuklik na pasku)"/>
            <Button x:Name="BtnClose" Content="&#xE8BB;" Style="{StaticResource ChromeClose}"/>
          </StackPanel>

          <!-- Dymek ze specyfikacja sprzetu - dawniej stala karta w lewym pasku,
               teraz chowa sie pod przyciskiem obok konsoli, zeby nie zajmowac
               miejsca na stale. PlacementTarget ustawiany w kodzie (BtnHardware
               musi juz istniec), nie w XAML. -->
          <Popup x:Name="HwPopup" StaysOpen="False" AllowsTransparency="True" Placement="Bottom"
                 PopupAnimation="Fade" HorizontalOffset="-206" VerticalOffset="10">
            <Border Background="#0B121D" CornerRadius="14" Padding="16,13" Width="250"
                    BorderBrush="{StaticResource Line}" BorderThickness="1">
              <Border.Effect>
                <DropShadowEffect Color="#000000" Opacity="0.45" BlurRadius="26" ShadowDepth="8"/>
              </Border.Effect>
              <StackPanel>
                <StackPanel Orientation="Horizontal" Margin="0,0,0,9">
                  <Border Width="10" Height="2" CornerRadius="1" Background="{StaticResource AccentGrad}"
                          VerticalAlignment="Center" Margin="0,0,7,0" Opacity="0.85"/>
                  <TextBlock Text="SPRZĘT" Style="{StaticResource Label}"/>
                </StackPanel>
                <TextBlock x:Name="HwCpu" Text="CPU: —" Foreground="{StaticResource Muted}" FontSize="11" TextWrapping="Wrap" Margin="0,0,0,6"/>
                <TextBlock x:Name="HwGpu" Text="GPU: —" Foreground="{StaticResource Muted}" FontSize="11" TextWrapping="Wrap" Margin="0,0,0,6"/>
                <TextBlock x:Name="HwRam" Text="RAM: —" Foreground="{StaticResource Muted}" FontSize="11" TextWrapping="Wrap" Margin="0,0,0,6"/>
                <TextBlock x:Name="HwDsk" Text="Dysk: —" Foreground="{StaticResource Muted}" FontSize="11" TextWrapping="Wrap" Margin="0,0,0,6"/>
                <TextBlock x:Name="HwOs"  Text="OS: —"  Foreground="{StaticResource Muted}" FontSize="11" TextWrapping="Wrap"/>
              </StackPanel>
            </Border>
          </Popup>
        </Grid>
      </Border>

      <!-- ================= KORPUS ================= -->
      <Grid Grid.Row="1">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="248"/>
          <ColumnDefinition Width="*"/>
          <ColumnDefinition Width="Auto"/>
        </Grid.ColumnDefinitions>

        <!-- MENU -->
        <Border Grid.Column="0" Background="{StaticResource Panel}" CornerRadius="0,0,0,16">
          <Grid>
            <Grid.RowDefinitions>
              <RowDefinition Height="*"/>
              <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>
            <Border Width="1" HorizontalAlignment="Right" Background="#151F2E" Grid.RowSpan="2"/>
            <ScrollViewer Grid.Row="0" VerticalScrollBarVisibility="Auto" Margin="0,14,0,0">
              <StackPanel>
                <StackPanel Orientation="Horizontal" Margin="29,0,0,5">
                  <Border Width="10" Height="2" CornerRadius="1" Background="{StaticResource AccentGrad}"
                          VerticalAlignment="Center" Margin="0,0,7,0" Opacity="0.85"/>
                  <TextBlock Text="PRZEGLĄD" Style="{StaticResource Label}"/>
                </StackPanel>
                <RadioButton x:Name="NavDash"    Content="Pulpit"          GroupName="nav" Tag="&#xE80F;" Style="{StaticResource Nav}" IsChecked="True"/>
                <RadioButton x:Name="NavGames"   Content="Moje gry"        GroupName="nav" Tag="&#xE7FC;" Style="{StaticResource Nav}"/>
                <RadioButton x:Name="NavStartup" Content="Autostart"       GroupName="nav" Tag="&#xE7E8;" Style="{StaticResource Nav}"/>
                <RadioButton x:Name="NavProc"    Content="Procesy w tle"   GroupName="nav" Tag="&#xE9D9;" Style="{StaticResource Nav}"/>
                <RadioButton x:Name="NavLink"    Content="Łącze"           GroupName="nav" Tag="&#xE839;" Style="{StaticResource Nav}"/>
                <RadioButton x:Name="NavDiag"    Content="Diagnostyka"     GroupName="nav" Tag="&#xE9F9;" Style="{StaticResource Nav}"/>
                <StackPanel Orientation="Horizontal" Margin="29,14,0,5">
                  <Border Width="10" Height="2" CornerRadius="1" Background="{StaticResource AccentGrad}"
                          VerticalAlignment="Center" Margin="0,0,7,0" Opacity="0.85"/>
                  <TextBlock Text="OPTYMALIZACJE" Style="{StaticResource Label}"/>
                </StackPanel>
                <RadioButton x:Name="NavGry"   Content="Gry i wydajność" GroupName="nav" Tag="&#xE7F4;" Style="{StaticResource Nav}"/>
                <RadioButton x:Name="NavSys"   Content="System"          GroupName="nav" Tag="&#xE770;" Style="{StaticResource Nav}"/>
                <RadioButton x:Name="NavSvc"   Content="Usługi"          GroupName="nav" Tag="&#xE9F5;" Style="{StaticResource Nav}"/>
                <RadioButton x:Name="NavApps"  Content="Aplikacje"       GroupName="nav" Tag="&#xECAA;" Style="{StaticResource Nav}"/>
                <RadioButton x:Name="NavClean" Content="Czyszczenie"     GroupName="nav" Tag="&#xE74D;" Style="{StaticResource Nav}"/>
                <RadioButton x:Name="NavNet"   Content="Sieć i naprawa"  GroupName="nav" Tag="&#xE968;" Style="{StaticResource Nav}"/>
                <RadioButton x:Name="NavTools" Content="Narzędzia"       GroupName="nav" Tag="&#xE90F;" Style="{StaticResource Nav}"/>
                <StackPanel Orientation="Horizontal" Margin="29,14,0,5">
                  <Border Width="10" Height="2" CornerRadius="1" Background="{StaticResource AccentGrad}"
                          VerticalAlignment="Center" Margin="0,0,7,0" Opacity="0.85"/>
                  <TextBlock Text="PROGRAM" Style="{StaticResource Label}"/>
                </StackPanel>
                <RadioButton x:Name="NavSkin"  Content="Wygląd"           GroupName="nav" Tag="&#xE790;" Style="{StaticResource Nav}"/>
              </StackPanel>
            </ScrollViewer>

            <StackPanel Grid.Row="1" Margin="16,14,16,16">
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="*"/>
                </Grid.ColumnDefinitions>
                <Button x:Name="BtnRestore" Grid.Column="0" Style="{StaticResource Secondary}"
                        Height="52" Margin="0,0,4,0" ToolTip="Tworzy punkt przywracania systemu Windows">
                  <StackPanel>
                    <TextBlock Text="&#xE777;" FontFamily="Segoe MDL2 Assets" FontSize="14"
                               HorizontalAlignment="Center" Margin="0,0,0,3"/>
                    <TextBlock Text="Punkt przywracania" FontSize="10" TextWrapping="Wrap"
                               TextAlignment="Center" LineHeight="12"/>
                  </StackPanel>
                </Button>
                <Button x:Name="BtnRevertAll" Grid.Column="1" Style="{StaticResource Danger}"
                        Height="52" Margin="4,0,0,0" ToolTip="Cofa wszystkie zmiany zapisane w backup.json">
                  <StackPanel>
                    <TextBlock Text="&#xE7A7;" FontFamily="Segoe MDL2 Assets" FontSize="14"
                               HorizontalAlignment="Center" Margin="0,0,0,3"/>
                    <TextBlock Text="Przywróć wszystko" FontSize="10" TextWrapping="Wrap"
                               TextAlignment="Center" LineHeight="12"/>
                  </StackPanel>
                </Button>
              </Grid>
            </StackPanel>
          </Grid>
        </Border>

        <!-- TRESC -->
        <Grid Grid.Column="1" Margin="26,20,20,0">
          <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
          </Grid.RowDefinitions>

          <!-- PASEK O DOSTEPNEJ AKTUALIZACJI -->
          <!-- Widoczny na kazdej zakladce i zostaje do skutku. Okno
               z lista zmian pokazuje sie raz i mozna je zamknac przez
               nieuwage; pigulka w pasku tytulu jest maleńka. -->
          <Border x:Name="AktBanner" Grid.Row="1" Visibility="Collapsed"
                  Background="#1F2410" BorderBrush="#4A3A12" BorderThickness="1"
                  CornerRadius="12" Padding="16,11,12,12" Margin="0,0,0,14">
            <Grid>
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="Auto"/>
              </Grid.ColumnDefinitions>

              <TextBlock Grid.Column="0" Text="&#xE896;" FontFamily="Segoe MDL2 Assets"
                         FontSize="15" Foreground="#FBBF24"
                         VerticalAlignment="Center" Margin="2,0,13,0"/>

              <StackPanel Grid.Column="1" VerticalAlignment="Center">
                <TextBlock x:Name="AktBannerTytul" Text="" FontSize="13.5" FontWeight="SemiBold"
                           Foreground="#FBBF24"/>
                <TextBlock x:Name="AktBannerOpis" Text="" FontSize="11.5" TextWrapping="Wrap"
                           Foreground="{StaticResource Dim}" Margin="0,3,12,0"/>
              </StackPanel>

              <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center">
                <Button x:Name="AktBannerPokaz"  Content="Zobacz zmiany" Style="{StaticResource Ghost}"
                        Margin="0,0,8,0"/>
                <Button x:Name="AktBannerUkryj"  Content="&#xE711;" Style="{StaticResource MiniIcon}"
                        ToolTip="Ukryj pasek do następnego uruchomienia"/>
              </StackPanel>
            </Grid>
          </Border>

          <Grid Grid.Row="0" Margin="0,0,0,16">
            <StackPanel x:Name="PageHead">
              <TextBlock x:Name="PageTitle" Text="Pulpit" Style="{StaticResource H1}"/>
              <TextBlock x:Name="PageDesc" Text="" Foreground="{StaticResource Muted}" FontSize="12.5" Margin="0,4,0,0"/>
            </StackPanel>
            <StackPanel x:Name="HeadTools" Orientation="Horizontal" HorizontalAlignment="Right" VerticalAlignment="Center">
              <Grid Width="212" Margin="0,0,8,0">
                <TextBox x:Name="SearchBox" Style="{StaticResource Search}"/>
                <TextBlock x:Name="SearchPlace" Text="Szukaj zadania   (Ctrl+F)" Foreground="{StaticResource Dim}"
                           FontSize="12" VerticalAlignment="Center" Margin="31,0,0,0" IsHitTestVisible="False"/>
                <Button x:Name="SearchClear" Content="&#xE711;" Style="{StaticResource MiniIcon}"
                        HorizontalAlignment="Right" Margin="0,0,6,0" Visibility="Collapsed"
                        ToolTip="Wyczyść filtr   (Esc)"/>
              </Grid>
              <Button x:Name="BtnRefresh" Content="Odśwież stan" Style="{StaticResource Ghost}"/>
              <Border Width="1" Background="{StaticResource Line}" Opacity="0.9" Margin="10,6,10,6"/>
              <Button x:Name="BtnSelRec"  Content="Zaznacz zalecane" Style="{StaticResource Ghost}" Margin="0,0,8,0"/>
              <Button x:Name="BtnSelNone" Content="Odznacz"          Style="{StaticResource GhostDim}"/>
            </StackPanel>
            <!-- cienka linia oddzielajaca naglowek zakladki od jej tresci -->
            <Border Height="1" VerticalAlignment="Bottom" Background="{StaticResource Line}" Opacity="0.8"/>
          </Grid>

          <ScrollViewer Grid.Row="2" VerticalScrollBarVisibility="Auto" Padding="0,0,12,0">
            <Grid>

              <!-- ============ PULPIT ============ -->
              <StackPanel x:Name="PanelDash">
                <Grid Margin="0,0,0,12">
                  <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="*"/>
                  </Grid.ColumnDefinitions>
                  <Border Grid.Column="0" Style="{StaticResource PlainCard}" Margin="0,0,6,0">
                    <StackPanel>
                      <TextBlock Text="PROCESOR" Style="{StaticResource Label}" HorizontalAlignment="Center"/>
                      <Grid Height="132" Margin="0,8,0,0">
                        <Border Width="130" Height="130" CornerRadius="65" Background="{StaticResource Aura}"/>
                        <Ellipse Width="112" Height="112" Stroke="#141D2C" StrokeThickness="9"/>
                        <Path x:Name="RingCpu" Width="112" Height="112" Stretch="None" HorizontalAlignment="Center" VerticalAlignment="Center" Stroke="{StaticResource Accent}" StrokeThickness="9" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                        <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
                          <TextBlock x:Name="TxtCpu" Text="—" Foreground="{StaticResource Txt}" FontSize="27" FontWeight="Bold" HorizontalAlignment="Center"/>
                          <TextBlock Text="obciążenie" Foreground="{StaticResource Dim}" FontSize="10.5" HorizontalAlignment="Center"/>
                        </StackPanel>
                      </Grid>
                    </StackPanel>
                  </Border>
                  <Border Grid.Column="1" Style="{StaticResource PlainCard}" Margin="6,0,6,0">
                    <StackPanel>
                      <TextBlock Text="PAMIĘĆ RAM" Style="{StaticResource Label}" HorizontalAlignment="Center"/>
                      <Grid Height="132" Margin="0,8,0,0">
                        <Border Width="130" Height="130" CornerRadius="65" Background="{StaticResource Aura}"/>
                        <Ellipse Width="112" Height="112" Stroke="#141D2C" StrokeThickness="9"/>
                        <Path x:Name="RingRam" Width="112" Height="112" Stretch="None" HorizontalAlignment="Center" VerticalAlignment="Center" Stroke="{StaticResource Accent}" StrokeThickness="9" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                        <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
                          <TextBlock x:Name="TxtRam" Text="—" Foreground="{StaticResource Txt}" FontSize="27" FontWeight="Bold" HorizontalAlignment="Center"/>
                          <TextBlock x:Name="TxtRamSub" Text="zajęte" Foreground="{StaticResource Dim}" FontSize="10.5" HorizontalAlignment="Center"/>
                        </StackPanel>
                      </Grid>
                    </StackPanel>
                  </Border>
                  <Border Grid.Column="2" Style="{StaticResource PlainCard}" Margin="6,0,0,0">
                    <StackPanel>
                      <TextBlock Text="DYSK SYSTEMOWY" Style="{StaticResource Label}" HorizontalAlignment="Center"/>
                      <Grid Height="132" Margin="0,8,0,0">
                        <Border Width="130" Height="130" CornerRadius="65" Background="{StaticResource Aura}"/>
                        <Ellipse Width="112" Height="112" Stroke="#141D2C" StrokeThickness="9"/>
                        <Path x:Name="RingDsk" Width="112" Height="112" Stretch="None" HorizontalAlignment="Center" VerticalAlignment="Center" Stroke="{StaticResource Accent}" StrokeThickness="9" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                        <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
                          <TextBlock x:Name="TxtDsk" Text="—" Foreground="{StaticResource Txt}" FontSize="27" FontWeight="Bold" HorizontalAlignment="Center"/>
                          <TextBlock x:Name="TxtDskSub" Text="zajęte" Foreground="{StaticResource Dim}" FontSize="10.5" HorizontalAlignment="Center"/>
                        </StackPanel>
                      </Grid>
                    </StackPanel>
                  </Border>
                </Grid>

                <Border Style="{StaticResource PlainCard}" Margin="0,0,0,12">
                  <StackPanel>
                    <Grid>
                      <StackPanel Orientation="Horizontal" HorizontalAlignment="Left">
                        <Border Width="10" Height="2" CornerRadius="1" Background="{StaticResource AccentGrad}"
                                VerticalAlignment="Center" Margin="0,0,7,0" Opacity="0.85"/>
                        <TextBlock Text="OBCIĄŻENIE W CZASIE" Style="{StaticResource Label}"/>
                      </StackPanel>
                      <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" VerticalAlignment="Center">
                        <Border Width="10" Height="3" CornerRadius="2" Background="{StaticResource Accent}"
                                VerticalAlignment="Center" Margin="0,0,6,0"/>
                        <TextBlock Text="procesor" Foreground="{StaticResource Muted}" FontSize="10.5" Margin="0,0,16,0"/>
                        <Border Width="10" Height="3" CornerRadius="2" Background="{StaticResource Violet}"
                                VerticalAlignment="Center" Margin="0,0,6,0"/>
                        <TextBlock Text="pamięć" Foreground="{StaticResource Muted}" FontSize="10.5"/>
                      </StackPanel>
                    </Grid>
                    <Grid x:Name="SparkHost" Height="78" Margin="0,10,0,0" ClipToBounds="True">
                      <Border Height="1" VerticalAlignment="Center" Background="#16202F"/>
                      <Border Height="1" VerticalAlignment="Top" Background="#131C2A"/>
                      <Polyline x:Name="SparkRam" Stroke="{StaticResource Violet}" StrokeThickness="1.5"
                                StrokeLineJoin="Round" Opacity="0.8"/>
                      <Polyline x:Name="SparkCpu" Stroke="{StaticResource Accent}" StrokeThickness="1.8"
                                StrokeLineJoin="Round"/>
                      <TextBlock x:Name="SparkPusto" Text="Zbieram pomiary..." Foreground="{StaticResource Dim}"
                                 FontSize="11.5" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Grid>
                    <Grid Margin="0,6,0,0">
                      <TextBlock Text="100%" Foreground="{StaticResource Dim}" FontSize="10" HorizontalAlignment="Left"
                                 VerticalAlignment="Top" Margin="0,-104,0,0"/>
                      <TextBlock x:Name="SparkOkno" Text="ostatnie 2 minuty" Foreground="{StaticResource Dim}" FontSize="10"/>
                      <TextBlock Text="teraz" Foreground="{StaticResource Dim}" FontSize="10" HorizontalAlignment="Right"/>
                    </Grid>
                  </StackPanel>
                </Border>

                <Border Style="{StaticResource PlainCard}" Margin="0,0,0,12">
                  <StackPanel>
                    <StackPanel Orientation="Horizontal" Margin="0,0,0,9">
                      <Border Width="10" Height="2" CornerRadius="1" Background="{StaticResource AccentGrad}"
                              VerticalAlignment="Center" Margin="0,0,7,0" Opacity="0.85"/>
                      <TextBlock Text="STAN OPTYMALIZACJI" Style="{StaticResource Label}"/>
                    </StackPanel>
                    <TextBlock x:Name="DashScore" Text="—" Foreground="{StaticResource Txt}" FontSize="19" FontWeight="Bold"/>
                    <ProgressBar x:Name="DashBar" Minimum="0" Maximum="100" Value="0" Margin="0,11,0,0"/>
                    <TextBlock x:Name="DashHint" Text="" Foreground="{StaticResource Muted}" FontSize="11.5" Margin="0,9,0,0" TextWrapping="Wrap"/>
                  </StackPanel>
                </Border>

                <!-- CZAS URUCHAMIANIA -->
                <!-- Dane z dziennika Diagnostics-Performance: Windows sam
                     mierzy kazdy rozruch i zapisuje, ktora aplikacja go
                     opoznila. Nikt tego uzytkownikowi nie pokazuje. -->
                <Border Style="{StaticResource PlainCard}" Margin="0,0,0,12">
                  <StackPanel>
                    <StackPanel Orientation="Horizontal" Margin="0,0,0,9">
                      <Border Width="10" Height="2" CornerRadius="1" Background="{StaticResource AccentGrad}"
                              VerticalAlignment="Center" Margin="0,0,7,0" Opacity="0.85"/>
                      <TextBlock Text="CZAS URUCHAMIANIA" Style="{StaticResource Label}"/>
                    </StackPanel>
                    <TextBlock x:Name="BootTime" Text="—" Foreground="{StaticResource Txt}" FontSize="19" FontWeight="Bold"/>
                    <TextBlock x:Name="BootHint" Text="Odczytuję pomiary Windows..." Foreground="{StaticResource Muted}"
                               FontSize="11.5" Margin="0,6,0,0" TextWrapping="Wrap"/>
                    <StackPanel x:Name="BootHost" Margin="0,11,0,0"/>
                  </StackPanel>
                </Border>

                <StackPanel Orientation="Horizontal" Margin="2,4,0,8">
                  <Border Width="10" Height="2" CornerRadius="1" Background="{StaticResource AccentGrad}"
                          VerticalAlignment="Center" Margin="0,0,7,0" Opacity="0.85"/>
                  <TextBlock Text="SZYBKIE AKCJE" Style="{StaticResource Label}"/>
                </StackPanel>
                <Grid Margin="0,0,0,12">
                  <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="*"/>
                  </Grid.ColumnDefinitions>
                  <Button x:Name="BtnDashFull" Grid.Column="0" Style="{StaticResource Primary}" Height="62" Margin="0,0,6,0">
                    <StackPanel Orientation="Horizontal">
                      <TextBlock Text="&#xE945;" FontFamily="Segoe MDL2 Assets" FontSize="17" VerticalAlignment="Center" Margin="0,0,10,0"/>
                      <StackPanel VerticalAlignment="Center">
                        <TextBlock Text="Pełna optymalizacja" FontSize="13.5" FontWeight="Bold"/>
                        <TextBlock Text="wszystko, co zalecane" FontSize="10.5" Opacity="0.7" Margin="0,1,0,0"/>
                      </StackPanel>
                    </StackPanel>
                  </Button>
                  <Button x:Name="BtnDashGames" Grid.Column="1" Style="{StaticResource Secondary}" Height="62" Margin="6,0,6,0">
                    <StackPanel Orientation="Horizontal">
                      <TextBlock Text="&#xE7FC;" FontFamily="Segoe MDL2 Assets" FontSize="17" VerticalAlignment="Center" Margin="0,0,10,0" Foreground="#22D3EE"/>
                      <StackPanel VerticalAlignment="Center">
                        <TextBlock Text="Moje gry" FontSize="13.5" FontWeight="SemiBold"/>
                        <TextBlock Text="ustawienia per gra" FontSize="10.5" Foreground="{StaticResource Muted}" Margin="0,1,0,0"/>
                      </StackPanel>
                    </StackPanel>
                  </Button>
                  <Button x:Name="BtnDashDiag" Grid.Column="2" Style="{StaticResource Secondary}" Height="62" Margin="6,0,0,0">
                    <StackPanel Orientation="Horizontal">
                      <TextBlock Text="&#xE9D9;" FontFamily="Segoe MDL2 Assets" FontSize="17" VerticalAlignment="Center" Margin="0,0,10,0" Foreground="#818CF8"/>
                      <StackPanel VerticalAlignment="Center">
                        <TextBlock Text="Skanuj system" FontSize="13.5" FontWeight="SemiBold"/>
                        <TextBlock Text="pełna diagnostyka" FontSize="10.5" Foreground="{StaticResource Muted}" Margin="0,1,0,0"/>
                      </StackPanel>
                    </StackPanel>
                  </Button>
                </Grid>

                <Border Style="{StaticResource PlainCard}">
                  <StackPanel>
                    <StackPanel Orientation="Horizontal" Margin="0,0,0,10">
                      <Border Width="10" Height="2" CornerRadius="1" Background="{StaticResource AccentGrad}"
                              VerticalAlignment="Center" Margin="0,0,7,0" Opacity="0.85"/>
                      <TextBlock Text="OSTATNIE DZIAŁANIA" Style="{StaticResource Label}"/>
                    </StackPanel>
                    <TextBlock x:Name="DashRecent" Text="Brak zapisanych zmian." Foreground="{StaticResource Muted}"
                               FontSize="12" TextWrapping="Wrap" LineHeight="20"/>
                  </StackPanel>
                </Border>
              </StackPanel>

              <!-- ============ MOJE GRY ============ -->
              <StackPanel x:Name="PanelGames" Visibility="Collapsed">
                <Border Style="{StaticResource PlainCard}" Margin="0,0,0,14">
                  <StackPanel>
                    <TextBlock Text="Optymalizacja pojedynczej gry" Style="{StaticResource CardHead}"/>
                    <TextBlock Style="{StaticResource Body}" Margin="0,6,0,0"
                               Text="Dodaj plik .exe gry, a program ustawi dla niej: wysoką wydajność GPU, wyłączone optymalizacje pełnoekranowe, wysoki priorytet procesora i we/wy oraz brak ograniczania mocy. Każdą grę da się cofnąć osobno."/>
                    <TextBlock x:Name="GameInfo" Text="" Foreground="{StaticResource Accent}" FontSize="12" Margin="0,10,0,0" TextWrapping="Wrap"/>
                    <Border Style="{StaticResource Hair}"/>
                    <WrapPanel>
                      <Button x:Name="BtnGameAdd"    Content="Dodaj grę"              Style="{StaticResource Primary}"   Height="38" Margin="0,0,8,8"/>
                      <Button x:Name="BtnGameDetect" Content="Wykryj gry"             Style="{StaticResource Secondary}" Height="38" Margin="0,0,8,8"/>
                      <Button x:Name="BtnGameAll"    Content="Zoptymalizuj wszystkie" Style="{StaticResource Secondary}" Height="38" Margin="0,0,8,8"/>
                      <Button x:Name="BtnGameFilter" Content="Tylko zoptymalizowane"  Style="{StaticResource Ghost}"     Height="38" Margin="0,0,8,8"/>
                      <Button x:Name="BtnGameClean"  Content="Usuń nieistniejące"     Style="{StaticResource GhostDim}"  Height="38" Margin="0,0,0,8"/>
                    </WrapPanel>
                  </StackPanel>
                </Border>
                <StackPanel x:Name="GameHost"/>
                <TextBlock x:Name="GameEmpty" Text="Nie dodano jeszcze żadnej gry. Kliknij Dodaj grę i wskaż plik .exe, albo Wykryj gry, żeby przeszukać biblioteki Steam i Epic."
                           Foreground="{StaticResource Dim}" FontSize="12.5" TextWrapping="Wrap" Margin="4,10,40,0" LineHeight="20"/>
              </StackPanel>

              <!-- ============ AUTOSTART ============ -->
              <StackPanel x:Name="PanelStartup" Visibility="Collapsed">
                <Border Style="{StaticResource PlainCard}" Margin="0,0,0,14">
                  <StackPanel>
                    <TextBlock Text="Programy uruchamiane przy starcie" Style="{StaticResource CardHead}"/>
                    <TextBlock Style="{StaticResource Body}" Margin="0,6,0,0"
                               Text="Każda pozycja wydłuża rozruch i zajmuje pamięć przez cały czas pracy komputera – zwykle jest to większy zysk niż wszystkie ustawienia rejestru razem wzięte. Wyłączenie działa dokładnie tak jak w Menedżerze zadań: wpis zostaje na swoim miejscu, zmienia się wyłącznie jego stan, więc w każdej chwili można go włączyć z powrotem."/>
                    <TextBlock x:Name="StartupInfo" Text="" Foreground="{StaticResource Accent}" FontSize="12" Margin="0,10,0,0"/>
                    <Border Style="{StaticResource Hair}"/>
                    <WrapPanel>
                      <Button x:Name="BtnStartupRefresh" Content="Odśwież listę" Style="{StaticResource Secondary}" Height="38"/>
                    </WrapPanel>
                  </StackPanel>
                </Border>
                <StackPanel x:Name="StartupHost"/>
                <TextBlock x:Name="StartupEmpty" Text="Nie znaleziono żadnych programów w autostarcie. To dobra wiadomość."
                           Foreground="{StaticResource Dim}" FontSize="12.5" TextWrapping="Wrap" Margin="4,10,40,0" LineHeight="20"/>
              </StackPanel>

              <StackPanel x:Name="PanelGry" Visibility="Collapsed"/>

              <!-- ============ PROCESY W TLE ============ -->
              <StackPanel x:Name="PanelProc" Visibility="Collapsed">
                <Border Style="{StaticResource PlainCard}" Margin="0,0,0,14">
                  <StackPanel>
                    <TextBlock Text="Co zajmuje pamięć teraz" Style="{StaticResource CardHead}"/>
                    <TextBlock Style="{StaticResource Body}" Margin="0,6,0,0"
                               Text="Procesy zgrupowane po nazwie i posortowane od najbardziej pamięciożernych. Zamknięcie nie zmienia niczego w systemie – przy następnym uruchomieniu program wróci. Jeśli chcesz, żeby nie wracał, wyłącz go w zakładce Autostart."/>
                    <TextBlock Style="{StaticResource Fine}" Margin="0,8,0,0"
                               Text="Procesy systemowe są zablokowane – ich zamknięcie kończy się zawieszeniem pulpitu lub restartem Windows."/>
                    <TextBlock x:Name="ProcInfo" Text="" Foreground="{StaticResource Accent}" FontSize="12" Margin="0,10,0,0"/>
                    <Border Style="{StaticResource Hair}"/>
                    <WrapPanel>
                      <Button x:Name="BtnProcRefresh" Content="Odśwież" Style="{StaticResource Secondary}" Height="38"/>
                    </WrapPanel>
                  </StackPanel>
                </Border>
                <StackPanel x:Name="ProcHost"/>
              </StackPanel>

              <!-- ============ LACZE ============ -->
              <StackPanel x:Name="PanelLink" Visibility="Collapsed">
                <Border Style="{StaticResource PlainCard}" Margin="0,0,0,14">
                  <StackPanel>
                    <TextBlock Text="Pomiar łącza i ustawienia karty" Style="{StaticResource CardHead}"/>
                    <TextBlock Style="{StaticResource Body}" Margin="0,6,0,0"
                               Text="Program mierzy opóźnienie, jitter i straty osobno do routera i osobno do internetu — bo to rozstrzyga, gdzie naprawdę jest problem. Jeśli ping do routera skacze, winne jest Wi-Fi albo kabel i żadne ustawienie systemu tego nie naprawi."/>
                    <TextBlock Style="{StaticResource Fine}" Margin="0,8,0,0"
                               Text="Świadomie nie ma tu rezerwacji pasma QoS, TcpAckFrequency ani wyłączania algorytmu Nagle'a. To albo mity, albo tweaki, które na dzisiejszych łączach szkodzą częściej, niż pomagają."/>
                    <TextBlock x:Name="LinkInfo" Text="" Foreground="{StaticResource Accent}" FontSize="12" Margin="0,10,0,0"/>
                    <Border Style="{StaticResource Hair}"/>
                    <WrapPanel>
                      <Button x:Name="BtnLinkScan" Content="Zmierz łącze" Style="{StaticResource Primary}" Height="38"/>
                    </WrapPanel>
                  </StackPanel>
                </Border>
                <StackPanel x:Name="LinkHost"/>
                <StackPanel x:Name="LinkPropHost"/>
              </StackPanel>

              <!-- ============ APLIKACJE ============ -->
              <StackPanel x:Name="PanelApps" Visibility="Collapsed">
                <Border Style="{StaticResource PlainCard}" Margin="0,0,0,14">
                  <StackPanel>
                    <TextBlock Text="Aplikacje wbudowane w Windows" Style="{StaticResource CardHead}"/>
                    <TextBlock Style="{StaticResource Body}" Margin="0,6,0,0"
                               Text="Program pokazuje wyłącznie aplikacje z własnej, ręcznie sprawdzonej listy – niczego innego nie ruszy. To celowo odwrotność typowych debloaterów, które kasują wszystko poza czarną listą i przy okazji wywalają ludziom Sklep albo komponenty systemowe."/>
                    <TextBlock Style="{StaticResource Fine}" Margin="0,8,0,0"
                               Text="Każdą z nich można zainstalować z powrotem ze Sklepu Microsoft. Usunięcie dotyczy bieżącego użytkownika."/>
                    <TextBlock x:Name="AppsInfo" Text="" Foreground="{StaticResource Accent}" FontSize="12" Margin="0,10,0,0"/>
                    <Border Style="{StaticResource Hair}"/>
                    <WrapPanel>
                      <Button x:Name="BtnAppsRefresh" Content="Odśwież listę" Style="{StaticResource Secondary}" Height="38"/>
                    </WrapPanel>
                  </StackPanel>
                </Border>
                <StackPanel x:Name="AppsHost"/>
                <TextBlock x:Name="AppsEmpty" Text="Nie znaleziono żadnej z aplikacji z listy. Ten system jest już czysty."
                           Foreground="{StaticResource Dim}" FontSize="12.5" TextWrapping="Wrap" Margin="4,10,40,0" LineHeight="20"/>
              </StackPanel>

              <StackPanel x:Name="PanelSkin" Visibility="Collapsed">
                <Border Style="{StaticResource PlainCard}" Margin="0,0,0,14">
                  <StackPanel>
                    <TextBlock Text="Kolorystyka interfejsu" Style="{StaticResource CardHead}"/>
                    <TextBlock Style="{StaticResource Body}" Margin="0,6,0,0"
                               Text="Wybór dotyczy wyłącznie wyglądu programu — żadne ustawienie systemu nie jest zmieniane. Zielony, żółty i czerwony zostają w każdym motywie takie same, bo niosą znaczenie: zastosowane, ostrożnie, nie weszło."/>
                    <TextBlock Style="{StaticResource Fine}" Margin="0,8,0,0"
                               Text="Zmiana wymaga ponownego uruchomienia programu — kolory są wtapiane w interfejs przy jego budowaniu. Program zrobi to sam, a niezapisane wyniki skanu przepadną."/>
                    <TextBlock x:Name="SkinInfo" Text="" Foreground="{StaticResource Accent}" FontSize="12" Margin="0,10,0,0"/>
                  </StackPanel>
                </Border>
                <Border Style="{StaticResource PlainCard}" Margin="0,0,0,14">
                  <Grid>
                    <Grid.ColumnDefinitions>
                      <ColumnDefinition Width="*"/>
                      <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>
                    <StackPanel Grid.Column="0" VerticalAlignment="Center" Margin="0,0,16,0">
                      <TextBlock Text="Gęstość widoku" Style="{StaticResource CardHead}"/>
                      <TextBlock Style="{StaticResource Body}" Margin="0,6,0,0"
                                 Text="Tryb zwarty ściąga marginesy i wysokości pozycji — na ekranie mieści się wtedy o kilka kart więcej. Rozmiary liter zostają bez zmian."/>
                      <TextBlock x:Name="SkinGestInfo" Text="" Foreground="{StaticResource Accent}" FontSize="12" Margin="0,9,0,0"/>
                    </StackPanel>
                    <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
                      <Button x:Name="BtnGestKomfort" Content="Komfortowy" Style="{StaticResource Ghost}" Width="118" Margin="0,0,8,0"/>
                      <Button x:Name="BtnGestZwarty"  Content="Zwarty"     Style="{StaticResource Ghost}" Width="104"/>
                    </StackPanel>
                  </Grid>
                </Border>

                <Border Style="{StaticResource PlainCard}" Margin="0,0,0,14">
                  <Grid>
                    <Grid.ColumnDefinitions>
                      <ColumnDefinition Width="*"/>
                      <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>
                    <StackPanel Grid.Column="0" VerticalAlignment="Center" Margin="0,0,16,0">
                      <TextBlock Text="Tło Mica" Style="{StaticResource CardHead}"/>
                      <TextBlock Style="{StaticResource Body}" Margin="0,6,0,0"
                                 Text="Okno przejmuje rozmyte tło pulpitu, tak jak Ustawienia Windows 11. Rysuje je menedżer okien, nie program."/>
                      <TextBlock Style="{StaticResource Fine}" Margin="0,8,0,0"
                                 Text="Wymaga Windows 11 (kompilacja 22000 lub nowsza). Na starszym systemie ustawienie zostanie pominięte, a okno wygląda jak dotąd. Przy włączonej Mice zaokrąglenie okna rysuje system, a nie program."/>
                      <TextBlock x:Name="SkinMicaInfo" Text="" Foreground="{StaticResource Accent}" FontSize="12" Margin="0,9,0,0"/>
                    </StackPanel>
                    <Button x:Name="BtnMica" Grid.Column="1" Content="Włącz" Style="{StaticResource Ghost}"
                            Width="118" VerticalAlignment="Center"/>
                  </Grid>
                </Border>

                <StackPanel Orientation="Horizontal" Margin="2,4,0,9">
                  <Border Width="10" Height="2" CornerRadius="1" Background="{StaticResource AccentGrad}"
                          VerticalAlignment="Center" Margin="0,0,7,0" Opacity="0.85"/>
                  <TextBlock Text="MOTYW KOLORYSTYCZNY" Style="{StaticResource Label}"/>
                </StackPanel>
                <StackPanel x:Name="SkinHost"/>
              </StackPanel>

              <StackPanel x:Name="PanelSvc"   Visibility="Collapsed"/>
              <StackPanel x:Name="PanelSys"   Visibility="Collapsed"/>
              <StackPanel x:Name="PanelClean" Visibility="Collapsed"/>
              <StackPanel x:Name="PanelNet"   Visibility="Collapsed"/>
              <StackPanel x:Name="PanelTools" Visibility="Collapsed"/>

              <!-- ============ DIAGNOSTYKA ============ -->
              <StackPanel x:Name="PanelDiag" Visibility="Collapsed">
                <Border Style="{StaticResource PlainCard}" Margin="0,0,0,14">
                  <StackPanel>
                    <TextBlock Text="Pomiar wydajności – przed i po" Style="{StaticResource CardHead}"/>
                    <TextBlock Style="{StaticResource Body}" Margin="0,6,0,0"
                               Text="Zapisz punkt odniesienia ZANIM cokolwiek zmienisz. Program zanotuje czas rozruchu z Dziennika zdarzeń, liczbę procesów i usług, zużycie pamięci oraz liczbę pozycji w autostarcie. Po zmianach i ponownym uruchomieniu komputera kliknij Zmierz teraz, a zobaczysz różnicę w liczbach zamiast wierzyć na słowo."/>
                    <TextBlock Style="{StaticResource Fine}" Margin="0,8,0,0"
                               Text="Uwaga: czas rozruchu aktualizuje się dopiero po restarcie komputera, więc sam pomiar tuż po zmianach jeszcze go nie pokaże."/>
                    <TextBlock x:Name="BenchOut" Text="" Foreground="{StaticResource Txt}" FontSize="12.5"
                               TextWrapping="Wrap" Margin="0,12,0,0" LineHeight="21" FontFamily="Consolas"/>
                    <Border Style="{StaticResource Hair}"/>
                    <WrapPanel>
                      <Button x:Name="BtnDiagRun"    Content="Skanuj system"            Style="{StaticResource Primary}"   Height="38" Margin="0,0,8,8"/>
                      <Button x:Name="BtnBenchNow"   Content="Zmierz teraz"             Style="{StaticResource Primary}"   Height="38" Margin="0,0,8,8"/>
                      <Button x:Name="BtnBenchBase"  Content="Zapisz punkt odniesienia" Style="{StaticResource Secondary}" Height="38" Margin="0,0,8,8"/>
                      <Button x:Name="BtnDiagReport" Content="Zapisz raport HTML"       Style="{StaticResource Ghost}"     Height="38" Margin="0,0,0,8"/>
                    </WrapPanel>
                  </StackPanel>
                </Border>

                <StackPanel x:Name="DiagHost"/>
              </StackPanel>
            </Grid>
          </ScrollViewer>

          <Border x:Name="Toast" Grid.Row="1" VerticalAlignment="Bottom" HorizontalAlignment="Center"
                  CornerRadius="10" Background="#16202F" BorderBrush="#2F4C74" BorderThickness="1"
                  Padding="16,10" Margin="0,0,0,10" Opacity="0" IsHitTestVisible="False">
            <Border.Effect>
              <DropShadowEffect Color="#000000" Opacity="0.4" BlurRadius="20" ShadowDepth="6" Direction="270"/>
            </Border.Effect>
            <StackPanel Orientation="Horizontal">
              <Grid Width="22" Height="22" Margin="0,0,10,0">
                <!-- pierscien "pukniecia" - dogrywa sie przy kazdym udanym zakonczeniu -->
                <Ellipse x:Name="ToastRing" Width="22" Height="22" Stroke="{StaticResource Good}"
                         StrokeThickness="1.3" Opacity="0" RenderTransformOrigin="0.5,0.5">
                  <Ellipse.RenderTransform>
                    <ScaleTransform ScaleX="0.6" ScaleY="0.6"/>
                  </Ellipse.RenderTransform>
                </Ellipse>
                <TextBlock x:Name="ToastIcon" Text="&#xE930;" FontFamily="Segoe MDL2 Assets" FontSize="13"
                           Foreground="{StaticResource Good}" HorizontalAlignment="Center" VerticalAlignment="Center"
                           RenderTransformOrigin="0.5,0.5">
                  <TextBlock.RenderTransform>
                    <ScaleTransform ScaleX="1" ScaleY="1"/>
                  </TextBlock.RenderTransform>
                </TextBlock>
              </Grid>
              <TextBlock x:Name="ToastText" Text="" Foreground="{StaticResource Txt}" FontSize="12.5"
                         VerticalAlignment="Center"/>
            </StackPanel>
          </Border>

          <!-- PASEK AKCJI -->
          <Border x:Name="ActionBar" Grid.Row="3" Background="{StaticResource Panel}" CornerRadius="14" Padding="18,13" Margin="0,16,0,18"
                  BorderBrush="{StaticResource Line}" BorderThickness="1">
            <Border.Effect>
              <DropShadowEffect Color="#000000" Opacity="0.22" BlurRadius="14" ShadowDepth="2" Direction="270"/>
            </Border.Effect>
            <Grid>
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="Auto"/>
              </Grid.ColumnDefinitions>
              <StackPanel Grid.Column="0" VerticalAlignment="Center">
                <TextBlock x:Name="SelInfo" Text="Zaznaczono 0 zadań" Foreground="{StaticResource Muted}" FontSize="12"/>
                <TextBlock x:Name="RebootInfo" Text="" Foreground="{StaticResource Warn}" FontSize="11.5" Margin="0,3,0,0" TextWrapping="Wrap"/>
              </StackPanel>
              <StackPanel Grid.Column="1" Orientation="Horizontal">
                <Button x:Name="BtnRunSel" Content="Uruchom zaznaczone" Style="{StaticResource Primary}" Margin="0,0,8,0"/>
                <Button x:Name="BtnFull"   Content="Pełna optymalizacja" Style="{StaticResource Secondary}" Margin="0,0,14,0"/>
                <Border Width="1" Background="#1E2A3D" Margin="0,4,14,4"/>
                <Button x:Name="BtnReboot" Content="Restart" Style="{StaticResource Danger}" MinWidth="96"/>
              </StackPanel>
            </Grid>
          </Border>
        </Grid>

        <!-- KONSOLA -->
        <Border x:Name="ConsolePane" Grid.Column="2" Width="320" ClipToBounds="True"
                Background="{StaticResource Panel}" CornerRadius="0,0,16,0">
          <Grid Width="284" Margin="18,20,18,18" HorizontalAlignment="Right">
            <Grid.RowDefinitions>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="*"/>
              <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>
            <Grid Grid.Row="0" Margin="0,0,0,11">
              <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                <Border x:Name="BusyDot" Width="7" Height="7" CornerRadius="4" Background="{StaticResource Accent}"
                        Margin="0,0,8,0" Opacity="0.25" VerticalAlignment="Center"/>
                <TextBlock Text="KONSOLA" Style="{StaticResource Label}" VerticalAlignment="Center"/>
              </StackPanel>
              <Button x:Name="BtnOpenLog" Content="Otwórz log" Style="{StaticResource GhostDim}"
                      HorizontalAlignment="Right" Height="27" FontSize="11" MinWidth="0"/>
            </Grid>
            <StackPanel Grid.Row="1" Margin="0,0,0,11">
              <TextBlock x:Name="StatusText" Text="Gotowy." Foreground="{StaticResource Good}"
                         FontSize="12.5" TextWrapping="Wrap" Margin="0,0,0,9"/>
              <ProgressBar x:Name="Prog" Minimum="0" Maximum="100" Value="0"/>
            </StackPanel>
            <Border Grid.Row="2" Background="#050810" CornerRadius="14" BorderBrush="{StaticResource Line}" BorderThickness="1">
              <ScrollViewer x:Name="LogScroll" VerticalScrollBarVisibility="Auto" Padding="13,11">
                <TextBlock x:Name="LogText" Foreground="#93A7BD" FontFamily="Cascadia Mono, Consolas"
                           FontSize="11.5" TextWrapping="Wrap" LineHeight="18"/>
              </ScrollViewer>
            </Border>
            <TextBlock Grid.Row="3" Text="OptiLauncher by Jerremi" Foreground="#31404F"
                       FontSize="11" HorizontalAlignment="Center" Margin="0,13,0,0"/>
          </Grid>
        </Border>
      </Grid>

      <!-- ================= NAKLADKA: RESTART KOMPUTERA ================= -->
      <Grid x:Name="RestartOverlay" Grid.Row="0" Grid.RowSpan="2" Visibility="Collapsed" Opacity="0">
        <Border Background="#B3000000" CornerRadius="16"/>
        <Border Width="380" HorizontalAlignment="Center" VerticalAlignment="Center"
                Background="{StaticResource TileGrad}" BorderBrush="{StaticResource TileBorderGrad}"
                BorderThickness="1.2" CornerRadius="18" Padding="28,26">
          <Border.Effect>
            <DropShadowEffect Color="#000000" Opacity="0.5" BlurRadius="34" ShadowDepth="10" Direction="270"/>
          </Border.Effect>
          <StackPanel HorizontalAlignment="Center">
            <Border Width="54" Height="54" CornerRadius="27" Background="#3A1220" HorizontalAlignment="Center" Margin="0,0,0,15">
              <TextBlock Text="&#xE777;" FontFamily="Segoe MDL2 Assets" FontSize="23"
                         Foreground="{StaticResource Bad}" HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Border>
            <TextBlock Text="Restart komputera" Foreground="{StaticResource Txt}" FontSize="17.5"
                       FontWeight="Bold" HorizontalAlignment="Center"/>
            <TextBlock Text="Zapisz otwarte pliki - za chwilę komputer się wyłączy i uruchomi ponownie."
                       Foreground="{StaticResource Muted}" FontSize="12" TextWrapping="Wrap"
                       TextAlignment="Center" Margin="0,9,0,20"/>
            <TextBlock x:Name="RestartCountdown" Text="10" Foreground="{StaticResource Bad}"
                       FontSize="40" FontWeight="Bold" HorizontalAlignment="Center"/>
            <TextBlock Text="sekund do restartu" Foreground="{StaticResource Dim}" FontSize="11"
                       HorizontalAlignment="Center" Margin="0,2,0,22"/>
            <Grid>
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="*"/>
              </Grid.ColumnDefinitions>
              <Button x:Name="BtnRestartCancel" Grid.Column="0" Content="Anuluj" Style="{StaticResource Secondary}" Margin="0,0,5,0"/>
              <Button x:Name="BtnRestartNow" Grid.Column="1" Content="Restartuj teraz" Style="{StaticResource Danger}" Margin="5,0,0,0"/>
            </Grid>
          </StackPanel>
        </Border>
      </Grid>
    </Grid>

    <Border.Triggers>
      <EventTrigger RoutedEvent="FrameworkElement.Loaded">
        <BeginStoryboard>
          <Storyboard>
            <DoubleAnimation Storyboard.TargetName="RootScale" Storyboard.TargetProperty="ScaleX"
                             From="0.985" To="1" Duration="0:0:0.42" EasingFunction="{StaticResource EaseOut}"/>
            <DoubleAnimation Storyboard.TargetName="RootScale" Storyboard.TargetProperty="ScaleY"
                             From="0.985" To="1" Duration="0:0:0.42" EasingFunction="{StaticResource EaseOut}"/>
          </Storyboard>
        </BeginStoryboard>
      </EventTrigger>
    </Border.Triggers>
  </Border>
</Window>
'@

# Backdrop nie ma gdzie sie rysowac, dopoki okno jest warstwowe.
# Przy wlaczonej Mice zdejmujemy przezroczystosc i startowe wygaszenie.
if ($script:Mica) {
    $XamlText = $XamlText.Replace('AllowsTransparency="True"', 'AllowsTransparency="False"')
    $XamlText = $XamlText.Replace('WindowStartupLocation="CenterScreen" Opacity="0"',
                                  'WindowStartupLocation="CenterScreen" Opacity="1"')
}

[xml]$XAML = Przemaluj $XamlText

$Window = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $XAML))

$UI = @{}
