                 'DashScore','DashBar','DashHint','DashRecent',
                 'BtnDashFull','BtnDashGames','BtnDashDiag',
                 'PageTitle','PageDesc','BtnRefresh','BtnSelRec','BtnSelNone',
                 'SelInfo','RebootInfo','BtnRunSel','BtnFull','BtnReboot','BtnRestore','BtnRevertAll',
                 'StatusText','Prog','LogText','LogScroll','BtnOpenLog',
                 'HwCpu','HwGpu','HwRam','HwDsk','HwOs','BtnHardware','HwPopup',
                 'Root','PageHead','BtnConsole','ConsolePane','BusyDot',
                 'BtnMax','SearchBox','SearchPlace','SearchClear',
                 'SparkHost','SparkCpu','SparkRam','SparkPusto','SparkOkno',
                 'Toast','ToastText','ToastIcon','ToastRing',
                 'RestartOverlay','RestartCountdown','BtnRestartCancel','BtnRestartNow',
                 'NavSkin','PanelSkin','SkinHost','SkinInfo',
                 'BtnGestKomfort','BtnGestZwarty','SkinGestInfo','BtnMica','SkinMicaInfo')) {
    $UI[$n] = $Window.FindName($n)
}
$UI.VerLabel.Text = "v$AppVersion"

