# =====================================================================
#  REALNY ZYSK
#
#  Kazde zadanie dostaje uczciwa etykiete. Trzy poziomy:
#    mierzalny   - widac w liczbach (miejsce na dysku, czas rozruchu, pamiec)
#    sytuacyjny  - zalezy od sprzetu albo od tego, czy jest co naprawiac
#    kosmetyczny - zmienia odczucie albo wyglad, wydajnosci nie rusza
#
#  Program, ktory przy wszystkim pisze "krytyczne", to straszak.
#  Ten mowi wprost, kiedy cos nic nie da.
# =====================================================================
$Zysk = @{
    # --- gry ---
    'mmcss'     = @{ k='sytuacyjny';  t='Zmienia priorytety watkow gry. Na mocnym sprzecie roznica bywa niezauwazalna.' }
    'powerplan' = @{ k='sytuacyjny';  t='Realny zysk na laptopach i przy oszczedzaniu energii. Na desktopie zwykle niewielki, kosztem poboru pradu.' }
    'gamemode'  = @{ k='sytuacyjny';  t='Pomaga, gdy w tle cos chodzi. Na czystym systemie prawie nic.' }
    'gamedvr'   = @{ k='mierzalny';   t='Nagrywanie w tle realnie zjada procesor i karte graficzna. Wylaczenie widac w klatkach.' }
    'hags'      = @{ k='sytuacyjny';  t='Zalezy od sterownika i gry. Potrafi pomoc, potrafi tez lekko zaszkodzic - warto sprawdzic u siebie.' }
    'fso'       = @{ k='sytuacyjny';  t='Mniejsze opoznienie wejscia w niektorych grach. W innych bez zmian.' }
    'mouse'     = @{ k='sytuacyjny';  t='Nie zmienia liczby klatek. Zmienia precyzje celowania - dla jednych kluczowe, dla innych zadne.' }
    'visualfx'  = @{ k='kosmetyczny'; t='Widoczne na slabszym sprzecie. Na mocnym oszczedzasz ulamek procenta, tracac animacje.' }

    # --- system ---
    'sysmain'   = @{ k='sytuacyjny';  t='Przy SSD zysk marginalny. Przy HDD zadanie samo sie pominie, bo tam SysMain pomaga.' }
    'delivery'  = @{ k='mierzalny';   t='Windows przestaje rozsylac aktualizacje innym. Widac to na lączu i na zapisach dysku.' }
    'svchost'   = @{ k='kosmetyczny'; t='Lista procesow robi sie krotsza, ale realna oszczednosc pamieci jest niewielka. Utrudnia za to diagnostyke uslug.' }
    'trim'      = @{ k='mierzalny';   t='Utrzymuje predkosc zapisu SSD w dluzszym okresie. Jedno z niewielu ustawien, ktore po prostu powinno byc wlaczone.' }
    'optdrive'  = @{ k='sytuacyjny';  t='Na HDD defragmentacja daje duzo. Na SSD to tylko ReTrim - porzadek, nie przyspieszenie.' }
    'hibernate' = @{ k='mierzalny';   t='Zwalnia na dysku tyle, ile masz mniej wiecej pamieci RAM. Kosztem Szybkiego uruchamiania.' }
    'telemetry' = @{ k='kosmetyczny'; t='Mniej sugestii i reklam w systemie. Na wydajnosc wplywu praktycznie nie ma.' }
    'faststartup' = @{ k='sytuacyjny'; t='Nie przyspiesza gier. Pomaga, gdy po wybudzeniu/hibernacji cos sie sypie, albo masz dwa systemy na jednym dysku. Kosztem odrobiny dluzszego zimnego startu.' }
    'cpusched'    = @{ k='kosmetyczny'; t='Na Windows 10/11 Home/Pro to zwykle juz domyslne ustawienie - zadanie tylko upewnia sie, ze nic go wczesniej nie zmienilo.' }

    # --- uslugi ---
    'svc_diagtrack' = @{ k='kosmetyczny'; t='Mniej zapisow w tle i mniej ruchu w siec. Na plynnosc systemu wplyw znikomy.' }
    'svc_xbox'      = @{ k='sytuacyjny';  t='Cztery uslugi mniej w pamieci. Jesli korzystasz z Game Pass albo pada Xbox - zostaw wlaczone.' }
    'svc_remote'    = @{ k='kosmetyczny'; t='Wydajnosci nie zmienia. To zysk po stronie bezpieczenstwa - zamyka zdalny dostep do rejestru.' }
    'svc_fax'       = @{ k='kosmetyczny'; t='Jedna usluga mniej. Realny zysk bliski zeru, ale i strata zadna.' }
    'svc_maps'      = @{ k='kosmetyczny'; t='Mapy dalej dzialaja online. Oszczednosc symboliczna.' }
    'svc_wmp'       = @{ k='kosmetyczny'; t='Dotyczy tylko udostepniania multimediow w sieci lokalnej.' }
    'svc_retail'    = @{ k='kosmetyczny'; t='Usluga i tak nigdy sie nie uruchamia na domowym komputerze.' }
    'svc_wsearch'   = @{ k='mierzalny';   t='Indeksowanie potrafi realnie obciazac dysk i procesor. Cena: wyszukiwanie plikow bedzie wolne.' }
    'svc_print'     = @{ k='sytuacyjny';  t='Bez drukarki to czysty zysk. Z drukarka - koniec drukowania, dopoki nie cofniesz.' }

    # --- czyszczenie ---
    'cleantemp' = @{ k='mierzalny';   t='Odzyskane megabajty widac w logu od razu.' }
    'cleanupd'  = @{ k='mierzalny';   t='Cache aktualizacji potrafi urosnac do kilku GB.' }
    'cleanbin'  = @{ k='mierzalny';   t='Tyle miejsca, ile trzymales w Koszu.' }
    'cleandns'  = @{ k='kosmetyczny'; t='Rozwiazuje problemy z nieaktualnymi adresami stron. Wydajnosci nie zmienia.' }
    'dismclean' = @{ k='mierzalny';   t='Zwykle kilka GB. Za cene braku mozliwosci odinstalowania starych aktualizacji.' }
    'cleanpre'  = @{ k='kosmetyczny'; t='Odzyskuje maks. kilkaset MB i na kilka dni SPOWALNIA start programow. Zwykle nie warto.' }

    # --- siec i naprawa ---
    'sfcdism'   = @{ k='sytuacyjny';  t='Ma sens tylko, gdy pliki systemowe sa uszkodzone. Na zdrowym systemie nic nie zmieni.' }
    'tcpopt'    = @{ k='sytuacyjny';  t='Przywraca wartosci domyslne. Pomaga, gdy ktos wczesniej namieszal w ustawieniach sieci.' }
