# =====================================================================
#  WORKER
# =====================================================================
$sync = [hashtable]::Synchronized(@{})
$sync.Queue      = [System.Collections.Concurrent.ConcurrentQueue[object]]::new()
$sync.Busy       = $false
$sync.LogFile    = $LogFile
$sync.BackupFile = $BackupFile
$sync.ReportDir  = $ReportDir
$sync.BenchFile  = $BenchFile
$sync.GamesFile  = $GamesFile
$sync.Games      = $null
$sync.Startup    = $null
$sync.Procs      = $null
$sync.NetDiag    = $null
$sync.NetProps   = $null
$sync.Apps       = $null
$sync.DiagData   = $null
$sync.Version    = $AppVersion

$WorkerBody = @'
param($sync, $mode, $ids)

$ErrorActionPreference = 'Continue'
$ProgressPreference    = 'SilentlyContinue'

function Send { param($o) $sync.Queue.Enqueue($o) }
function Log {
    param([string]$m, [string]$lvl = 'info')
    Send @{ type='log'; text=$m; level=$lvl }
    try { Add-Content -LiteralPath $sync.LogFile -Value ("[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $m) -Encoding UTF8 } catch {}
}
function Status { param([string]$m) Send @{ type='status'; text=$m } }
function Prog   { param([int]$p)    Send @{ type='prog'; value=$p } }
function NeedReboot { Send @{ type='reboot' } }

# ------------------------------------------------------- rejestr
function Get-RegVal {
    param([string]$Path, [string]$Name)
    try { return (Get-ItemProperty -LiteralPath $Path -Name $Name -ErrorAction Stop).$Name }
    catch { return $null }
}
function Set-Reg {
    param([string]$Path, [string]$Name, $Value, [string]$Type = 'DWord')
    if (-not (Test-Path $Path)) { New-Item -Path $Path -Force | Out-Null }
    New-ItemProperty -Path $Path -Name $Name -Value $Value -PropertyType $Type -Force | Out-Null
}

# ------------------------------------------------------- kopia zapasowa
$script:BK        = @{}
$script:CurTask   = $null
$script:Recording = $false

function Load-Backup {
    $h = @{}
    if (Test-Path $sync.BackupFile) {
        try {
            $o = Get-Content -Raw -LiteralPath $sync.BackupFile -Encoding UTF8 | ConvertFrom-Json
            foreach ($p in $o.PSObject.Properties) { $h[$p.Name] = @($p.Value) }
        } catch { }
    }
    return $h
}
function Save-Backup {
    try { ($script:BK | ConvertTo-Json -Depth 8) | Set-Content -LiteralPath $sync.BackupFile -Encoding UTF8 } catch {}
}
function Begin-Task {
    param([string]$Id)
    $script:CurTask = $Id
    Send @{ type='state'; id=$Id; state='running' }
    if ($script:BK.ContainsKey($Id)) {
        $script:Recording = $false          # oryginal juz zapisany, nie nadpisujemy
    } else {
        $script:Recording = $true
        $script:BK[$Id] = @()
    }
}
function Rec {
    param($Entry)
    if (-not $script:Recording -or -not $script:CurTask) { return }
    $script:BK[$script:CurTask] = @($script:BK[$script:CurTask]) + $Entry
}

# zapis do rejestru z kopia starej wartosci
function Set-RegB {
    param([string]$Path, [string]$Name, $Value, [string]$Type = 'DWord')
    $old     = Get-RegVal $Path $Name
    $existed = ($null -ne $old)
    Rec @{ k='reg'; path=$Path; name=$Name; type=$Type; value=$old; existed=$existed }
    Set-Reg $Path $Name $Value $Type
}

function Restore-Entry {
    param($e)
    switch ($e.k) {
        'reg' {
            if ($e.existed) {
                Set-Reg $e.path $e.name $e.value $e.type
                Log "  przywrocono $($e.name) = $($e.value)"
            } else {
                Remove-ItemProperty -LiteralPath $e.path -Name $e.name -Force -ErrorAction SilentlyContinue
                Log "  usunieto wpis $($e.name) (wczesniej nie istnial)"
            }
        }
        'svc' {
            try {
                Set-Service -Name $e.name -StartupType $e.start -ErrorAction Stop
                if ($e.running) { Start-Service -Name $e.name -ErrorAction SilentlyContinue }
                Log "  usluga $($e.name): przywrocono tryb $($e.start)"
            } catch { Log "  usluga $($e.name): $($_.Exception.Message)" 'warn' }
        }
        'power' {
            powercfg /setactive $e.guid 2>&1 | Out-Null
            Log "  przywrocono poprzedni plan zasilania"
        }
        'trim' {
            fsutil behavior set DisableDeleteNotify $e.value 2>&1 | Out-Null
            Log "  TRIM: przywrocono DisableDeleteNotify = $($e.value)"
        }
        'hib' {
            if ($e.on) {
                powercfg -h on 2>&1 | Out-Null
                Log "  hibernacja wlaczona z powrotem"
            } else {
                Log "  hibernacja byla wylaczona juz przed zmiana - zostawiam"
            }
        }
        'netprop' {
            try {
                $obj = Get-NetAdapterAdvancedProperty -Name $e.adapter -ErrorAction Stop |
                       Where-Object { "$($_.RegistryKeyword)" -eq "$($e.kw)" } | Select-Object -First 1
                if ($obj) {
                    Set-NetAdapterAdvancedProperty -InputObject $obj -RegistryValue $e.val `
                                                   -NoRestart -ErrorAction Stop
                    Log ("  karta sieciowa, " + $e.kw + ": przywrocono " + $e.val)
                } else {
                    Log ("  karta sieciowa, " + $e.kw + ": wlasciwosc juz nie istnieje") 'warn'
                }
            } catch { Log ("  karta sieciowa, " + $e.kw + ": " + $_.Exception.Message) 'warn' }
        }
        'task' {
            try {
                if ($e.enabled) {
                    Enable-ScheduledTask -TaskPath $e.path -TaskName $e.name -ErrorAction Stop | Out-Null
                    Log "  zadanie $($e.name): wlaczone z powrotem"
                } else {
                    Log "  zadanie $($e.name): bylo wylaczone juz przed zmiana - zostawiam"
                }
            } catch { Log "  zadanie $($e.name): $($_.Exception.Message)" 'warn' }
        }
        default { Log "  nieznany typ wpisu: $($e.k)" 'warn' }
    }
}

# ------------------------------------------------------- narzedzia pomocnicze
function Get-DirSize {
    param([string]$Path)
    if (-not (Test-Path $Path)) { return 0 }
    try {
        $s = (Get-ChildItem -LiteralPath $Path -Recurse -Force -File -ErrorAction SilentlyContinue |
              Measure-Object -Property Length -Sum).Sum
        if ($s) { return [int64]$s } else { return 0 }
    } catch { return 0 }
}
function Clear-Dir {
    # Jeden przebieg: liczymy rozmiar tylko tego, co faktycznie udalo sie usunac.
    # Wczesniej katalog byl skanowany trzy razy, co na %TEMP% z dziesiatkami
    # tysiecy plikow wygladalo jak zawieszenie programu.
    param([string]$Path)
    if (-not (Test-Path $Path)) { return 0 }
    [int64]$freed = 0
    Get-ChildItem -LiteralPath $Path -Force -ErrorAction SilentlyContinue | ForEach-Object {
        $item = $_
        [int64]$size = 0
        try {
            if ($item.PSIsContainer) {
                $s = (Get-ChildItem -LiteralPath $item.FullName -Recurse -Force -File -ErrorAction SilentlyContinue |
                      Measure-Object -Property Length -Sum).Sum
                if ($s) { $size = [int64]$s }
            } else {
                $size = [int64]$item.Length
            }
        } catch { $size = 0 }
        try {
            Remove-Item -LiteralPath $item.FullName -Recurse -Force -ErrorAction Stop
            $freed += $size
        } catch { }
    }
    return $freed
}
function Fmt-MB { param([int64]$b) "{0:N0} MB" -f ($b / 1MB) }
function Fmt-GB { param([int64]$b) "{0:N1} GB" -f ($b / 1GB) }

# Win32_VideoController.AdapterRAM to pole 32-bitowe. Wszystko powyzej
# 4 GB nie miesci sie w typie i WMI zwraca rowne 4 GB - wiec karta
# z 16 GB wyglada tam identycznie jak karta z 4 GB. Prawdziwy rozmiar
# lezy w rejestrze, w kluczu karty. Sterowniki zapisuja go pod roznymi
# nazwami i w roznych typach (QWORD, DWORD, tablica bajtow), wiec
# zbieramy wszystkie warianty i bierzemy najwieksza sensowna wartosc.
function Odczytaj-Rozmiar {
    param($V)
    if ($null -eq $V) { return [int64]0 }
    try {
        if ($V -is [byte[]]) {
            if ($V.Length -ge 8) { return [int64][BitConverter]::ToUInt64($V, 0) }
            if ($V.Length -ge 4) { return [int64][BitConverter]::ToUInt32($V, 0) }
            return [int64]0
        }
        return [int64]$V
    } catch { return [int64]0 }
}

function Get-VramKarty {
    param([string]$Nazwa, $Fallback = 0)

    $klasa = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
    $nazwyWartosci = @(
        'HardwareInformation.qwMemorySize',
        'HardwareInformation.QwMemorySize',
        'HardwareInformation.MemorySize'
    )
    $kandydaci = New-Object System.Collections.ArrayList

    # UWAGA: pod kluczem klasy siedzi podklucz "Properties", do ktorego
    # zwykly uzytkownik nie ma dostepu. Z -ErrorAction Stop ten jeden
    # odmowiony podklucz przerywal cala enumeracje, zanim zdazyla zwrocic
    # cokolwiek - i funkcja konczyla z pustymi rekami mimo poprawnych
    # danych w kluczach kart. Dlatego bledy tu sa ignorowane pojedynczo.
    $klucze = @()
    try {
        $klucze = @(Get-ChildItem -LiteralPath $klasa -ErrorAction SilentlyContinue |
                    Where-Object { $_.PSChildName -match '^\d{4}$' })
    } catch { $klucze = @() }

    foreach ($k in $klucze) {
        try {
            $p = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
            if (-not $p) { continue }

            $ile = [int64]0
            foreach ($n in $nazwyWartosci) {
                $q = Odczytaj-Rozmiar $p.$n
                if ($q -gt $ile) { $ile = $q }
            }
            if ($ile -le 0) { continue }

            # DriverDesc bywa puste, wtedy ratuje AdapterString.
            $opis = "$($p.DriverDesc)"
            if (-not $opis) { $opis = "$($p.'HardwareInformation.AdapterString')" }

            [void]$kandydaci.Add([pscustomobject]@{ Opis = $opis; Ile = $ile })
        } catch { continue }
    }

    # Najpierw klucz opisany dokladnie ta sama nazwa co karta z WMI.
    # Jesli zaden nie pasuje, bierzemy najwieksza znaleziona wartosc -
    # po wymianie karty w rejestrze zostaja klucze starych kart, a ta
    # nowa jest z reguly ta z wieksza pamiecia.
    $pas = @($kandydaci | Where-Object { $Nazwa -and $_.Opis -eq $Nazwa })
    if ($pas.Count -eq 0) { $pas = @($kandydaci) }

    $wynik = [int64]0
    foreach ($c in $pas) { if ($c.Ile -gt $wynik) { $wynik = $c.Ile } }
    if ($wynik -gt 0) { return $wynik }

    try { return [int64]$Fallback } catch { return [int64]0 }
}

function Get-SysDriveType {
    try {
        $L    = ($env:SystemDrive).TrimEnd(':')
        $part = Get-Partition -DriveLetter $L -ErrorAction Stop
        $disk = Get-PhysicalDisk -ErrorAction Stop | Where-Object { $_.DeviceId -eq $part.DiskNumber }
        if ($disk -and $disk.MediaType) { return "$($disk.MediaType)" }
    } catch { }
    return 'SSD'
}
function Get-TrimState {
    try {
        $o = fsutil behavior query DisableDeleteNotify 2>&1 | Out-String
        if ($o -match 'DisableDeleteNotify\s*=?\s*(\d)') { return [int]$Matches[1] }
        if ($o -match '=\s*(\d)') { return [int]$Matches[1] }
    } catch { }
    return $null
}

# wlasny klucz na drobne notatki programu (np. GUID utworzonego planu zasilania)
$OptiKey = 'HKCU:\Software\OptiLauncher'
$PowerUltimate = 'e9a42b02-d5df-448d-aa00-03f14749eb61'
$PowerHigh     = '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c'
function Get-ActiveScheme {
    try {
        $o = powercfg /getactivescheme 2>&1 | Out-String
        $m = [regex]::Match($o, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')
        if ($m.Success) { return $m.Value }
    } catch { }
    return $null
}

