    Set-RegB $gm 'Affinity'            0
    Set-RegB $gm 'Clock Rate'          10000
    Set-RegB $gm 'Background Only'     'False' 'String'
    Set-RegB $gm 'Scheduling Category' 'High'  'String'
    Set-RegB $gm 'SFIO Priority'       'High'  'String'
    Log 'MMCSS: profil gier ustawiony.' 'ok'
    NeedReboot
}

$A['powerplan'] = {
    Status 'Plan zasilania...'
    try {
        if (Get-CimInstance Win32_Battery -ErrorAction Stop) {
            Log 'Wykryto laptop: Ultimate Performance wyraznie skraca czas pracy na baterii.' 'warn'
        }
    } catch { }
    $prev = Get-ActiveScheme
    if ($prev) { Rec @{ k='power'; guid=$prev } }
    $target = $null
    $list = powercfg /list 2>&1 | Out-String

    # powercfg -duplicatescheme NIE tworzy planu o GUID-zie Ultimate Performance,
    # tylko kopie z zupelnie nowym GUID-em. Dlatego zapamietujemy go u siebie:
    # bez tego kazde kolejne uruchomienie tworzy nastepna kopie planu,
    # a test stanu nigdy nie rozpoznaje wlasnej roboty.
    $saved = Get-RegVal $OptiKey 'PowerPlanGuid'
    if ($saved -and ($list -match [regex]::Escape("$saved"))) {
        $target = "$saved"
        Log 'Plan utworzony wczesniej przez OptiLauncher - uzywam go ponownie.'
    } elseif ($list -match [regex]::Escape($PowerUltimate)) {
        $target = $PowerUltimate
        Log 'Plan Ultimate Performance juz istnieje.'
    } else {
        $dup = powercfg -duplicatescheme $PowerUltimate 2>&1 | Out-String
        $m = [regex]::Match($dup, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')
        if ($m.Success) { $target = $m.Value; Log ("Utworzono plan Ultimate Performance: " + $m.Value) }
    }
    if (-not $target) {
        $target = $PowerHigh
        Log 'Ultimate Performance niedostepny - ustawiam Wysoka wydajnosc.' 'warn'
    }
    powercfg /setactive $target 2>&1 | Out-Null

    $teraz = Get-ActiveScheme
    if ($teraz -and ($teraz -eq $target)) {
        Set-Reg $OptiKey 'PowerPlanGuid' $target 'String'
        Log 'Plan zasilania aktywowany.' 'ok'
    } else {
        Log 'Aktywacja planu zasilania nie powiodla sie.' 'err'
    }
}

