$A['sysmain'] = {
    Status 'SysMain...'
    if ((Get-SysDriveType) -eq 'HDD') {
        Log 'Wykryto HDD - SysMain realnie pomaga, POMIJAM.' 'warn'
        return
    }
    $svc = Get-Service -Name 'SysMain' -ErrorAction SilentlyContinue
    if (-not $svc) { Log 'Usluga SysMain nie istnieje.' 'warn'; return }
    $start = 'Automatic'
    try { $start = (Get-CimInstance Win32_Service -Filter "Name='SysMain'").StartMode } catch {}
    if ($start -eq 'Auto') { $start = 'Automatic' }
    Rec @{ k='svc'; name='SysMain'; start=$start; running=($svc.Status -eq 'Running') }
    if ($svc.Status -eq 'Running') { Stop-Service -Name 'SysMain' -Force -ErrorAction SilentlyContinue }
    Set-Service -Name 'SysMain' -StartupType Disabled -ErrorAction SilentlyContinue
    Log 'SysMain zatrzymany i wylaczony.' 'ok'
}

