$A['optdrive'] = {
    Status 'Optymalizacja dyskow...'
    Get-Volume -ErrorAction SilentlyContinue |
        Where-Object { $_.DriveLetter -and $_.DriveType -eq 'Fixed' -and $_.FileSystemType -eq 'NTFS' } |
        ForEach-Object {
            $L = $_.DriveLetter
            try {
                $part = Get-Partition -DriveLetter $L -ErrorAction Stop
                $pd   = Get-PhysicalDisk | Where-Object { $_.DeviceId -eq $part.DiskNumber }
                if ($pd -and $pd.MediaType -eq 'HDD') {
                    Log "Dysk ${L}: HDD - defragmentacja..."
                    Optimize-Volume -DriveLetter $L -Defrag -ErrorAction Stop
                } else {
                    Log "Dysk ${L}: SSD - ReTrim..."
                    Optimize-Volume -DriveLetter $L -ReTrim -ErrorAction Stop
                }
                Log "Dysk ${L}: gotowe." 'ok'
            } catch { Log "Dysk ${L}: pominiety ($($_.Exception.Message))" 'warn' }
        }
}

