    $cdm = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager'
    foreach ($n in @('SubscribedContent-338388Enabled','SubscribedContent-338389Enabled',
                     'SubscribedContent-353694Enabled','SubscribedContent-353696Enabled',
                     'SystemPaneSuggestionsEnabled','SilentInstalledAppsEnabled')) {
        Set-RegB $cdm $n 0
    }
    Set-RegB 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection' 'AllowTelemetry' 1
    # TaskPath musi konczyc sie ukosnikiem, inaczej Get/Disable-ScheduledTask
    # nie znajduje zadania i cala petla cicho nic nie robila.
    $zad = 0
    foreach ($t in @('\Microsoft\Windows\Application Experience\ProgramDataUpdater',
                     '\Microsoft\Windows\Customer Experience Improvement Program\Consolidator',
                     '\Microsoft\Windows\Customer Experience Improvement Program\UsbCeip')) {
        $tp = (Split-Path $t) + '\'
        $tn = Split-Path $t -Leaf
        try {
            $st = Get-ScheduledTask -TaskPath $tp -TaskName $tn -ErrorAction Stop
            $byloWlaczone = ($st.State -ne 'Disabled')
            Rec @{ k='task'; path=$tp; name=$tn; enabled=$byloWlaczone }
            if ($byloWlaczone) {
                Disable-ScheduledTask -TaskPath $tp -TaskName $tn -ErrorAction Stop | Out-Null
                Log "  zadanie $tn - wylaczone"
                $zad++
            } else {
                Log "  zadanie $tn - bylo juz wylaczone"
            }
        } catch { Log "  zadanie $tn - pominiete ($($_.Exception.Message))" 'warn' }
    }
    Log "Sugestie wylaczone, zadan CEIP wylaczonych: $zad." 'ok'
}

$A['faststartup'] = {
    Status 'Szybki rozruch...'
    Set-RegB 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' 'HiberbootEnabled' 0
    Log 'Szybki rozruch wylaczony - zadziala od nastepnego pelnego wylaczenia komputera.' 'ok'
}

$A['cpusched'] = {
    Status 'Planowanie procesora...'
    Set-RegB 'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl' 'Win32PrioritySeparation' 2
    Log 'Planowanie procesora ustawione na Programy.' 'ok'
}

$A['t_killrec'] = {
    Status 'Zamykanie nakladek nagrywania...'
    $procs = @('GameBarFTServer','GameBar','GameBarPresenceWriter','NVIDIA Overlay','NVIDIA Share')
    $n = 0
    foreach ($p in $procs) {
        $running = Get-Process -Name $p -ErrorAction SilentlyContinue
        if ($running) {
            $running | Stop-Process -Force -ErrorAction SilentlyContinue
            Log "  zamknieto: $p"
            $n++
        }
    }
    if ($n -eq 0) { Log 'Nie znaleziono dzialajacych nakladek nagrywania.' 'warn' }
    else          { Log "Zamknieto nakladek: $n." 'ok' }
}

$A['cleantemp'] = {
    Status 'Pliki tymczasowe...'
    $total = 0
    foreach ($p in @($env:TEMP, (Join-Path $env:SystemRoot 'Temp'),
                     (Join-Path $env:LOCALAPPDATA 'CrashDumps'),
                     (Join-Path $env:SystemRoot 'Minidump'))) {
        if ($p -and (Test-Path $p)) {
            $f = Clear-Dir $p; $total += $f
            Log ("  $p  ->  " + (Fmt-MB $f))
        }
    }
    Log ("Zwolniono lacznie: " + (Fmt-MB $total)) 'ok'
}

$A['cleanupd'] = {
    Status 'Cache Windows Update...'
    $stopped = @()
    foreach ($s in @('wuauserv','bits','DoSvc')) {
        $sv = Get-Service -Name $s -ErrorAction SilentlyContinue
        if ($sv -and $sv.Status -eq 'Running') {
            try { Stop-Service -Name $s -Force -ErrorAction Stop; $stopped += $s } catch {}
        }
    }
    Start-Sleep -Seconds 2
    $total  = Clear-Dir (Join-Path $env:SystemRoot 'SoftwareDistribution\Download')
    $total += Clear-Dir (Join-Path $env:SystemRoot 'ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Cache')
    foreach ($s in $stopped) { try { Start-Service -Name $s -ErrorAction Stop } catch {} }
    Log ("Cache aktualizacji: " + (Fmt-MB $total) + ". Uslugi wznowione.") 'ok'
}

$A['cleanbin'] = {
    Status 'Kosz...'
    try { Clear-RecycleBin -Force -ErrorAction Stop; Log 'Kosz oprozniony.' 'ok' }
    catch { Log 'Kosz byl juz pusty.' 'warn' }
}

$A['cleandns'] = {
    Status 'Cache DNS i miniatur...'
    ipconfig /flushdns 2>&1 | Out-Null
    Log 'Cache DNS wyczyszczony.'
    $thumbs = Join-Path $env:LOCALAPPDATA 'Microsoft\Windows\Explorer'
    if (Test-Path $thumbs) {
        $exp = [bool](Get-Process explorer -ErrorAction SilentlyContinue)
        if ($exp) { Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue; Start-Sleep -Seconds 1 }
        $freed = 0
        foreach ($pat in @('thumbcache_*.db','iconcache_*.db')) {
            Get-ChildItem $thumbs -Filter $pat -Force -ErrorAction SilentlyContinue | ForEach-Object {
                $freed += $_.Length
                try { Remove-Item $_.FullName -Force -ErrorAction Stop } catch {}
            }
        }
        if ($exp) { Start-Process explorer.exe }
        Log ("Cache miniatur: " + (Fmt-MB $freed)) 'ok'
    }
}

$A['dismclean'] = {
    Status 'Magazyn komponentow (dlugo)...'
    & dism.exe /Online /Cleanup-Image /StartComponentCleanup /ResetBase 2>&1 | ForEach-Object {
        $l = ($_ -replace "`0", '').Trim()
        if ($l -and $l -notmatch '^\[=*\s*\d*%?') { Log "  $l" }
    }
    Log 'Magazyn komponentow oczyszczony.' 'ok'
}

$A['cleanpre'] = {
    Status 'Prefetch...'
    $f = Clear-Dir (Join-Path $env:SystemRoot 'Prefetch')
    Log ("Prefetch: " + (Fmt-MB $f) + ". Przez kilka dni programy moga startowac wolniej.") 'warn'
}

$A['sfcdism'] = {
    Status 'DISM RestoreHealth...'
    Log '=== DISM /Online /Cleanup-Image /RestoreHealth ==='
    & dism.exe /Online /Cleanup-Image /RestoreHealth 2>&1 | ForEach-Object {
        $l = ($_ -replace "`0", '').Trim()
        if ($l -and $l -notmatch '^\[=*\s*\d*%?') { Log "  $l" }
