}

$A['tcpopt'] = {
    Status 'Ustawienia TCP...'
    foreach ($c in @('int tcp set global autotuninglevel=normal',
                     'int tcp set global ecncapability=disabled',
                     'int tcp set global rss=enabled',
                     'int tcp set global timestamps=disabled')) {
        $o = netsh $c.Split(' ') 2>&1 | Out-String
        Log ("  netsh $c -> " + $o.Trim())
    }
    Log 'Ustawienia TCP przywrocone do wartosci domyslnych.' 'ok'
}

$A['netreset'] = {
    Status 'Reset stosu sieciowego...'
    netsh winsock reset 2>&1 | ForEach-Object { $l = "$_".Trim(); if ($l) { Log "  $l" } }
    netsh int ip reset  2>&1 | ForEach-Object { $l = "$_".Trim(); if ($l) { Log "  $l" } }
    Log 'Stos sieciowy zresetowany - WYMAGANY restart.' 'warn'
    NeedReboot
}

$A['chkdisk'] = {
    Status 'Skanowanie dysku...'
    $L = ($env:SystemDrive).TrimEnd(':')
    try {
        $r = Repair-Volume -DriveLetter $L -Scan -ErrorAction Stop
        Log ("Wynik skanowania dysku ${L}: $r") 'ok'
    } catch { Log ("Skanowanie nieudane: " + $_.Exception.Message) 'warn' }
}

$A['winupd'] = {
    Status 'winget upgrade...'
    if (-not (Get-Command winget -ErrorAction SilentlyContinue)) {
        Log 'winget nie jest zainstalowany (App Installer ze Sklepu).' 'warn'; return
    }
    # --disable-interactivity: bez tej flagi winget zatrzymuje sie na
    # pakietach, ktore wymagaja podania katalogu instalacji (paczki
    # przenosne, np. Battle.net) i czeka w nieskonczonosc na wpis
    # w oknie, do ktorego nikt nie zaglada. Z nia po prostu pomija taki
    # pakiet i idzie dalej - reszta programow zostaje zaktualizowana.
    Start-Process -FilePath 'cmd.exe' -ArgumentList '/k',
        'winget upgrade --all --include-unknown --disable-interactivity --accept-source-agreements --accept-package-agreements'
    Log 'Postep w otwartym oknie konsoli.' 'ok'
}

