            Start-Process 'control.exe' -ArgumentList '/name','Microsoft.WindowsUpdate' -ErrorAction Stop
            Log 'Otwarto Windows Update (starszy panel). Poszukaj "Wyświetl opcjonalne aktualizacje".' 'ok'
        } catch {
