# =====================================================================
#  TEST - wykrywanie stanu
#  zwraca $true / $false / $null (nie wiadomo)
# =====================================================================
$T = @{}

# testy dla zadan uslug - musza byc PO deklaracji $T, inaczej zostalyby
# skasowane razem z nia
foreach ($sk in $SvcZadania) {
    $T[$sk] = { Test-SvcGroup $sk }.GetNewClosure()
}
$T['mmcss']     = { $gm='HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games'
                    ((Get-RegVal $gm 'GPU Priority') -eq 8) -and ((Get-RegVal $gm 'Priority') -eq 6) }
$T['powerplan'] = { $a = Get-ActiveScheme
                    if (-not $a) { return $null }
                    if (($a -eq $PowerUltimate) -or ($a -eq $PowerHigh)) { return $true }
                    # plan zduplikowany przez nas ma wlasny, losowy GUID
                    $s = Get-RegVal $OptiKey 'PowerPlanGuid'
                    if ($s -and ("$a" -eq "$s")) { return $true }
                    return $false }
$T['gamemode']  = { (Get-RegVal 'HKCU:\Software\Microsoft\GameBar' 'AutoGameModeEnabled') -eq 1 }
$T['gamedvr']   = { (Get-RegVal 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled') -eq 0 }
$T['hags']      = { (Get-RegVal 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' 'HwSchMode') -eq 2 }
$T['fso']       = { (Get-RegVal 'HKCU:\System\GameConfigStore' 'GameDVR_FSEBehaviorMode') -eq 2 }
$T['mouse']     = { "$(Get-RegVal 'HKCU:\Control Panel\Mouse' 'MouseSpeed')" -eq '0' }
$T['visualfx']  = { (Get-RegVal 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' 'VisualFXSetting') -eq 3 }
$T['sysmain']   = { $s = Get-Service -Name SysMain -ErrorAction SilentlyContinue
                    if (-not $s) { return $null }
                    try { (Get-CimInstance Win32_Service -Filter "Name='SysMain'").StartMode -eq 'Disabled' } catch { $null } }
$T['delivery']  = { (Get-RegVal 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization' 'DODownloadMode') -eq 0 }
$T['svchost']   = { # sama obecnosc wpisu nic nie znaczy - Windows ustawia go sam.
                    # Liczy sie, czy prog jest podniesiony do rozmiaru pamieci.
                    $v = Get-RegVal 'HKLM:\SYSTEM\CurrentControlSet\Control' 'SvcHostSplitThresholdInKB'
                    if ($null -eq $v) { return $false }
                    try { $ram = [int64]((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1KB) }
                    catch { return $null }
                    ([int64]$v -ge ($ram * 0.9)) }
$T['trim']      = { $v = Get-TrimState; if ($null -eq $v) { $null } else { $v -eq 0 } }
$T['hibernate'] = { -not (Test-Path (Join-Path $env:SystemDrive 'hiberfil.sys')) }
$T['telemetry'] = { $reg = (Get-RegVal 'HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager' 'SystemPaneSuggestionsEnabled') -eq 0
                    if (-not $reg) { return $false }
                    try {
                        $z = Get-ScheduledTask -TaskPath '\Microsoft\Windows\Customer Experience Improvement Program\' `
                                               -TaskName 'Consolidator' -ErrorAction Stop
                        return ($z.State -eq 'Disabled')
                    } catch { return $reg } }
$T['faststartup']  = { (Get-RegVal 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' 'HiberbootEnabled') -eq 0 }
$T['cpusched']      = { (Get-RegVal 'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl' 'Win32PrioritySeparation') -eq 2 }

# =====================================================================
#  DIAGNOSTYKA
# =====================================================================
function New-Sec { param($Title, $Icon) @{ Title=$Title; Icon=$Icon; Rows=(New-Object System.Collections.ArrayList) } }
function Add-Row { param($Sec, $K, $V, $S = '') [void]$Sec.Rows.Add(@{ k=$K; v="$V"; s=$S }) }

function Collect-Diag {
    $out = New-Object System.Collections.ArrayList

    # ---------- system ----------
    Status 'Diagnostyka: system...'
    $s1 = New-Sec 'System' '&#xE770;'
    try {
        $os = Get-CimInstance Win32_OperatingSystem
        Add-Row $s1 'System operacyjny' ($os.Caption -replace 'Microsoft ','')
        Add-Row $s1 'Wersja / build' ("{0} (build {1})" -f $os.Version, $os.BuildNumber)
        $up = (Get-Date) - $os.LastBootUpTime
        $upTxt = "{0} dni, {1} godz., {2} min" -f $up.Days, $up.Hours, $up.Minutes
        Add-Row $s1 'Czas pracy' $upTxt $(if ($up.Days -gt 7) { 'warn' } else { '' })
        Add-Row $s1 'Ostatni rozruch' $os.LastBootUpTime.ToString('yyyy-MM-dd HH:mm')
    } catch { Add-Row $s1 'System' 'brak danych' 'warn' }

    try {
        $ev = Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-Diagnostics-Performance/Operational'; Id=100} -MaxEvents 1 -ErrorAction Stop
        $x  = [xml]$ev.ToXml()
        $bt = ($x.Event.EventData.Data | Where-Object { $_.Name -eq 'BootTime' }).'#text'
        if ($bt) {
            $sec = [math]::Round(([int]$bt) / 1000, 1)
            Add-Row $s1 'Czas rozruchu' "$sec s" $(if ($sec -gt 60) { 'warn' } else { 'ok' })
        }
    } catch { Add-Row $s1 'Czas rozruchu' 'brak w dzienniku zdarzen' }

    $pending = $false
    foreach ($p in @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending',
                     'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired')) {
        if (Test-Path $p) { $pending = $true }
    }
    Add-Row $s1 'Oczekujacy restart' $(if ($pending) { 'TAK' } else { 'nie' }) $(if ($pending) { 'warn' } else { 'ok' })
    [void]$out.Add($s1)

    # ---------- procesor i pamiec ----------
    Status 'Diagnostyka: pamiec...'
    $s2 = New-Sec 'Procesor i pamiec' '&#xE964;'
    try {
        # Uwaga: samo odczytanie LoadPercentage z tej klasy kosztuje ~1 s,
        # bo WMI musi zebrac probke. Pobieramy tylko wybrane wlasciwosci.
        $cpu = Get-CimInstance Win32_Processor -Property Name, NumberOfCores, NumberOfLogicalProcessors, MaxClockSpeed |
               Select-Object -First 1
        Add-Row $s2 'Procesor' $cpu.Name.Trim()
        Add-Row $s2 'Rdzenie / watki' ("{0} / {1}" -f $cpu.NumberOfCores, $cpu.NumberOfLogicalProcessors)
        if ($cpu.MaxClockSpeed) { Add-Row $s2 'Taktowanie bazowe' ("{0} MHz" -f $cpu.MaxClockSpeed) }
    } catch {}
    try {
        $os  = Get-CimInstance Win32_OperatingSystem
        $tot = [int64]$os.TotalVisibleMemorySize * 1KB
        $fre = [int64]$os.FreePhysicalMemory * 1KB
        $pct = [math]::Round((($tot - $fre) / $tot) * 100, 0)
        Add-Row $s2 'Pamiec RAM' ("{0} zajete z {1} ({2} %)" -f (Fmt-GB ($tot-$fre)), (Fmt-GB $tot), $pct) `
                $(if ($pct -gt 85) { 'bad' } elseif ($pct -gt 70) { 'warn' } else { 'ok' })
        $sticks = @(Get-CimInstance Win32_PhysicalMemory)
        if ($sticks.Count) {
            Add-Row $s2 'Moduly' ("{0} x, {1} MHz" -f $sticks.Count, ($sticks[0].Speed))
        }
    } catch {}
    [void]$out.Add($s2)

    # ---------- top procesy ----------
    $s3 = New-Sec 'Najwieksi konsumenci RAM' '&#xE9D9;'
    try {
        Get-Process -ErrorAction SilentlyContinue |
            Sort-Object WorkingSet64 -Descending | Select-Object -First 8 |
            ForEach-Object {
                $mb = [math]::Round($_.WorkingSet64 / 1MB, 0)
                Add-Row $s3 $_.ProcessName ("{0} MB" -f $mb) $(if ($mb -gt 1500) { 'warn' } else { '' })
            }
    } catch { Add-Row $s3 'Procesy' 'brak danych' 'warn' }
    [void]$out.Add($s3)

    # ---------- dyski ----------
    Status 'Diagnostyka: dyski...'
    $s4 = New-Sec 'Dyski' '&#xEDA2;'
    try {
        Get-Volume -ErrorAction SilentlyContinue |
            Where-Object { $_.DriveLetter -and $_.DriveType -eq 'Fixed' } |
            ForEach-Object {
                $free = $_.SizeRemaining
                $tot  = $_.Size
                if ($tot -gt 0) {
                    $pct  = [math]::Round(($free / $tot) * 100, 0)
                    $type = ''
                    try {
                        $part = Get-Partition -DriveLetter $_.DriveLetter -ErrorAction Stop
                        $pd   = Get-PhysicalDisk | Where-Object { $_.DeviceId -eq $part.DiskNumber }
                        if ($pd) { $type = " - $($pd.MediaType)" }
                    } catch {}
                    Add-Row $s4 ("Dysk " + $_.DriveLetter + ":" + $type) `
                            ("{0} wolne z {1} ({2} %)" -f (Fmt-GB $free), (Fmt-GB $tot), $pct) `
                            $(if ($pct -lt 10) { 'bad' } elseif ($pct -lt 20) { 'warn' } else { 'ok' })
                }
            }
    } catch { Add-Row $s4 'Dyski' 'brak danych' 'warn' }
    [void]$out.Add($s4)

    # ---------- grafika ----------
    Status 'Diagnostyka: sterowniki...'
    $s5 = New-Sec 'Karta graficzna i sterowniki' '&#xE7F4;'
    try {
        Get-CimInstance Win32_VideoController | ForEach-Object {
            Add-Row $s5 'Karta' $_.Name
            Add-Row $s5 '  Wersja sterownika' $_.DriverVersion
            if ($_.DriverDate) {
                $age = [int]((Get-Date) - $_.DriverDate).TotalDays
                Add-Row $s5 '  Data sterownika' ("{0} ({1} dni temu)" -f $_.DriverDate.ToString('yyyy-MM-dd'), $age) `
                        $(if ($age -gt 365) { 'bad' } elseif ($age -gt 180) { 'warn' } else { 'ok' })
            }
            $vram = Get-VramKarty "$($_.Name)" $_.AdapterRAM
            if ($vram -gt 0) {
                $txtVram = Fmt-GB $vram
                # Jesli odczyt z rejestru nie wyszedl i zostala nam wartosc
                # z WMI zatrzymana na granicy typu, mowimy to wprost zamiast
                # podawac liczbe, ktora prawie na pewno jest za mala.
                $zWmi = [int64]0
                try { $zWmi = [int64]$_.AdapterRAM } catch { }
                if ($vram -le $zWmi -and $zWmi -ge 4200000000) {
                    $txtVram = "co najmniej $txtVram - Windows nie podaje dokladniej"
                    Add-Row $s5 '  Pamiec' $txtVram 'warn'
                } else {
                    Add-Row $s5 '  Pamiec' $txtVram
                }
            }
        }
    } catch { Add-Row $s5 'Grafika' 'brak danych' 'warn' }
    [void]$out.Add($s5)

    # ---------- autostart ----------
    Status 'Diagnostyka: autostart...'
    $s6 = New-Sec 'Programy w autostarcie' '&#xE7E8;'
    try {
        # Win32_StartupCommand to jedna z najwolniejszych klas WMI - potrafila
        # sama zjesc kilka sekund calego skanu. Te same dane leza w czterech
        # kluczach Run i dwoch folderach Autostart, a odczyt trwa milisekundy.
        $items = New-Object System.Collections.ArrayList
        foreach ($r in @(
            @{ P = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run';             S = 'Rejestr: uzytkownik' },
            @{ P = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run';             S = 'Rejestr: system' },
            @{ P = 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'; S = 'Rejestr: system (32-bit)' },
            @{ P = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\RunOnce';         S = 'Rejestr: jednorazowo' }
        )) {
            if (-not (Test-Path $r.P)) { continue }
            $k = Get-Item -LiteralPath $r.P -ErrorAction SilentlyContinue
            if (-not $k) { continue }
            foreach ($n in $k.GetValueNames()) {
                if ($n) { [void]$items.Add([pscustomobject]@{ Nazwa = $n; Zrodlo = $r.S }) }
            }
        }
        foreach ($f in @([Environment]::GetFolderPath('Startup'),
                         (Join-Path $env:ProgramData 'Microsoft\Windows\Start Menu\Programs\Startup'))) {
            if ($f -and (Test-Path $f)) {
                Get-ChildItem -LiteralPath $f -File -ErrorAction SilentlyContinue |
                    Where-Object { $_.Extension -ne '.ini' } |
                    ForEach-Object { [void]$items.Add([pscustomobject]@{ Nazwa = $_.BaseName; Zrodlo = 'Folder Autostart' }) }
            }
        }
        Add-Row $s6 'Liczba pozycji' $items.Count $(if ($items.Count -gt 12) { 'warn' } else { 'ok' })
        $items | Select-Object -First 15 | ForEach-Object { Add-Row $s6 $_.Nazwa $_.Zrodlo }
        if ($items.Count -gt 15) { Add-Row $s6 '...' ("i jeszcze {0} pozycji" -f ($items.Count - 15)) }
    } catch { Add-Row $s6 'Autostart' 'brak danych' 'warn' }
    [void]$out.Add($s6)

    # ---------- temperatury ----------
    $s7 = New-Sec 'Temperatury' '&#xE9CA;'
    $gotTemp = $false
    try {
        # Wiekszosc plyt nie udostepnia tej klasy, a WMI nie zglasza tego od razu
        # tylko wisi do wlasnego timeoutu. Trzy sekundy i idziemy dalej.
        Get-CimInstance -Namespace root/WMI -ClassName MSAcpi_ThermalZoneTemperature `
                        -OperationTimeoutSec 3 -ErrorAction Stop |
            ForEach-Object {
                $c = [math]::Round(($_.CurrentTemperature / 10) - 273.15, 1)
                Add-Row $s7 'Strefa termiczna' "$c °C" $(if ($c -gt 85) { 'bad' } elseif ($c -gt 75) { 'warn' } else { 'ok' })
                $gotTemp = $true
            }
    } catch {}
    if (-not $gotTemp) {
        Add-Row $s7 'Odczyt' 'Niedostepny przez WMI - wiekszosc plyt tego nie udostepnia. Uzyj HWiNFO.'
    }
    [void]$out.Add($s7)

    # ---------- stan optymalizacji ----------
    Status 'Diagnostyka: stan optymalizacji...'
    $s8 = New-Sec 'Stan optymalizacji' '&#xE9D2;'
    foreach ($k in ($T.Keys | Sort-Object)) {
        $r = $null
        try { $r = & $T[$k] } catch { $r = $null }
        if ($r -eq $true)       { Add-Row $s8 $k 'zastosowane' 'ok' }
        elseif ($r -eq $false)  { Add-Row $s8 $k 'nie zastosowane' '' }
        else                    { Add-Row $s8 $k 'nie wiadomo' 'warn' }
    }
    [void]$out.Add($s8)

    return $out
}

# =====================================================================
#  RAPORT HTML
# =====================================================================
function Esc { param($s) [System.Net.WebUtility]::HtmlEncode("$s") }

function Write-Report {
    param($Sections)
    $stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
    $path  = Join-Path $sync.ReportDir "raport_$stamp.html"

    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine('<!DOCTYPE html><html lang="pl"><head><meta charset="utf-8">')
    [void]$sb.AppendLine('<title>OptiLauncher - raport systemu</title><style>')
    $css = @(
        '*{box-sizing:border-box}'
        'body{margin:0;padding:40px 24px;background:#0B0E14;color:#E6EDF3;'
        '     font-family:"Segoe UI",system-ui,sans-serif;font-size:14px;line-height:1.55}'
        '.wrap{max-width:960px;margin:0 auto}'
        'header{border-bottom:1px solid #233044;padding-bottom:20px;margin-bottom:28px}'
        'h1{margin:0;font-size:26px;letter-spacing:-.3px}'
        'h1 span{color:#22D3EE}'
        '.meta{color:#8B98A9;font-size:13px;margin-top:6px}'
        'section{background:#121722;border:1px solid #233044;border-radius:12px;'
        '        padding:18px 20px;margin-bottom:16px}'
        'h2{margin:0 0 14px;font-size:15px;color:#22D3EE;text-transform:uppercase;'
        '   letter-spacing:.6px;font-weight:700}'
        'table{width:100%;border-collapse:collapse}'
        'td{padding:7px 0;border-bottom:1px solid #1A2130;vertical-align:top}'
        'tr:last-child td{border-bottom:0}'
        'td.k{color:#8B98A9;width:44%;padding-right:16px}'
        'td.v{color:#E6EDF3;font-weight:500}'
        '.pill{display:inline-block;padding:2px 9px;border-radius:6px;font-size:12px;font-weight:600}'
        '.ok{background:#0F2E24;color:#34D399}'
        '.warn{background:#33280A;color:#FBBF24}'
        '.bad{background:#3A1220;color:#F43F5E}'
        'footer{color:#3D4A5C;font-size:12px;text-align:center;margin-top:32px}'
    ) -join "`n"
    [void]$sb.AppendLine($css)
    [void]$sb.AppendLine('</style></head><body><div class="wrap">')
    [void]$sb.AppendLine('<header><h1>OptiLauncher <span>raport systemu</span></h1>')
    [void]$sb.AppendLine('<div class="meta">Wygenerowano: ' + (Esc (Get-Date -Format 'yyyy-MM-dd HH:mm:ss')) +
                         ' &middot; komputer: ' + (Esc $env:COMPUTERNAME) +
                         ' &middot; OptiLauncher v' + (Esc $sync.Version) + '</div></header>')

    foreach ($sec in $Sections) {
        [void]$sb.AppendLine('<section><h2>' + (Esc $sec.Title) + '</h2><table>')
        foreach ($r in $sec.Rows) {
            $v = Esc $r.v
            if ($r.s -eq 'ok' -or $r.s -eq 'warn' -or $r.s -eq 'bad') {
                $v = '<span class="pill ' + $r.s + '">' + $v + '</span>'
            }
            [void]$sb.AppendLine('<tr><td class="k">' + (Esc $r.k) + '</td><td class="v">' + $v + '</td></tr>')
        }
        [void]$sb.AppendLine('</table></section>')
    }

    [void]$sb.AppendLine('<footer>OptiLauncher by Jerremi</footer></div></body></html>')

    [System.IO.File]::WriteAllText($path, $sb.ToString(), (New-Object System.Text.UTF8Encoding($true)))
    return $path
}


# =====================================================================
#  BIBLIOTEKA GIER - optymalizacja per .exe
#
#  Co dokladnie ustawiamy dla wskazanego pliku gry:
#   1. UserGpuPreferences   -> GpuPreference=2  (wysoka wydajnosc GPU;
#                              kluczowe na laptopach z grafika hybrydowa)
#   2. AppCompatFlags\Layers -> DISABLEDXMAXIMIZEDWINDOWEDMODE
#                              (wylaczone optymalizacje pelnoekranowe)
#   3. IFEO\<exe>\PerfOptions -> CpuPriorityClass=3, IoPriority=3
#                              (trwaly wysoki priorytet CPU i we/wy)
#   4. powercfg /powerthrottling disable  (brak dlawienia mocy procesora)
#
#  Punkty 1-3 sa sprawdzalne, punkt 4 nie - powercfg zwraca tekst
#  w jezyku systemu, wiec nie zgadujemy i nie liczymy go do wyniku.
# =====================================================================

$GameKeyDX    = 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences'
$GameKeyLayer = 'HKCU:\Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers'
$FsoFlag      = 'DISABLEDXMAXIMIZEDWINDOWEDMODE'

function Get-IfeoKey {
    param([string]$Exe)
    $n = [System.IO.Path]::GetFileName($Exe)
    "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$n\PerfOptions"
}

function Load-Games {
    $list = New-Object System.Collections.ArrayList
    if (Test-Path $sync.GamesFile) {
        try {
            $raw = Get-Content -Raw -LiteralPath $sync.GamesFile -Encoding UTF8 | ConvertFrom-Json
            foreach ($g in @($raw)) {
                if ($g.path) { [void]$list.Add(@{ name = "$($g.name)"; path = "$($g.path)" }) }
            }
        } catch { }
    }
    # UWAGA: przecinek przed zmienna jest tu KLUCZOWY.
    # Bez niego PowerShell rozpakowuje kolekcje przy zwracaniu z funkcji:
    # pusta ArrayList wraca jako $null, jednoelementowa jako goly element,
    # a wieksza jako zwykla tablica Object[] - i zadna z nich nie ma metody
    # .Add(). Wlasnie dlatego "Wykryj gry" liczylo dodane pozycje, ale
    # zadna nie trafiala na liste: kazde $l.Add() cicho sie wywalalo.
    return ,$list
}
function Save-Games {
    param($List)
    try {
        $arr = @($List | Where-Object { $_ } | ForEach-Object { @{ name = "$($_.name)"; path = "$($_.path)" } })
        if ($arr.Count -eq 0) { '[]' | Set-Content -LiteralPath $sync.GamesFile -Encoding UTF8 }
        else { ($arr | ConvertTo-Json -Depth 4) | Set-Content -LiteralPath $sync.GamesFile -Encoding UTF8 }
    } catch { Log ("Nie zapisano listy gier: " + $_.Exception.Message) 'warn' }
}

# Zwraca stan kazdego z trzech ustawien osobno - karta pokazuje to
# w podpowiedzi, zeby przy "1/3 ustawien" bylo wiadomo, czego brakuje.
function Get-GameOptDetail {
    param([string]$Exe)
    $dx = Get-RegVal $GameKeyDX $Exe
    $ly = Get-RegVal $GameKeyLayer $Exe
    $io = Get-RegVal (Get-IfeoKey $Exe) 'CpuPriorityClass'
    return @{
        gpu  = [bool]($dx -and "$dx" -match 'GpuPreference=2')
        fso  = [bool]($ly -and "$ly" -match $FsoFlag)
        prio = [bool]($io -eq 3)
    }
}

function Test-GameOpt {
    param([string]$Exe)
    $d = Get-GameOptDetail $Exe
    $n = 0
    if ($d.gpu)  { $n++ }
    if ($d.fso)  { $n++ }
    if ($d.prio) { $n++ }
    return $n
}

function Optimize-Game {
    param([string]$Exe, [string]$Name)
    if (-not (Test-Path -LiteralPath $Exe)) {
        Log "Pominieto (brak pliku): $Exe" 'warn'; return
    }
    Log "Optymalizacja: $Name"

    # 1. preferencja GPU
    Set-Reg $GameKeyDX $Exe 'GpuPreference=2;' 'String'
    Log '  GPU: wysoka wydajnosc'

    # 2. optymalizacje pelnoekranowe - dopisujemy flage, nie kasujemy cudzych
    $cur = Get-RegVal $GameKeyLayer $Exe
    if (-not $cur) {
        $new = "~ $FsoFlag"
    } elseif ("$cur" -notmatch $FsoFlag) {
        $new = ("$cur".Trim() + " $FsoFlag")
    } else {
        $new = "$cur"
    }
    Set-Reg $GameKeyLayer $Exe $new 'String'
    Log '  Optymalizacje pelnoekranowe: wylaczone'

    # 3. trwaly priorytet procesu
    $k = Get-IfeoKey $Exe
    Set-Reg $k 'CpuPriorityClass' 3
    Set-Reg $k 'IoPriority'       3
    Log '  Priorytet CPU i we/wy: wysoki'

    # 4. brak dlawienia mocy
    try {
        powercfg /powerthrottling disable /path "$Exe" 2>&1 | Out-Null
        Log '  Ograniczanie mocy: wylaczone'
    } catch { Log '  Ograniczanie mocy: nie udalo sie ustawic' 'warn' }

    Log "Gotowe: $Name" 'ok'
}

function Revert-Game {
    param([string]$Exe, [string]$Name)
    Log "Cofanie: $Name"

    Remove-ItemProperty -LiteralPath $GameKeyDX -Name $Exe -Force -ErrorAction SilentlyContinue

    $cur = Get-RegVal $GameKeyLayer $Exe
    if ($cur) {
        $rest = ("$cur" -replace [regex]::Escape($FsoFlag), '').Trim()
        if ($rest -eq '~' -or $rest -eq '') {
            Remove-ItemProperty -LiteralPath $GameKeyLayer -Name $Exe -Force -ErrorAction SilentlyContinue
        } else {
            Set-Reg $GameKeyLayer $Exe $rest 'String'
        }
    }

    $k = Get-IfeoKey $Exe
    if (Test-Path $k) { Remove-Item -LiteralPath $k -Recurse -Force -ErrorAction SilentlyContinue }

    try { powercfg /powerthrottling reset /path "$Exe" 2>&1 | Out-Null } catch { }

    Log "Cofnieto: $Name" 'ok'
}

function Detect-Games {
    $found = New-Object System.Collections.ArrayList
    $skip  = 'unins|crashhandler|crashreport|redist|vcredist|dxsetup|dotnet|setup|installer|helper|UnityCrash|EasyAntiCheat|BattlEye|launcher\.exe$'
    # Foldery, ktore siedza w bibliotece Steam, ale grami nie sa - ustawianie
    # im wysokiego priorytetu CPU nie ma sensu, a tylko smieci na liscie.
    $skipDir = '^(Steamworks Common Redistributables|SteamVR|Steam Linux Runtime.*|Proton.*|Wallpaper Engine|Steam Controller Configs|Spacewar)$'

    # ---------- Steam ----------
    Status 'Szukam gier Steam...'
    $steam = $null
    foreach ($p in @('HKLM:\SOFTWARE\WOW6432Node\Valve\Steam','HKLM:\SOFTWARE\Valve\Steam')) {
        $v = Get-RegVal $p 'InstallPath'
        if ($v) { $steam = "$v"; break }
    }
    if ($steam -and (Test-Path $steam)) {
        $libs = New-Object System.Collections.ArrayList
        [void]$libs.Add($steam)
        $vdf = Join-Path $steam 'steamapps\libraryfolders.vdf'
        if (Test-Path $vdf) {
            try {
                foreach ($m in ([regex]::Matches((Get-Content -Raw -LiteralPath $vdf), '"path"\s+"([^"]+)"'))) {
                    $lp = $m.Groups[1].Value -replace '\\\\', '\'
                    if ((Test-Path $lp) -and -not $libs.Contains($lp)) { [void]$libs.Add($lp) }
                }
            } catch { }
        }
        foreach ($lib in $libs) {
            $common = Join-Path $lib 'steamapps\common'
            if (-not (Test-Path $common)) { continue }
            Get-ChildItem -LiteralPath $common -Directory -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -notmatch $skipDir } | ForEach-Object {
                $dir = $_
                try {
                    $exe = Get-ChildItem -LiteralPath $dir.FullName -Filter '*.exe' -Recurse -Depth 2 -File -ErrorAction SilentlyContinue |
                           Where-Object { $_.Name -notmatch $skip } |
                           Sort-Object Length -Descending | Select-Object -First 1
                    if ($exe) { [void]$found.Add(@{ name = $dir.Name; path = $exe.FullName }) }
                } catch { }
            }
        }
        Log "Steam: przeszukano $($libs.Count) bibliotek."
    } else {
        Log 'Steam: nie wykryto instalacji.'
    }

    # ---------- Epic ----------
    Status 'Szukam gier Epic...'
    $man = Join-Path $env:ProgramData 'Epic\EpicGamesLauncher\Data\Manifests'
    if (Test-Path $man) {
        Get-ChildItem -LiteralPath $man -Filter '*.item' -ErrorAction SilentlyContinue | ForEach-Object {
            try {
                $j = Get-Content -Raw -LiteralPath $_.FullName | ConvertFrom-Json
                if ($j.InstallLocation -and $j.LaunchExecutable) {
                    $exe = Join-Path $j.InstallLocation $j.LaunchExecutable
                    if (Test-Path -LiteralPath $exe) {
                        [void]$found.Add(@{ name = "$($j.DisplayName)"; path = $exe })
                    }
                }
            } catch { }
        }
        Log 'Epic: sprawdzono manifesty.'
    } else {
        Log 'Epic: nie wykryto instalacji.'
    }

    return $found
}

function Send-Games {
    param($List)
    $data = New-Object System.Collections.ArrayList
    foreach ($g in $List) {
        $exists = Test-Path -LiteralPath $g.path
        $n = 0
        $det = @{ gpu = $false; fso = $false; prio = $false }
        if ($exists) {
            $det = Get-GameOptDetail $g.path
            if ($det.gpu)  { $n++ }
            if ($det.fso)  { $n++ }
            if ($det.prio) { $n++ }
        }
        [void]$data.Add(@{
            name = $g.name; path = $g.path; applied = $n; missing = (-not $exists)
            dGpu = $det.gpu; dFso = $det.fso; dPrio = $det.prio
        })
    }
    $sync.Games = $data
    Log ("Lista gier: " + $data.Count + " pozycji przekazanych do widoku.")
    Send @{ type='games' }
}

# =====================================================================
#  USLUGI
#
#  Wspolny mechanizm: przed wylaczeniem zapisujemy do kopii poprzedni
#  tryb startu i to, czy usluga dzialala. Dzieki temu "Przywroc wszystko"
#  umie ja wlaczyc dokladnie tak, jak byla - a nie "na automatyczny".
# =====================================================================
$SvcGrupy = @{
    'svc_diagtrack' = @('DiagTrack','dmwappushservice')
    'svc_xbox'      = @('XblAuthManager','XblGameSave','XboxNetApiSvc','XboxGipSvc')
    'svc_remote'    = @('RemoteRegistry','RemoteAccess')
    'svc_fax'       = @('Fax')
    'svc_maps'      = @('MapsBroker')
    'svc_wmp'       = @('WMPNetworkSvc')
    'svc_retail'    = @('RetailDemo')
    'svc_wsearch'   = @('WSearch')
    'svc_print'     = @('Spooler')
}

function Disable-SvcGroup {
    param([string]$Klucz)
    $names = $SvcGrupy[$Klucz]
    if (-not $names) { Log "Nieznana grupa uslug: $Klucz" 'warn'; return }
    $ok = 0; $brak = 0; $juz = 0
    foreach ($n in $names) {
        $svc = Get-Service -Name $n -ErrorAction SilentlyContinue
        if (-not $svc) { $brak++; continue }
        $start = 'Automatic'
        try { $start = (Get-CimInstance Win32_Service -Filter "Name='$n'" -ErrorAction Stop).StartMode } catch { }
        if ($start -eq 'Auto') { $start = 'Automatic' }
        if ($start -eq 'Disabled') { Log "  $n - byla juz wylaczona"; $juz++; continue }
        Rec @{ k='svc'; name=$n; start=$start; running=($svc.Status -eq 'Running') }
        try {
            if ($svc.Status -eq 'Running') { Stop-Service -Name $n -Force -ErrorAction SilentlyContinue }
            Set-Service -Name $n -StartupType Disabled -ErrorAction Stop
            Log "  $n - zatrzymana i wylaczona"
            $ok++
        } catch { Log ("  $n - nie udalo sie: " + $_.Exception.Message) 'warn' }
    }
    if ($ok -gt 0)                  { Log "Wylaczonych uslug: $ok." 'ok' }
    elseif ($juz -gt 0)             { Log 'Wszystkie uslugi z tej grupy byly juz wylaczone.' 'ok' }
    elseif ($brak -eq $names.Count) { Log 'Zadna z tych uslug nie istnieje w tym systemie.' 'warn' }
}

function Test-SvcGroup {
    param([string]$Klucz)
    $names = $SvcGrupy[$Klucz]
    if (-not $names) { return $null }
    $ist = 0; $wyl = 0
    foreach ($n in $names) {
        try {
            $c = Get-CimInstance Win32_Service -Filter "Name='$n'" -ErrorAction Stop
            if (-not $c) { continue }
            $ist++
            if ($c.StartMode -eq 'Disabled') { $wyl++ }
        } catch { }
    }
    if ($ist -eq 0) { return $null }     # nie ma czego oceniac
    return ($wyl -eq $ist)
}

# =====================================================================
#  PROCESY W TLE
# =====================================================================
# Procesy, ktorych program nie pozwoli zamknac - ubicie ktoregokolwiek
# konczy sie zawieszeniem pulpitu albo restartem Windows.
$ProcChronione = @(
    'System','Idle','Registry','Memory Compression','smss','csrss','wininit','winlogon',
    'services','lsass','svchost','fontdrvhost','dwm','explorer','sihost','ctfmon',
    'RuntimeBroker','ShellExperienceHost','StartMenuExperienceHost','SearchHost',
    'TextInputHost','LsaIso','SecurityHealthService','MsMpEng','WUDFHost','audiodg',
    'powershell','pwsh','conhost','OptiLauncher'
)

function Get-ProcList {
    $mapa = @{}
    foreach ($p in (Get-Process -ErrorAction SilentlyContinue)) {
        $n = "$($p.ProcessName)"
        if (-not $n) { continue }
        if (-not $mapa.ContainsKey($n)) {
            $mapa[$n] = @{ name = $n; ram = [double]0; ile = 0; tytul = '' }
        }
        $mapa[$n].ram += [double]$p.WorkingSet64
        $mapa[$n].ile++
        if (-not $mapa[$n].tytul -and $p.MainWindowTitle) { $mapa[$n].tytul = "$($p.MainWindowTitle)" }
    }
    $lista = New-Object System.Collections.ArrayList
    foreach ($k in ($mapa.Keys | Sort-Object { -$mapa[$_].ram })) {
        $e = $mapa[$k]
        [void]$lista.Add(@{
            name     = $e.name
            ramMB    = [math]::Round($e.ram / 1MB, 1)
            ile      = $e.ile
            tytul    = $e.tytul
            chroniony = [bool]($ProcChronione -contains $e.name)
        })
    }
    return ,$lista
}

function Send-Procs {
    param($Lista)
    $sync.Procs = @($Lista)
    Send @{ type = 'procs' }
}

