    'Microsoft.YourPhone'                    = 'Połączenie z telefonem'
    'Microsoft.WindowsSoundRecorder'         = 'Rejestrator dźwięku'
    'Microsoft.OneConnect'                   = 'Mobile Plans'
    'Microsoft.549981C3F5F10'                = 'Cortana'
}

function Get-AppxList {
    $lista = New-Object System.Collections.ArrayList
    try {
        $zainst = Get-AppxPackage -ErrorAction Stop | Where-Object { -not $_.IsFramework }
    } catch {
        Log ('Nie udalo sie odczytac aplikacji: ' + $_.Exception.Message) 'err'
        return ,$lista
    }
    foreach ($klucz in $AppxDozwolone.Keys) {
        $p = $zainst | Where-Object { $_.Name -eq $klucz } | Select-Object -First 1
        if ($p) {
            [void]$lista.Add(@{
                id    = "$($p.PackageFullName)"
                name  = "$klucz"
                tytul = "$($AppxDozwolone[$klucz])"
            })
        }
    }
    return ,$lista
}

function Send-Apps {
    param($Lista)
    $sync.Apps = @($Lista)
    Send @{ type = 'apps' }
}

# =====================================================================
#  LACZE - POMIAR I KARTA SIECIOWA
#
#  Uwaga na to, czego tu NIE MA. Nie ma rezerwacji pasma QoS (Windows
#  nigdy nie rezerwowal 20% - to mit z poradnikow), nie ma TcpAckFrequency
#  ani wylaczania algorytmu Nagle'a (na dzisiejszych laczach czesciej
#  szkodzi niz pomaga), nie ma czyszczenia DNS w petli (to spowalnia
#  przegladanie, a nie przyspiesza).
#
#  Jest za to pomiar, ktory mowi GDZIE jest problem, i te ustawienia
#  sterownika karty, ktore realnie dotykaja opoznien.
# =====================================================================

# Wlasciwosci sterownika warte ruszenia. Kazda karta ma inny zestaw,
# dlatego pokazujemy WYLACZNIE te, ktore faktycznie istnieja.
$NetProps = @(
    @{ kw='*EEE';                 nazwa='Energy Efficient Ethernet'; cel='0'
       opis='Karta usypia port miedzy pakietami. Oszczedza ulamki wata kosztem mikroprzeciec.' }
    @{ kw='EnableGreenEthernet';  nazwa='Green Ethernet'; cel='0'
       opis='Realtekowy odpowiednik EEE - obniza moc nadajnika przy krotkim kablu.' }
    @{ kw='*InterruptModeration'; nazwa='Interrupt Moderation'; cel='0'
       opis='Grupuje przerwania, zeby oszczedzic procesor. Wylaczenie obniza opoznienie kosztem kilku procent CPU.' }
    @{ kw='*FlowControl';         nazwa='Flow Control'; cel='0'
       opis='Wstrzymywanie ramek przy przeciazeniu. Przy dzisiejszych przelacznikach zwykle zbedne.' }
    @{ kw='*SelectiveSuspend';    nazwa='Selective Suspend'; cel='0'
       opis='Usypianie karty przy bezczynnosci. Typowa przyczyna zrywania polaczenia.' }
    @{ kw='WakeOnMagicPacket';    nazwa='Wybudzanie pakietem sieciowym'; cel='0'
       opis='Zdalne wybudzanie komputera. Bez tego karta nie nasluchuje w uspieniu.' }
)

function Get-ActiveAdapter {
    # Karta z domyslna trasa - czyli ta, przez ktora naprawde leci ruch.
    # Wybieranie "pierwszej wlaczonej" myli sie przy VPN-ach i kartach wirtualnych.
    try {
        $r = Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction Stop |
             Sort-Object RouteMetric | Select-Object -First 1
        if ($r) {
            $a = Get-NetAdapter -InterfaceIndex $r.InterfaceIndex -ErrorAction Stop
            if ($a) { return $a }
        }
    } catch { }
    try {
        return (Get-NetAdapter -Physical -ErrorAction Stop |
                Where-Object { $_.Status -eq 'Up' } | Select-Object -First 1)
    } catch { }
    return $null
}

function Measure-Latency {
    param([string]$Cel, [int]$Ile = 10)
    $czasy = New-Object System.Collections.ArrayList
    $zgubione = 0
    $ping = New-Object System.Net.NetworkInformation.Ping
    for ($i = 0; $i -lt $Ile; $i++) {
        try {
            $r = $ping.Send($Cel, 1200)
            if ($r -and $r.Status -eq 'Success') { [void]$czasy.Add([double]$r.RoundtripTime) }
            else { $zgubione++ }
        } catch { $zgubione++ }
        Start-Sleep -Milliseconds 120
    }
    if ($czasy.Count -eq 0) {
        return @{ ok=$false; avg=0; min=0; max=0; jitter=0; loss=100 }
    }
    # Jitter liczymy jako srednia roznica miedzy kolejnymi pomiarami -
    # to on odpowiada za przycinanie w grach, nie sam ping.
    $sumaJ = 0.0; $n = 0
    for ($i = 1; $i -lt $czasy.Count; $i++) {
        $sumaJ += [math]::Abs($czasy[$i] - $czasy[$i-1]); $n++
    }
    $jit = 0.0
    if ($n -gt 0) { $jit = $sumaJ / $n }
    $st = ($czasy | Measure-Object -Average -Minimum -Maximum)
    return @{
        ok     = $true
        avg    = [math]::Round($st.Average, 1)
        min    = [math]::Round($st.Minimum, 1)
        max    = [math]::Round($st.Maximum, 1)
        jitter = [math]::Round($jit, 1)
        loss   = [math]::Round(($zgubione / [double]$Ile) * 100, 0)
    }
}

function Get-WifiInfo {
    # netsh to jedyne zrodlo sily sygnalu i pasma, ktore dziala wszedzie
    $wynik = @{ sygnal=$null; pasmo=$null; kanal=$null; radio=$null }
    try {
        $txt = netsh wlan show interfaces 2>&1 | Out-String
        foreach ($line in ($txt -split "`r?`n")) {
            if (-not $wynik.sygnal -and $line -match '(\d+)\s*%') { $wynik.sygnal = [int]$Matches[1] }
            if ($line -match '(?i)(band|pasmo)\s*:\s*(.+)$')  { $wynik.pasmo = $Matches[2].Trim() }
            if ($line -match '(?i)(channel|kana)\S*\s*:\s*(\d+)') { $wynik.kanal = $Matches[2].Trim() }
            if ($line -match '(?i)radio type\s*:\s*(.+)$')        { $wynik.radio = $Matches[1].Trim() }
        }
    } catch { }
    return $wynik
}

function Get-NetDiag {
    $rows = New-Object System.Collections.ArrayList
    function AddN { param($l, $v, $s = '') [void]$rows.Add(@{ label = "$l"; value = "$v"; stan = "$s" }) }

    $ad = Get-ActiveAdapter
    if (-not $ad) {
        AddN 'Karta sieciowa' 'nie wykryto aktywnego polaczenia' 'err'
        return ,$rows
    }

    Status 'Odczyt karty sieciowej...'
    AddN 'Karta' ("$($ad.InterfaceDescription)")
    AddN 'Predkosc polaczenia' ("$($ad.LinkSpeed)")

    $wifi = $false
    try { $wifi = ("$($ad.PhysicalMediaType)" -match '802.11') } catch { }

    if ($wifi) {
        $w = Get-WifiInfo
        if ($w.sygnal) {
            $s = 'ok'
            if ($w.sygnal -lt 50) { $s = 'err' } elseif ($w.sygnal -lt 70) { $s = 'warn' }
            AddN 'Sila sygnalu Wi-Fi' ("$($w.sygnal) %") $s
        }
        if ($w.radio) { AddN 'Standard Wi-Fi' $w.radio }
        if ($w.pasmo) { AddN 'Pasmo' $w.pasmo }
        if ($w.kanal) { AddN 'Kanal' $w.kanal }
    }

    $brama = $null
    try {
        $brama = (Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction Stop |
                  Sort-Object RouteMetric | Select-Object -First 1).NextHop
    } catch { }
    if ($brama) { AddN 'Brama' $brama }

    try {
        $mtu = (Get-NetIPInterface -InterfaceIndex $ad.InterfaceIndex -AddressFamily IPv4 -ErrorAction Stop).NlMtu
        if ($mtu) {
            $s = ''
            if ($mtu -lt 1400) { $s = 'warn' }
            AddN 'MTU' $mtu $s
        }
    } catch { }

    try {
        $dns = (Get-DnsClientServerAddress -InterfaceIndex $ad.InterfaceIndex -AddressFamily IPv4 -ErrorAction Stop).ServerAddresses
        if ($dns) { AddN 'Serwery DNS' ($dns -join ', ') }
    } catch { }

    # --- pomiary ---
    $g = @{ ok = $false; jitter = 0; loss = 0 }
    if ($brama) {
        Status 'Pomiar do bramy...'
        $g = Measure-Latency $brama 10
        if ($g.ok) {
            $s = 'ok'
            if ($g.jitter -gt 5 -or $g.loss -gt 0) { $s = 'err' } elseif ($g.jitter -gt 2) { $s = 'warn' }
            AddN 'Ping do bramy' ("srednio {0} ms, jitter {1} ms, strata {2} %" -f $g.avg, $g.jitter, $g.loss) $s
        } else { AddN 'Ping do bramy' 'brak odpowiedzi' 'err' }
    }

    Status 'Pomiar do internetu...'
    $c = Measure-Latency '1.1.1.1' 10
    if ($c.ok) {
        $s = 'ok'
        if ($c.avg -gt 80 -or $c.loss -gt 0) { $s = 'err' } elseif ($c.avg -gt 40 -or $c.jitter -gt 10) { $s = 'warn' }
        AddN 'Ping do internetu' ("srednio {0} ms, min {1}, max {2}, jitter {3} ms, strata {4} %" -f $c.avg, $c.min, $c.max, $c.jitter, $c.loss) $s
    } else { AddN 'Ping do internetu' 'brak odpowiedzi' 'err' }

    # --- interpretacja: w tym pomiarze to jest cala wartosc ---
    if ($brama -and $g.ok -and ($g.jitter -gt 5 -or $g.loss -gt 0)) {
        AddN 'Wniosek' 'Problem jest MIEDZY komputerem a routerem: kabel, Wi-Fi albo sam router. Zadne ustawienie Windows tego nie naprawi.' 'err'
    } elseif ($c.ok -and $c.loss -gt 0) {
        AddN 'Wniosek' 'Do routera jest stabilnie, pakiety gina dalej - to strona operatora.' 'warn'
    } elseif ($wifi -and $c.ok -and $c.jitter -gt 10) {
        AddN 'Wniosek' 'Ping w normie, ale jitter wysoki jak na Wi-Fi. Kabel rozwiazalby to od reki.' 'warn'
    } elseif ($c.ok) {
        AddN 'Wniosek' 'Lacze zachowuje sie prawidlowo - nie ma tu czego optymalizowac.' 'ok'
    }

    # --- adres publiczny ---
    Status 'Odczyt adresu publicznego...'
    $pubIP = Get-PublicznyIP
    if ($pubIP) {
        AddN 'Publiczny adres IP' $pubIP
        AddN 'Uwaga' 'Przydatne przy hostowaniu gry i przekierowaniu portow. Jesli ten adres rozni sie od adresu WAN na stronie routera, operator uzywa NAT operatorskiego (CGNAT) - przekierowanie portow wtedy nie zadziala.'
    } else {
        AddN 'Publiczny adres IP' 'nie udalo sie odczytac' 'warn'
    }

    # --- predkosci ---
    Status 'Pomiar predkosci pobierania...'
    $pred = Measure-Predkosc
    if ($pred.ok) {
        $s = 'ok'
        if ($pred.mbps -lt 20) { $s = 'err' } elseif ($pred.mbps -lt 50) { $s = 'warn' }
        AddN 'Pobieranie' ("{0} Mb/s   (pobrano {1} MB w {2} s)" -f $pred.mbps, $pred.mb, $pred.sek) $s
        AddN 'Uwaga' 'Jeden strumien, jeden serwer - na bardzo szybkich laczach wynik bywa nizszy od realnego.'
    } else {
        AddN 'Pobieranie' 'nie udalo sie zmierzyc' 'warn'
    }

    Status 'Pomiar predkosci wysylania...'
    $predUp = Measure-PredkoscWysylania
    if ($predUp.ok) {
        $s = 'ok'
        if ($predUp.mbps -lt 5) { $s = 'err' } elseif ($predUp.mbps -lt 15) { $s = 'warn' }
        AddN 'Wysylanie' ("{0} Mb/s   (wyslano {1} MB w {2} s)" -f $predUp.mbps, $predUp.mb, $predUp.sek) $s
    } else {
        AddN 'Wysylanie' 'nie udalo sie zmierzyc' 'warn'
    }

    # --- serwery gier ---
    Status 'Pomiar do platform gamingowych...'
    foreach ($wg in (Measure-Serwery $SerweryGier 6)) {
        if ($wg.ok) {
            $s = 'ok'
            if ($wg.avg -gt 100 -or $wg.loss -gt 0) { $s = 'warn' }
            AddN $wg.nazwa ("{0} ms   jitter {1} ms   straty {2} %" -f $wg.avg, $wg.jitter, $wg.loss) $s
        } else {
            AddN $wg.nazwa 'brak odpowiedzi (firma moze blokowac ping - to nie musi oznaczac problemu)'
        }
    }

    # --- trasa do internetu ---
    Status 'Sledzenie trasy do 1.1.1.1...'
    foreach ($skok in (Get-Traceroute -Cel '1.1.1.1' -MaxSkokow 18 -TimeoutMs 700)) {
        if (-not $skok.odpowiedzial) {
            AddN "Skok $($skok.skok)" '* brak odpowiedzi (mozliwa blokada ICMP na tym wezle)'
        } else {
            $s = 'ok'
            if ($skok.czas -gt 80) { $s = 'err' } elseif ($skok.czas -gt 40) { $s = 'warn' }
            $adr = $(if ($skok.adres) { $skok.adres } else { '?' })
            AddN "Skok $($skok.skok)" ("{0}   -   {1} ms" -f $adr, $skok.czas) $s
        }
    }

    return ,$rows
}

# =====================================================================
#  POMIARY PRZENIESIONE ZE SPRAWDZANIA LACZA 1.4
#  Ping, jitter i straty OptiLauncher mierzyl juz wczesniej. To sa te
#  cztery rzeczy, ktorych nie mial: predkosc w obie strony, adres
#  publiczny, traceroute i pomiar do platform gamingowych.
# =====================================================================

$SerweryGier = @(
    @{ nazwa = 'Steam (Valve)';  cel = 'steampowered.com' }
    @{ nazwa = 'Xbox Live';      cel = 'xbox.com' }
    @{ nazwa = 'Discord';        cel = 'discord.com' }
    @{ nazwa = 'Riot Games';     cel = 'riotgames.com' }
)

function Measure-Serwery {
    param([array]$Lista, [int]$Ile = 6, [scriptblock]$Postep = $null)
    $wyniki = New-Object System.Collections.ArrayList
    foreach ($s in $Lista) {
        $ip = $null
        try {
            $rec = Resolve-DnsName -Name $s.cel -Type A -ErrorAction Stop |
                   Where-Object { $_.Type -eq 'A' } | Select-Object -First 1
            if ($rec) { $ip = $rec.IPAddress }
        } catch { }
        if (-not $ip) {
            [void]$wyniki.Add(@{ nazwa = $s.nazwa; cel = $s.cel; ok = $false; avg=0; jitter=0; loss=100 })
            if ($Postep) { & $Postep }
            continue
        }
        $m = Measure-Latency $ip $Ile
        $m.nazwa = $s.nazwa
        $m.cel   = $s.cel
        [void]$wyniki.Add($m)
        if ($Postep) { & $Postep }
    }
    return ,$wyniki
}

function Get-PublicznyIP {
    # Metoda 1: trik DNS przez OpenDNS - dziala nawet gdy cos przycina
    # zwykly ruch webowy, ale niektore routery/sieci blokuja zapytania
    # do wskazanego wprost serwera DNS (port 53 poza standardowa trasa).
    try {
        $rec = Resolve-DnsName -Name 'myip.opendns.com' -Server 'resolver1.opendns.com' `
                                -Type A -ErrorAction Stop | Select-Object -First 1
        if ($rec -and $rec.IPAddress) { return "$($rec.IPAddress)" }
    } catch { }

    # Metoda 2: ten sam trik, ale przez DNS Google (inny serwer - jesli
    # akurat OpenDNS jest niedostepny/zablokowany, Google moze przejsc).
    try {
        $rec = Resolve-DnsName -Name 'o-o.myaddr.l.google.com' -Server 'ns1.google.com' `
                                -Type TXT -ErrorAction Stop | Select-Object -First 1
        if ($rec -and $rec.Strings) {
            $ip = ($rec.Strings -join '').Trim('"')
            if ($ip) { return $ip }
        }
    } catch { }

    # Metoda 3: zwykle zapytanie HTTP jako ostatnia deska ratunku - jesli
    # obie proby po DNS zawiodly (np. siec blokuje zapytania do obcych
    # serwerow DNS), zwykla strona przez HTTPS zwykle dziala.
    foreach ($url in @('https://api.ipify.org', 'https://icanhazip.com')) {
        try {
            $odp = Invoke-RestMethod -Uri $url -TimeoutSec 5 -ErrorAction Stop
            $ip  = "$odp".Trim()
            if ($ip -match '^\d{1,3}(\.\d{1,3}){3}$' -or $ip -match ':') { return $ip }
        } catch { }
    }

    return $null
}

function Measure-Predkosc {
    param([long]$Bajtow = 20000000, [int]$TimeoutSec = 20)
    $url = "https://speed.cloudflare.com/__down?bytes=$Bajtow"
    try {
        $sw  = [System.Diagnostics.Stopwatch]::StartNew()
        $odp = Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec $TimeoutSec -ErrorAction Stop
        $sw.Stop()
        $sek = $sw.Elapsed.TotalSeconds
        $bajty = [int64]$odp.RawContentLength
        if ($bajty -le 0 -and $odp.Content) { $bajty = [int64]$odp.Content.Length }
        if ($sek -le 0 -or $bajty -le 0) { return @{ ok = $false } }
        $mbps = [math]::Round((($bajty * 8) / $sek) / 1MB, 1)
        return @{ ok = $true; mbps = $mbps; mb = [math]::Round($bajty / 1MB, 1); sek = [math]::Round($sek, 1) }
    } catch {
        return @{ ok = $false }
    }
}

function Measure-PredkoscWysylania {
    param([long]$Bajtow = 8000000, [int]$TimeoutSec = 20)
    $url = "https://speed.cloudflare.com/__up"
    try {
        $dane = New-Object byte[] $Bajtow
        (New-Object System.Random).NextBytes($dane)
        $sw  = [System.Diagnostics.Stopwatch]::StartNew()
        $null = Invoke-WebRequest -Uri $url -Method Post -Body $dane -UseBasicParsing -TimeoutSec $TimeoutSec -ErrorAction Stop
        $sw.Stop()
        $sek = $sw.Elapsed.TotalSeconds
        if ($sek -le 0) { return @{ ok = $false } }
        $mbps = [math]::Round((($Bajtow * 8) / $sek) / 1MB, 1)
        return @{ ok = $true; mbps = $mbps; mb = [math]::Round($Bajtow / 1MB, 1); sek = [math]::Round($sek, 1) }
    } catch {
        return @{ ok = $false }
    }
}

function Get-Traceroute {
    param([string]$Cel, [int]$MaxSkokow = 20, [int]$TimeoutMs = 1000, [scriptblock]$Postep = $null)
    $wyniki  = New-Object System.Collections.ArrayList
    $ping    = New-Object System.Net.NetworkInformation.Ping
    $bufor   = [byte[]](0..31 | ForEach-Object { 0 })
    $dotarto = $false
    for ($ttl = 1; $ttl -le $MaxSkokow -and -not $dotarto; $ttl++) {
        $opts   = New-Object System.Net.NetworkInformation.PingOptions ($ttl, $true)
        $czasy  = New-Object System.Collections.ArrayList
        $adres  = $null
        for ($proba = 0; $proba -lt 3; $proba++) {
            try {
                $r = $ping.Send($Cel, $TimeoutMs, $bufor, $opts)
                if ($r -and $r.Address -and -not $adres) { $adres = $r.Address.ToString() }
                if ($r -and ($r.Status -eq [System.Net.NetworkInformation.IPStatus]::TtlExpired -or
                             $r.Status -eq [System.Net.NetworkInformation.IPStatus]::Success)) {
                    [void]$czasy.Add([double]$r.RoundtripTime)
                    if ($r.Status -eq [System.Net.NetworkInformation.IPStatus]::Success) { $dotarto = $true }
                }
            } catch { }
        }
        $srednia = 0
        if ($czasy.Count -gt 0) { $srednia = [math]::Round((($czasy | Measure-Object -Average).Average), 0) }
        [void]$wyniki.Add(@{
            skok        = $ttl
            adres       = $(if ($adres) { $adres } else { $null })
            czas        = $srednia
            odpowiedzial= ($czasy.Count -gt 0)
        })
        if ($Postep) { & $Postep }
    }
    return ,$wyniki
}

# UWAGA: -RegistryKeyword traktuje gwiazdke jako WIELOZNACZNIK, a standardowe
# klucze NDIS naprawde zaczynaja sie od gwiazdki (*EEE, *FlowControl).
# Zapytanie o '*EEE' zwracalo wiec kilka wlasciwosci naraz, a ich wartosci
# sklejaly sie w "0 0". Dlatego pobieramy cala liste RAZ i filtrujemy
# doslownym porownaniem - przy okazji zamiast szesciu zapytan jest jedno.
function Get-NetPropAll {
    param($Ad)
    try { return @(Get-NetAdapterAdvancedProperty -Name $Ad.Name -ErrorAction Stop) }
    catch { return @() }
}

function Find-NetProp {
    param($Wszystkie, [string]$Kw)
    return ($Wszystkie | Where-Object { "$($_.RegistryKeyword)" -eq $Kw } | Select-Object -First 1)
}

function Get-NetPropList {
    $lista = New-Object System.Collections.ArrayList
    $ad = Get-ActiveAdapter
    if (-not $ad) { return ,$lista }
    $wsz = Get-NetPropAll $ad
    foreach ($p in $NetProps) {
        $cur = Find-NetProp $wsz $p.kw
        if (-not $cur) { continue }
        # RegistryValue to tablica - bierzemy pierwszy element, nie cala sklejke
        $val = "$(@($cur.RegistryValue)[0])"
        [void]$lista.Add(@{
            kw        = "$($p.kw)"
            nazwa     = "$($p.nazwa)"
            opis      = "$($p.opis)"
            adapter   = "$($ad.Name)"
            wartosc   = $val
            pokaz     = "$(@($cur.DisplayValue)[0])"
            wylaczone = [bool]($val -eq $p.cel)
        })
    }
    return ,$lista
}

function Send-Net {
    param($Rows, $Props)
    $sync.NetDiag  = @($Rows)
    $sync.NetProps = @($Props)
    Send @{ type = 'net' }
}

# =====================================================================
#  AUTOSTART
#
#  Windows trzyma sam wpis (co uruchomic) w kluczach Run lub w folderze
#  Autostart, a osobno - w StartupApproved - informacje, czy jest wlaczony.
#  Menedzer zadan robi dokladnie to samo: nie kasuje wpisu, tylko zmienia
#  jego stan. Dlatego ta operacja nie potrzebuje backup.json - jest
#  odwracalna tym samym przyciskiem, a program niczego nie niszczy.
#
#  Format wartosci w StartupApproved: 12 bajtow.
#    bajt 0 = 2 lub 6  -> wlaczony
#    bajt 0 = 3        -> wylaczony, bajty 4-11 to czas wylaczenia (FILETIME)
# =====================================================================
$StartupSources = @(
    @{ Run = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
       App = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run'
       Label = 'Uzytkownik' }
    @{ Run = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run'
       App = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run'
       Label = 'System' }
    @{ Run = 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'
       App = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run32'
       Label = 'System (32-bit)' }
)
$StartupFolders = @(
    @{ Dir = [Environment]::GetFolderPath('Startup')
       App = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\StartupFolder'
       Label = 'Folder uzytkownika' }
    @{ Dir = (Join-Path $env:ProgramData 'Microsoft\Windows\Start Menu\Programs\Startup')
       App = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\StartupFolder'
       Label = 'Folder wspolny' }
)

function Test-StartupEnabled {
    param([string]$App, [string]$Name)
    $v = Get-RegVal $App $Name
    if ($null -eq $v) { return $true }        # brak wpisu = nigdy nie ruszany = wlaczony
    try { return -not ((([byte[]]$v)[0]) -band 1) } catch { return $true }
}

function Set-StartupEnabled {
    param([string]$App, [string]$Name, [bool]$On)
    if (-not (Test-Path $App)) { New-Item -Path $App -Force | Out-Null }
    $b = New-Object byte[] 12
    if ($On) {
        $b[0] = 2
    } else {
        $b[0] = 3
        $ft = [BitConverter]::GetBytes((Get-Date).ToFileTime())
        [Array]::Copy($ft, 0, $b, 4, 8)
    }
    New-ItemProperty -Path $App -Name $Name -Value $b -PropertyType Binary -Force | Out-Null
}

function Get-StartupItems {
    $lista = New-Object System.Collections.ArrayList
    foreach ($s in $StartupSources) {
        if (-not (Test-Path $s.Run)) { continue }
        $k = Get-Item -LiteralPath $s.Run -ErrorAction SilentlyContinue
        if (-not $k) { continue }
        foreach ($n in $k.GetValueNames()) {
            if (-not $n) { continue }
            [void]$lista.Add(@{
                id      = ($s.Label + '|' + $n)
                name    = $n
                cmd     = "$(Get-RegVal $s.Run $n)"
                source  = $s.Label
                app     = $s.App
                appname = $n
                enabled = [bool](Test-StartupEnabled $s.App $n)
            })
        }
    }
    foreach ($f in $StartupFolders) {
        if (-not $f.Dir -or -not (Test-Path $f.Dir)) { continue }
        Get-ChildItem -LiteralPath $f.Dir -File -ErrorAction SilentlyContinue |
            Where-Object { $_.Extension -ne '.ini' } |
            ForEach-Object {
                [void]$lista.Add(@{
                    id      = ($f.Label + '|' + $_.Name)
                    name    = $_.BaseName
                    cmd     = $_.FullName
                    source  = $f.Label
                    app     = $f.App
                    appname = $_.Name
                    enabled = [bool](Test-StartupEnabled $f.App $_.Name)
                })
            }
    }
    return ,$lista
}

function Send-Startup {
    param($Lista)
    $sync.Startup = @($Lista)
    Send @{ type = 'startup' }
}

# =====================================================================
#  POMIAR WYDAJNOSCI
#
#  Program, ktory zmienia ustawienia i nie potrafi pokazac efektu, jest
#  programem na wiare. Te kilka liczb da sie zebrac bez zadnych zewnetrznych
#  narzedzi i wystarczaja, zeby zobaczyc, czy cokolwiek drgnelo.
#
#  Czas rozruchu bierzemy z Dziennika zdarzen (Diagnostics-Performance,
#  zdarzenie 100). Windows zapisuje tam po kazdym starcie:
#    BootTime          - calkowity czas rozruchu
#    MainPathBootTime  - czas do momentu, gdy pulpit jest gotowy
#  Ta wartosc aktualizuje sie WYLACZNIE po ponownym uruchomieniu komputera.
# =====================================================================
function Get-BootTimes {
    $wynik = @{ boot = $null; main = $null; kiedy = $null }
    try {
        $ev = Get-WinEvent -FilterHashtable @{
                  LogName = 'Microsoft-Windows-Diagnostics-Performance/Operational'
                  Id      = 100
              } -MaxEvents 1 -ErrorAction Stop
        if ($ev) {
            $x = [xml]$ev.ToXml()
            foreach ($d in $x.Event.EventData.Data) {
                if ($d.Name -eq 'BootTime')         { $wynik.boot = [int]$d.'#text' }
                if ($d.Name -eq 'MainPathBootTime') { $wynik.main = [int]$d.'#text' }
            }
            $wynik.kiedy = $ev.TimeCreated.ToString('yyyy-MM-dd HH:mm')
        }
    } catch { }
    return $wynik
}

function Get-Snapshot {
    $s = @{
        data      = (Get-Date).ToString('yyyy-MM-dd HH:mm')
        procesy   = 0
        uslugi    = 0
        ramPct    = 0
        ramGB     = 0.0
        autostart = 0
        boot      = $null
        main      = $null
        bootKiedy = $null
        uptimeMin = 0
    }
    try { $s.procesy = @(Get-Process -ErrorAction SilentlyContinue).Count } catch { }
    try { $s.uslugi  = @(Get-Service -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Running' }).Count } catch { }
    try {
        $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
        $tot = [double]$os.TotalVisibleMemorySize
        $use = $tot - [double]$os.FreePhysicalMemory
        $s.ramPct = [int](($use / $tot) * 100)
        $s.ramGB  = [math]::Round($use / 1MB, 1)
        $s.uptimeMin = [int]((New-TimeSpan -Start $os.LastBootUpTime -End (Get-Date)).TotalMinutes)
    } catch { }
    try { $s.autostart = @((Get-StartupItems) | Where-Object { $_.enabled }).Count } catch { }
    $bt = Get-BootTimes
    $s.boot = $bt.boot; $s.main = $bt.main; $s.bootKiedy = $bt.kiedy
    return $s
}

function Save-Snapshot {
    param($S)
    try { ($S | ConvertTo-Json -Depth 5) | Set-Content -LiteralPath $sync.BenchFile -Encoding UTF8; return $true }
    catch { Log ('Nie udalo sie zapisac pomiaru: ' + $_.Exception.Message) 'err'; return $false }
}

function Load-Snapshot {
    if (-not (Test-Path $sync.BenchFile)) { return $null }
    try { return (Get-Content -Raw -LiteralPath $sync.BenchFile -Encoding UTF8 | ConvertFrom-Json) }
    catch { return $null }
}

function Fmt-Sek { param($ms) if ($null -eq $ms) { return 'brak danych' } else { return ('{0:N1} s' -f ($ms / 1000.0)) } }

# jedna linia porownania: nazwa, przed, po, roznica
function Cmp-Line {
    param([string]$Nazwa, $Przed, $Po, [string]$Jedn = '', [bool]$MniejLepiej = $true, [int]$Dziesietne = 0)
    if ($null -eq $Przed -or $null -eq $Po) { return "$Nazwa : brak danych" }
    $p = [double]$Przed; $k = [double]$Po
    $d = $k - $p
    $fmt = "N$Dziesietne"
    $txt = "{0} : {1} -> {2}" -f $Nazwa, $p.ToString($fmt), $k.ToString($fmt)
    if ($Jedn) { $txt += " $Jedn" }
    if ([math]::Abs($d) -lt 0.05) { return "$txt   (bez zmian)" }
    $znak = if ($d -gt 0) { '+' } else { '' }
    $lepiej = if ($MniejLepiej) { $d -lt 0 } else { $d -gt 0 }
    $ocena  = if ($lepiej) { 'lepiej' } else { 'gorzej' }
    return ("{0}   ({1}{2}, {3})" -f $txt, $znak, $d.ToString($fmt), $ocena)
}

function Send-Bench { param([string]$Txt) Send @{ type = 'bench'; text = $Txt } }

# =====================================================================
#  DYSPOZYTOR
# =====================================================================
$script:BK = Load-Backup

switch ($mode) {

    'apply' {
        $n = @($ids).Count; $i = 0
        $script:ApplyOk = @{}
        foreach ($id in $ids) {
            $i++
            Prog ([int]((($i - 1) / [double]$n) * 100))
            if (-not $A.ContainsKey($id)) { Log "Nieznane zadanie: $id" 'warn'; continue }
            Begin-Task $id
            try { & $A[$id]; $script:ApplyOk[$id] = $true } catch { Log ("BLAD [$id]: " + $_.Exception.Message) 'err'; $script:ApplyOk[$id] = $false }
        }
        Save-Backup

        # ------------------------------------------------------------------
        #  WERYFIKACJA
        #  Zastosowanie zmiany to nie to samo, co jej wejscie w zycie.
        #  Kazde zadanie, ktore ma test stanu, sprawdzamy od razu po zapisie
        #  i mowimy wprost, czy sie udalo.
        #
        #  Zadania jednorazowe (czyszczenie, naprawa, otwarcie okna) nie maja
        #  testu - nie da sie ich "sprawdzic" jak przelacznika. Bez wpisu
        #  ponizej taka karta zostawalaby zawieszona w pulsujacym "W toku..."
        #  na zawsze, bo nikt nigdy nie wysylalby dla niej kolejnego stanu -
        #  dokladnie to zglosil uzytkownik (Kosz i cache DNS utkniete mimo
        #  wyraznego "Zakonczono" w konsoli). Zamiast tego mowimy wprost:
        #  wykonano albo sie nie udalo, na podstawie tego, czy blok Apply
        #  rzucil wyjatek.
        # ------------------------------------------------------------------
        Status 'Weryfikacja zmian...'
        Prog 100
        $vOk = 0; $vNie = 0; $vNiepewne = 0
        foreach ($id in $ids) {
            if ($T.ContainsKey($id)) {
                $r = $null
                try { $r = & $T[$id] } catch { $r = $null }
                if ($r -eq $true) {
                    Send @{ type='state'; id=$id; state='on' }
                    Log "  potwierdzone: $id" 'ok'
                    $vOk++
                } elseif ($r -eq $false) {
                    Send @{ type='state'; id=$id; state='off' }
                    Log "  NIE WESZLO: $id - system odrzucil zmiane" 'err'
                    $vNie++
                } else {
                    Send @{ type='state'; id=$id; state='unknown' }
                    Log "  nie da sie zweryfikowac: $id" 'warn'
                    $vNiepewne++
                }
            } elseif ($A.ContainsKey($id)) {
                if ($script:ApplyOk[$id]) {
                    Send @{ type='state'; id=$id; state='done' }
                    $vOk++
                } else {
                    Send @{ type='state'; id=$id; state='unknown' }
                    $vNiepewne++
                }
            }
        }
        if (($vOk + $vNie + $vNiepewne) -gt 0) {
            $pod = "Weryfikacja: $vOk potwierdzonych"
            if ($vNie -gt 0)      { $pod += ", $vNie nieudanych" }
            if ($vNiepewne -gt 0) { $pod += ", $vNiepewne niepewnych" }
            if ($vNie -gt 0) { Log $pod 'err' } else { Log $pod 'ok' }
        }
        Send @{ type='backup'; ids=@($script:BK.Keys) }
    }

    'revert' {
        # Ten sam blad co przy 'apply': karta dostawala "running" na
        # poczatku cofania, ale nigdy kolejnego stanu po zakonczeniu -
        # zostawala zawieszona w pulsujacym "W toku..." na zawsze, a przycisk
        # "Cofnij"/Ostatnie dzialania na Pulpicie tez sie nie odswiezaly (brak
        # wiadomosci 'backup'). Po kazdym cofnieciu odpytujemy test zadania
        # jeszcze raz - to najdokladniejszy sposob, zeby pokazac prawdziwy
        # stan (powinien wypasc na "nie zastosowane"), a nie zakladac go na sile.
        $list = @($ids)
        if ($list -contains '__all__') { $list = @($script:BK.Keys) }
        if ($list.Count -eq 0) { Log 'Nie ma czego cofac - kopia zapasowa jest pusta.' 'warn' }
        $n = $list.Count; $i = 0
        foreach ($id in $list) {
            $i++
            Prog ([int]((($i - 1) / [double][Math]::Max($n,1)) * 100))
            if (-not $script:BK.ContainsKey($id)) { Log "Brak kopii zapasowej dla: $id" 'warn'; continue }
            Send @{ type='state'; id=$id; state='running' }
            Log "Cofanie: $id"
            $entries = @($script:BK[$id])
            [array]::Reverse($entries)
            foreach ($e in $entries) {
                try { Restore-Entry $e } catch { Log ("  blad: " + $_.Exception.Message) 'err' }
            }
            $script:BK.Remove($id)
            Log "Cofnieto: $id" 'ok'

            if ($T.ContainsKey($id)) {
                $r = $null
                try { $r = & $T[$id] } catch { $r = $null }
                if     ($r -eq $true)  { Send @{ type='state'; id=$id; state='on' } }
                elseif ($r -eq $false) { Send @{ type='state'; id=$id; state='off' } }
                else                   { Send @{ type='state'; id=$id; state='unknown' } }
            } else {
                Send @{ type='state'; id=$id; state='unknown' }
            }
        }
        Save-Backup
        Send @{ type='backup'; ids=@($script:BK.Keys) }
        NeedReboot
    }

    'scan' {
        Status 'Sprawdzanie stanu systemu...'
        $keys = @($T.Keys)
        $n = $keys.Count; $i = 0
        foreach ($k in $keys) {
            $i++
            Prog ([int](($i / [double]$n) * 100))
            $r = $null
            try { $r = & $T[$k] } catch { $r = $null }
            $state = 'unknown'
            if ($r -eq $true) { $state = 'on' } elseif ($r -eq $false) { $state = 'off' }
            Send @{ type='state'; id=$k; state=$state }
        }
        # ktore zadania da sie cofnac
        Send @{ type='backup'; ids=@($script:BK.Keys) }
        Status 'Stan odswiezony.'
    }

    'bench_base' {
        Status 'Zapisywanie punktu odniesienia...'
        $s = Get-Snapshot
        if (Save-Snapshot $s) {
            Log 'Punkt odniesienia zapisany.' 'ok'
            Log ("  czas rozruchu: " + (Fmt-Sek $s.boot) + "   procesy: " + $s.procesy + "   uslugi: " + $s.uslugi)
            Log ("  pamiec: " + $s.ramPct + "%   autostart: " + $s.autostart + " pozycji")
            $txt  = "PUNKT ODNIESIENIA zapisany " + $s.data + "`n"
            $txt += "Czas rozruchu: " + (Fmt-Sek $s.boot) + "   |   do pulpitu: " + (Fmt-Sek $s.main) + "`n"
            $txt += "Procesy: " + $s.procesy + "   |   uslugi: " + $s.uslugi + "   |   pamiec: " + $s.ramPct + "% (" + $s.ramGB + " GB)`n"
            $txt += "Autostart: " + $s.autostart + " wlaczonych pozycji`n`n"
            $txt += "Teraz zastosuj zmiany, uruchom komputer ponownie i kliknij `"Zmierz teraz`"."
            Send-Bench $txt
        }
    }

    'bench_now' {
        Status 'Pomiar...'
        $stary = Load-Snapshot
        $nowy  = Get-Snapshot
        if (-not $stary) {
            Log 'Brak punktu odniesienia - najpierw kliknij "Zapisz punkt odniesienia".' 'warn'
            $txt  = "Nie ma z czym porownywac.`n`n"
            $txt += "Stan teraz: rozruch " + (Fmt-Sek $nowy.boot) + ", procesy " + $nowy.procesy
            $txt += ", uslugi " + $nowy.uslugi + ", pamiec " + $nowy.ramPct + "%, autostart " + $nowy.autostart + "`n`n"
            $txt += "Kliknij `"Zapisz punkt odniesienia`", zeby zaczac mierzyc."
            Send-Bench $txt
        } else {
            $txt  = "PORÓWNANIE   " + $stary.data + "  ->  " + $nowy.data + "`n`n"
            if ($null -ne $stary.boot -and $null -ne $nowy.boot -and $stary.bootKiedy -eq $nowy.bootKiedy) {
                $txt += "Czas rozruchu: bez restartu ta wartosc sie nie zmieni.`n"
                $txt += "Uruchom komputer ponownie i zmierz jeszcze raz.`n`n"
                Log 'Czas rozruchu pochodzi z tego samego startu systemu - potrzebny restart.' 'warn'
            } else {
                $txt += (Cmp-Line 'Czas rozruchu   ' $stary.boot $nowy.boot 'ms' $true) + "`n"
                $txt += (Cmp-Line 'Czas do pulpitu ' $stary.main $nowy.main 'ms' $true) + "`n"
            }
            $txt += (Cmp-Line 'Procesy         ' $stary.procesy   $nowy.procesy   ''   $true) + "`n"
            $txt += (Cmp-Line 'Uslugi dzialajace' $stary.uslugi   $nowy.uslugi    ''   $true) + "`n"
            $txt += (Cmp-Line 'Pamiec zajeta   ' $stary.ramPct    $nowy.ramPct    '%'  $true) + "`n"
            $txt += (Cmp-Line 'Autostart       ' $stary.autostart $nowy.autostart ''   $true) + "`n`n"
            $txt += "Uwaga: pamiec i procesy zaleza od tego, co masz akurat otwarte."
            Send-Bench $txt

            Log '--- Porownanie z punktem odniesienia ---' 'ok'
            Log ("  rozruch: " + (Fmt-Sek $stary.boot) + " -> " + (Fmt-Sek $nowy.boot))
            Log ("  procesy: " + $stary.procesy + " -> " + $nowy.procesy + "   uslugi: " + $stary.uslugi + " -> " + $nowy.uslugi)
            Log ("  autostart: " + $stary.autostart + " -> " + $nowy.autostart)
        }
    }

    'net_scan' {
        Status 'Diagnostyka lacza...'
        $rows = Get-NetDiag
        Prog 70
        $props = Get-NetPropList
        Send-Net $rows $props
        Log 'Pomiar lacza zakonczony.' 'ok'
    }

    'net_prop' {
        $ad = Get-ActiveAdapter
        if (-not $ad) { Log 'Brak aktywnej karty sieciowej.' 'err' }
        else {
            $wsz = Get-NetPropAll $ad
            foreach ($kw in $ids) {
                $def = $NetProps | Where-Object { $_.kw -eq $kw } | Select-Object -First 1
                if (-not $def) { continue }
                $cur = Find-NetProp $wsz $kw
                if (-not $cur) { Log "Karta nie ma wlasciwosci $kw." 'warn'; continue }
                $stara = "$(@($cur.RegistryValue)[0])"
                if ($stara -eq $def.cel) { Log ("  " + $def.nazwa + ": juz wylaczone"); continue }
                try {
                    Rec @{ k='netprop'; adapter="$($ad.Name)"; kw="$kw"; val=$stara }
                    # -InputObject celuje w konkretny obiekt, wiec gwiazdka
                    # w nazwie klucza nie jest juz traktowana jak wieloznacznik
                    Set-NetAdapterAdvancedProperty -InputObject $cur -RegistryValue $def.cel `
                                                   -NoRestart -ErrorAction Stop
                    # sprawdzamy, czy naprawde weszlo - sterowniki bywaja uparte
                    $po = Find-NetProp (Get-NetPropAll $ad) $kw
                    if ($po -and "$(@($po.RegistryValue)[0])" -eq $def.cel) {
                        Log ("  " + $def.nazwa + ": wylaczone (bylo " + $stara + ")") 'ok'
                    } else {
                        Log ("  " + $def.nazwa + ": sterownik odrzucil zmiane") 'err'
                    }
                } catch { Log ("  " + $def.nazwa + ": " + $_.Exception.Message) 'err' }
            }
            Save-Backup
            Send @{ type='backup'; ids=@($script:BK.Keys) }
            Send-Net (Get-NetDiag) (Get-NetPropList)
        }
    }

    'proc_scan' {
        Status 'Odczyt procesów...'
        Send-Procs (Get-ProcList)
    }

    'proc_kill' {
        foreach ($n in $ids) {
            if ($ProcChronione -contains $n) { Log "Proces chroniony, pomijam: $n" 'warn'; continue }
            try {
                Stop-Process -Name $n -Force -ErrorAction Stop
                Log "Zamknieto proces: $n" 'ok'
            } catch { Log ("Nie udalo sie zamknac " + $n + ": " + $_.Exception.Message) 'warn' }
        }
        Start-Sleep -Milliseconds 400
        Send-Procs (Get-ProcList)
    }

    'appx_scan' {
        Status 'Odczyt aplikacji wbudowanych...'
        Send-Apps (Get-AppxList)
    }

    'appx_remove' {
        foreach ($full in $ids) {
            try {
                Remove-AppxPackage -Package $full -ErrorAction Stop
                Log ("Usunieto aplikacje: " + ($full -split '_')[0]) 'ok'
            } catch { Log ("Nie udalo sie usunac " + ($full -split '_')[0] + ": " + $_.Exception.Message) 'err' }
        }
        Send-Apps (Get-AppxList)
    }

    'startup_scan' {
        Status 'Odczyt autostartu...'
        Send-Startup (Get-StartupItems)
        Status 'Lista autostartu odswiezona.'
    }

    'startup_toggle' {
        $lista = Get-StartupItems
        foreach ($id in $ids) {
            $it = $lista | Where-Object { $_.id -eq $id } | Select-Object -First 1
            if (-not $it) { Log "Nie znaleziono pozycji autostartu: $id" 'warn'; continue }
            $nowy = -not $it.enabled
            try {
                Set-StartupEnabled $it.app $it.appname $nowy
                if ($nowy) { Log ("Autostart WLACZONY: "  + $it.name) 'ok' }
                else       { Log ("Autostart WYLACZONY: " + $it.name + " - nie bedzie startowal z systemem") 'ok' }
            } catch {
                Log ("Nie udalo sie zmienic pozycji " + $it.name + ": " + $_.Exception.Message) 'err'
            }
        }
        Send-Startup (Get-StartupItems)
    }

    'games_scan' { Send-Games (Load-Games) }

    'games_add' {
        $l = New-Object System.Collections.ArrayList
        foreach ($x in @(Load-Games)) { [void]$l.Add($x) }
        foreach ($p in $ids) {
            if (-not ($l | Where-Object { $_.path -eq $p })) {
                [void]$l.Add(@{ name = [System.IO.Path]::GetFileNameWithoutExtension($p); path = $p })
                Log "Dodano gre: $p" 'ok'
            } else { Log 'Ta gra jest juz na liscie.' 'warn' }
        }
        Save-Games $l
        Send-Games $l
    }

    'games_del' {
        $l = Load-Games
        $keep = New-Object System.Collections.ArrayList
        foreach ($g in $l) { if ($ids -notcontains $g.path) { [void]$keep.Add($g) } }
        Save-Games $keep
        Log 'Usunieto z listy.' 'ok'
        Send-Games $keep
    }

    'games_opt' {
        $l = Load-Games
        $sel = @($ids)
        if ($sel -contains '__all__') { $sel = @($l | ForEach-Object { $_.path }) }
        $n = [Math]::Max($sel.Count, 1); $i = 0
        foreach ($p in $sel) {
            $i++; Prog ([int]((($i - 1) / [double]$n) * 100))
            $g = @($l | Where-Object { $_.path -eq $p })[0]
            if ($g) { Optimize-Game $g.path $g.name }
        }
        Send-Games $l
    }

    'games_revert' {
        $l = Load-Games
        $sel = @($ids)
        if ($sel -contains '__all__') { $sel = @($l | ForEach-Object { $_.path }) }
        foreach ($p in $sel) {
            $g = @($l | Where-Object { $_.path -eq $p })[0]
            if ($g) { Revert-Game $g.path $g.name }
        }
        Send-Games $l
    }

    'games_clean' {
        $l = New-Object System.Collections.ArrayList
        $usuniete = 0
        foreach ($x in @(Load-Games)) {
            if (Test-Path -LiteralPath $x.path) { [void]$l.Add($x) }
            else { Log ("Usunieto martwy wpis: " + $x.name) 'ok'; $usuniete++ }
        }
        Save-Games $l
        if ($usuniete -gt 0) { Log "Usunieto wpisow bez pliku: $usuniete." 'ok' }
        else { Log 'Wszystkie gry z listy istnieja na dysku.' 'ok' }
        Send-Games $l
    }

    'games_detect' {
        # Budujemy wlasna kolekcje zamiast polegac na typie zwroconym z funkcji.
        $l = New-Object System.Collections.ArrayList
        foreach ($x in @(Load-Games)) { [void]$l.Add($x) }
        $d = Detect-Games
        $added = 0
        foreach ($f in $d) {
            if (-not ($l | Where-Object { $_.path -eq $f.path })) { [void]$l.Add($f); $added++ }
        }
        Save-Games $l
        if ($added -gt 0) { Log "Wykryto i dodano $added nowych gier." 'ok' }
        else { Log 'Nie znaleziono nowych gier.' 'warn' }
        Send-Games $l
    }

    'diag' {
        $sync.DiagData = Collect-Diag
        Send @{ type='diag' }
        Log 'Skanowanie diagnostyczne zakonczone.' 'ok'
    }

    'report' {
        if (-not $sync.DiagData) {
            Log 'Brak danych - najpierw skanuje system...'
            $sync.DiagData = Collect-Diag
            Send @{ type='diag' }
        }
        Status 'Generowanie raportu HTML...'
        $p = Write-Report $sync.DiagData
        Log "Raport zapisany: $p" 'ok'
        Send @{ type='report'; path=$p }
    }
}

Prog 100
Send @{ type='done'; mode=$mode }
'@

# =====================================================================
#  UI: LOG I STATUS
# =====================================================================
function Br {
    param($hex)
    # Kolory wpisane w kodzie (pigulki, kropki, sekcje) ida przez te sama
    # mape co XAML - inaczej po zmianie motywu polowa interfejsu zostalaby
    # w starej palecie.
    $k = "$hex".ToUpper()
    if ($script:Motyw -and $script:Motyw.Mapa.ContainsKey($k)) {
        $w = "$($script:Motyw.Mapa[$k])"
        if ($w -match '^#([0-9A-Fa-f]{6}|[0-9A-Fa-f]{8})$') { $hex = $w }
    }
    New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString($hex))
}

# =====================================================================
#  SILNIK ANIMACJI
#
#  Wszystko chodzi na wlasnych, per-element obiektach: kazda karta
#  dostaje swoj pedzel i swoja transformacje. Dzieki temu animacja
#  jednej karty nie rusza pozostalych - wspoldzielony pedzel ze stylu
#  probowalby animowac sto kart naraz.
# =====================================================================
$script:MotionOn = $true

function Get-Ease {
    # 'Pop' daje lekkie przestrzelenie i odbicie (jak EasePop w XAML) -
    # do miejsc, gdzie chcemy podkreslic zakonczenie akcji, a nie tylko
    # plynne dojechanie do wartosci.
    param([string]$Mode = 'Out')
    if ($Mode -eq 'Pop') {
        $e = New-Object Windows.Media.Animation.BackEase
        $e.EasingMode = 'EaseOut'
        $e.Amplitude  = 0.4
        return $e
    }
    $e = New-Object Windows.Media.Animation.CubicEase
    if ($Mode -eq 'In') { $e.EasingMode = 'EaseIn' } else { $e.EasingMode = 'EaseOut' }
    return $e
}

function New-Anim {
    param([double]$To, $From = $null, [int]$Ms = 220, [int]$Delay = 0, [bool]$Ease = $true, [string]$EaseMode = 'Out')
    $a = New-Object Windows.Media.Animation.DoubleAnimation
    if ($null -ne $From) { $a.From = [double]$From }
    $a.To       = $To
    $a.Duration = New-Object Windows.Duration ([TimeSpan]::FromMilliseconds($Ms))
    if ($Delay -gt 0) { $a.BeginTime = [TimeSpan]::FromMilliseconds($Delay) }
    if ($Ease) { $a.EasingFunction = (Get-Ease $EaseMode) }
    return $a
}

function Fade {
    param($El, [double]$To, [int]$Ms = 220, $From = $null, [int]$Delay = 0)
    if (-not $El) { return }
    if (-not $script:MotionOn) { $El.Opacity = $To; return }
    try { $El.BeginAnimation([Windows.UIElement]::OpacityProperty, (New-Anim $To $From $Ms $Delay)) } catch {}
}

function Get-Shift {
    # Zwraca wlasna transformacje przesuniecia elementu (tworzy przy pierwszym uzyciu).
    param($El)
    if (-not $El) { return $null }
    $t = $El.RenderTransform
    if ($t -is [Windows.Media.TranslateTransform]) { return $t }
    $t = New-Object Windows.Media.TranslateTransform
    $El.RenderTransform = $t
    return $t
}

function Shift {
    param($El, [double]$To, $From = $null, [int]$Ms = 260, [int]$Delay = 0, [string]$EaseMode = 'Out')
    if (-not $El) { return }
    $t = Get-Shift $El
    if (-not $t) { return }
    if (-not $script:MotionOn) { $t.Y = $To; return }
    try { $t.BeginAnimation([Windows.Media.TranslateTransform]::YProperty, (New-Anim $To $From $Ms $Delay $true $EaseMode)) } catch {}
}

function Tint {
    param($Brush, [string]$Hex, [int]$Ms = 170)
    if (-not $Brush) { return }
    # kolor docelowy animacji tez musi przejsc przez mape motywu,
    # inaczej najazd na karte wracalby do bazowej palety
    $k = "$Hex".ToUpper()
    if ($script:Motyw -and $script:Motyw.Mapa.ContainsKey($k)) {
        $w = "$($script:Motyw.Mapa[$k])"
        if ($w -match '^#([0-9A-Fa-f]{6}|[0-9A-Fa-f]{8})$') { $Hex = $w }
    }
    try {
        $c = New-Object Windows.Media.Animation.ColorAnimation
        $c.To       = [Windows.Media.Color][Windows.Media.ColorConverter]::ConvertFromString($Hex)
        $c.Duration = New-Object Windows.Duration ([TimeSpan]::FromMilliseconds($Ms))
        $Brush.BeginAnimation([Windows.Media.SolidColorBrush]::ColorProperty, $c)
    } catch {}
}

function Tint-Color {
    # Jak Tint, tylko bierze gotowy obiekt Color zamiast hex-a z mapy
    # motywu - do miejsc, gdzie kolor juz jest wyliczony na zywo z
    # aktywnego motywu (np. szklane karty), wiec druga mapa by tylko
    # przeszkadzala.
    param($Brush, $Color, [int]$Ms = 170)
    if (-not $Brush) { return }
    try {
        $c = New-Object Windows.Media.Animation.ColorAnimation
        $c.To       = $Color
        $c.Duration = New-Object Windows.Duration ([TimeSpan]::FromMilliseconds($Ms))
        $Brush.BeginAnimation([Windows.Media.SolidColorBrush]::ColorProperty, $c)
    } catch {}
}

function Get-Scale {
    # Jak Get-Shift, tylko dla powiekszenia/pomniejszenia zamiast przesuniecia.
    param($El)
    if (-not $El) { return $null }
    $t = $El.RenderTransform
    if ($t -is [Windows.Media.ScaleTransform]) { return $t }
    $t = New-Object Windows.Media.ScaleTransform 1,1
    $El.RenderTransform = $t
    return $t
}

function Pop-In {
    # Wejscie ze skalowaniem i odbiciem - do jednorazowych akcentow (np.
    # logo przy starcie), nie do rzeczy powtarzanych masowo.
    param($El, [double]$From = 0.3, [int]$Ms = 420, [int]$Delay = 0)
    if (-not $El) { return }
    $t = Get-Scale $El
    if (-not $t) { return }
    if (-not $script:MotionOn) { $t.ScaleX = 1; $t.ScaleY = 1; return }
    try {
        $t.BeginAnimation([Windows.Media.ScaleTransform]::ScaleXProperty, (New-Anim 1 $From $Ms $Delay $true 'Pop'))
        $t.BeginAnimation([Windows.Media.ScaleTransform]::ScaleYProperty, (New-Anim 1 $From $Ms $Delay $true 'Pop'))
    } catch {}
}

function Ping-Ring {
    # Pierscien, ktory raz "pukuje": rozszerza sie i gasnie. Uzywany tylko
    # przy starcie programu na znaczku w pasku tytulu - nigdzie indziej,
    # zeby nie stalo sie to meczacym tikiem.
    param($El, [int]$Ms = 900, [int]$Delay = 0)
    if (-not $El -or -not $script:MotionOn) { return }
    $t = Get-Scale $El
    if (-not $t) { return }
    try {
        $El.Opacity = 0.7
        $t.BeginAnimation([Windows.Media.ScaleTransform]::ScaleXProperty, (New-Anim 2.0 0.6 $Ms $Delay $true 'Out'))
        $t.BeginAnimation([Windows.Media.ScaleTransform]::ScaleYProperty, (New-Anim 2.0 0.6 $Ms $Delay $true 'Out'))
        $El.BeginAnimation([Windows.UIElement]::OpacityProperty, (New-Anim 0 0.7 $Ms $Delay $true 'Out'))
    } catch {}
}

function Set-Bar {
    # Pasek postepu dojezdza plynnie zamiast przeskakiwac. Przy krokach
    # posrednich (nie na 0 i nie na 100) dokladamy lekkie odbicie -
    # przy samych krancach wygladaloby to na "utkniecie" w scianie.
    param($Bar, [double]$To, [int]$Ms = 300)
    if (-not $Bar) { return }
    $mode = if ($To -gt 0.5 -and $To -lt 99.5) { 'Pop' } else { 'Out' }
    try { $Bar.BeginAnimation([Windows.Controls.Primitives.RangeBase]::ValueProperty, (New-Anim $To $null $Ms 0 $true $mode)) } catch {}
}

function Add-CardMotion {
    # "Szklana" karta: tlo jest czesciowo przezroczyste (przy wlaczonej
    # Mice realnie przebija przez nie tlo pulpitu Windows - patrz
    # Apply-Mica), a cienka, jasna obwodka na krawedzi udaje odbicie
    # swiatla, zamiast plaskiej ciemnej ramki. Pod kursorem obwodka
    # przechodzi w kolor akcentu, a tlo lekko gestnieje.
    #
    # Kolory bierzemy na zywo z zasobow aktywnego motywu (Surface,
    # Surface2, Accent), wiec dziala poprawnie w kazdej z dziewieciu skorek
    # bez dopisywania czegokolwiek do map kolorow - te zasoby juz sa
    # przemalowane, gdy program tu dochodzi.
    param($El)
    if (-not $El) { return }

    $surf   = $Window.FindResource('Surface').Color
    $surf2  = $Window.FindResource('Surface2').Color
    $accent = $Window.FindResource('Accent').Color

    $cBg    = [Windows.Media.Color]::FromArgb(206, $surf.R,  $surf.G,  $surf.B)
    $cBgHot = [Windows.Media.Color]::FromArgb(226, $surf2.R, $surf2.G, $surf2.B)
    $cBd    = [Windows.Media.Color]::FromArgb(58,  255, 255, 255)
    $cBdHot = [Windows.Media.Color]::FromArgb(150, $accent.R, $accent.G, $accent.B)

    $bgB = New-Object Windows.Media.SolidColorBrush $cBg
    $bdB = New-Object Windows.Media.SolidColorBrush $cBd
    $El.Background      = $bgB
    $El.BorderBrush     = $bdB
    $El.BorderThickness = New-Object Windows.Thickness 1.2
    $null = Get-Shift $El
    $El.Add_MouseEnter({
        Tint-Color $bgB $cBgHot 160
        Tint-Color $bdB $cBdHot 160
        Shift $El -2 $null 190
    }.GetNewClosure())
    $El.Add_MouseLeave({
        Tint-Color $bgB $cBg 240
        Tint-Color $bdB $cBd 240
        Shift $El 0 $null 240
    }.GetNewClosure())
}

function Show-Panel {
    # Wejscie zakladki: panel wjezdza z dolu, a jego pierwsze karty
    # pojawiaja sie jedna po drugiej z niewielkim opoznieniem.
    param($Panel, [int]$Max = 12)
    if (-not $Panel) { return }
    if (-not $script:MotionOn) { return }
    Fade $Panel 1 200 0.35
    $i = 0
    foreach ($ch in $Panel.Children) {
        if ($i -ge $Max) { break }
        if ($ch -is [Windows.UIElement]) {
            Fade  $ch 1 240 0 ($i * 26)
            Shift $ch 0 16 300 ($i * 26)
            $i++
        }
    }
}

function Pulse {
    param($El, [double]$From = 0.2)
    Fade $El 1 320 $From
}

# =====================================================================
#  PASEK POWIADOMIEN
#  Log w konsoli zostaje, ale przy zwinietej konsoli nie bylo widac,
#  ze cokolwiek sie skonczylo. To wysuwa sie nad paskiem akcji
#  i znika samo po trzech sekundach.
# =====================================================================
$script:ToastTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:ToastTimer.Interval = [TimeSpan]::FromMilliseconds(3000)
$script:ToastTimer.Add_Tick({
    $script:ToastTimer.Stop()
    Fade  $UI.Toast 0 260
    Shift $UI.Toast 14 $null 260
})

function Toast {
    param([string]$Text, [string]$Level = 'ok')
    if (-not $UI.Toast) { return }
    $UI.ToastText.Text = $Text
    switch ($Level) {
        'warn' { $UI.ToastIcon.Text = [char]0xE7BA; $UI.ToastIcon.Foreground = $Colors.warn; $UI.ToastRing.Stroke = $Colors.warn }
        'err'  { $UI.ToastIcon.Text = [char]0xEA39; $UI.ToastIcon.Foreground = $Colors.err;  $UI.ToastRing.Stroke = $Colors.err  }
        default{ $UI.ToastIcon.Text = [char]0xE930; $UI.ToastIcon.Foreground = $Colors.ok;   $UI.ToastRing.Stroke = $Colors.ok   }
    }
    Fade  $UI.Toast 1 200
    Shift $UI.Toast 0 16 320
    # Zakonczenie dostaje wlasny, maly "pop": ikona wjezdza z odbiciem,
    # a przy sukcesie do tego jeden gasnacy pierscien - to samo, co przy
    # logo na starcie, tylko w miniaturze i za kazdym razem, gdy cos sie
    # naprawde skonczylo.
    Pop-In $UI.ToastIcon 0.5 300 0
    if ($Level -eq 'ok') { Ping-Ring $UI.ToastRing 620 40 }
    $script:ToastTimer.Stop()
    $script:ToastTimer.Start()
}

# =====================================================================
#  HISTORIA OBCIAZENIA
#  Dwie listy po 60 probek co 1,2 s - okolo dwoch minut wstecz.
#  Nowe punkty wchodza z prawej, siatka jest stala, wiec wykres
#  nie rozciaga sie w miare zbierania danych.
# =====================================================================
$script:HistCpu = New-Object System.Collections.ArrayList
$script:HistRam = New-Object System.Collections.ArrayList

function Push-Hist {
    param($Lista, [double]$V)
    [void]$Lista.Add($V)
    while ($Lista.Count -gt 60) { $Lista.RemoveAt(0) }
}

function Draw-Spark {
    param($Poly, $Lista)
    if (-not $Poly -or -not $UI.SparkHost) { return }
    $w = [double]$UI.SparkHost.ActualWidth
    $h = [double]$UI.SparkHost.ActualHeight
    if ($w -lt 20 -or $h -lt 20 -or $Lista.Count -lt 2) { return }
    $pts = New-Object Windows.Media.PointCollection
    $krok = $w / 59.0
    $n = $Lista.Count
    for ($i = 0; $i -lt $n; $i++) {
        $x = $w - (($n - 1 - $i) * $krok)
        $y = $h - 3 - (([double]$Lista[$i] / 100.0) * ($h - 6))
        $pts.Add((New-Object Windows.Point($x, $y)))
    }
    $Poly.Points = $pts
}

function Draw-Sparks {
    Draw-Spark $UI.SparkCpu $script:HistCpu
    Draw-Spark $UI.SparkRam $script:HistRam
    if ($script:HistCpu.Count -ge 2 -and $UI.SparkPusto.Visibility -eq 'Visible') {
        $UI.SparkPusto.Visibility = 'Collapsed'
    }
    if ($script:HistCpu.Count -ge 2) {
        $sek = [int]($script:HistCpu.Count * 1.2)
        if ($sek -lt 90) { $UI.SparkOkno.Text = "ostatnie $sek s" }
        else             { $UI.SparkOkno.Text = 'ostatnie 2 minuty' }
    }
}

# =====================================================================
#  FILTR ZADAN
#  Przy ponad pieciudziesieciu zadaniach szukanie oczami po opisach
#  trwalo dluzej niz samo kliknięcie. Pole u gory zwija karty,
#  ktore nie pasuja - bez ruszania zaznaczenia.
# =====================================================================
$script:FiltrQ  = ''
$script:FiltrIle = 0

function Apply-Filter {
    if (-not $UI.SearchBox) { return }
    $q = "$($UI.SearchBox.Text)".Trim()
    $script:FiltrQ = $q
    if ($q) {
        $UI.SearchPlace.Visibility = 'Collapsed'
        $UI.SearchClear.Visibility = 'Visible'
    } else {
        $UI.SearchPlace.Visibility = 'Visible'
        $UI.SearchClear.Visibility = 'Collapsed'
    }

    $panel = Get-VisiblePanel
    $trafienia = 0
    foreach ($t in $Tasks) {
        $c = $Cards["$($t.Id)"]
        if (-not $c -or -not $c.Border) { continue }
        $pasuje = $true
        if ($q) {
            $stog = "$($t.Title) $($t.Desc) $($t.Tag)"
            $pasuje = ($stog.IndexOf($q, [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
        }
        if ($pasuje) {
            if ($c.Border.Visibility -ne 'Visible') {
                $c.Border.Visibility = 'Visible'
                Fade  $c.Border 1 200 0
                Shift $c.Border 0 12 260
            }
            if ($CatPanel["$($t.Cat)"] -eq $panel) { $trafienia++ }
        } elseif ($c.Border.Visibility -eq 'Visible') {
            # Zwijamy dopiero po wygaszeniu - skok o pol ekranu przy
            # kazdej wpisanej literze byl nie do czytania.
            $b = $c.Border
            Fade $b 0 130
            $t = New-Object System.Windows.Threading.DispatcherTimer
            $t.Interval = [TimeSpan]::FromMilliseconds(140)
            $t.Add_Tick({
                $t.Stop()
                if ($b.Opacity -lt 0.2) { $b.Visibility = 'Collapsed' }
            }.GetNewClosure())
            $t.Start()
        }
    }
    $script:FiltrIle = $trafienia
    Update-SelInfo
}

# =====================================================================
#  POSTEP NA PASKU ZADAN
#  Ikona programu na pasku zadan wypelnia sie tak samo jak pasek
#  w konsoli - widac postep, nie majac okna na wierzchu.
# =====================================================================
try { $Window.TaskbarItemInfo = New-Object System.Windows.Shell.TaskbarItemInfo } catch { }

function Set-TaskbarProgress {
    param([string]$Stan = 'None', [double]$Ulamek = 0)
    try {
        $ti = $Window.TaskbarItemInfo
        if (-not $ti) { return }
        $ti.ProgressState = $Stan
        if ($Ulamek -lt 0) { $Ulamek = 0 }
        if ($Ulamek -gt 1) { $Ulamek = 1 }
        $ti.ProgressValue = $Ulamek
    } catch { }
}


$Colors = @{
    info = (Br '#9FB3C8')
    ok   = (Br '#34D399')
    warn = (Br '#FBBF24')
    err  = (Br '#F43F5E')
}

function Add-Log {
    param([string]$Text, [string]$Level = 'info')
    $run = New-Object Windows.Documents.Run
    $run.Text = ("[{0}] {1}`n" -f (Get-Date -Format 'HH:mm:ss'), $Text)
    if ($Colors.ContainsKey($Level)) { $run.Foreground = $Colors[$Level] }
    $UI.LogText.Inlines.Add($run)
    if ($UI.LogText.Inlines.Count -gt 700) {
        $first = $UI.LogText.Inlines | Select-Object -First 1
        $UI.LogText.Inlines.Remove($first)
    }
    $UI.LogScroll.ScrollToEnd()
}

function Set-Status {
    param([string]$Text, [string]$Level = 'info')
    $UI.StatusText.Text = $Text
    if ($Colors.ContainsKey($Level)) { $UI.StatusText.Foreground = $Colors[$Level] }
    Pulse $UI.StatusText 0.15
}

# =====================================================================
#  BUDOWA KART
# =====================================================================
if ($Zwarty) {
    foreach ($p in $Pages) { try { $p.Nav.Height = $G.NavH } catch { } }
}

$CatPanel = @{
    Gry = $UI.PanelGry; Sys = $UI.PanelSys; Clean = $UI.PanelClean
    Net = $UI.PanelNet; Tools = $UI.PanelTools; Svc = $UI.PanelSvc
}
$BadgeColor = @{
    'Zalecane' = '#34D399'; 'Restart' = '#60A5FA'
    'Ostrożnie' = '#FBBF24'; 'Wolne' = '#A78BFA'
}
# Zywy, nasycony kolor dla kazdej kategorii zadan - buduje tozsamosc karty
# (tlo, znaczek ikony, poswiata) niezaleznie od tego, czy zadanie ma
# dodatkowa etykiete (Tag) czy nie. Celowo nie idzie przez mape motywu
# (tak samo jak BadgeColor wyzej) - to stale barwy kategorii, nie
# elementy palety, ktore maja sie przemalowywac ze zmiana skorki.
$CatColor = @{
    'Gry' = '#A855F7'; 'Sys' = '#38BDF8'; 'Clean' = '#2DD4BF'
    'Net' = '#818CF8'; 'Tools' = '#FB923C'; 'Svc' = '#F472B6'
}
$PillLook = @{
    on      = @{ t = 'Zastosowane';     bg = '#0F2E24'; fg = '#34D399' }
    off     = @{ t = 'Nie zastosowane'; bg = '#1A2130'; fg = '#8B98A9' }
    unknown = @{ t = '—';               bg = '#161B26'; fg = '#5C6B80' }
    running = @{ t = 'W toku...';       bg = '#132038'; fg = '#60A5FA' }
    done    = @{ t = 'Wykonano';        bg = '#0F2E24'; fg = '#34D399' }
}

# =====================================================================
#  ZNACZKI - wspolne elementy dla kart
#  Znaczek ikony (kolko z bladym tlem w kolorze motywu) i kropka stanu
#  w pigulce - to samo spojne "spojrzenie" powtarzane na kazdej karcie,
#  zamiast goleg glifu plywajacego w powietrzu. Kolor zawsze schodzi
#  z aktywnego zasobu motywu, wiec dziala na wszystkich dziewieciu skorkach
#  bez dopisywania czegokolwiek do map kolorow.
# =====================================================================
function New-IconBadge {
    # "Chip" zamiast kropki: zaokraglony kwadrat z delikatnym gradientem
    # (jasniej w lewym gornym rogu, ciemniej w prawym dolnym - wrazenie
    # malej, wypukłej plytki) i cienka obwodka w kolorze akcentu. Bardziej
    # rozpoznawalny ksztalt niz plaskie kolko, przy tym wciaz dziala na
    # wszystkich dziewieciu skorkach, bo kolor schodzi z zywego zasobu.
    param([string]$Glyph, [double]$Size = 34, [double]$GlyphSize = 15, $Brush = $null)
    if (-not $Brush) { $Brush = $Window.FindResource('Accent') }
    $ac = $Brush.Color

    $badge = New-Object Windows.Controls.Border
    $badge.Width  = $Size
    $badge.Height = $Size
    $badge.CornerRadius = New-Object Windows.CornerRadius ($Size * 0.32)
    $badge.BorderThickness = New-Object Windows.Thickness 1
    $badge.BorderBrush = New-Object Windows.Media.SolidColorBrush (
        [Windows.Media.Color]::FromArgb(80, $ac.R, $ac.G, $ac.B))

    $grad = New-Object Windows.Media.LinearGradientBrush
    $grad.StartPoint = New-Object Windows.Point 0,0
    $grad.EndPoint   = New-Object Windows.Point 1,1
    $stop1 = New-Object Windows.Media.GradientStop ([Windows.Media.Color]::FromArgb(58, $ac.R, $ac.G, $ac.B)), 0
    $stop2 = New-Object Windows.Media.GradientStop ([Windows.Media.Color]::FromArgb(16, $ac.R, $ac.G, $ac.B)), 1
    $grad.GradientStops.Add($stop1)
    $grad.GradientStops.Add($stop2)
    $badge.Background = $grad

    $badge.HorizontalAlignment = 'Center'
    $badge.VerticalAlignment   = 'Center'
    $badge.Effect = New-Object Windows.Media.Effects.DropShadowEffect -Property @{
        Color = $ac; Opacity = 0.30; BlurRadius = 10; ShadowDepth = 0
    }

    $ico = New-Object Windows.Controls.TextBlock
    $ico.Text              = [System.Net.WebUtility]::HtmlDecode($Glyph)
    $ico.FontFamily        = New-Object Windows.Media.FontFamily 'Segoe MDL2 Assets'
    $ico.FontSize          = $GlyphSize
    $ico.Foreground        = $Brush
    $ico.HorizontalAlignment = 'Center'
    $ico.VerticalAlignment   = 'Center'
    $badge.Child = $ico

    return $badge
}

function New-StatusDot {
    # Mala kropka w kolorze pigulki/stanu - dodana obok tekstu, zeby stan
    # dalo sie odczytac kątem oka, bez czytania napisu.
    param([string]$Hex, [double]$Size = 6)
    $d = New-Object Windows.Controls.Border
    $d.Width  = $Size
    $d.Height = $Size
    $d.CornerRadius = New-Object Windows.CornerRadius ($Size / 2)
    $d.Background = Br $Hex
    $d.VerticalAlignment = 'Center'
    $d.Margin = New-Object Windows.Thickness 0,0,6,0
    return $d
}

function New-DotBadge {
    # Kropka stanu w miekkiej, przezroczystej obwodce - ta sama logika
    # co New-IconBadge, tylko mniejsza i bez glifu. Uzywana tam, gdzie
    # karta ma prosty wskaznik wl/wyl zamiast ikony.
    param($Brush, [double]$Size = 20, [double]$DotSize = 9)
    $ac = $Brush.Color

    $wrap = New-Object Windows.Controls.Grid
    $wrap.Width  = $Size
    $wrap.Height = $Size
    $wrap.VerticalAlignment = 'Center'

    $ring = New-Object Windows.Controls.Border
    $ring.Width  = $Size
    $ring.Height = $Size
    $ring.CornerRadius = New-Object Windows.CornerRadius ($Size / 2)
    $ring.Background = New-Object Windows.Media.SolidColorBrush (
        [Windows.Media.Color]::FromArgb(32, $ac.R, $ac.G, $ac.B))

    $dot = New-Object Windows.Controls.Border
    $dot.Width  = $DotSize
    $dot.Height = $DotSize
    $dot.CornerRadius = New-Object Windows.CornerRadius ($DotSize / 2)
    $dot.Background = $Brush
    $dot.HorizontalAlignment = 'Center'
    $dot.VerticalAlignment   = 'Center'

    $wrap.Children.Add($ring) | Out-Null
    $wrap.Children.Add($dot)  | Out-Null
    return @{ Wrap = $wrap; Dot = $dot; Ring = $ring }
}

function New-TaskCard {
    param([hashtable]$Task)

    # Zywy kolor calej karty - wedlug kategorii zadania (Gry/System/Uslugi/
    # Czyszczenie/Siec/Aplikacje). Uzywany do teczowego tla, znaczka ikony
    # i poswiaty pod karta - to on daje kartom rozny, wyrazny charakter,
    # zamiast jednego, wspolnego odcienia dla calej listy.
    $catHex = $CatColor[$Task.Cat]; if (-not $catHex) { $catHex = '#22D3EE' }
    $catCol = [Windows.Media.Color][Windows.Media.ColorConverter]::ConvertFromString($catHex)

    $border = New-Object Windows.Controls.Border
    $border.Style = $Window.FindResource('Card')
    Zageszcz $border
    Add-CardMotion $border
    # Poswiata pod karta w kolorze kategorii zamiast plaskiego, czarnego
    # cienia ze stylu. Robi podwojna robote: w spoczynku to tylko lekki
    # sygnal koloru kategorii, ale w trakcie wykonywania zadania sama
    # poswiata zaczyna pulsowac na zielono - to ona jest teraz "paskiem
    # postepu", zamiast osobnego paska pod opisem. Stonowana (maly promien
    # rozmycia, niska nieprzezroczystosc), zeby nie zlewala sie z sasiednimi
    # kartami w jedna kolorowa plame i nie przygaszala tekstu.
    $glow = New-Object Windows.Media.Effects.DropShadowEffect -Property @{
        Color = $catCol; Opacity = 0.20; BlurRadius = 13; ShadowDepth = 3; Direction = 270
    }
    $border.Effect = $glow

    $grid = New-Object Windows.Controls.Grid
    $widths = @([Windows.GridLength]::Auto, [Windows.GridLength]::Auto,
                (New-Object Windows.GridLength(1, [Windows.GridUnitType]::Star)),
                [Windows.GridLength]::Auto, [Windows.GridLength]::Auto, [Windows.GridLength]::Auto)
    foreach ($w in $widths) {
        $cd = New-Object Windows.Controls.ColumnDefinition
        $cd.Width = $w
        $grid.ColumnDefinitions.Add($cd)
    }

    # --- checkbox ---
    $cb = New-Object Windows.Controls.CheckBox
    $cb.Style  = $Window.FindResource('Chk')
    $cb.Margin = '0,0,14,0'
    if ($Task.Tool) { $cb.Visibility = 'Hidden' } else { $cb.IsChecked = [bool]$Task.Rec }
    [Windows.Controls.Grid]::SetColumn($cb, 0)
    $grid.Children.Add($cb) | Out-Null

    # --- ikona: wieksza, w kolorze kategorii ---
    $ico = New-IconBadge -Glyph $Task.Icon -Size 42 -GlyphSize 18 -Brush (Br $catHex)
    $ico.VerticalAlignment = 'Center'
    $ico.Margin            = '0,0,15,0'
    [Windows.Controls.Grid]::SetColumn($ico, 1)
    $grid.Children.Add($ico) | Out-Null

    # --- tytul i opis ---
    $sp = New-Object Windows.Controls.StackPanel
    $sp.VerticalAlignment = 'Center'

    $titleRow = New-Object Windows.Controls.StackPanel
    $titleRow.Orientation = 'Horizontal'

    $t = New-Object Windows.Controls.TextBlock
    $t.Text = $Task.Title; $t.Foreground = $Window.FindResource('Txt')
    $t.FontSize = 14; $t.FontWeight = 'SemiBold'; $t.VerticalAlignment = 'Center'
    $titleRow.Children.Add($t) | Out-Null

    if ($Task.Tag) {
        $col = $BadgeColor[$Task.Tag]; if (-not $col) { $col = '#8B98A9' }
        # Znaczek dostaje wlasne, przyciemnione tlo w kolorze etykiety zamiast
        # jednego, wspolnego dla wszystkich - latwiej rozroznic "Zalecane"
        # od "Ostroznie" rzutem oka, nie czytajac napisu.
        $fgBrush = Br $col
        $c = $fgBrush.Color
        $bb = New-Object Windows.Controls.Border
        $bb.CornerRadius   = New-Object Windows.CornerRadius 8
        $bb.Background     = New-Object Windows.Media.SolidColorBrush ([Windows.Media.Color]::FromArgb(36, $c.R, $c.G, $c.B))
        $bb.BorderBrush    = New-Object Windows.Media.SolidColorBrush ([Windows.Media.Color]::FromArgb(90, $c.R, $c.G, $c.B))
        $bb.BorderThickness = New-Object Windows.Thickness 1
        $bb.Padding      = New-Object Windows.Thickness 7,1,7,2
        $bb.Margin       = New-Object Windows.Thickness 9,0,0,0
        $bb.VerticalAlignment = 'Center'
        $bt = New-Object Windows.Controls.TextBlock
        $bt.Text = $Task.Tag; $bt.FontSize = 10.5; $bt.FontWeight = 'SemiBold'
        $bt.Foreground = $fgBrush
        $bb.Child = $bt
        $titleRow.Children.Add($bb) | Out-Null
    }
    $sp.Children.Add($titleRow) | Out-Null

    $d = New-Object Windows.Controls.TextBlock
    $d.Text = $Task.Desc; $d.Foreground = $Window.FindResource('Muted')
    $d.FontSize = 11.5; $d.TextWrapping = 'Wrap'; $d.Margin = '0,4,16,0'
    $sp.Children.Add($d) | Out-Null

    # --- uczciwa etykieta: co to realnie daje ---
    if (-not $Task.Tool -and $Zysk.ContainsKey($Task.Id)) {
        $z    = $Zysk[$Task.Id]
        $look = $ZyskLook[$z.k]
        if ($look) {
            $zr = New-Object Windows.Controls.TextBlock
            $zr.TextWrapping = 'Wrap'
            $zr.FontSize = 11
            $zr.Margin = '0,7,16,0'
            $zr.LineHeight = 17

            $lbl = New-Object Windows.Documents.Run
            $lbl.Text = ($look.nazwa + '  ')
            $lbl.Foreground = Br $look.fg
            $lbl.FontWeight = 'SemiBold'
            $zr.Inlines.Add($lbl)

            $txt = New-Object Windows.Documents.Run
            $txt.Text = $z.t
            $txt.Foreground = $Window.FindResource('Dim')
            $zr.Inlines.Add($txt)

            $sp.Children.Add($zr) | Out-Null
        }
    }

    # --- czego program przy tym zadaniu NIE zrobi ---
    # README obiecuje, ze po kazdej zmianie program sprawdza, czy naprawde
    # weszla, i ze kazda zmiane da sie cofnac. Przy czesci zadan - glownie
    # czyszczacych i naprawczych - nie ma czego sprawdzac ani do czego
    # wracac, bo nie zmieniaja ustawien, tylko wykonuja operacje. Zamiast
    # zostawiac to w domysle, karta mowi o tym wprost.
    if (-not $Task.Tool) {
        $bezTestu = -not $Task.Test
        $bezCofki = -not $Task.Rev
        $tresc = ''
        if     ($bezTestu -and $bezCofki) { $tresc = 'program nie potwierdzi, czy zmiana weszła, i nie zapisze jej do przywrócenia' }
        elseif ($bezTestu)                { $tresc = 'program nie potwierdzi, czy zmiana faktycznie weszła' }
        elseif ($bezCofki)                { $tresc = 'tej zmiany nie przywróci przycisk "Przywróć wszystko"' }

        if ($tresc) {
            $uw = New-Object Windows.Controls.TextBlock
            $uw.TextWrapping = 'Wrap'
            $uw.FontSize = 11
            $uw.Margin = '0,7,16,0'
            $uw.LineHeight = 17

            $uwL = New-Object Windows.Documents.Run
            $uwL.Text = 'Bez potwierdzenia  '
            if ($bezCofki -and -not $bezTestu) { $uwL.Text = 'Bez cofania  ' }
            $uwL.Foreground = Br '#8B98A9'
            $uwL.FontWeight = 'SemiBold'
            $uw.Inlines.Add($uwL)

            $uwT = New-Object Windows.Documents.Run
            $uwT.Text = $tresc
            $uwT.Foreground = $Window.FindResource('Dim')
            $uw.Inlines.Add($uwT)

            $sp.Children.Add($uw) | Out-Null
        }
    }

    [Windows.Controls.Grid]::SetColumn($sp, 2)
    $grid.Children.Add($sp) | Out-Null

    # --- pigulka ze stanem ---
    $pill     = New-Object Windows.Controls.Border
    $pillText = New-Object Windows.Controls.TextBlock
    $pillDot  = New-Object Windows.Controls.Border
    if (-not $Task.Tool) {
        $pill.CornerRadius      = New-Object Windows.CornerRadius 8
        $pill.Padding           = New-Object Windows.Thickness 10,3,10,4
        $pill.Margin            = New-Object Windows.Thickness 0,0,12,0
        $pill.VerticalAlignment = 'Center'
        $pill.MinWidth          = 108
        $pillText.FontSize = 11; $pillText.FontWeight = 'SemiBold'

        $pillDot.Width  = 6; $pillDot.Height = 6
        $pillDot.CornerRadius = New-Object Windows.CornerRadius 3
        $pillDot.Margin = New-Object Windows.Thickness 0,0,6,0
        $pillDot.VerticalAlignment = 'Center'

        $pillRow = New-Object Windows.Controls.StackPanel
        $pillRow.Orientation = 'Horizontal'
        $pillRow.HorizontalAlignment = 'Center'
        $pillRow.Children.Add($pillDot)  | Out-Null
        $pillRow.Children.Add($pillText) | Out-Null
        $pill.Child = $pillRow

        $look = $PillLook['unknown']
        $pill.Background = Br $look.bg; $pillText.Foreground = Br $look.fg; $pillText.Text = $look.t
        $pillDot.Background = Br $look.fg
        [Windows.Controls.Grid]::SetColumn($pill, 3)
        $grid.Children.Add($pill) | Out-Null
    }

    # --- przyciski ---
    $btn = New-Object Windows.Controls.Button
    $btn.Style = $Window.FindResource('Ghost')
    $btn.Content = 'Uruchom'; $btn.VerticalAlignment = 'Center'
    [Windows.Controls.Grid]::SetColumn($btn, 4)
    $grid.Children.Add($btn) | Out-Null

    $rev = New-Object Windows.Controls.Button
    if (-not $Task.Tool -and $Task.Rev) {
        $rev.Style = $Window.FindResource('GhostWarn')
        $rev.Content = 'Cofnij'; $rev.VerticalAlignment = 'Center'
        $rev.Margin = New-Object Windows.Thickness 8,0,0,0
        $rev.IsEnabled = $false
        $rev.ToolTip = 'Przywraca wartości sprzed pierwszego zastosowania'
        [Windows.Controls.Grid]::SetColumn($rev, 5)
        $grid.Children.Add($rev) | Out-Null
    } else {
        $rev = $null
    }

    # --- teczowe tlo karty: kolor kategorii widoczny tylko w wąskim pasie
    #     przy lewej krawedzi (tam, gdzie i tak jest tylko checkbox i
    #     ikona), szybko gasnacy - zamiast zalewac cala karte i przygaszac
    #     czytelnosc tytulu/opisu po prawej. Nalozony NAD "szklanym" tlem
    #     karty (to ono daje ciemne, czytelne tlo pod tekstem).
    #     IsHitTestVisible=False, zeby nie przejmowal klikniec/najazdu
    #     kursora - tym nadal zajmuje sie sam $border (Add-CardMotion). ---
    $wash = New-Object Windows.Controls.Border
    $wash.CornerRadius = New-Object Windows.CornerRadius 14
    $wash.IsHitTestVisible = $false
    $washGrad = New-Object Windows.Media.LinearGradientBrush
    $washGrad.StartPoint = New-Object Windows.Point 0,0
    $washGrad.EndPoint   = New-Object Windows.Point 1,0
    $ws1 = New-Object Windows.Media.GradientStop ([Windows.Media.Color]::FromArgb(40, $catCol.R, $catCol.G, $catCol.B)), 0
    $ws2 = New-Object Windows.Media.GradientStop ([Windows.Media.Color]::FromArgb(8,  $catCol.R, $catCol.G, $catCol.B)), 0.22
    $ws3 = New-Object Windows.Media.GradientStop ([Windows.Media.Color]::FromArgb(0,  $catCol.R, $catCol.G, $catCol.B)), 0.42
    foreach ($s in @($ws1, $ws2, $ws3)) { $washGrad.GradientStops.Add($s) }
    $wash.Background = $washGrad

    # Wash pod spodem, tresc karty na wierzchu - Grid maluje dzieci w
    # kolejnosci dodania, wiec kolejnosc ponizej wystarczy (bez osobnych
    # wierszy/kolumn - jeden pasek postepu zniknal, wiec karta znow
    # potrzebuje tylko jednej komorki).
    $root = New-Object Windows.Controls.Grid
    $root.Children.Add($wash) | Out-Null
    $root.Children.Add($grid) | Out-Null

    $border.Child = $root

    if (-not $Task.Tool) {
        $border.Add_MouseLeftButtonUp({
            param($s, $e)
            if ($e.OriginalSource -is [Windows.Controls.Button]) { return }
            $c = $s.Tag
            if ($c) { $c.IsChecked = -not $c.IsChecked }
        })
        $border.Tag    = $cb
        $border.Cursor = [System.Windows.Input.Cursors]::Hand
    }

    return @{ Border = $border; Check = $cb; Button = $btn; Revert = $rev
              Pill = $pill; PillText = $pillText; PillDot = $pillDot; Glow = $glow
              CatColor = $catCol; Task = $Task }
}

$Cards = @{}
foreach ($t in $Tasks) {
    $card = New-TaskCard -Task $t
    $Cards[$t.Id] = $card
    $CatPanel[$t.Cat].Children.Add($card.Border) | Out-Null
}

function Set-CardState {
    param([string]$Id, [string]$State)
    if (-not $Cards.ContainsKey($Id)) { return }
    $c = $Cards[$Id]
    if (-not $c.Pill -or -not $c.PillText) { return }

    # Kropka w pigulce pulsuje wlasnym, ciaglym rytmem tylko w stanie "w
    # toku" - przy kazdym innym stanie trzeba ta animacje najpierw zdjac,
    # inaczej zostalaby wlaczona na zawsze (ostatni Set-CardState wygrywa).
    if ($c.PillDot) {
        if ($State -eq 'running') {
            $pAnim = New-Object Windows.Media.Animation.DoubleAnimation
            $pAnim.From = 0.3; $pAnim.To = 1
            $pAnim.Duration = New-Object Windows.Duration ([TimeSpan]::FromMilliseconds(560))
            $pAnim.AutoReverse    = $true
            $pAnim.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
            try { $c.PillDot.BeginAnimation([Windows.UIElement]::OpacityProperty, $pAnim) } catch {}
        } else {
            try { $c.PillDot.BeginAnimation([Windows.UIElement]::OpacityProperty, $null) } catch {}
            $c.PillDot.Opacity = 1
        }
    }

    $look = $PillLook[$State]
    if (-not $look) { $look = $PillLook['unknown'] }
    $c.Pill.Background   = Br $look.bg
    $c.PillText.Foreground = Br $look.fg
    $c.PillText.Text     = $look.t
    if ($c.PillDot) { $c.PillDot.Background = Br $look.fg }
    Pulse $c.Pill 0.15
    Shift $c.Pill 0 -4 260 0 'Pop'

    # --- poswiata karty jako pasek postepu: zamiast osobnej, dodatkowej
    #     kreski pod opisem (ktora gryzla sie kolorystycznie z kolorowym
    #     tlem), to sama poswiata pod karta pulsuje na zielono, dopoki
    #     zadanie trwa, a po zakonczeniu rozblyskuje wynikiem i wraca do
    #     spokojnego koloru kategorii. ---
    if ($c.Glow) {
        if ($State -eq 'running') {
            $gCol = New-Object Windows.Media.Animation.ColorAnimation
            $gCol.To = $Window.FindResource('Good').Color
            $gCol.Duration = New-Object Windows.Duration ([TimeSpan]::FromMilliseconds(220))
            try { $c.Glow.BeginAnimation([Windows.Media.Effects.DropShadowEffect]::ColorProperty, $gCol) } catch {}

            $gOp = New-Object Windows.Media.Animation.DoubleAnimation
            $gOp.From = 0.16; $gOp.To = 0.40
            $gOp.Duration = New-Object Windows.Duration ([TimeSpan]::FromMilliseconds(620))
            $gOp.AutoReverse    = $true
            $gOp.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
            try { $c.Glow.BeginAnimation([Windows.Media.Effects.DropShadowEffect]::OpacityProperty, $gOp) } catch {}
        } else {
            try { $c.Glow.BeginAnimation([Windows.Media.Effects.DropShadowEffect]::OpacityProperty, $null) } catch {}
            $flashCol =
                if     ($State -eq 'on' -or $State -eq 'done') { $Window.FindResource('Good').Color }
                elseif ($State -eq 'off')                       { $Window.FindResource('Bad').Color }
                elseif ($c.CatColor)                            { $c.CatColor }
                else                                             { $Window.FindResource('Accent').Color }
            $fCol = New-Object Windows.Media.Animation.ColorAnimation
            $fCol.To = $flashCol
            $fCol.Duration = New-Object Windows.Duration ([TimeSpan]::FromMilliseconds(180))
            try { $c.Glow.BeginAnimation([Windows.Media.Effects.DropShadowEffect]::ColorProperty, $fCol) } catch {}
            $c.Glow.Opacity = 0.34

            $gt = New-Object System.Windows.Threading.DispatcherTimer
            $gt.Interval = [TimeSpan]::FromMilliseconds(650)
            $gt.Add_Tick({
                $gt.Stop()
                if ($c.CatColor) {
                    $rCol = New-Object Windows.Media.Animation.ColorAnimation
                    $rCol.To = $c.CatColor
                    $rCol.Duration = New-Object Windows.Duration ([TimeSpan]::FromMilliseconds(450))
                    try { $c.Glow.BeginAnimation([Windows.Media.Effects.DropShadowEffect]::ColorProperty, $rCol) } catch {}
                }
                $rOp = New-Object Windows.Media.Animation.DoubleAnimation
                $rOp.To = 0.20
                $rOp.Duration = New-Object Windows.Duration ([TimeSpan]::FromMilliseconds(450))
                try { $c.Glow.BeginAnimation([Windows.Media.Effects.DropShadowEffect]::OpacityProperty, $rOp) } catch {}
            }.GetNewClosure())
            $gt.Start()
        }
    }

    if ($State -eq 'on') {
        # Sukces dostaje wlasny, krotki "oddech" calej karty - zielonkawy
        # blask, ktory sam gasnie i wraca do szklanego stanu spoczynku
        # (tego samego, co ustawia Add-CardMotion), a nie do starych,
        # nieprzezroczystych kolorow sprzed "szklanej" karty.
        $brdBg = $c.Border.Background
        $brdBr = $c.Border.BorderBrush
        if ($brdBg -is [Windows.Media.SolidColorBrush] -and $brdBr -is [Windows.Media.SolidColorBrush]) {
            $surf = $Window.FindResource('Surface').Color
            $good = $Window.FindResource('Good').Color
            $cRestBg  = [Windows.Media.Color]::FromArgb(206, $surf.R, $surf.G, $surf.B)
            $cRestBd  = [Windows.Media.Color]::FromArgb(58,  255, 255, 255)
            $cFlashBg = [Windows.Media.Color]::FromArgb(150, $good.R, $good.G, $good.B)
            $cFlashBd = [Windows.Media.Color]::FromArgb(210, $good.R, $good.G, $good.B)
            Tint-Color $brdBg $cFlashBg 140
            Tint-Color $brdBr $cFlashBd 140
            $t = New-Object System.Windows.Threading.DispatcherTimer
            $t.Interval = [TimeSpan]::FromMilliseconds(650)
            $t.Add_Tick({
                $t.Stop()
                Tint-Color $brdBg $cRestBg 450
                Tint-Color $brdBr $cRestBd 450
            }.GetNewClosure())
            $t.Start()
        }
    }
}

function Set-RevertAvailability {
    param([string[]]$Ids)
    $set = @{}
    foreach ($i in $Ids) { $set[$i] = $true }
    $any = $false
    foreach ($k in $Cards.Keys) {
        $r = $Cards[$k].Revert
        if ($r) {
            $r.IsEnabled = $set.ContainsKey($k)
            if ($set.ContainsKey($k)) { $any = $true }
        }
    }
    $UI.BtnRevertAll.IsEnabled = $any
}

# =====================================================================
#  URUCHAMIANIE W TLE
# =====================================================================
$script:RS         = $null
$script:PSInstance = $null
$script:Handle     = $null
$script:LastMode   = ''

function Set-BusyState {
    param([bool]$Busy)
    $sync.Busy = $Busy
    foreach ($b in @($UI.BtnRunSel, $UI.BtnFull, $UI.BtnRestore, $UI.BtnRefresh,
                     $UI.BtnRevertAll, $UI.BtnDiagRun, $UI.BtnDiagReport)) {
        if ($b) { $b.IsEnabled = -not $Busy }
    }
    foreach ($k in $Cards.Keys) {
        $Cards[$k].Button.IsEnabled = -not $Busy
        if ($Cards[$k].Revert -and $Busy) { $Cards[$k].Revert.IsEnabled = $false }
    }
    if ($Busy) { $UI.BtnRunSel.Content = 'Pracuję...' } else { $UI.BtnRunSel.Content = 'Uruchom zaznaczone' }

    # Pulsujaca kropka przy naglowku konsoli + pulsujacy pasek postepu.
    if ($Busy) {
        $UI.Prog.Tag = 'busy'
        Set-TaskbarProgress 'Normal' 0

        try {
            $p = New-Object Windows.Media.Animation.DoubleAnimation
            $p.From = 0.25; $p.To = 1
            $p.Duration = New-Object Windows.Duration ([TimeSpan]::FromMilliseconds(650))
            $p.AutoReverse    = $true
            $p.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
            $UI.BusyDot.BeginAnimation([Windows.UIElement]::OpacityProperty, $p)
        } catch {}
    } else {
        $UI.Prog.Tag = $null
        Set-TaskbarProgress 'None' 0
        try {
            $UI.BusyDot.BeginAnimation([Windows.UIElement]::OpacityProperty, $null)
            $UI.BusyDot.Opacity = 0.25
        } catch {}
    }
}

function Start-Worker {
    param([string]$Mode, [string[]]$Ids = @())

    if ($sync.Busy) { Add-Log 'Poczekaj – poprzednie zadanie jeszcze trwa.' 'warn'; return }
    if ($Mode -eq 'apply' -and $Ids.Count -eq 0) { Add-Log 'Nie zaznaczono żadnego zadania.' 'warn'; return }

    Set-BusyState $true
    $script:LastMode = $Mode
    Set-Bar $UI.Prog 0 150

    # Szkielety tylko tam, gdzie lista dopiero powstanie - nie przy
    # zadaniach, ktore odswiezaja juz widoczne karty.
    switch ($Mode) {
        'startup_scan'  { if ($UI.StartupHost.Children.Count -eq 0) { Show-Skeletons $UI.StartupHost 4 } }
        'proc_scan'     { if ($UI.ProcHost.Children.Count    -eq 0) { Show-Skeletons $UI.ProcHost 5 } }
        'appx_scan'     { if ($UI.AppsHost.Children.Count    -eq 0) { Show-Skeletons $UI.AppsHost 4 } }
        'games_detect'  { if ($UI.GameHost.Children.Count    -eq 0) { Show-Skeletons $UI.GameHost 3 } }
        'games_scan'    { if ($UI.GameHost.Children.Count    -eq 0) { Show-Skeletons $UI.GameHost 3 } }
        'net_scan'      { Show-Skeletons $UI.LinkHost 3 }
        'diag'          { Show-Skeletons $UI.DiagHost 4 }
    }

    $rs = [runspacefactory]::CreateRunspace()
    $rs.ApartmentState = 'STA'
    $rs.ThreadOptions  = 'ReuseThread'
    $rs.Open()

    $script:PSInstance = [powershell]::Create()
    $script:PSInstance.Runspace = $rs
    $null = $script:PSInstance.AddScript($WorkerBody).AddArgument($sync).AddArgument($Mode).AddArgument($Ids)
    $script:Handle = $script:PSInstance.BeginInvoke()
    $script:RS = $rs
}

function Stop-Worker {
    if ($script:PSInstance) {
        try { $script:PSInstance.EndInvoke($script:Handle) | Out-Null } catch {}
        try { $script:PSInstance.Dispose() } catch {}
        $script:PSInstance = $null
    }
    if ($script:RS) {
        try { $script:RS.Close(); $script:RS.Dispose() } catch {}
        $script:RS = $null
    }
}

# =====================================================================
#  DIAGNOSTYKA - RENDEROWANIE
# =====================================================================
$StatePill = @{ ok = @{bg='#0F2E24'; fg='#34D399'}; warn = @{bg='#33280A'; fg='#FBBF24'}
                bad = @{bg='#3A1220'; fg='#F43F5E'} }

function Render-Diag {
    $UI.DiagHost.Children.Clear()
    if (-not $sync.DiagData) { return }

    foreach ($sec in $sync.DiagData) {
        $b = New-Object Windows.Controls.Border
        $b.Style = $Window.FindResource('Card')
        Add-CardMotion $b
        Zageszcz $b
        $b.Padding = New-Object Windows.Thickness 18,15,18,15

        $stack = New-Object Windows.Controls.StackPanel

        $head = New-Object Windows.Controls.TextBlock
        $head.Text = $sec.Title
        $head.Foreground = $Window.FindResource('Accent')
        $head.FontSize = 13; $head.FontWeight = 'Bold'
        $head.Margin = '0,0,0,12'
        $stack.Children.Add($head) | Out-Null

        foreach ($r in $sec.Rows) {
            $g = New-Object Windows.Controls.Grid
            $g.Margin = '0,0,0,6'
            $c1 = New-Object Windows.Controls.ColumnDefinition
            $c1.Width = New-Object Windows.GridLength(1, [Windows.GridUnitType]::Star)
            $c2 = New-Object Windows.Controls.ColumnDefinition
            $c2.Width = New-Object Windows.GridLength(1.15, [Windows.GridUnitType]::Star)
            $g.ColumnDefinitions.Add($c1); $g.ColumnDefinitions.Add($c2)

            $k = New-Object Windows.Controls.TextBlock
            $k.Text = "$($r.k)"; $k.Foreground = $Window.FindResource('Muted')
            $k.FontSize = 12; $k.TextWrapping = 'Wrap'; $k.Margin = '0,0,14,0'
            [Windows.Controls.Grid]::SetColumn($k, 0)
            $g.Children.Add($k) | Out-Null

            if ($StatePill.ContainsKey("$($r.s)")) {
                $look = $StatePill["$($r.s)"]
                $pb = New-Object Windows.Controls.Border
                $pb.CornerRadius = New-Object Windows.CornerRadius 6
                $pb.Background = Br $look.bg
                $pb.Padding = New-Object Windows.Thickness 8,2,8,3
                $pb.HorizontalAlignment = 'Left'
                $pt = New-Object Windows.Controls.TextBlock
                $pt.Text = "$($r.v)"; $pt.FontSize = 11.5; $pt.FontWeight = 'SemiBold'
                $pt.Foreground = Br $look.fg; $pt.TextWrapping = 'Wrap'
                $pb.Child = $pt
                [Windows.Controls.Grid]::SetColumn($pb, 1)
                $g.Children.Add($pb) | Out-Null
            } else {
                $v = New-Object Windows.Controls.TextBlock
                $v.Text = "$($r.v)"; $v.Foreground = $Window.FindResource('Txt')
                $v.FontSize = 12; $v.TextWrapping = 'Wrap'
                [Windows.Controls.Grid]::SetColumn($v, 1)
                $g.Children.Add($v) | Out-Null
            }
            $stack.Children.Add($g) | Out-Null
        }

        $b.Child = $stack
        $UI.DiagHost.Children.Add($b) | Out-Null
    }
}

# =====================================================================
#  POMPA KOMUNIKATOW
# =====================================================================
$Timer = New-Object System.Windows.Threading.DispatcherTimer
$Timer.Interval = [TimeSpan]::FromMilliseconds(100)
$Timer.Add_Tick({
    $msg = $null
    $count = 0
    while ($sync.Queue.TryDequeue([ref]$msg) -and $count -lt 80) {
        $count++
        # Bez tego try/catch kazdy blad w kodzie interfejsu przerywal tik
        # po cichu: ekran zostawal w poprzednim stanie, a w konsoli ani slowa.
        # Teraz awarię widać od razu i wiadomo, ktory komunikat ja wywolal.
        try {
        switch ($msg.type) {
            'log'    { Add-Log $msg.text $msg.level }
            'status' { Set-Status $msg.text }
            'prog'   {
                $v = [Math]::Max(0, [Math]::Min(100, [int]$msg.value))
                Set-Bar $UI.Prog $v 320
                Set-TaskbarProgress 'Normal' ($v / 100.0)
            }
            'reboot' { $UI.RebootInfo.Text = 'Część zmian zadziała dopiero po ponownym uruchomieniu komputera.' }
            'state'  { $script:StateMap["$($msg.id)"] = "$($msg.state)"; Set-CardState $msg.id $msg.state }
            'backup' { $script:BackupIds = @($msg.ids); Set-RevertAvailability @($msg.ids); Update-Dash }
            'diag'   { Render-Diag }
            'games'  { Render-Games }
            'startup' { Render-Startup }
            'procs'   { Render-Procs }
            'net'     { Render-Net }
            'apps'    { Render-Apps }
            'bench'   { $UI.BenchOut.Text = "$($msg.text)" }
            'report' {
                Add-Log 'Raport otwarty w przeglądarce.' 'ok'
                try { Start-Process $msg.path } catch { Add-Log 'Nie udało się otworzyć raportu.' 'warn' }
            }
            'done' {
                Set-Bar $UI.Prog 100 260
                Stop-Worker
                Set-BusyState $false
                $m = "$($msg.mode)"
                if ($m -eq 'apply' -or $m -eq 'revert') {
                    Set-Status 'Gotowe – odświeżam stan...' 'ok'
                    Add-Log '--- Zakończono ---' 'ok'
                    if ($m -eq 'apply') { Toast 'Zadania wykonane. Sprawdzam, czy zmiany weszły.' 'ok' }
                    else                { Toast 'Cofnięto zmiany.' 'ok' }
                    Start-Worker 'scan'
                } elseif ($m -eq 'scan') {
                    Update-Dash
                    if (-not $script:GamesLoaded) {
                        $script:GamesLoaded = $true
                        Start-Worker 'games_scan'
                    } else { Set-Status 'Gotowy.' 'ok' }
                } elseif ($m -like 'bench_*') {
                    Set-Status 'Pomiar zakończony.' 'ok'
                    Toast 'Pomiar zapisany.' 'ok'
                } elseif ($m -like 'net_*') {
                    Set-Status 'Pomiar zakończony.' 'ok'
                } elseif ($m -like 'proc_*' -or $m -like 'appx_*') {
                    Set-Status 'Gotowy.' 'ok'
                } elseif ($m -like 'startup_*') {
                    Set-Status 'Gotowy.' 'ok'
                } elseif ($m -like 'games_*') {
                    Set-Status 'Gotowy.' 'ok'
                } else {
                    Set-Status 'Gotowe.' 'ok'
                }
            }
        }
        } catch {
            Set-Bar $UI.Prog 0 200
            Add-Log ("BLAD INTERFEJSU przy komunikacie '" + "$($msg.type)" + "': " + $_.Exception.Message) 'err'
            if ($_.InvocationInfo -and $_.InvocationInfo.ScriptLineNumber) {
                Add-Log ("  linia " + $_.InvocationInfo.ScriptLineNumber + ": " + "$($_.InvocationInfo.Line)".Trim()) 'err'
            }
        }
    }
})
$Timer.Start()

# =====================================================================
#  ZDARZENIA
# =====================================================================
# Okno bez ramki nie ma systemowego maksymalizowania. Rozciagamy je
# recznie do obszaru roboczego, zeby nie wchodzilo pod pasek zadan.
$script:Maxed = $false
$script:OknoBylo = $null

function Toggle-Max {
    try {
        if (-not $script:Maxed) {
            $script:OknoBylo = @{ L = $Window.Left; T = $Window.Top; W = $Window.Width; H = $Window.Height }
            $wa = [Windows.SystemParameters]::WorkArea
            $Window.Left = $wa.Left; $Window.Top = $wa.Top
            $Window.Width = $wa.Width; $Window.Height = $wa.Height
            $UI.Root.CornerRadius = New-Object Windows.CornerRadius 0
            $UI.BtnMax.Content = [char]0xE923
            $script:Maxed = $true
        } else {
            if ($script:OknoBylo) {
                $Window.Left = $script:OknoBylo.L; $Window.Top = $script:OknoBylo.T
                $Window.Width = $script:OknoBylo.W; $Window.Height = $script:OknoBylo.H
            }
            $UI.Root.CornerRadius = New-Object Windows.CornerRadius 16
            $UI.BtnMax.Content = [char]0xE922
            $script:Maxed = $false
        }
    } catch { }
}

$UI.TitleBar.Add_MouseLeftButtonDown({
    param($s, $e)
    if ($e.ClickCount -eq 2) { Toggle-Max; return }
    try { $Window.DragMove() } catch {}
})
$UI.BtnMax.Add_Click({ Toggle-Max })
$UI.BtnMin.Add_Click({ $Window.WindowState = 'Minimized' })
$script:Closing = $false
function Close-Window {
    if ($script:Closing) { return }
    $script:Closing = $true
    try {
        $a = New-Anim 0 $null 150 0 $false
        $a.Add_Completed({ try { $Window.Close() } catch {} })
        $Window.BeginAnimation([Windows.UIElement]::OpacityProperty, $a)
        # Bezpiecznik: gdyby animacja z jakiegos powodu nie doszla do konca,
        # okno i tak sie zamknie.
        $t = New-Object System.Windows.Threading.DispatcherTimer
        $t.Interval = [TimeSpan]::FromMilliseconds(400)
        $t.Add_Tick({ $t.Stop(); try { $Window.Close() } catch {} }.GetNewClosure())
        $t.Start()
    } catch { $Window.Close() }
}
$UI.BtnClose.Add_Click({ Close-Window })

# =====================================================================
#  IKONA W ZASOBNIKU SYSTEMOWYM
#
#  Stale widoczna, dopoki program dziala - nawet po zminimalizowaniu
#  okna. NotifyIcon z System.Windows.Forms dziala tu bez wlasnej petli
#  komunikatow: petla WPF-a uruchomiona przez $Window.ShowDialog() na
#  koncu skryptu obsluguje ten sam watek, wiec zdarzenia (klik, menu)
#  przychodza normalnie.
# =====================================================================
$script:TrayIcon = $null
try {
    $bytesIco = [Convert]::FromBase64String(($IkonaB64 -replace '\s', ''))
    $msIco    = New-Object System.IO.MemoryStream(,$bytesIco)
    $winIco   = New-Object System.Drawing.Icon($msIco)

    $script:TrayIcon = New-Object System.Windows.Forms.NotifyIcon
    $script:TrayIcon.Icon = $winIco
    $script:TrayIcon.Text = "$AppNazwa $AppVersion"
    $script:TrayIcon.Visible = $true

    $trayMenu = New-Object System.Windows.Forms.ContextMenuStrip
    $miPokaz   = $trayMenu.Items.Add("Pokaż $AppNazwa")
    [void]$trayMenu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
    $miZamknij = $trayMenu.Items.Add('Zamknij')
    $script:TrayIcon.ContextMenuStrip = $trayMenu

    function Show-ZZasobnika {
        $Window.Show()
        $Window.WindowState = 'Normal'
        $Window.Activate() | Out-Null
    }

    $miPokaz.Add_Click({ Show-ZZasobnika })
    $miZamknij.Add_Click({ Close-Window })
    $script:TrayIcon.Add_MouseDoubleClick({
        param($s, $e)
        if ($e.Button -eq [System.Windows.Forms.MouseButtons]::Left) { Show-ZZasobnika }
    })
} catch { $script:TrayIcon = $null }

$Pages = @(
    @{ Nav=$UI.NavDash;  Panel=$UI.PanelDash;  Tasks=$false; Title='Pulpit';           Desc='Stan komputera w jednym miejscu.' }
    @{ Nav=$UI.NavGames; Panel=$UI.PanelGames; Tasks=$false; Title='Moje gry';         Desc='Dodaj grę i ustaw dla niej maksymalną wydajność.' }
    @{ Nav=$UI.NavStartup; Panel=$UI.PanelStartup; Tasks=$false; Title='Autostart';     Desc='Programy startujące razem z Windows. Wyłączenie jest w pełni odwracalne.' }
    @{ Nav=$UI.NavDiag;  Panel=$UI.PanelDiag;  Tasks=$false; Title='Diagnostyka';      Desc='Pełny przegląd stanu komputera z eksportem do HTML.' }
    @{ Nav=$UI.NavGry;   Panel=$UI.PanelGry;   Tasks=$true;  Title='Gry i wydajność';  Desc='Ustawienia globalne wpływające na płynność i opóźnienia.' }
    @{ Nav=$UI.NavProc;  Panel=$UI.PanelProc;  Tasks=$false; Title='Procesy w tle';    Desc='Co zajmuje pamięć w tej chwili.' }
    @{ Nav=$UI.NavLink;  Panel=$UI.PanelLink;  Tasks=$false; Title='Łącze';            Desc='Pomiar opóźnień i ustawienia karty sieciowej.' }
    @{ Nav=$UI.NavSys;   Panel=$UI.PanelSys;   Tasks=$true;  Title='System';           Desc='Usługi, zasilanie, pamięć i dyski.' }
    @{ Nav=$UI.NavSvc;   Panel=$UI.PanelSvc;   Tasks=$true;  Title='Usługi';           Desc='Usługi Windows, które na domowym komputerze zwykle nie są potrzebne.' }
    @{ Nav=$UI.NavApps;  Panel=$UI.PanelApps;  Tasks=$false; Title='Aplikacje';        Desc='Wbudowane aplikacje Windows, które można usunąć.' }
    @{ Nav=$UI.NavClean; Panel=$UI.PanelClean; Tasks=$true;  Title='Czyszczenie';      Desc='Odzyskiwanie miejsca. Każde zadanie raportuje, ile zwolniło.' }
    @{ Nav=$UI.NavNet;   Panel=$UI.PanelNet;   Tasks=$true;  Title='Sieć i naprawa';   Desc='Naprawa plików systemowych i ustawienia sieci.' }
    @{ Nav=$UI.NavTools; Panel=$UI.PanelTools; Tasks=$true;  Title='Narzędzia';        Desc='Skróty do paneli systemowych i przydatnych programów.' }
    @{ Nav=$UI.NavSkin;  Panel=$UI.PanelSkin;  Tasks=$false; Title='Wygląd';           Desc='Kolorystyka programu. Nie zmienia niczego w systemie.' }
)

function Show-Page {
    param($Page)

    # Stara zakladka gasnie i lekko zjezdza w dol, dopiero potem znika
    # z ukladu - dzieki temu zmiana zakladki jest przenikaniem miedzy
    # dwoma nakladajacymi sie panelami (oba siedza w tej samej komorce
    # Grida), a nie twardym cieciem jak wczesniej.
    $Stary = Get-VisiblePanel
    if ($script:MotionOn -and $Stary -and $Stary -ne $Page.Panel -and $Stary.Visibility -eq 'Visible') {
        $s = $Stary
        Fade  $s 0 130
        Shift $s 10 0 150
        $t = New-Object System.Windows.Threading.DispatcherTimer
        $t.Interval = [TimeSpan]::FromMilliseconds(150)
        $t.Add_Tick({
            $t.Stop()
            if ($s.Opacity -lt 0.15) { $s.Visibility = 'Collapsed' }
        }.GetNewClosure())
        $t.Start()
        foreach ($p in $Pages) { if ($p.Panel -ne $s -and $p.Panel -ne $Page.Panel) { $p.Panel.Visibility = 'Collapsed' } }
    } else {
        foreach ($p in $Pages) { $p.Panel.Visibility = 'Collapsed' }
    }

    $Page.Panel.Visibility = 'Visible'
    $UI.PageTitle.Text = $Page.Title
    $UI.PageDesc.Text  = $Page.Desc
    Show-Panel $Page.Panel
    Fade  $UI.PageHead 1 260 0.2
    Shift $UI.PageHead 0 -8 280
    if ($Page.Tasks) {
        $UI.ActionBar.Visibility = 'Visible'
        $UI.HeadTools.Visibility = 'Visible'
    } else {
        $UI.ActionBar.Visibility = 'Collapsed'
        $UI.HeadTools.Visibility = 'Collapsed'
    }
    if ($Page.Panel -eq $UI.PanelDash) { Update-Gauges; Update-Dash; Draw-Sparks }
    if ($Page.Panel -eq $UI.PanelSkin -and $UI.SkinHost.Children.Count -eq 0) { Render-Skins }
    if ($Page.Tasks) { Apply-Filter }
    if ($Page.Panel -eq $UI.PanelStartup -and -not $script:StartupLoaded) {
        $script:StartupLoaded = $true
        Start-Worker 'startup_scan'
    }
    if ($Page.Panel -eq $UI.PanelProc -and -not $script:ProcLoaded) {
        $script:ProcLoaded = $true
        Start-Worker 'proc_scan'
    }
    if ($Page.Panel -eq $UI.PanelApps -and -not $script:AppsLoaded) {
        $script:AppsLoaded = $true
        Start-Worker 'appx_scan'
    }
    Update-SelInfo
}

foreach ($p in $Pages) {
    $pp = $p
    $pp.Nav.Add_Checked({ Show-Page $pp }.GetNewClosure())
}

function Get-VisiblePanel {
    foreach ($p in $Pages) { if ($p.Panel.Visibility -eq 'Visible') { return $p.Panel } }
    return $UI.PanelGry
}
function Get-SelectedIds {
    $ids = @()
    foreach ($t in $Tasks) {
        if ($t.Tool) { continue }
        # karta zwinieta filtrem nie jest zaznaczona z punktu widzenia
        # uzytkownika - nie widzi jej, wiec nie moze jej odznaczyc
        if ($Cards[$t.Id].Border.Visibility -ne 'Visible') { continue }
        if ($Cards[$t.Id].Check.IsChecked) { $ids += $t.Id }
    }
    return $ids
}
function Update-SelInfo {
    $txt = "Zaznaczono {0} zadań" -f (Get-SelectedIds).Count
    if ($script:FiltrQ) { $txt += "   •   filtr `"$script:FiltrQ`": $script:FiltrIle na tej zakładce" }
    if ($UI.SelInfo.Text -ne $txt) { Pulse $UI.SelInfo 0.25 }
    $UI.SelInfo.Text = $txt
}

foreach ($t in $Tasks) {
    if ($t.Tool) { continue }
    $Cards[$t.Id].Check.Add_Checked({ Update-SelInfo })
    $Cards[$t.Id].Check.Add_Unchecked({ Update-SelInfo })
}

foreach ($t in $Tasks) {
    $tid = $t.Id
    if ($tid -eq 't_winpin') {
        # To narzedzie otwiera wlasne okno, wiec nie moze isc przez workera -
        # watek w tle nie ma prawa dotknac kontrolek WPF.
        $Cards[$tid].Button.Add_Click({ Pokaz-BlokadyWinget })
    } else {
        $Cards[$tid].Button.Add_Click({ Start-Worker 'apply' @($tid) }.GetNewClosure())
    }
    if ($Cards[$tid].Revert) {
        $Cards[$tid].Revert.Add_Click({ Start-Worker 'revert' @($tid) }.GetNewClosure())
    }
}

$UI.BtnSelRec.Add_Click({
    $panel = Get-VisiblePanel
    foreach ($t in $Tasks) {
        if ($t.Tool) { continue }
        if ($CatPanel[$t.Cat] -eq $panel) { $Cards[$t.Id].Check.IsChecked = [bool]$t.Rec }
    }
    Update-SelInfo
})
$UI.BtnSelNone.Add_Click({
    foreach ($t in $Tasks) { if (-not $t.Tool) { $Cards[$t.Id].Check.IsChecked = $false } }
    Update-SelInfo
})
$UI.BtnRefresh.Add_Click({ Start-Worker 'scan' })
$UI.BtnRunSel.Add_Click({ Start-Worker 'apply' (Get-SelectedIds) })

$UI.BtnFull.Add_Click({
    $r = [System.Windows.MessageBox]::Show(
        "Zostaną wykonane wszystkie ZALECANE optymalizacje.`n`nStare wartości trafią do kopii zapasowej – każdą zmianę da się cofnąć przyciskiem `"Przywróć wszystko`".`n`nKontynuować?",
        "Pełna optymalizacja", 'YesNo', 'Question')
    if ($r -ne 'Yes') { return }
    $ids = @()
    foreach ($t in $Tasks) { if (-not $t.Tool -and $t.Rec) { $ids += $t.Id } }
    Start-Worker 'apply' $ids
})

$UI.BtnRestore.Add_Click({ Start-Worker 'apply' @('restorepoint') })

$UI.BtnRevertAll.Add_Click({
    $r = [System.Windows.MessageBox]::Show(
        "Cofnąć WSZYSTKIE zmiany zapisane w kopii zapasowej?`n`nWartości rejestru, usługi i plan zasilania wrócą do stanu sprzed pierwszego uruchomienia OptiLaunchera.`n`nCzyszczenia dysku nie da się cofnąć.",
        "Przywróć wszystko", 'YesNo', 'Warning')
    if ($r -eq 'Yes') { Start-Worker 'revert' @('__all__') }
})

# =====================================================================
#  KOMUNIKAT RESTARTU
#  Zamiast systemowego okienka Tak/Nie: nakladka we wlasnym stylu z
#  zywym odliczaniem, ktore samo widac - i, w odroznieniu od starego
#  "shutdown /t 10" wypuszczonego w system od razu po kliknieciu,
#  faktyczna mozliwoscia anulowania z poziomu programu, zanim
#  cokolwiek zostanie zaplanowane.
# =====================================================================
$script:RestartTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:RestartTimer.Interval = [TimeSpan]::FromSeconds(1)
$script:RestartCounter = 0
$script:RestartTimer.Add_Tick({
    $script:RestartCounter--
    if ($script:RestartCounter -le 0) { Do-Restart; return }
    if ($UI.RestartCountdown) {
        $UI.RestartCountdown.Text = "$($script:RestartCounter)"
        Pulse $UI.RestartCountdown 0.3
    }
})

function Hide-RestartOverlay {
    $script:RestartTimer.Stop()
    if (-not $UI.RestartOverlay) { return }
    Fade $UI.RestartOverlay 0 200
    $t = New-Object System.Windows.Threading.DispatcherTimer
    $t.Interval = [TimeSpan]::FromMilliseconds(220)
    $t.Add_Tick({ $t.Stop(); $UI.RestartOverlay.Visibility = 'Collapsed' }.GetNewClosure())
    $t.Start()
}

function Do-Restart {
    $script:RestartTimer.Stop()
    Hide-RestartOverlay
    try { shutdown.exe /r /t 3 /c "OptiLauncher - restart po optymalizacji" }
    catch { Add-Log "Nie udalo sie zaplanowac restartu: $($_.Exception.Message)" 'err' }
}

function Show-RestartOverlay {
    if (-not $UI.RestartOverlay) { return }
    $script:RestartCounter = 10
    $UI.RestartCountdown.Text = '10'
    $UI.RestartOverlay.Visibility = 'Visible'
    $UI.RestartOverlay.Opacity = 0
    Fade $UI.RestartOverlay 1 220
    $script:RestartTimer.Stop()
    $script:RestartTimer.Start()
}

$UI.BtnReboot.Add_Click({ Show-RestartOverlay })
$UI.BtnRestartCancel.Add_Click({ Hide-RestartOverlay })
$UI.BtnRestartNow.Add_Click({ Do-Restart })

$UI.BtnOpenLog.Add_Click({
    if (Test-Path $LogFile) { Start-Process notepad.exe $LogFile } else { Add-Log 'Log jeszcze pusty.' 'warn' }
})
$UI.BtnDiagRun.Add_Click({ Start-Worker 'diag' })
$UI.BtnDiagReport.Add_Click({ Start-Worker 'report' })

$Window.Add_Closing({
    try { $Timer.Stop() } catch {}
    if ($sync.Busy -and $script:PSInstance) { try { $script:PSInstance.Stop() } catch {} }
    Stop-Worker
    # Bez tego ikona zostaje "duchem" w zasobniku do restartu Explorera.
    try {
        if ($script:TrayIcon) {
            $script:TrayIcon.Visible = $false
            $script:TrayIcon.Dispose()
        }
    } catch {}
})

# =====================================================================
#  INFO O SPRZECIE
# =====================================================================
function Update-Hardware {
    try {
        $cpu = Get-CimInstance Win32_Processor | Select-Object -First 1
        $UI.HwCpu.Text = "CPU: $($cpu.Name.Trim()) ($($cpu.NumberOfCores)C/$($cpu.NumberOfLogicalProcessors)T)"
    } catch { $UI.HwCpu.Text = 'CPU: brak danych' }
    try {
        $UI.HwGpu.Text = "GPU: " + ((@(Get-CimInstance Win32_VideoController | ForEach-Object { $_.Name })) -join ' + ')
    } catch { $UI.HwGpu.Text = 'GPU: brak danych' }
    try {
        $gb  = [math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB, 0)
        $spd = (Get-CimInstance Win32_PhysicalMemory | Select-Object -First 1).Speed
        $UI.HwRam.Text = "RAM: $gb GB" + $(if ($spd) { " @ $spd MHz" } else { '' })
    } catch { $UI.HwRam.Text = 'RAM: brak danych' }
    try {
        $sys  = $env:SystemDrive.TrimEnd(':')
        $v    = Get-Volume -DriveLetter $sys -ErrorAction Stop
        $type = 'SSD'
        try {
            $part = Get-Partition -DriveLetter $sys -ErrorAction Stop
            $pd = Get-PhysicalDisk | Where-Object { $_.DeviceId -eq $part.DiskNumber }
            if ($pd -and $pd.MediaType) { $type = $pd.MediaType }
        } catch {}
        $UI.HwDsk.Text = "Dysk ${sys}: {0:N1} / {1:N1} GB wolne ($type)" -f ($v.SizeRemaining/1GB), ($v.Size/1GB)
    } catch { $UI.HwDsk.Text = 'Dysk: brak danych' }
    try {
        $os = Get-CimInstance Win32_OperatingSystem
        $UI.HwOs.Text = "OS: $($os.Caption -replace 'Microsoft ','') (build $($os.BuildNumber))"
    } catch { $UI.HwOs.Text = 'OS: brak danych' }
}


# =====================================================================
#  PULPIT - liczniki pierscieniowe
# =====================================================================
$script:StateMap  = @{}
$script:BackupIds = @()

# Liczniki dojezdzaja do nowej wartosci zamiast skakac: osobny zegar
# 45 ms dolicza roznice, ale pracuje tylko wtedy, gdy widac Pulpit
# i gdy jest jeszcze co animowac.
$script:GTarget = @{ cpu = 0.0; ram = 0.0; dsk = 0.0 }
$script:GCur    = @{ cpu = 0.0; ram = 0.0; dsk = 0.0 }

function Set-Gauge { param([string]$K, [double]$V) $script:GTarget[$K] = $V }

# Pierscien odswieza sie kilkanascie razy na sekunde - bez tej podreczej
# pamieci kazda klatka tworzylaby nowy pedzel. Te trzy sa zamrozone,
# bo nigdy nie sa animowane (animowane pedzle kart robi Add-CardMotion).
$script:RingBrush = @{}
function Get-RingBrush {
    param([string]$Hex)
    if (-not $script:RingBrush.ContainsKey($Hex)) {
        $b = Br $Hex
        try { $b.Freeze() } catch {}
        $script:RingBrush[$Hex] = $b
    }
    return $script:RingBrush[$Hex]
}

function Set-Ring {
    param($Path, [double]$Pct, [string]$Hex)
    if (-not $Path) { return }
    if ($Pct -lt 0) { $Pct = 0 }
    if ($Pct -gt 100) { $Pct = 100 }
    # Kazdy pierscien ma wlasny, nieszamrozony pedzel - dzieki temu
    # przejscie z zielonego w zolty jest plynne zamiast skokowe.
    if ($Path.Stroke -is [Windows.Media.SolidColorBrush] -and -not $Path.Stroke.IsFrozen) {
        Tint $Path.Stroke $Hex 400
    } else {
        $Path.Stroke = Br $Hex
    }
    if ($Pct -le 0.4) { $Path.Data = $null; return }

    $cx = 56.0; $cy = 56.0; $r = 51.5
    $angle = 360.0 * $Pct / 100.0
    if ($angle -ge 359.9) { $angle = 359.9 }
    $rad = ($angle - 90.0) * [Math]::PI / 180.0

    $fig = New-Object Windows.Media.PathFigure
    $fig.StartPoint = New-Object Windows.Point($cx, ($cy - $r))
    $arc = New-Object Windows.Media.ArcSegment
    $arc.Point          = New-Object Windows.Point(($cx + $r * [Math]::Cos($rad)), ($cy + $r * [Math]::Sin($rad)))
    $arc.Size           = New-Object Windows.Size($r, $r)
    $arc.IsLargeArc     = ($angle -gt 180.0)
    $arc.SweepDirection = 'Clockwise'
    $fig.Segments.Add($arc)
    $geo = New-Object Windows.Media.PathGeometry
    $geo.Figures.Add($fig)
    $Path.Data = $geo
}

function Hue { param([double]$p) if ($p -ge 88) { '#FB7185' } elseif ($p -ge 70) { '#FBBF24' } else { '#22D3EE' } }

# ---------------------------------------------------------------------
#  SZYBKIE LICZNIKI SYSTEMOWE
#
#  Wersja 7.0 odpytywala WMI co 3 sekundy. Win32_Processor.LoadPercentage
#  kosztuje kilkaset milisekund i sam obciaza procesor, ktory ma mierzyc -
#  licznik podbijal wartosc, ktora pokazywal.
#
#  Tutaj sa bezposrednie wywolania kernel32: GetSystemTimes liczy obciazenie
#  z roznicy czasow miedzy tikami, GlobalMemoryStatusEx podaje pamiec,
#  a DriveInfo dysk. Wszystko w ulamku milisekundy i - co wazne -
#  niezaleznie od jezyka systemu (nazwy licznikow wydajnosci sa
#  tlumaczone, wiec 'Processor Information' na polskim Windows nie dziala).
# ---------------------------------------------------------------------
if (-not ('OptiPerf.Sys' -as [type])) {
    try {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
namespace OptiPerf {
    [StructLayout(LayoutKind.Sequential)]
    public struct MemStat {
        public uint  dwLength;
        public uint  dwMemoryLoad;
        public ulong ullTotalPhys;
        public ulong ullAvailPhys;
        public ulong ullTotalPageFile;
        public ulong ullAvailPageFile;
        public ulong ullTotalVirtual;
        public ulong ullAvailVirtual;
        public ulong ullAvailExtendedVirtual;
    }
    public static class Sys {
        [DllImport("kernel32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool GlobalMemoryStatusEx(ref MemStat lpBuffer);

        [DllImport("kernel32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        public static extern bool GetSystemTimes(out long idle, out long kernel, out long user);

        public static MemStat Mem() {
            MemStat m = new MemStat();
            m.dwLength = (uint)Marshal.SizeOf(typeof(MemStat));
            GlobalMemoryStatusEx(ref m);
            return m;
        }
    }
}
'@ -ErrorAction Stop
    } catch { }
}

$script:TickIdle = 0; $script:TickKernel = 0; $script:TickUser = 0; $script:TickReady = $false

function Get-CpuLoadFast {
    # Obciazenie liczone z przyrostu czasow systemowych miedzy dwoma wywolaniami.
    # Pierwsze wywolanie tylko ustawia punkt odniesienia i zwraca $null.
    if (-not ('OptiPerf.Sys' -as [type])) { return $null }
    $i = [int64]0; $k = [int64]0; $u = [int64]0
    try { if (-not [OptiPerf.Sys]::GetSystemTimes([ref]$i, [ref]$k, [ref]$u)) { return $null } }
    catch { return $null }

    $di = $i - $script:TickIdle
    $dk = $k - $script:TickKernel
    $du = $u - $script:TickUser
    $script:TickIdle = $i; $script:TickKernel = $k; $script:TickUser = $u

    if (-not $script:TickReady) { $script:TickReady = $true; return $null }

    $suma = $dk + $du          # czas jadra zawiera juz czas bezczynnosci
    if ($suma -le 0) { return $null }
    $pct = ((($suma - $di) / [double]$suma) * 100.0)
    if ($pct -lt 0)   { $pct = 0 }
    if ($pct -gt 100) { $pct = 100 }
    return $pct
}

function Update-Gauges {
    # --- procesor ---
    try {
        $load = Get-CpuLoadFast
        if ($null -eq $load) {
            # zapasowo WMI, gdyby kernel32 z jakiegos powodu zawiodlo
            $load = (Get-CimInstance Win32_Processor -ErrorAction Stop | Measure-Object -Property LoadPercentage -Average).Average
        }
        if ($null -ne $load) {
            Set-Gauge 'cpu' $load
        }
    } catch { }

    # --- pamiec ---
    try {
        $pct = $null
        if ('OptiPerf.Sys' -as [type]) {
            $m = [OptiPerf.Sys]::Mem()
            if ($m.ullTotalPhys -gt 0) {
                $totGB = [double]$m.ullTotalPhys / 1GB
                $useGB = [double]($m.ullTotalPhys - $m.ullAvailPhys) / 1GB
                $pct   = [double]$m.dwMemoryLoad
                $UI.TxtRamSub.Text = "{0:N1} z {1:N0} GB" -f $useGB, $totGB
            }
        }
        if ($null -eq $pct) {
            $os  = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
            $tot = [double]$os.TotalVisibleMemorySize
            $use = $tot - [double]$os.FreePhysicalMemory
            $pct = ($use / $tot) * 100.0
            $UI.TxtRamSub.Text = "{0:N1} z {1:N0} GB" -f ($use/1MB), ($tot/1MB)
        }
        Set-Gauge 'ram' $pct
    } catch { }

    # --- dysk systemowy ---
    try {
        # DriveInfo jest natychmiastowe, Get-Volume schodzi do warstwy storage
        $d    = New-Object System.IO.DriveInfo ($env:SystemDrive + '\')
        $size = [double]$d.TotalSize
        $free = [double]$d.AvailableFreeSpace
        if ($size -gt 0) {
            $pct = (($size - $free) / $size) * 100.0
            $UI.TxtDskSub.Text = "{0:N0} GB wolne" -f ($free/1GB)
            Set-Gauge 'dsk' $pct
        }
    } catch { }
}

function Update-Dash {
    $on = 0; $known = 0
    foreach ($k in $script:StateMap.Keys) {
        if ($script:StateMap[$k] -eq 'on')  { $on++;    $known++ }
        if ($script:StateMap[$k] -eq 'off') { $known++ }
    }
    if ($known -eq 0) {
        $UI.DashScore.Text = 'Sprawdzam...'
        Set-Bar $UI.DashBar 0 200
        $UI.DashHint.Text  = ''
    } else {
        $pct = [int](($on / [double]$known) * 100)
        $UI.DashScore.Text = "$on z $known optymalizacji zastosowanych"
        Set-Bar $UI.DashBar $pct 700
        if ($pct -ge 90)      { $UI.DashHint.Text = 'System jest dobrze przygotowany. Możesz jeszcze zajrzeć do zakładki Moje gry.' }
        elseif ($pct -ge 50)  { $UI.DashHint.Text = 'Sporo już zrobione. Zajrzyj do zakładek po lewej po resztę.' }
        else                  { $UI.DashHint.Text = 'Zacznij od punktu przywracania, potem kliknij Pełna optymalizacja.' }
    }

    if ($script:BackupIds.Count -eq 0) {
        $UI.DashRecent.Text = 'Brak zapisanych zmian. Nic jeszcze nie zostało zmodyfikowane przez OptiLauncher.'
    } else {
        $names = @()
        foreach ($id in $script:BackupIds) {
            $t = @($Tasks | Where-Object { $_.Id -eq $id })[0]
            if ($t) { $names += $t.Title } else { $names += $id }
        }
        $UI.DashRecent.Text = ("Zmienione przez OptiLauncher ({0}):`n• " -f $names.Count) + ($names -join "`n• ") +
                              "`n`nKażdą z tych pozycji cofniesz przyciskiem obok niej albo globalnie w lewym dolnym rogu."
    }
}



# =====================================================================
#  SZKIELETY LADOWANIA
#  Pusty obszar i kręcący sie pasek czytaja sie jak "nic tu nie ma".
#  Migoczace placeholdery w ksztalcie kart czytaja sie jak "zaraz bedzie".
# =====================================================================
function New-Skeleton {
    param([int]$Szerokosc = 200, [int]$Wysokosc = 11, [int]$Opoznienie = 0)
    $b = New-Object Windows.Controls.Border
    $b.Height = $Wysokosc
    $b.Width  = $Szerokosc
    $b.HorizontalAlignment = 'Left'
    $b.CornerRadius = New-Object Windows.CornerRadius 4
    $b.Background = Br '#1A2434'
    $b.Opacity = 0.35
    if ($script:MotionOn) {
        try {
            $a = New-Object Windows.Media.Animation.DoubleAnimation
            $a.From = 0.28; $a.To = 0.75
            $a.Duration = New-Object Windows.Duration ([TimeSpan]::FromMilliseconds(850))
            $a.BeginTime = [TimeSpan]::FromMilliseconds($Opoznienie)
            $a.AutoReverse    = $true
            $a.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
            $a.EasingFunction = (Get-Ease)
            $b.BeginAnimation([Windows.UIElement]::OpacityProperty, $a)
        } catch { }
    }
    return $b
}

function Show-Skeletons {
    # UWAGA: parametr nie moze nazywac sie $Host - to zmienna stala
    # PowerShella i proba jej przeslonienia konczy sie bledem.
    param($Kontener, [int]$Ile = 4)
    if (-not $Kontener) { return }
    $Kontener.Children.Clear()
    for ($i = 0; $i -lt $Ile; $i++) {
        $karta = New-Object Windows.Controls.Border
        $karta.Style = $Window.FindResource('Card')
        Zageszcz $karta
        $karta.Tag = 'szkielet'

        $sp = New-Object Windows.Controls.StackPanel
        $sp.Children.Add((New-Skeleton (170 + ($i * 23) % 90) 12 ($i * 120))) | Out-Null
        $d = New-Skeleton (330 + ($i * 37) % 120) 9 (($i * 120) + 90)
        $d.Margin = New-Object Windows.Thickness 0,9,0,0
        $sp.Children.Add($d) | Out-Null
        $karta.Child = $sp
        $Kontener.Children.Add($karta) | Out-Null
    }
}

function Clear-Skeletons {
    param($Kontener)
    if (-not $Kontener) { return }
    for ($i = $Kontener.Children.Count - 1; $i -ge 0; $i--) {
        if ("$($Kontener.Children[$i].Tag)" -eq 'szkielet') { $Kontener.Children.RemoveAt($i) }
    }
}

# =====================================================================
#  TLO MICA  (Windows 11)
#
#  Backdrop rysuje menedzer okien, nie WPF - a ten nie ma go gdzie
#  narysowac, dopoki okno jest warstwowe (AllowsTransparency). Dlatego
#  przy wlaczonej Mice okno przechodzi na zwykly tryb, ramka jest
#  rozciagnieta na cala powierzchnie, a zaokraglenie robi juz system.
# =====================================================================
$script:MicaOK = $false
try {
    if (-not ([System.Management.Automation.PSTypeName]'OptiDwm.Api').Type) {
        Add-Type -Namespace OptiDwm -Name Api -MemberDefinition @"
[System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]
public struct MARGINS { public int L; public int R; public int T; public int B; }
[System.Runtime.InteropServices.DllImport("dwmapi.dll")]
public static extern int DwmSetWindowAttribute(System.IntPtr h, int a, ref int v, int s);
[System.Runtime.InteropServices.DllImport("dwmapi.dll")]
public static extern int DwmExtendFrameIntoClientArea(System.IntPtr h, ref MARGINS m);
"@ -ErrorAction Stop
    }
    $script:MicaOK = $true
} catch { $script:MicaOK = $false }

function Test-MicaMozliwa {
    try { return ([Environment]::OSVersion.Version.Build -ge 22000) } catch { return $false }
}

function Apply-Mica {
    if (-not $script:Mica -or -not $script:MicaOK) { return }
    if (-not (Test-MicaMozliwa)) {
        Add-Log 'Tlo Mica wymaga Windows 11 - pomijam.' 'warn'
        return
    }
    try {
        $hwnd = (New-Object Windows.Interop.WindowInteropHelper $Window).Handle
        if ($hwnd -eq [IntPtr]::Zero) { return }

        $ciemny = 1
        if ($script:MotywId -eq 'jasny') { $ciemny = 0 }
        [OptiDwm.Api]::DwmSetWindowAttribute($hwnd, 20, [ref]$ciemny, 4) | Out-Null

        $rog = 2
        [OptiDwm.Api]::DwmSetWindowAttribute($hwnd, 33, [ref]$rog, 4) | Out-Null

        $m = New-Object OptiDwm.Api+MARGINS
        $m.L = -1; $m.R = -1; $m.T = -1; $m.B = -1
        [OptiDwm.Api]::DwmExtendFrameIntoClientArea($hwnd, [ref]$m) | Out-Null

        $typ = 2
        $r = [OptiDwm.Api]::DwmSetWindowAttribute($hwnd, 38, [ref]$typ, 4)
        if ($r -ne 0) { Add-Log 'System odrzucil tlo Mica - zostaje zwykle.' 'warn'; return }

        # Tlo okna musi byc czesciowo przezroczyste, inaczej przykryje backdrop.
        $UI.Root.CornerRadius = New-Object Windows.CornerRadius 0
        $kol = $UI.Root.Background
        if ($kol -is [Windows.Media.SolidColorBrush]) {
            $c = $kol.Color
            $c.A = 190
            $UI.Root.Background = New-Object Windows.Media.SolidColorBrush $c
        }
        Add-Log 'Tlo Mica wlaczone.' 'ok'
    } catch {
        Add-Log "Nie udalo sie wlaczyc tla Mica: $($_.Exception.Message)" 'warn'
    }
}

# =====================================================================
#  WYGLAD - wybor motywu
# =====================================================================
function New-SkinCard {
    param($M, [bool]$Aktywny)

    $border = New-Object Windows.Controls.Border
    $border.Style = $Window.FindResource('Card')
    Zageszcz $border
    if ($Aktywny) {
        $border.Background  = Br '#161F30'
        $border.BorderBrush = Br '#2F4C74'
    } else {
        Add-CardMotion $border
    }

    $grid = New-Object Windows.Controls.Grid
    foreach ($w in @([Windows.GridLength]::Auto,
                     (New-Object Windows.GridLength(1, [Windows.GridUnitType]::Star)),
                     [Windows.GridLength]::Auto)) {
        $cd = New-Object Windows.Controls.ColumnDefinition
        $cd.Width = $w
        $grid.ColumnDefinitions.Add($cd)
    }

    # --- podglad palety: piec probek w kolorach DOCELOWYCH ---
    # Te kolory celowo NIE ida przez Br: maja pokazac, jak wyglada inny
    # motyw, wiec nie wolno ich przemalowac na obecny.
    $pas = New-Object Windows.Controls.StackPanel
    $pas.Orientation = 'Horizontal'
    $pas.VerticalAlignment = 'Center'
    $pas.Margin = New-Object Windows.Thickness 0,0,16,0

    $ramka = New-Object Windows.Controls.Border
    $ramka.CornerRadius = New-Object Windows.CornerRadius 10
    $ramka.Padding = New-Object Windows.Thickness 9,8,9,8
    $ramka.Background = New-Object Windows.Media.SolidColorBrush (
        [Windows.Media.ColorConverter]::ConvertFromString($M.Probki[3]))
    $ramka.BorderThickness = New-Object Windows.Thickness 1
    $ramka.BorderBrush = New-Object Windows.Media.SolidColorBrush (
        [Windows.Media.ColorConverter]::ConvertFromString($M.Probki[2]))

    $wnetrze = New-Object Windows.Controls.StackPanel
    $wnetrze.Orientation = 'Horizontal'
    $i = 0
    foreach ($p in @($M.Probki[0], $M.Probki[1], $M.Probki[2], $M.Probki[4])) {
        $kropka = New-Object Windows.Controls.Border
        $kropka.Width = 22; $kropka.Height = 22
        $kropka.CornerRadius = New-Object Windows.CornerRadius 6
        $kropka.Background = New-Object Windows.Media.SolidColorBrush (
            [Windows.Media.ColorConverter]::ConvertFromString($p))
        if ($i -gt 0) { $kropka.Margin = New-Object Windows.Thickness 6,0,0,0 }
        $wnetrze.Children.Add($kropka) | Out-Null
        $i++
    }
    $ramka.Child = $wnetrze
    $pas.Children.Add($ramka) | Out-Null
    [Windows.Controls.Grid]::SetColumn($pas, 0)
    $grid.Children.Add($pas) | Out-Null

    # --- nazwa i opis ---
    $sp = New-Object Windows.Controls.StackPanel
    $sp.VerticalAlignment = 'Center'

    $rzad = New-Object Windows.Controls.StackPanel
    $rzad.Orientation = 'Horizontal'

    $nm = New-Object Windows.Controls.TextBlock
    $nm.Text = "$($M.Nazwa)"
    $nm.FontSize = 14; $nm.FontWeight = 'SemiBold'
    $nm.Foreground = $Window.FindResource('Txt')
    $nm.VerticalAlignment = 'Center'
    $rzad.Children.Add($nm) | Out-Null

    if ($Aktywny) {
        $bb = New-Object Windows.Controls.Border
        $bb.CornerRadius = New-Object Windows.CornerRadius 8
        $bb.Background = Br '#0F2E24'
        $bb.Padding = New-Object Windows.Thickness 8,1,8,2
        $bb.Margin  = New-Object Windows.Thickness 10,0,0,0
        $bb.VerticalAlignment = 'Center'
        $bt = New-Object Windows.Controls.TextBlock
        $bt.Text = 'w użyciu'; $bt.FontSize = 10.5; $bt.FontWeight = 'SemiBold'
        $bt.Foreground = Br '#34D399'
        $bb.Child = $bt
        $rzad.Children.Add($bb) | Out-Null
    }
    $sp.Children.Add($rzad) | Out-Null

    $op = New-Object Windows.Controls.TextBlock
    $op.Text = "$($M.Opis)"
    $op.FontSize = 11.5
    $op.Foreground = $Window.FindResource('Muted')
    $op.Margin = New-Object Windows.Thickness 0,4,16,0
    $sp.Children.Add($op) | Out-Null

    if ($SkinUwagi.ContainsKey("$($M.Id)")) {
        $uw = New-Object Windows.Controls.TextBlock
        $uw.Text = $SkinUwagi["$($M.Id)"]
        $uw.FontSize = 11
        $uw.TextWrapping = 'Wrap'
        $uw.LineHeight = 16
        $uw.Foreground = $Window.FindResource('Dim')
        $uw.Margin = New-Object Windows.Thickness 0,6,16,0
        $sp.Children.Add($uw) | Out-Null
    }

    [Windows.Controls.Grid]::SetColumn($sp, 1)
    $grid.Children.Add($sp) | Out-Null

    $btn = New-Object Windows.Controls.Button
    $btn.VerticalAlignment = 'Center'
    $btn.Width = 130
    if ($Aktywny) {
        $btn.Style = $Window.FindResource('GhostDim')
        $btn.Content = 'W użyciu'
        $btn.IsEnabled = $false
    } else {
        $btn.Style = $Window.FindResource('Ghost')
        $btn.Content = 'Ustaw'
    }
    [Windows.Controls.Grid]::SetColumn($btn, 2)
    $grid.Children.Add($btn) | Out-Null

    $border.Child = $grid
    return @{ Border = $border; Btn = $btn }
}

# Uczciwie: dwa motywy gryza sie z kolorami znaczeniowymi programu.
$SkinUwagi = @{
    bursztyn = 'Akcent jest blisko żółtego, którym program oznacza ostrożność przy zadaniu — te dwie rzeczy będą się zlewać.'
    karmin   = 'Akcent jest blisko czerwonego, którym program oznacza nieudaną zmianę i brak pliku — ostrzeżenia mniej rzucają się w oczy.'
    roz      = 'Akcent jest odcieniem różu bliskim czerwieni ostrzeżeń — przy szybkim rzucie oka mogą się mylić.'
    jasny    = 'Motyw dzienny. Wykres i pierścienie mają cieńsze linie niż na ciemnym tle.'
}

function Restart-Programu {
    param([string]$Id = '')
    if ($Id) { $script:MotywId = $Id }
    Save-Wyglad
    try {
        if ($IsCompiled -and $HostExe) {
            Start-Process -FilePath $HostExe
        } elseif ($ScriptPath) {
            Start-Process -FilePath $HostExe `
                -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',"`"$ScriptPath`"")
        } else {
            [System.Windows.MessageBox]::Show(
                'Nie udalo sie ustalic sciezki programu. Motyw jest zapisany - uruchom program ponownie recznie.',
                'OptiLauncher', 'OK', 'Information') | Out-Null
            return
        }
    } catch {
        [System.Windows.MessageBox]::Show(
            "Nie udalo sie uruchomic programu ponownie: $($_.Exception.Message)`n`nMotyw jest zapisany - wystarczy uruchomic recznie.",
            'OptiLauncher', 'OK', 'Warning') | Out-Null
        return
    }
    try { $Timer.Stop() } catch { }
    try { $Window.Close() } catch { }
}

function Pytaj-Restart {
    param([string]$Co)
    $r = [System.Windows.MessageBox]::Show(
        "$Co" + [Environment]::NewLine + [Environment]::NewLine +
        'Program uruchomi sie ponownie, zeby zastosowac zmiane. Trwajace zadanie zostanie przerwane.',
        'OptiLauncher - wyglad', 'YesNo', 'Question')
    return ($r -eq 'Yes')
}

function Odswiez-Wyglad {
    if ($script:Gestosc -eq 'zwarty') {
        $UI.SkinGestInfo.Text = 'W użyciu: zwarty'
        $UI.BtnGestKomfort.IsEnabled = $true
        $UI.BtnGestZwarty.IsEnabled  = $false
    } else {
        $UI.SkinGestInfo.Text = 'W użyciu: komfortowy'
        $UI.BtnGestKomfort.IsEnabled = $false
        $UI.BtnGestZwarty.IsEnabled  = $true
    }

    if (-not (Test-MicaMozliwa)) {
        $UI.SkinMicaInfo.Text  = 'Niedostępne na tym systemie — wymaga Windows 11.'
        $UI.BtnMica.IsEnabled  = $false
        $UI.BtnMica.Content    = 'Włącz'
    } elseif ($script:Mica) {
        $UI.SkinMicaInfo.Text = 'Włączone'
        $UI.BtnMica.Content   = 'Wyłącz'
    } else {
        $UI.SkinMicaInfo.Text = 'Wyłączone'
        $UI.BtnMica.Content   = 'Włącz'
    }
}

$UI.BtnGestKomfort.Add_Click({
    if ($script:Gestosc -eq 'komfort') { return }
    if (Pytaj-Restart 'Ustawic gestosc: komfortowa?') {
        $script:Gestosc = 'komfort'
        Restart-Programu
    }
})

$UI.BtnGestZwarty.Add_Click({
    if ($script:Gestosc -eq 'zwarty') { return }
    if (Pytaj-Restart 'Ustawic gestosc: zwarta?') {
        $script:Gestosc = 'zwarty'
        Restart-Programu
    }
})

$UI.BtnMica.Add_Click({
    if (-not (Test-MicaMozliwa)) { return }
    if ($script:Mica) {
        if (Pytaj-Restart 'Wylaczyc tlo Mica?') { $script:Mica = $false; Restart-Programu }
    } else {
        if (Pytaj-Restart 'Wlaczyc tlo Mica?')  { $script:Mica = $true;  Restart-Programu }
    }
})

function Render-Skins {
    Odswiez-Wyglad
    $UI.SkinHost.Children.Clear()
    $UI.SkinInfo.Text = "W użyciu: $($script:Motyw.Nazwa)"
    foreach ($m in $Motywy) {
        $akt  = ($m.Id -eq $script:MotywId)
        $card = New-SkinCard $m $akt
        if (-not $akt) {
            $mid = "$($m.Id)"
            $mnz = "$($m.Nazwa)"
            $card.Btn.Add_Click({
                $r = [System.Windows.MessageBox]::Show(
                    "Ustawic motyw: $mnz ?" + [Environment]::NewLine + [Environment]::NewLine +
                    "Program uruchomi sie ponownie, zeby wtopic kolory w interfejs. Trwajace zadanie zostanie przerwane.",
                    'OptiLauncher - wyglad', 'YesNo', 'Question')
                if ($r -eq 'Yes') { Restart-Programu $mid }
            }.GetNewClosure())
        }
        $UI.SkinHost.Children.Add($card.Border) | Out-Null
    }
}

# =====================================================================
#  BIBLIOTEKA GIER - interfejs
# =====================================================================
function Get-ExeIcon {
    param([string]$Path)
    try {
        if (-not (Test-Path -LiteralPath $Path)) { return $null }
        $i = [System.Drawing.Icon]::ExtractAssociatedIcon($Path)
        if (-not $i) { return $null }
        return [System.Windows.Interop.Imaging]::CreateBitmapSourceFromHIcon(
            $i.Handle, [System.Windows.Int32Rect]::Empty,
            [System.Windows.Media.Imaging.BitmapSizeOptions]::FromEmptyOptions())
    } catch { return $null }
}

function New-GameCard {
    param($G)

    $border = New-Object Windows.Controls.Border
    $border.Style = $Window.FindResource('Card')
    Zageszcz $border
    Add-CardMotion $border

    $grid = New-Object Windows.Controls.Grid
    foreach ($w in @([Windows.GridLength]::Auto,
                     (New-Object Windows.GridLength(1, [Windows.GridUnitType]::Star)),
                     [Windows.GridLength]::Auto, [Windows.GridLength]::Auto)) {
        $cd = New-Object Windows.Controls.ColumnDefinition
        $cd.Width = $w
        $grid.ColumnDefinitions.Add($cd)
    }

    # ikona gry
    $iconBox = New-Object Windows.Controls.Border
    $iconBox.Width = 44; $iconBox.Height = 44
    $iconBox.CornerRadius = New-Object Windows.CornerRadius 12
    $iconBox.Background = Br '#0A0F19'
    $iconBox.BorderBrush = Br '#1E2A3D'
    $iconBox.BorderThickness = New-Object Windows.Thickness 1
    $iconBox.Margin = New-Object Windows.Thickness 0,0,15,0
    $iconBox.VerticalAlignment = 'Center'
    $src = Get-ExeIcon $G.path
    if ($src) {
        $img = New-Object Windows.Controls.Image
        $img.Source = $src; $img.Width = 28; $img.Height = 28
        $iconBox.Child = $img
    } else {
        $ph = New-Object Windows.Controls.TextBlock
        $ph.Text = [System.Net.WebUtility]::HtmlDecode('&#xE7FC;')
        $ph.FontFamily = New-Object Windows.Media.FontFamily 'Segoe MDL2 Assets'
        $ph.FontSize = 18; $ph.Foreground = $Window.FindResource('Accent')
        $ph.HorizontalAlignment = 'Center'; $ph.VerticalAlignment = 'Center'
        $iconBox.Child = $ph
    }
    [Windows.Controls.Grid]::SetColumn($iconBox, 0)
    $grid.Children.Add($iconBox) | Out-Null

    # nazwa i sciezka
    $sp = New-Object Windows.Controls.StackPanel
    $sp.VerticalAlignment = 'Center'
    $nm = New-Object Windows.Controls.TextBlock
    $nm.Text = "$($G.name)"; $nm.Foreground = $Window.FindResource('Txt')
    $nm.FontSize = 14; $nm.FontWeight = 'SemiBold'
    $sp.Children.Add($nm) | Out-Null
    # Pelna sciezka i tak sie nie miesci - ucinana w polowie nie mowila nic.
    # Pokazujemy folder gry i nazwe pliku .exe, bo to wlasnie po nazwie exe
    # Windows przypisuje priorytet procesu. Calosc zostaje w podpowiedzi.
    $pt = New-Object Windows.Controls.TextBlock
    $pt.Foreground = $Window.FindResource('Dim')
    $pt.FontSize = 10.5
    $pt.TextTrimming = 'CharacterEllipsis'
    $pt.Margin = '0,3,16,0'
    $pt.ToolTip = "$($G.path)"

    # Wykryta gra bez zapisanej sciezki (np. wpis dodany recznie, zanim
    # udalo sie znalezc plik .exe) ma $G.path puste - Split-Path na pustym
    # stringu rzuca wyjatkiem, wiec najpierw sprawdzamy, czy jest co dzielic.
    $exeName = ''
    $folder  = ''
    if ("$($G.path)" -ne '') {
        try { $exeName = Split-Path "$($G.path)" -Leaf } catch { }
        try { $folder  = Split-Path (Split-Path "$($G.path)" -Parent) -Leaf } catch { }
    }
    if (-not $exeName) { $exeName = 'brak pliku .exe' }

    $rFold = New-Object Windows.Documents.Run
    if ($folder) { $rFold.Text = ($folder + '  \  ') } else { $rFold.Text = '' }
    $rFold.Foreground = $Window.FindResource('Dim')
    $pt.Inlines.Add($rFold)

    $rExe = New-Object Windows.Documents.Run
    $rExe.Text = $exeName
    $rExe.Foreground = $Window.FindResource('Muted')
    $pt.Inlines.Add($rExe)

    $sp.Children.Add($pt) | Out-Null
    [Windows.Controls.Grid]::SetColumn($sp, 1)
    $grid.Children.Add($sp) | Out-Null

    # stan
    $pill = New-Object Windows.Controls.Border
    $pill.CornerRadius = New-Object Windows.CornerRadius 8
    $pill.Padding = New-Object Windows.Thickness 11,4,11,5
    $pill.Margin  = New-Object Windows.Thickness 0,0,12,0
    $pill.VerticalAlignment = 'Center'
    $ptx = New-Object Windows.Controls.TextBlock
    $ptx.FontSize = 11; $ptx.FontWeight = 'SemiBold'
    if ($G.missing) {
        $fgHex = '#FB7185'
        $pill.Background = Br '#3A1220'; $ptx.Foreground = Br $fgHex; $ptx.Text = 'brak pliku'
    } elseif ($G.applied -ge 3) {
        $fgHex = '#34D399'
        $pill.Background = Br '#0F2E24'; $ptx.Foreground = Br $fgHex; $ptx.Text = 'maks. wydajność'
    } elseif ($G.applied -gt 0) {
        $fgHex = '#FBBF24'
        $pill.Background = Br '#33280A'; $ptx.Foreground = Br $fgHex; $ptx.Text = "$($G.applied)/3 ustawień"
    } else {
        $fgHex = '#7E8DA1'
        $pill.Background = Br '#141D2C'; $ptx.Foreground = Br $fgHex; $ptx.Text = 'domyślne'
    }
    # podpowiedz: ktore z trzech ustawien jest na miejscu, a ktorego brakuje
    if (-not $G.missing) {
        $zn = { param($b) if ($b) { '[v]' } else { '[ ]' } }
        $tt  = "$(& $zn $G.dGpu) preferencja GPU: wysoka wydajność" + [Environment]::NewLine
        $tt += "$(& $zn $G.dFso) wyłączone optymalizacje pełnoekranowe" + [Environment]::NewLine
        $tt += "$(& $zn $G.dPrio) wysoki priorytet procesora i we/wy"
        $pill.ToolTip = $tt
    } else {
        $pill.ToolTip = 'Plik .exe nie istnieje pod zapisaną ścieżką. Gra została odinstalowana lub przeniesiona.'
    }
    $pillRow = New-Object Windows.Controls.StackPanel
    $pillRow.Orientation = 'Horizontal'
    $pillRow.Children.Add((New-StatusDot $fgHex)) | Out-Null
    $pillRow.Children.Add($ptx) | Out-Null
    $pill.Child = $pillRow
    [Windows.Controls.Grid]::SetColumn($pill, 2)
    $grid.Children.Add($pill) | Out-Null

    # przyciski
    $btns = New-Object Windows.Controls.StackPanel
    $btns.Orientation = 'Horizontal'; $btns.VerticalAlignment = 'Center'

    $bOpt = New-Object Windows.Controls.Button
    $bOpt.Style = $Window.FindResource('Ghost')
    $bOpt.Content = 'Optymalizuj'
    $bOpt.IsEnabled = (-not $G.missing)
    $btns.Children.Add($bOpt) | Out-Null

    $bRev = New-Object Windows.Controls.Button
    $bRev.Style = $Window.FindResource('GhostWarn')
    $bRev.Content = 'Cofnij'
    $bRev.Margin = New-Object Windows.Thickness 8,0,0,0
    $bRev.IsEnabled = ($G.applied -gt 0)
    $btns.Children.Add($bRev) | Out-Null

    $bDel = New-Object Windows.Controls.Button
    $bDel.Style = $Window.FindResource('GhostDim')
    $bDel.Content = 'Usuń'
    $bDel.MinWidth = 60
    $bDel.Margin = New-Object Windows.Thickness 8,0,0,0
    $bDel.ToolTip = 'Usuwa grę tylko z tej listy, nie z dysku'
    $btns.Children.Add($bDel) | Out-Null

    [Windows.Controls.Grid]::SetColumn($btns, 3)
    $grid.Children.Add($btns) | Out-Null

    $border.Child = $grid
    return @{ Border = $border; Opt = $bOpt; Rev = $bRev; Del = $bDel }
}

# tylko filtr widoku - nie zmienia niczego w systemie
$script:GameOnlyOpt = $false

# Naglowek sekcji: kropka w kolorze grupy, tekst, cienka linia wypelniajaca
# reszte szerokosci i licznik po prawej. Sama linia robi najwiecej -
# oko dostaje wyrazna granice miedzy grupami zamiast luznego tekstu.
function New-GameSection {
    param([string]$Tytul, [string]$Kolor, [int]$Ile)

    $g = New-Object Windows.Controls.Grid
    $g.Margin = New-Object Windows.Thickness 4,18,2,10
    foreach ($w in @([Windows.GridLength]::Auto,
                     [Windows.GridLength]::Auto,
                     (New-Object Windows.GridLength(1, [Windows.GridUnitType]::Star)),
                     [Windows.GridLength]::Auto)) {
        $cd = New-Object Windows.Controls.ColumnDefinition
        $cd.Width = $w
        $g.ColumnDefinitions.Add($cd)
    }

    $dot = New-Object Windows.Controls.Border
    $dot.Width = 6; $dot.Height = 6
    $dot.CornerRadius = New-Object Windows.CornerRadius 3
    $dot.Background = Br $Kolor
    $dot.VerticalAlignment = 'Center'
    $dot.Margin = New-Object Windows.Thickness 0,0,9,0
    [Windows.Controls.Grid]::SetColumn($dot, 0)
    $g.Children.Add($dot) | Out-Null

    $tb = New-Object Windows.Controls.TextBlock
    $tb.Text = $Tytul
    $tb.FontSize = 11
    $tb.FontWeight = 'SemiBold'
    $tb.Foreground = Br $Kolor
    $tb.VerticalAlignment = 'Center'
    $tb.Margin = New-Object Windows.Thickness 0,0,12,0
    [Windows.Controls.Grid]::SetColumn($tb, 1)
    $g.Children.Add($tb) | Out-Null

    $ln = New-Object Windows.Controls.Border
    $ln.Height = 1
    $ln.Background = $Window.FindResource('Line')
    $ln.VerticalAlignment = 'Center'
    $ln.Opacity = 0.7
    [Windows.Controls.Grid]::SetColumn($ln, 2)
    $g.Children.Add($ln) | Out-Null

    $cnt = New-Object Windows.Controls.TextBlock
    $cnt.Text = "$Ile"
    $cnt.FontSize = 11
    $cnt.Foreground = $Window.FindResource('Dim')
    $cnt.VerticalAlignment = 'Center'
    $cnt.Margin = New-Object Windows.Thickness 12,0,0,0
    [Windows.Controls.Grid]::SetColumn($cnt, 3)
    $g.Children.Add($cnt) | Out-Null

    return $g
}

function Render-Games {
    $UI.GameHost.Children.Clear()
    $list = @()
    if ($null -ne $sync.Games) { $list = @($sync.Games) }
    if ($list.Count -eq 0) {
        Add-Log 'Widok gier: brak pozycji do wyświetlenia.' 'warn'
        $UI.GameEmpty.Visibility  = 'Visible'
        $UI.BtnGameAll.IsEnabled  = $false
        $UI.BtnGameFilter.IsEnabled = $false
        $UI.BtnGameClean.IsEnabled  = $false
        $UI.GameInfo.Text = ''
        return
    }
    $UI.GameEmpty.Visibility = 'Collapsed'
    $UI.BtnGameAll.IsEnabled = $true
    $UI.BtnGameFilter.IsEnabled = $true

    # --- podzial na trzy grupy wg faktycznego stanu w rejestrze ---
    $pelne   = @($list | Where-Object { -not $_.missing -and $_.applied -ge 3 })
    $czesc   = @($list | Where-Object { -not $_.missing -and $_.applied -gt 0 -and $_.applied -lt 3 })
    $bez     = @($list | Where-Object { -not $_.missing -and $_.applied -eq 0 })
    $brak    = @($list | Where-Object { $_.missing })

    $UI.BtnGameClean.IsEnabled = ($brak.Count -gt 0)
    $zopt = $pelne.Count + $czesc.Count
    $info = "Zoptymalizowanych: $zopt z $($list.Count)"
    if ($czesc.Count -gt 0) { $info += "   •   częściowo: $($czesc.Count)" }
    if ($bez.Count   -gt 0) { $info += "   •   bez zmian: $($bez.Count)" }
    if ($brak.Count  -gt 0) { $info += "   •   brak pliku: $($brak.Count)" }
    $UI.GameInfo.Text = $info
    # kolor licznika mowi to samo co liczby, tylko szybciej
    if     ($zopt -eq 0)            { $UI.GameInfo.Foreground = Br '#7E8DA1' }
    elseif ($pelne.Count -eq $list.Count) { $UI.GameInfo.Foreground = Br '#34D399' }
    else                            { $UI.GameInfo.Foreground = Br '#FBBF24' }

    if ($script:GameOnlyOpt) {
        $UI.BtnGameFilter.Content = 'Pokaż wszystkie'
        $grupy = @(
            @{ T = 'Z PEŁNĄ OPTYMALIZACJĄ';  K = '#34D399'; L = $pelne }
            @{ T = 'ZOPTYMALIZOWANE CZĘŚCIOWO'; K = '#FBBF24'; L = $czesc }
        )
    } else {
        $UI.BtnGameFilter.Content = 'Tylko zoptymalizowane'
        $grupy = @(
            @{ T = 'Z PEŁNĄ OPTYMALIZACJĄ';  K = '#34D399'; L = $pelne }
            @{ T = 'ZOPTYMALIZOWANE CZĘŚCIOWO'; K = '#FBBF24'; L = $czesc }
            @{ T = 'BEZ OPTYMALIZACJI';      K = '#7E8DA1'; L = $bez }
            @{ T = 'BRAK PLIKU NA DYSKU';    K = '#FB7185'; L = $brak }
        )
    }

    $pokazano = 0
    foreach ($gr in $grupy) {
        $poz = @($gr.L)
        if ($poz.Count -eq 0) { continue }
        $UI.GameHost.Children.Add((New-GameSection $gr.T $gr.K $poz.Count)) | Out-Null
        foreach ($g in ($poz | Sort-Object @{ Expression = { "$($_.name)" } })) {
            $card = New-GameCard $g
            $gp = "$($g.path)"
            $card.Opt.Add_Click({ Start-Worker 'games_opt'    @($gp) }.GetNewClosure())
            $card.Rev.Add_Click({ Start-Worker 'games_revert' @($gp) }.GetNewClosure())
            $card.Del.Add_Click({ Start-Worker 'games_del'    @($gp) }.GetNewClosure())
            $UI.GameHost.Children.Add($card.Border) | Out-Null
            $pokazano++
        }
    }

    if ($pokazano -eq 0) {
        $pusto = New-Object Windows.Controls.TextBlock
        $pusto.Text = 'Żadna z dodanych gier nie ma jeszcze zastosowanej optymalizacji. Użyj przycisku Pokaż wszystkie, żeby zobaczyć całą listę.'
        $pusto.Foreground = $Window.FindResource('Dim')
        $pusto.FontSize = 12.5
        $pusto.TextWrapping = 'Wrap'
        $pusto.Margin = New-Object Windows.Thickness 4,10,40,0
        $UI.GameHost.Children.Add($pusto) | Out-Null
    }
}

$UI.BtnGameClean.Add_Click({ Start-Worker 'games_clean' })

$UI.BtnGameFilter.Add_Click({
    $script:GameOnlyOpt = -not $script:GameOnlyOpt
    Render-Games
})

# =====================================================================
#  AUTOSTART - widok
# =====================================================================
$script:StartupLoaded = $false


# Pigulka z ocena z bazy opisow. Trzy stany, te same kolory co w reszcie
# programu: zielony "mozna", zolty "zalezy", czerwony "nie ruszaj".
$OcenyBazy = @{
    'bezpieczne' = @{ Tekst = 'można wyłączyć';   Fg = '#34D399'; Bg = '#0C2A22' }
    'zalezy'     = @{ Tekst = 'zależy od Ciebie'; Fg = '#FBBF24'; Bg = '#33280A' }
    'zostaw'     = @{ Tekst = 'zostaw włączone';  Fg = '#FB7185'; Bg = '#3A1220' }
}

function Nowa-PigulkaOceny {
    param([string]$Ocena)
    if (-not $Ocena -or -not $OcenyBazy.ContainsKey($Ocena)) { return $null }
    $o = $OcenyBazy[$Ocena]

    $pill = New-Object Windows.Controls.Border
    $pill.CornerRadius = New-Object Windows.CornerRadius 8
    $pill.Padding = New-Object Windows.Thickness 9,2,10,3
    $pill.Background = Br $o.Bg
    $pill.VerticalAlignment = 'Center'
    $pill.Margin = New-Object Windows.Thickness 0,0,10,0

    $row = New-Object Windows.Controls.StackPanel
    $row.Orientation = 'Horizontal'
    $row.Children.Add((New-StatusDot $o.Fg)) | Out-Null

    $tx = New-Object Windows.Controls.TextBlock
    $tx.Text = $o.Tekst
    $tx.FontSize = 10.5
    $tx.FontWeight = 'SemiBold'
    $tx.Foreground = Br $o.Fg
    $row.Children.Add($tx) | Out-Null

    $pill.Child = $row
    return $pill
}

# Wiersz "co to jest": pigulka, nazwa czlowiekowi zrozumiala, zrodlo.
# Pod spodem opis. Zwraca $null, gdy bazy nie ma albo nie zna wpisu -
# wtedy karta wyglada dokladnie tak, jak przedtem.
function Nowy-OpisZBazy {
    param([string]$Nazwa, [string]$Cmd = '')

    $info = Opis-Dla $Nazwa $Cmd
    if (-not $info) { return $null }

    $box = New-Object Windows.Controls.StackPanel
    $box.Margin = New-Object Windows.Thickness 0,8,14,0

    $gora = New-Object Windows.Controls.StackPanel
    $gora.Orientation = 'Horizontal'
    $p = Nowa-PigulkaOceny $info.ocena
    if ($p) { $gora.Children.Add($p) | Out-Null }

    $kto = New-Object Windows.Controls.TextBlock
    $kto.Text = $info.nazwa
    if ($info.zrodlo) { $kto.Text = "$($info.nazwa)   •   $($info.zrodlo)" }
    $kto.FontSize = 11.5
    $kto.VerticalAlignment = 'Center'
    $kto.Foreground = $Window.FindResource('Muted')
    $gora.Children.Add($kto) | Out-Null
    $box.Children.Add($gora) | Out-Null

    $op = New-Object Windows.Controls.TextBlock
    $op.Text = $info.opis
    $op.FontSize = 11.5
    $op.TextWrapping = 'Wrap'
    $op.LineHeight = 17
    $op.Foreground = $Window.FindResource('Dim')
    $op.Margin = New-Object Windows.Thickness 0,6,0,0
    $box.Children.Add($op) | Out-Null

    return $box
}

function New-StartupCard {
    param($It)

    $border = New-Object Windows.Controls.Border
    $border.Style = $Window.FindResource('Card')
    Zageszcz $border
    Add-CardMotion $border

    $grid = New-Object Windows.Controls.Grid
    foreach ($w in @([Windows.GridLength]::Auto,
                     (New-Object Windows.GridLength(1, [Windows.GridUnitType]::Star)),
                     [Windows.GridLength]::Auto)) {
        $cd = New-Object Windows.Controls.ColumnDefinition
        $cd.Width = $w
        $grid.ColumnDefinitions.Add($cd)
    }

    # kropka stanu w miekkiej obwodce - spojnie ze znaczkami ikon na innych kartach
    if ($It.enabled) { $dotBrush = $Window.FindResource('Good') }
    else              { $dotBrush = $Window.FindResource('Dim')  }
    $dotBadge = New-DotBadge $dotBrush
    $dotBadge.Wrap.Margin = New-Object Windows.Thickness 0,0,14,0
    $dot = $dotBadge.Dot
    [Windows.Controls.Grid]::SetColumn($dotBadge.Wrap, 0)
    $grid.Children.Add($dotBadge.Wrap) | Out-Null

    # nazwa, stan, polecenie
    $sp = New-Object Windows.Controls.StackPanel
    $sp.VerticalAlignment = 'Center'

    $nm = New-Object Windows.Controls.TextBlock
    $nm.Text = "$($It.name)"
    $nm.FontSize = 14; $nm.FontWeight = 'SemiBold'
    if ($It.enabled) { $nm.Foreground = $Window.FindResource('Txt')   }
    else             { $nm.Foreground = $Window.FindResource('Muted') }
    $sp.Children.Add($nm) | Out-Null

    $meta = New-Object Windows.Controls.TextBlock
    $stan = if ($It.enabled) { 'włączony' } else { 'wyłączony' }
    $meta.Text = "$stan   •   $($It.source)"
    $meta.FontSize = 11.5
    if ($It.enabled) { $meta.Foreground = $Window.FindResource('Good')  }
    else             { $meta.Foreground = $Window.FindResource('Muted') }
    $meta.Margin = New-Object Windows.Thickness 0,3,0,0
    $sp.Children.Add($meta) | Out-Null

    # z dlugiego polecenia z przelacznikami wyciagamy sam plik wykonywalny,
    # calosc zostaje w podpowiedzi
    $cmd = New-Object Windows.Controls.TextBlock
    $cmd.FontSize = 11
    $cmd.Foreground = $Window.FindResource('Dim')
    $cmd.TextTrimming = 'CharacterEllipsis'
    $cmd.Margin = New-Object Windows.Thickness 0,4,0,0
    $cmd.ToolTip = "$($It.cmd)"

    $krotki = "$($It.cmd)"
    try {
        $m = [regex]::Match($krotki, '(?i)"?([A-Za-z]:\\[^"]*?\.exe)"?')
        if ($m.Success) { $krotki = Split-Path $m.Groups[1].Value -Leaf }
    } catch { }
    $cmd.Text = $krotki
    $sp.Children.Add($cmd) | Out-Null

    # Nazwa pliku nic nie mowi. Opis z bazy to jedyny powod, dla ktorego
    # ta zakladka jest czyms wiecej niz lista do odhaczenia.
    $opisBox = Nowy-OpisZBazy "$($It.name)" "$($It.cmd)"
    if ($opisBox) { $sp.Children.Add($opisBox) | Out-Null }

    # Zmierzone opoznienie startu - nie nasz szacunek, tylko liczba
    # z dziennika Windows. To ona zamienia te zakladke z listy do
    # odhaczania w liste uszeregowana wedlug tego, co realnie boli.
    $kluczOp = Klucz-Nazwy "$($It.name)"
    $kluczOp2 = Klucz-Polecenia "$($It.cmd)"
    $msOp = 0
    foreach ($k in @($kluczOp, $kluczOp2)) {
        if ($k -and $script:OpoznieniaStartu.ContainsKey($k)) {
            if ($script:OpoznieniaStartu[$k] -gt $msOp) { $msOp = $script:OpoznieniaStartu[$k] }
        }
    }
    if ($msOp -gt 0) {
        $op = New-Object Windows.Controls.TextBlock
        $op.FontSize = 11.5
        $op.Margin = '0,7,16,0'
        $op.TextWrapping = 'Wrap'

        $opL = New-Object Windows.Documents.Run
        $opL.Text = ((Fmt-Sek $msOp) + ' do startu systemu  ')
        $opL.Foreground = $(if ($msOp -ge 3000) { Br '#FB7185' } elseif ($msOp -ge 1000) { Br '#FBBF24' } else { Br '#34D399' })
        $opL.FontWeight = 'SemiBold'
        $op.Inlines.Add($opL)

        $opT = New-Object Windows.Documents.Run
        $opT.Text = 'zmierzone przez Windows, średnia z ostatnich rozruchów'
        $opT.Foreground = $Window.FindResource('Dim')
        $op.Inlines.Add($opT)

        $sp.Children.Add($op) | Out-Null
    }

    [Windows.Controls.Grid]::SetColumn($sp, 1)
    $grid.Children.Add($sp) | Out-Null

    # przelacznik
    $btn = New-Object Windows.Controls.Primitives.ToggleButton
    $btn.Style   = $Window.FindResource('Switch')
    $btn.IsChecked = [bool]$It.enabled
    $btn.VerticalAlignment = 'Center'
    $btn.Margin = New-Object Windows.Thickness 16,0,0,0
    $btn.ToolTip = if ($It.enabled) { 'Kliknij, żeby wyłączyć' } else { 'Kliknij, żeby włączyć' }
    [Windows.Controls.Grid]::SetColumn($btn, 2)
    $grid.Children.Add($btn) | Out-Null

    $border.Child = $grid
    return @{ Border = $border; Btn = $btn; Dot = $dot }
}

function Render-Startup {
    $UI.StartupHost.Children.Clear()
    $lista = @($sync.Startup)
    if (-not $lista -or $lista.Count -eq 0) {
        $UI.StartupEmpty.Visibility = 'Visible'
        $UI.StartupInfo.Text = ''
        return
    }
    $UI.StartupEmpty.Visibility = 'Collapsed'

    $wl = @($lista | Where-Object { $_.enabled }).Count
    $wy = $lista.Count - $wl
    $UI.StartupInfo.Text = "Pozycji: $($lista.Count)   •   włączonych: $wl   •   wyłączonych: $wy"

    # wlaczone na gorze - to one kosztuja czas rozruchu
    $posort = $lista | Sort-Object @{ Expression = { -[int][bool]$_.enabled } }, @{ Expression = { "$($_.name)" } }
    foreach ($it in $posort) {
        $card = New-StartupCard $it
        $sid  = "$($it.id)"
        $card.Btn.Add_Click({ Start-Worker 'startup_toggle' @($sid) }.GetNewClosure())
        $UI.StartupHost.Children.Add($card.Border) | Out-Null
    }
}

$UI.BtnStartupRefresh.Add_Click({ Start-Worker 'startup_scan' })

# Pasek tytulu lapie MouseLeftButtonDown i wola DragMove(), ktore
# przechwytuje mysz i wchodzi w petle przeciagania okna - zwolnienie
# przycisku nigdy nie dociera do dziecka. Dlatego pigulka reaguje na
