        Sprawdz-Recznie
    })
}

# =====================================================================
#  PROCESY W TLE - widok
# =====================================================================
$script:ProcLoaded = $false
$script:AppsLoaded = $false

function New-ProcCard {
    param($It)
    $border = New-Object Windows.Controls.Border
    $border.Style = $Window.FindResource('Card')
    Zageszcz $border
    Add-CardMotion $border

    $grid = New-Object Windows.Controls.Grid
    foreach ($w in @((New-Object Windows.GridLength(1, [Windows.GridUnitType]::Star)),
                     [Windows.GridLength]::Auto,
                     [Windows.GridLength]::Auto)) {
        $cd = New-Object Windows.Controls.ColumnDefinition
        $cd.Width = $w
        $grid.ColumnDefinitions.Add($cd)
    }

    $sp = New-Object Windows.Controls.StackPanel
    $sp.VerticalAlignment = 'Center'

    $nm = New-Object Windows.Controls.TextBlock
    $nm.Text = "$($It.name)"
    $nm.FontSize = 14; $nm.FontWeight = 'SemiBold'
    $nm.Foreground = $Window.FindResource('Txt')
    $sp.Children.Add($nm) | Out-Null

    $meta = New-Object Windows.Controls.TextBlock
    $opis = ''
    if ($It.ile -gt 1) { $opis = "$($It.ile) procesów" } else { $opis = '1 proces' }
    if ($It.tytul)     { $opis += "   •   $($It.tytul)" }
    if ($It.chroniony) { $opis += '   •   proces systemowy' }
    $meta.Text = $opis
    $meta.FontSize = 11
    $meta.TextTrimming = 'CharacterEllipsis'
    $meta.Foreground = $Window.FindResource('Dim')
    $meta.Margin = New-Object Windows.Thickness 0,4,16,0
    $sp.Children.Add($meta) | Out-Null

    $opisBox = Nowy-OpisZBazy "$($It.name)"
    if ($opisBox) { $sp.Children.Add($opisBox) | Out-Null }

    [Windows.Controls.Grid]::SetColumn($sp, 0)
    $grid.Children.Add($sp) | Out-Null

    # zuzycie pamieci
    $pill = New-Object Windows.Controls.Border
    $pill.CornerRadius = New-Object Windows.CornerRadius 8
    $pill.Padding = New-Object Windows.Thickness 11,4,11,5
    $pill.Margin  = New-Object Windows.Thickness 0,0,12,0
    $pill.VerticalAlignment = 'Center'
    $ptx = New-Object Windows.Controls.TextBlock
    $ptx.FontSize = 11; $ptx.FontWeight = 'SemiBold'
    $ptx.Text = "{0:N0} MB" -f $It.ramMB
    if ($It.ramMB -ge 1000)     { $fgHex = '#FB7185'; $pill.Background = Br '#3A1220'; $ptx.Foreground = Br $fgHex }
    elseif ($It.ramMB -ge 300)  { $fgHex = '#FBBF24'; $pill.Background = Br '#33280A'; $ptx.Foreground = Br $fgHex }
    else                        { $fgHex = '#7E8DA1'; $pill.Background = Br '#141D2C'; $ptx.Foreground = Br $fgHex }
    $pillRow = New-Object Windows.Controls.StackPanel
    $pillRow.Orientation = 'Horizontal'
    $pillRow.Children.Add((New-StatusDot $fgHex)) | Out-Null
    $pillRow.Children.Add($ptx) | Out-Null
    $pill.Child = $pillRow
    [Windows.Controls.Grid]::SetColumn($pill, 1)
    $grid.Children.Add($pill) | Out-Null

    $btn = New-Object Windows.Controls.Button
    $btn.Style = $Window.FindResource('GhostWarn')
    $btn.Content = 'Zakończ'
    $btn.Width = 110
    $btn.VerticalAlignment = 'Center'
    $btn.IsEnabled = (-not $It.chroniony)
    if ($It.chroniony) { $btn.ToolTip = 'Proces systemowy – zamknięcie zawiesiłoby Windows.' }
    [Windows.Controls.Grid]::SetColumn($btn, 2)
    $grid.Children.Add($btn) | Out-Null

    $border.Child = $grid
    return @{ Border = $border; Btn = $btn }
}

function Render-Procs {
    $UI.ProcHost.Children.Clear()
    $lista = @()
    if ($null -ne $sync.Procs) { $lista = @($sync.Procs) }
    if ($lista.Count -eq 0) { $UI.ProcInfo.Text = ''; return }

    $suma = 0.0
    foreach ($p in $lista) { $suma += [double]$p.ramMB }
    $UI.ProcInfo.Text = "Grup procesów: $($lista.Count)   •   łącznie: {0:N1} GB" -f ($suma / 1024)

    # tylko pierwsze 30 - dalej sa same drobiazgi po kilka MB
    foreach ($it in ($lista | Select-Object -First 30)) {
        $card = New-ProcCard $it
        $pn = "$($it.name)"
        $card.Btn.Add_Click({
            $r = [System.Windows.MessageBox]::Show(
                "Zamknąć wszystkie procesy o nazwie: $pn ?" + [Environment]::NewLine + [Environment]::NewLine +
                "Niezapisane dane w tym programie zostaną utracone.",
                'OptiLauncher', 'YesNo', 'Warning')
            if ($r -eq 'Yes') { Start-Worker 'proc_kill' @($pn) }
        }.GetNewClosure())
        $UI.ProcHost.Children.Add($card.Border) | Out-Null
    }
}

$UI.BtnProcRefresh.Add_Click({ Start-Worker 'proc_scan' })

# =====================================================================
#  LACZE - widok
# =====================================================================
$LinkStan = @{
    'ok'   = '#34D399'
    'warn' = '#FBBF24'
    'err'  = '#FB7185'
}

function New-LinkRow {
    param($R)
    $border = New-Object Windows.Controls.Border
    $border.Style = $Window.FindResource('Card')
    Zageszcz $border
    Add-CardMotion $border

    $grid = New-Object Windows.Controls.Grid
    foreach ($w in @([Windows.GridLength]::Auto,
                     (New-Object Windows.GridLength(1, [Windows.GridUnitType]::Star)))) {
        $cd = New-Object Windows.Controls.ColumnDefinition
        $cd.Width = $w
        $grid.ColumnDefinitions.Add($cd)
    }

    $kolor = $LinkStan["$($R.stan)"]
    if (-not $kolor) { $kolor = '#7E8DA1' }

    $dot = New-Object Windows.Controls.Border
    $dot.Width = 8; $dot.Height = 8
    $dot.CornerRadius = New-Object Windows.CornerRadius 4
    $dot.VerticalAlignment = 'Top'
    $dot.Margin = New-Object Windows.Thickness 2,7,14,0
    $dot.Background = Br $kolor
    [Windows.Controls.Grid]::SetColumn($dot, 0)
    $grid.Children.Add($dot) | Out-Null

    $sp = New-Object Windows.Controls.StackPanel

    $lb = New-Object Windows.Controls.TextBlock
    $lb.Text = "$($R.label)"
    $lb.FontSize = 12; $lb.FontWeight = 'SemiBold'
    $lb.Foreground = $Window.FindResource('Muted')
    $sp.Children.Add($lb) | Out-Null

    $vl = New-Object Windows.Controls.TextBlock
    $vl.Text = "$($R.value)"
    $vl.FontSize = 13
    $vl.TextWrapping = 'Wrap'
    $vl.Margin = New-Object Windows.Thickness 0,3,10,0
    if ("$($R.stan)") { $vl.Foreground = Br $kolor } else { $vl.Foreground = $Window.FindResource('Txt') }
    $sp.Children.Add($vl) | Out-Null

    [Windows.Controls.Grid]::SetColumn($sp, 1)
    $grid.Children.Add($sp) | Out-Null

    $border.Child = $grid
    return $border
}

function New-NetPropCard {
    param($It)
