function Render-Net {
    $UI.LinkHost.Children.Clear()
    $UI.LinkPropHost.Children.Clear()

    $rows = @()
    if ($null -ne $sync.NetDiag) { $rows = @($sync.NetDiag) }
    $props = @()
    if ($null -ne $sync.NetProps) { $props = @($sync.NetProps) }

    if ($rows.Count -eq 0) { $UI.LinkInfo.Text = ''; return }

    $zle = @($rows | Where-Object { $_.stan -eq 'err' }).Count
    $ost = @($rows | Where-Object { $_.stan -eq 'warn' }).Count
    if ($zle -gt 0) {
        $UI.LinkInfo.Text = "Wykryto problemy: $zle"
        $UI.LinkInfo.Foreground = Br '#FB7185'
    } elseif ($ost -gt 0) {
        $UI.LinkInfo.Text = "Uwagi: $ost"
        $UI.LinkInfo.Foreground = Br '#FBBF24'
    } else {
        $UI.LinkInfo.Text = 'Łącze bez zastrzeżeń.'
        $UI.LinkInfo.Foreground = Br '#34D399'
    }

    foreach ($r in $rows) { $UI.LinkHost.Children.Add((New-LinkRow $r)) | Out-Null }

    if ($props.Count -gt 0) {
        $UI.LinkPropHost.Children.Add((New-GameSection 'USTAWIENIA STEROWNIKA KARTY' '#60A5FA' $props.Count)) | Out-Null
        foreach ($p in $props) {
            $card = New-NetPropCard $p
            $kw = "$($p.kw)"
            $card.Btn.Add_Click({ Start-Worker 'net_prop' @($kw) }.GetNewClosure())
            $UI.LinkPropHost.Children.Add($card.Border) | Out-Null
        }
    }
}

$UI.BtnLinkScan.Add_Click({ Start-Worker 'net_scan' })

