                "Aplikację można później zainstalować z powrotem ze Sklepu Microsoft.",
                'OptiLauncher', 'YesNo', 'Question')
            if ($r -eq 'Yes') { Start-Worker 'appx_remove' @($aid) }
        }.GetNewClosure())
        $UI.AppsHost.Children.Add($card.Border) | Out-Null
    }
}

