        "Optymalizacja gier", 'YesNo', 'Question')
    if ($r -eq 'Yes') { Start-Worker 'games_opt' @('__all__') }
})

$UI.BtnDashFull.Add_Click({ $UI.BtnFull.RaiseEvent((New-Object Windows.RoutedEventArgs ([Windows.Controls.Button]::ClickEvent))) })
$UI.BtnDashGames.Add_Click({ $UI.NavGames.IsChecked = $true })
$UI.BtnDashDiag.Add_Click({ $UI.NavDiag.IsChecked = $true; Start-Worker 'diag' })

$GaugeTimer = New-Object System.Windows.Threading.DispatcherTimer
$GaugeTimer.Interval = [TimeSpan]::FromMilliseconds(1200)
$GaugeTimer.Add_Tick({
    # licznik chodzi caly czas, zeby historia nie miala dziur po powrocie
    # na Pulpit; rysujemy tylko wtedy, gdy jest to widoczne
    Update-Gauges
    Push-Hist $script:HistCpu ([double]$script:GTarget['cpu'])
    Push-Hist $script:HistRam ([double]$script:GTarget['ram'])
    if ($UI.PanelDash.Visibility -eq 'Visible') { Draw-Sparks }
})
$GaugeTimer.Start()

# Zegar plynnosci pierscieni. Nie rysuje nic, gdy wartosci sa na miejscu.
$RingTimer = New-Object System.Windows.Threading.DispatcherTimer
$RingTimer.Interval = [TimeSpan]::FromMilliseconds(45)
$RingTimer.Add_Tick({
    if ($UI.PanelDash.Visibility -ne 'Visible') { return }
    foreach ($k in @('cpu','ram','dsk')) {
        $t = [double]$script:GTarget[$k]
        $c = [double]$script:GCur[$k]
        $d = $t - $c
        if ([Math]::Abs($d) -lt 0.12) {
            if ($c -ne $t) { $script:GCur[$k] = $t } else { continue }
        } else {
            $c = $c + ($d * 0.2)
            $script:GCur[$k] = $c
        }
        $v = [double]$script:GCur[$k]
        switch ($k) {
            'cpu' { $UI.TxtCpu.Text = "{0:N0}%" -f $v; Set-Ring $UI.RingCpu $v (Hue $v) }
            'ram' { $UI.TxtRam.Text = "{0:N0}%" -f $v; Set-Ring $UI.RingRam $v (Hue $v) }
            'dsk' { $UI.TxtDsk.Text = "{0:N0}%" -f $v; Set-Ring $UI.RingDsk $v (Hue $v) }
        }
    }
})
$RingTimer.Start()

# ---------------------------------------------------------------------
#  Konsola chowana suwakiem szerokosci
# ---------------------------------------------------------------------
# ---------------------------------------------------------------------
#  Filtr zadan i skroty klawiszowe
# ---------------------------------------------------------------------
$UI.SearchBox.Add_TextChanged({ Apply-Filter })
$UI.SearchClear.Add_Click({ $UI.SearchBox.Text = ''; $UI.SearchBox.Focus() | Out-Null })

$Window.Add_PreviewKeyDown({
    param($sender, $e)
    $ctrl = ([System.Windows.Input.Keyboard]::Modifiers -band [System.Windows.Input.ModifierKeys]::Control) -ne 0

    if ($e.Key -eq 'Escape') {
        if ("$($UI.SearchBox.Text)" -ne '') { $UI.SearchBox.Text = ''; $e.Handled = $true }
        return
    }
    if ($e.Key -eq 'F5') {
        if (-not $sync.Busy) { Start-Worker 'scan' }
        $e.Handled = $true
        return
    }
    if (-not $ctrl) { return }

    switch ("$($e.Key)") {
        'F' {
            if ($UI.HeadTools.Visibility -ne 'Visible') { $UI.NavGry.IsChecked = $true }
            $UI.SearchBox.Focus() | Out-Null
            $UI.SearchBox.SelectAll()
            $e.Handled = $true
        }
        'K' { $UI.BtnConsole.RaiseEvent((New-Object Windows.RoutedEventArgs ([Windows.Controls.Button]::ClickEvent))); $e.Handled = $true }
        'R' { if (-not $sync.Busy) { Start-Worker 'scan' }; $e.Handled = $true }
        default {
            # Ctrl + 1..9 przeskakuje po zakladkach w kolejnosci z menu
            $k = "$($e.Key)"
            if ($k -match '^D([1-9])$') {
                $i = [int]$Matches[1] - 1
                if ($i -lt $Pages.Count) { $Pages[$i].Nav.IsChecked = $true; $e.Handled = $true }
            }
        }
    }
})

$script:ConsoleOpen = $true
$UI.BtnConsole.Add_Click({
    $script:ConsoleOpen = -not $script:ConsoleOpen
    $to = 0
    if ($script:ConsoleOpen) { $to = 320 }
    try { $UI.ConsolePane.BeginAnimation([Windows.FrameworkElement]::WidthProperty, (New-Anim $to $null 280 0 $true)) }
    catch { $UI.ConsolePane.Width = $to }
})

# Dymek ze sprzetem - PlacementTarget nie idzie ustawic w XAML (Popup wtedy
