Update-Dash
Add-Log "OptiLauncher v$AppVersion uruchomiony jako Administrator." 'ok'
Add-Log "Log: $LogFile"
Set-Status 'Sprawdzam stan systemu...'

# =====================================================================
#  OKNO AKTUALIZACJI
#  Budowane w kodzie, nie w XAML - dzieki temu nie dokladamy nic do
#  glownego szablonu okna i nie ma czego zepsuc przy zmianie motywu.
#  Kolory ida przez Br, wiec okno chodzi za wybranym motywem.
# =====================================================================

function Nowy-PrzyciskAkt {
    param([string]$Tekst, [string]$Tlo, [string]$Napis, [switch]$Glowny)
    $b = New-Object Windows.Controls.Button
    $b.Content    = $Tekst
    $b.Foreground = (Br $Napis)
    $b.Background = (Br $Tlo)
    $b.BorderBrush = (Br '#1E2A3A')
    $b.BorderThickness = New-Object Windows.Thickness 1
    $b.Padding    = New-Object Windows.Thickness 16,8,16,8
    $b.Margin     = New-Object Windows.Thickness 0,0,8,0
    $b.Cursor     = 'Hand'
    $b.FontSize   = 13
    if ($Glowny) { $b.FontWeight = 'SemiBold' }
    return $b
}

# =====================================================================
#  WSKAZNIK AKTUALIZACJI W PASKU TYTULU
#
#  Okno z aktualizacja pokazuje sie tylko w chwili, gdy cos sie znajdzie.
#  Poza tym momentem uzytkownik nie mial gdzie sprawdzic, na czym stoi.
#  Pigulka obok odznaki Administrator jest widoczna caly czas i klikalna.
# =====================================================================

$script:AktZnaleziona = $null

# =====================================================================
#  CZAS URUCHAMIANIA
#
#  Windows od wersji 7 mierzy kazdy rozruch i zapisuje wynik do dziennika
#  Microsoft-Windows-Diagnostics-Performance/Operational:
#    100 - ile trwal rozruch (BootTime, MainPathBootTime)
#    101 - ktora APLIKACJA go opoznila i o ile
#    103 - ktora USLUGA go opoznila i o ile
#
#  To sa pomiary systemu, nie nasze szacunki. Dzieki nim zakladka
#  Autostart przestaje byc lista do zgadywania: przy wpisie widac, ile
#  sekund realnie dokladal do startu.
# =====================================================================

$script:OpoznieniaStartu = @{}

function Zbadaj-CzasStartu {
    param($Okno, [scriptblock]$Gotowe)

    $wspolne = [hashtable]::Synchronized(@{ Gotowe = $false; Wynik = $null })

    try {
        $rs = [runspacefactory]::CreateRunspace()
        $rs.ApartmentState = 'STA'
        $rs.ThreadOptions  = 'ReuseThread'
        $rs.Open()
        $rs.SessionStateProxy.SetVariable('S', $wspolne)

        $ps = [powershell]::Create()
        $ps.Runspace = $rs
        $null = $ps.AddScript({
            $wynik = @{ Ok = $false; Blad = ''; Boot = 0; Main = 0; Ile = 0; Winni = @(); Historia = @() }
            $log = 'Microsoft-Windows-Diagnostics-Performance/Operational'
            try {
                # Ostatnie rozruchy - czas kazdego z nich. Jeden pomiar mowi
                # tylko "tyle trwalo dzis"; dopiero ciag pokazuje, czy zmiany
                # w Autostarcie cokolwiek dadzy.
                $e100 = @(Get-WinEvent -FilterHashtable @{ LogName = $log; Id = 100 } `
                                       -MaxEvents 24 -ErrorAction Stop)
                $hist = New-Object System.Collections.ArrayList
                foreach ($e in $e100) {
                    try {
                        $x = [xml]$e.ToXml()
                        $d = @{}
                        foreach ($pd in $x.Event.EventData.Data) { $d[$pd.Name] = "$($pd.'#text')" }
                        $bt = 0
                        if ($d['BootTime']) { $bt = [int]$d['BootTime'] }
                        if ($bt -le 0) { continue }
                        [void]$hist.Add([pscustomobject]@{ Ms = $bt; Kiedy = $e.TimeCreated })
                    } catch { }
                }
                if ($hist.Count -gt 0) {
                    $wynik.Ok   = $true
                    $wynik.Boot = $hist[0].Ms
                    # Najstarszy z lewej, najnowszy z prawej.
                    $wynik.Historia = @($hist | Sort-Object Kiedy)
                    try {
                        $x0 = [xml]$e100[0].ToXml()
                        foreach ($pd in $x0.Event.EventData.Data) {
                            if ($pd.Name -eq 'MainPathBootTime') { $wynik.Main = [int]"$($pd.'#text')" }
                        }
                    } catch { }
                }

                # Winowajcy z ostatnich kilkunastu rozruchow. Pojedynczy
                # pomiar potrafi klamac (akurat trwala aktualizacja), wiec
                # bierzemy srednia z tego, co system zdazyl zapisac.
                $sumy = @{}
                $ile  = @{}
                foreach ($id in @(101, 103)) {
                    $ev = @()
                    try {
                        $ev = @(Get-WinEvent -FilterHashtable @{ LogName = $log; Id = $id } `
                                             -MaxEvents 60 -ErrorAction Stop)
                    } catch { }
                    foreach ($e in $ev) {
                        try {
                            $x = [xml]$e.ToXml()
                            $d = @{}
                            foreach ($pd in $x.Event.EventData.Data) { $d[$pd.Name] = "$($pd.'#text')" }
                            $nazwa = "$($d['Name'])"
                            $ms    = 0
                            if ($d['TotalTime']) { $ms = [int]$d['TotalTime'] }
                            if ($ms -le 0 -or -not $nazwa) { continue }
                            if (-not $sumy.ContainsKey($nazwa)) { $sumy[$nazwa] = 0; $ile[$nazwa] = 0 }
                            $sumy[$nazwa] = $sumy[$nazwa] + $ms
                            $ile[$nazwa]  = $ile[$nazwa] + 1
                        } catch { }
                    }
                }

                $lista = New-Object System.Collections.ArrayList
                foreach ($k in $sumy.Keys) {
                    $sr = [int]($sumy[$k] / [Math]::Max(1, $ile[$k]))
                    if ($sr -lt 300) { continue }   # ponizej 0,3 s to szum
                    [void]$lista.Add([pscustomobject]@{ Nazwa = $k; Ms = $sr; Razy = $ile[$k] })
                }
                $wynik.Winni = @($lista | Sort-Object Ms -Descending | Select-Object -First 6)
                $wynik.Ile   = @($lista).Count
            } catch {
                $wynik.Blad = "$($_.Exception.Message)"
            }
            $S.Wynik = $wynik
            $S.Gotowe = $true
        })
        $uchwyt = $ps.BeginInvoke()
    } catch { return }

    $zegar = New-Object System.Windows.Threading.DispatcherTimer
    $zegar.Interval = [TimeSpan]::FromMilliseconds(300)
    $zegar.Add_Tick({
        if (-not $wspolne.Gotowe) { return }
        $zegar.Stop()
        try { $null = $ps.EndInvoke($uchwyt) } catch { }
        try { $ps.Dispose(); $rs.Close(); $rs.Dispose() } catch { }
        try { & $Gotowe $wspolne.Wynik } catch { }
    }.GetNewClosure())
    $zegar.Start()
}

function Fmt-Sek {
    param([int]$Ms)
    if ($Ms -ge 1000) { return ('{0:N1} s' -f ($Ms / 1000)) }
    return ("$Ms ms")
}

function Pokaz-CzasStartu {
    param($W)

    if (-not $UI.BootTime) { return }
    $UI.BootHost.Children.Clear()

    if (-not $W -or -not $W.Ok) {
        $UI.BootTime.Text = 'brak danych'
        $UI.BootHint.Text = 'Windows nie zapisał jeszcze pomiaru rozruchu. Zwykle pojawia się po kilku uruchomieniach komputera.'
        return
    }

    $UI.BootTime.Text = Fmt-Sek $W.Boot

    $opis = 'Tyle trwał ostatni rozruch według pomiaru Windows.'
    if ($W.Main -gt 0 -and $W.Main -lt $W.Boot) {
        $opis = "Tyle trwał ostatni rozruch według pomiaru Windows. Do pulpitu: $(Fmt-Sek $W.Main), reszta to programy dogrywające się w tle."
    }
    $UI.BootHint.Text = $opis

    # --- historia: slupek na kazdy rozruch ---
    # To jest odpowiedz na pytanie "czy moje zmiany cokolwiek dały".
    # Bez tego Autostart jest wiara, a nie pomiarem.
    $hist = @($W.Historia)
    if ($hist.Count -ge 3) {
        $naglH = New-Object Windows.Controls.TextBlock
        $naglH.Text = "Ostatnie rozruchy ($($hist.Count))"
        $naglH.Foreground = Br '#9FB3C8'
        $naglH.FontSize = 11.5
        $naglH.Margin = New-Object Windows.Thickness 0,0,0,7
        $UI.BootHost.Children.Add($naglH) | Out-Null

        $maxH = 1
        foreach ($h in $hist) { if ($h.Ms -gt $maxH) { $maxH = $h.Ms } }

        $wykres = New-Object Windows.Controls.StackPanel
        $wykres.Orientation = 'Horizontal'
        $wykres.Height = 56
        $wykres.Margin = New-Object Windows.Thickness 0,0,0,6
        foreach ($h in $hist) {
            $kol = New-Object Windows.Controls.Border
            $kol.Width  = 13
            $kol.Margin = New-Object Windows.Thickness 0,0,3,0
            $kol.VerticalAlignment = 'Bottom'
            $kol.CornerRadius = New-Object Windows.CornerRadius 3
            $kol.Height = [Math]::Max(4, 56 * ($h.Ms / $maxH))
            $kol.Background = $(if ($h.Ms -ge 60000) { Br '#FB7185' } elseif ($h.Ms -ge 30000) { Br '#FBBF24' } else { Br '#34D399' })
            $kol.ToolTip = ((Fmt-Sek $h.Ms) + '   ' + $h.Kiedy.ToString('yyyy-MM-dd HH:mm'))
            $wykres.Children.Add($kol) | Out-Null
        }
        $UI.BootHost.Children.Add($wykres) | Out-Null

        # Porownanie polowek - bez udawania precyzji, ktorej tu nie ma.
        if ($hist.Count -ge 6) {
            $n = [Math]::Min(5, [int]($hist.Count / 2))
            $stare = @($hist | Select-Object -First $n)
            $nowe  = @($hist | Select-Object -Last  $n)
            $srS = ($stare | Measure-Object Ms -Average).Average
            $srN = ($nowe  | Measure-Object Ms -Average).Average
            $roz = [int]($srS - $srN)

            $tr = New-Object Windows.Controls.TextBlock
            $tr.FontSize = 11.5
            $tr.TextWrapping = 'Wrap'
            $tr.Margin = New-Object Windows.Thickness 0,0,0,10

            $trL = New-Object Windows.Documents.Run
            if ($roz -ge 1500) {
                $trL.Text = ('Szybciej o ' + (Fmt-Sek $roz) + '  ')
                $trL.Foreground = Br '#34D399'
            } elseif ($roz -le -1500) {
                $trL.Text = ('Wolniej o ' + (Fmt-Sek ([Math]::Abs($roz))) + '  ')
                $trL.Foreground = Br '#FB7185'
            } else {
                $trL.Text = 'Bez wyraźnej zmiany  '
                $trL.Foreground = Br '#9FB3C8'
            }
            $trL.FontWeight = 'SemiBold'
            $tr.Inlines.Add($trL)

            $trT = New-Object Windows.Documents.Run
            $trT.Text = "średnia z $n ostatnich rozruchów wobec $n najstarszych z tej listy"
            $trT.Foreground = $Window.FindResource('Dim')
            $tr.Inlines.Add($trT)

            $UI.BootHost.Children.Add($tr) | Out-Null
        }
    }

    if (@($W.Winni).Count -eq 0) {
        $t = New-Object Windows.Controls.TextBlock
        $t.Text = 'Żaden program nie opóźnia startu na tyle, żeby system to odnotował.'
        $t.Foreground = Br '#34D399'
        $t.FontSize = 11.5
        $t.TextWrapping = 'Wrap'
        $UI.BootHost.Children.Add($t) | Out-Null
        return
    }

    $naglowek = New-Object Windows.Controls.TextBlock
    $naglowek.Text = 'Co najbardziej opóźnia start, według Windows:'
    $naglowek.Foreground = Br '#9FB3C8'
    $naglowek.FontSize = 11.5
    $naglowek.Margin = New-Object Windows.Thickness 0,0,0,8
    $UI.BootHost.Children.Add($naglowek) | Out-Null

    $max = 1
    foreach ($poz in $W.Winni) { if ($poz.Ms -gt $max) { $max = $poz.Ms } }

    foreach ($poz in $W.Winni) {
        $rzad = New-Object Windows.Controls.Grid
        $rzad.Margin = New-Object Windows.Thickness 0,0,0,6
        foreach ($sz in @((New-Object Windows.GridLength(1, [Windows.GridUnitType]::Star)),
                          [Windows.GridLength]::Auto)) {
            $cd = New-Object Windows.Controls.ColumnDefinition
            $cd.Width = $sz
            $rzad.ColumnDefinitions.Add($cd)
        }

        $lewo = New-Object Windows.Controls.StackPanel
        [Windows.Controls.Grid]::SetColumn($lewo, 0)
        $rzad.Children.Add($lewo) | Out-Null

        $nz = New-Object Windows.Controls.TextBlock
        $nz.Text = $poz.Nazwa
        $nz.Foreground = Br '#C7D6E6'
        $nz.FontSize = 12
        $nz.TextTrimming = 'CharacterEllipsis'
        $lewo.Children.Add($nz) | Out-Null

        # Pasek proporcjonalny do najwiekszego opoznienia - pokazuje
        # relacje szybciej niz same liczby.
        $tlo = New-Object Windows.Controls.Border
        $tlo.Height = 4
        $tlo.CornerRadius = New-Object Windows.CornerRadius 2
        $tlo.Background = Br '#16202F'
        $tlo.Margin = New-Object Windows.Thickness 0,5,14,0
        $tlo.HorizontalAlignment = 'Stretch'
        $lewo.Children.Add($tlo) | Out-Null

        $wyp = New-Object Windows.Controls.Border
        $wyp.Height = 4
        $wyp.CornerRadius = New-Object Windows.CornerRadius 2
        $wyp.HorizontalAlignment = 'Left'
        $wyp.Background = $(if ($poz.Ms -ge 3000) { Br '#FB7185' } elseif ($poz.Ms -ge 1000) { Br '#FBBF24' } else { Br '#34D399' })
        $wyp.Width = 1
        $tlo.Child = $wyp
        $tlo.Add_SizeChanged({
            param($s, $e)
            $szer = [double]$e.NewSize.Width
            if ($szer -gt 0) { $s.Child.Width = [Math]::Max(2, $szer * ($poz.Ms / $max)) }
        }.GetNewClosure())

        $ms = New-Object Windows.Controls.TextBlock
        $ms.Text = Fmt-Sek $poz.Ms
        $ms.Foreground = $(if ($poz.Ms -ge 3000) { Br '#FB7185' } elseif ($poz.Ms -ge 1000) { Br '#FBBF24' } else { Br '#9FB3C8' })
        $ms.FontSize = 12
        $ms.FontWeight = 'SemiBold'
        $ms.VerticalAlignment = 'Top'
        [Windows.Controls.Grid]::SetColumn($ms, 1)
        $rzad.Children.Add($ms) | Out-Null

        $UI.BootHost.Children.Add($rzad) | Out-Null
    }

    $stopka = New-Object Windows.Controls.TextBlock
    $stopka.Text = 'Średnia z ostatnich rozruchów. Te same wartości widać przy wpisach w Autostarcie.'
    $stopka.Foreground = Br '#7E8DA1'
    $stopka.FontSize = 11
    $stopka.TextWrapping = 'Wrap'
    $stopka.Margin = New-Object Windows.Thickness 0,4,0,0
    $UI.BootHost.Children.Add($stopka) | Out-Null

    # Slownik dla zakladki Autostart - klucze znormalizowane tak samo
    # jak w bazie opisow, zeby "Steam.exe" trafilo w "steam".
    $script:OpoznieniaStartu = @{}
    foreach ($poz in $W.Winni) {
        $k = Klucz-Nazwy $poz.Nazwa
        if ($k) { $script:OpoznieniaStartu[$k] = $poz.Ms }
    }
    try { if ($sync.Startup) { Render-Startup } } catch { }
}


# Pasek nad trescia. Zostaje widoczny az do zainstalowania albo
# pominiecia wersji - w odroznieniu od okna, ktore pokazuje sie raz.
function Pokaz-PasekAkt {
    param($Info)
    if (-not $UI.AktBanner -or -not $Info) { return }

    $UI.AktBannerTytul.Text = "Dostępna aktualizacja $($Info.Wersja)"

    $opis = "Masz $AppWersja."
    if ($Info.Zmiany -and @($Info.Zmiany).Count -gt 0) {
        $ile = @($Info.Zmiany).Count
        $opis = "$($Info.Zmiany[0])"
        if ($ile -gt 1) { $opis = $opis + "   (i $($ile - 1) więcej)" }
    }
    $UI.AktBannerOpis.Text = $opis
    $UI.AktBanner.Visibility = 'Visible'
}

function Ukryj-PasekAkt {
    if ($UI.AktBanner) { $UI.AktBanner.Visibility = 'Collapsed' }
}

function Ustaw-PigulkeAkt {
    param([string]$Stan)
    if (-not $UI.AktPill) { return }

    # Napis jest staly. Pigulka to przycisk, nie komunikat - o dostepnej
    # wersji mowi pasek nad trescia, ktory ma na to miejsce i nie znika
    # po kliknieciu gdzie indziej.
    $UI.AktPill.Visibility = 'Visible'
    $UI.AktPillText.Text = 'Aktualizacje'

    switch ($Stan) {
        'nowa' {
            $UI.AktPill.Background     = Br '#33280A'
            $UI.AktPillText.Foreground = Br '#FBBF24'
            $UI.AktPillIcon.Foreground = Br '#FBBF24'
            $UI.AktPillIcon.Text       = [char]0xE896
            $UI.AktPill.ToolTip        = 'Czeka nowa wersja - kliknij, żeby zobaczyć zmiany'
            try { Pulse $UI.AktPill 0.25 } catch { }
        }
        'szukam' {
            $UI.AktPill.Background     = Br '#0E2430'
            $UI.AktPillText.Foreground = Br '#22D3EE'
            $UI.AktPillIcon.Foreground = Br '#22D3EE'
            $UI.AktPillIcon.Text       = [char]0xE895
            $UI.AktPill.ToolTip        = 'Sprawdzam dostępność nowej wersji...'
        }
        'aktualny' {
            $UI.AktPill.Background     = Br '#0F2E24'
            $UI.AktPillText.Foreground = Br '#34D399'
            $UI.AktPillIcon.Foreground = Br '#34D399'
            $UI.AktPillIcon.Text       = [char]0xE73E
            $UI.AktPill.ToolTip        = 'Masz najnowszą wersję'
            # Potwierdzenie pokazuje sie na chwile i wraca do spoczynku -
            # zielony na stale niosl by zadnej informacji, bo bylby zawsze.
            $z = New-Object System.Windows.Threading.DispatcherTimer
            $z.Interval = [TimeSpan]::FromSeconds(4)
            $z.Add_Tick({ $z.Stop(); if (-not $script:AktZnaleziona) { Ustaw-PigulkeAkt 'neutral' } }.GetNewClosure())
            $z.Start()
        }
        'blad' {
            $UI.AktPill.Background     = Br '#33280A'
            $UI.AktPillText.Foreground = Br '#FBBF24'
            $UI.AktPillIcon.Foreground = Br '#FBBF24'
            $UI.AktPillIcon.Text       = [char]0xE7BA
            $UI.AktPill.ToolTip        = 'Nie udało się połączyć. Kliknij, żeby spróbować ponownie'
        }
        default {
            $UI.AktPill.Background     = Br '#141E2E'
            $UI.AktPillText.Foreground = Br '#7E8DA1'
            $UI.AktPillIcon.Foreground = Br '#7E8DA1'
            $UI.AktPillIcon.Text       = [char]0xE895
            $UI.AktPill.ToolTip        = 'Kliknij, żeby sprawdzić aktualizacje'
        }
    }
}

# Jedno miejsce obslugi wyniku - obojetne, czy przyszedl ze sprawdzenia
# automatycznego przy starcie, czy z klikniecia w pigulke.
function Odbierz-WynikAkt {
    param($W, [switch]$Reczne)

    if ($W -and $W.BazaOdswiezona) {
        if (Load-Baza) {
            Add-Log "Baza opisów zaktualizowana (wersja $script:BazaWersja)." 'ok'
            try { if ($sync.Startup) { Render-Startup } } catch { }
            try { if ($sync.Procs)   { Render-Procs   } } catch { }
        }
    }

    if ($W -and $W.Akt) {
        $script:AktZnaleziona = $W.Akt
        Ustaw-PigulkeAkt 'nowa'
        Pokaz-PasekAkt $W.Akt
        Pokaz-Aktualizacje $W.Akt
        return
    }

    if (-not $Reczne) { return }

    # Ponizej juz tylko sprawdzenie reczne: uzytkownik czeka na odpowiedz,
    # wiec musi ja dostac takze wtedy, gdy nic nowego nie ma.
    if ($W -and $W.Polaczono) {
        Ustaw-PigulkeAkt 'aktualny'
        Add-Log "Sprawdzono aktualizacje - masz najnowszą wersję ($AppWersja)." 'ok'
    } else {
        Ustaw-PigulkeAkt 'blad'
        Add-Log 'Nie udało się sprawdzić aktualizacji - brak połączenia z serwerem.' 'warn'
    }
}

function Sprawdz-Recznie {
    if ($script:AktZnaleziona) { Pokaz-Aktualizacje $script:AktZnaleziona; return }
    if (-not (Akt-Skonfigurowane)) {
        Ustaw-PigulkeAkt 'blad'
        Add-Log 'Adres aktualizacji nie jest ustawiony w tej kopii programu.' 'warn'
        return
    }
    Ustaw-PigulkeAkt 'szukam'
    Sprawdz-AktualizacjeWTle $Window { param($w) Odbierz-WynikAkt $w -Reczne } -Wymuszone
}


# =====================================================================
#  BLOKADY AKTUALIZACJI (winget pin)
#
#  Zadanie "Aktualizuj programy" puszcza winget upgrade --all. To wygodne
#  do momentu, w ktorym --all obejmie cos, czego nie chcesz ruszac:
#  narzedzie do podkrecania, sterownik peryferium, program z wlasnym
#  systemem licencji. "winget pin" oznacza pakiet jako wylaczony
#  z aktualizacji zbiorczych - i to jest odwracalne jednym klikiem.
#
#  Lista pakietow idzie z "winget export" (JSON, jednoznaczne
#  identyfikatory), a nie z parsowania tabeli "winget upgrade" - tamta
#  ma szerokosci kolumn zalezne od szerokosci okna i tlumaczone naglowki.
# =====================================================================

function Winget-Jest {
    return [bool](Get-Command winget -ErrorAction SilentlyContinue)
}

function Pobierz-ListePakietow {
    $plik = Join-Path $env:TEMP ("OptiWinget_{0}.json" -f [guid]::NewGuid().ToString('N'))
    $lista = New-Object System.Collections.ArrayList
    try {
        $null = & winget export --output $plik --accept-source-agreements --disable-interactivity 2>&1
        if (Test-Path $plik) {
            $j = Get-Content -LiteralPath $plik -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($z in @($j.Sources)) {
                foreach ($p in @($z.Packages)) {
                    if ($p.PackageIdentifier) { [void]$lista.Add("$($p.PackageIdentifier)") }
                }
            }
        }
    } catch { }
    Remove-Item -LiteralPath $plik -Force -ErrorAction SilentlyContinue
    return ,@($lista | Sort-Object -Unique)
}

# Zamiast rozbierac tabele na kolumny sprawdzamy, czy identyfikator
# w ogole wystepuje w jej tresci. Identyfikatory winget sa na tyle
# charakterystyczne, ze falszywe trafienie praktycznie nie wchodzi w gre.
function Pobierz-TekstBlokad {
    try { return ((& winget pin list --accept-source-agreements 2>&1) | Out-String) }
    catch { return '' }
}

function Ustaw-Blokade {
    param([string]$Id, [bool]$Wlacz)
    try {
        if ($Wlacz) {
            $o = (& winget pin add --id $Id --exact --accept-source-agreements --disable-interactivity 2>&1) | Out-String
        } else {
            $o = (& winget pin remove --id $Id --exact --accept-source-agreements --disable-interactivity 2>&1) | Out-String
        }
        return @{ Ok = ($LASTEXITCODE -eq 0); Tekst = "$o".Trim() }
    } catch {
        return @{ Ok = $false; Tekst = $_.Exception.Message }
    }
}

function Pokaz-BlokadyWinget {

    $okno = New-Object Windows.Window
    $okno.Title = 'Blokady aktualizacji'
    $okno.Width = 640
    $okno.Height = 620
    $okno.WindowStyle = 'None'
    $okno.AllowsTransparency = $true
    $okno.Background = [Windows.Media.Brushes]::Transparent
    $okno.ResizeMode = 'NoResize'
    $okno.ShowInTaskbar = $false
    try { $okno.Owner = $Window; $okno.WindowStartupLocation = 'CenterOwner' }
    catch { $okno.WindowStartupLocation = 'CenterScreen' }

    $ramka = New-Object Windows.Controls.Border
    $ramka.Background      = (Br '#111826')
    $ramka.BorderBrush     = (Br '#22D3EE')
    $ramka.BorderThickness = New-Object Windows.Thickness 1
    $ramka.CornerRadius    = New-Object Windows.CornerRadius 16
    $ramka.Padding         = New-Object Windows.Thickness 24,20,24,20
    $okno.Content = $ramka

    $siatka = New-Object Windows.Controls.Grid
    foreach ($h in @([Windows.GridLength]::Auto,
                     [Windows.GridLength]::Auto,
                     (New-Object Windows.GridLength(1, [Windows.GridUnitType]::Star)),
                     [Windows.GridLength]::Auto)) {
        $rd = New-Object Windows.Controls.RowDefinition
        $rd.Height = $h
        $siatka.RowDefinitions.Add($rd)
    }
    $ramka.Child = $siatka

    # ---------------- naglowek ----------------
    $glowa = New-Object Windows.Controls.StackPanel
    [Windows.Controls.Grid]::SetRow($glowa, 0)
    $siatka.Children.Add($glowa) | Out-Null

    $tytul = New-Object Windows.Controls.TextBlock
    $tytul.Text = 'Blokady aktualizacji'
    $tytul.Foreground = (Br '#EAF2F8')
    $tytul.FontSize = 19
    $tytul.FontWeight = 'SemiBold'
    $glowa.Children.Add($tytul) | Out-Null

    $pod = New-Object Windows.Controls.TextBlock
    $pod.Text = 'Zaznaczone programy zostaną pominięte przez "Aktualizuj programy (winget)". Nie blokuje to ich własnych aktualizatorów ani ręcznej instalacji.'
    $pod.Foreground = (Br '#9FB3C8')
    $pod.FontSize = 12
    $pod.TextWrapping = 'Wrap'
    $pod.Margin = New-Object Windows.Thickness 0,4,0,12
    $glowa.Children.Add($pod) | Out-Null

    # ---------------- filtr ----------------
    $filtr = New-Object Windows.Controls.TextBox
    $filtr.FontSize = 12.5
    $filtr.Padding = New-Object Windows.Thickness 8,5,8,6
    $filtr.Margin = New-Object Windows.Thickness 0,0,0,10
    $filtr.Background = (Br '#0B121D')
    $filtr.Foreground = (Br '#EAF2F8')
    $filtr.BorderBrush = (Br '#1E2A3A')
    $filtr.CaretBrush = (Br '#22D3EE')
    $filtr.ToolTip = 'Filtruj listę'
    [Windows.Controls.Grid]::SetRow($filtr, 1)
    $siatka.Children.Add($filtr) | Out-Null

    # ---------------- lista ----------------
    $przewijak = New-Object Windows.Controls.ScrollViewer
    $przewijak.VerticalScrollBarVisibility = 'Auto'
    $przewijak.HorizontalScrollBarVisibility = 'Disabled'
    [Windows.Controls.Grid]::SetRow($przewijak, 2)
    $siatka.Children.Add($przewijak) | Out-Null

    $host_ = New-Object Windows.Controls.StackPanel
    $przewijak.Content = $host_

    # ---------------- stopka ----------------
    $stopka = New-Object Windows.Controls.Grid
    $stopka.Margin = New-Object Windows.Thickness 0,14,0,0
    foreach ($w in @((New-Object Windows.GridLength(1, [Windows.GridUnitType]::Star)),
                     [Windows.GridLength]::Auto)) {
        $cd = New-Object Windows.Controls.ColumnDefinition
        $cd.Width = $w
        $stopka.ColumnDefinitions.Add($cd)
    }
    [Windows.Controls.Grid]::SetRow($stopka, 3)
    $siatka.Children.Add($stopka) | Out-Null

    $stan = New-Object Windows.Controls.TextBlock
    $stan.Foreground = (Br '#9FB3C8')
    $stan.FontSize = 12
    $stan.TextWrapping = 'Wrap'
    $stan.VerticalAlignment = 'Center'
    [Windows.Controls.Grid]::SetColumn($stan, 0)
    $stopka.Children.Add($stan) | Out-Null

    $przyciski = New-Object Windows.Controls.StackPanel
    $przyciski.Orientation = 'Horizontal'
    [Windows.Controls.Grid]::SetColumn($przyciski, 1)
    $stopka.Children.Add($przyciski) | Out-Null

    $bOdsw = Nowy-PrzyciskAkt 'Odśwież'  '#151E2C' '#9FB3C8'
    $bZam  = Nowy-PrzyciskAkt 'Zamknij'  '#22D3EE' '#04121A' -Glowny
    $bZam.Margin = New-Object Windows.Thickness 0
    $przyciski.Children.Add($bOdsw) | Out-Null
    $przyciski.Children.Add($bZam)  | Out-Null

    $odswiezUI = {
        try { $okno.Dispatcher.Invoke([action]{}, [Windows.Threading.DispatcherPriority]::Render) } catch { }
    }.GetNewClosure()

    $script:PinWiersze = @()

    $zastosujFiltr = {
        $f = "$($filtr.Text)".Trim().ToLower()
        $widoczne = 0
        foreach ($w in $script:PinWiersze) {
            if (-not $f -or $w.Id.ToLower().Contains($f)) { $w.Box.Visibility = 'Visible'; $widoczne++ }
            else { $w.Box.Visibility = 'Collapsed' }
        }
        if ($f) { $stan.Text = "Pasuje: $widoczne z $($script:PinWiersze.Count)" }
    }.GetNewClosure()

    $wczytaj = {
        $host_.Children.Clear()
        $script:PinWiersze = @()
        $stan.Foreground = (Br '#9FB3C8')
        $stan.Text = 'Wczytuję listę programów...'
        $bOdsw.IsEnabled = $false
        & $odswiezUI

        if (-not (Winget-Jest)) {
            $stan.Foreground = (Br '#FBBF24')
            $stan.Text = 'Nie znaleziono winget. Zainstaluj "Instalator aplikacji" ze Sklepu Microsoft.'
            $bOdsw.IsEnabled = $true
            return
        }

        $pakiety = Pobierz-ListePakietow
        $blokady = Pobierz-TekstBlokad

        if ($pakiety.Count -eq 0) {
            $stan.Foreground = (Br '#FBBF24')
            $stan.Text = 'winget nie zwrócił żadnych pakietów. Sprawdź połączenie z internetem.'
            $bOdsw.IsEnabled = $true
            return
        }

        $ileBlok = 0
        foreach ($id in $pakiety) {
            $zablok = $false
            try { $zablok = ($blokady -match [regex]::Escape($id)) } catch { }
            if ($zablok) { $ileBlok++ }

            $wiersz = New-Object Windows.Controls.Border
            $wiersz.Background = (Br '#0E1724')
            $wiersz.CornerRadius = New-Object Windows.CornerRadius 8
            $wiersz.Padding = New-Object Windows.Thickness 12,7,12,8
            $wiersz.Margin  = New-Object Windows.Thickness 0,0,8,5

            $cb = New-Object Windows.Controls.CheckBox
            $cb.Content = $id
            $cb.Foreground = $(if ($zablok) { Br '#FBBF24' } else { Br '#C7D6E6' })
            $cb.FontSize = 12.5
            $cb.IsChecked = $zablok
            $cb.ToolTip = 'Zaznacz, żeby pominąć ten program przy aktualizacji zbiorczej'
            $wiersz.Child = $cb

            $host_.Children.Add($wiersz) | Out-Null
            $script:PinWiersze += [pscustomobject]@{ Id = $id; Box = $wiersz; Check = $cb }

            $klik = {
                param($s, $e)
                $chce = [bool]$s.IsChecked
                $s.IsEnabled = $false
                $stan.Foreground = (Br '#9FB3C8')
                $stan.Text = $(if ($chce) { "Blokuję $id..." } else { "Zdejmuję blokadę z $id..." })
                & $odswiezUI

                $w = Ustaw-Blokade $id $chce
                if ($w.Ok) {
                    $s.Foreground = $(if ($chce) { Br '#FBBF24' } else { Br '#C7D6E6' })
                    $stan.Foreground = (Br '#34D399')
                    $stan.Text = $(if ($chce) { "$id - pominięty przy aktualizacjach" } else { "$id - znowu aktualizowany" })
                    Add-Log $(if ($chce) { "Zablokowano aktualizacje: $id" } else { "Odblokowano aktualizacje: $id" }) 'ok'
                } else {
                    # cofamy zaznaczenie, zeby okno nie klamalo o stanie
                    $s.IsChecked = -not $chce
                    $stan.Foreground = (Br '#F43F5E')
                    $krotki = "$($w.Tekst)"
                    if ($krotki.Length -gt 140) { $krotki = $krotki.Substring(0,140) + '...' }
                    $stan.Text = "Nie udało się: $krotki"
                    Add-Log "winget pin nie zadzialal dla $id" 'err'
                }
                $s.IsEnabled = $true
            }.GetNewClosure()

            $cb.Add_Click($klik)
        }

        $stan.Foreground = (Br '#9FB3C8')
        $stan.Text = "Programów: $($pakiety.Count)   •   zablokowanych: $ileBlok"
        $bOdsw.IsEnabled = $true
    }.GetNewClosure()

    $filtr.Add_TextChanged($zastosujFiltr)
    $bOdsw.Add_Click({ & $wczytaj }.GetNewClosure())
    $bZam.Add_Click({ $okno.Close() }.GetNewClosure())

    $okno.Add_ContentRendered({ & $wczytaj }.GetNewClosure())
    $okno.ShowDialog() | Out-Null
}


# Po aktualizacji program dotad po prostu wstawal - bez slowa o tym,
# co sie wlasciwie zmienilo. Ten ekran pokazuje sie raz, przy pierwszym
# uruchomieniu nowej wersji, i sam sie kasuje.
function Pokaz-CoNowego {
    $u = Load-UstAkt
    if (-not $u.poWersja) { return }
    if ("$($u.poWersja)" -ne "$AppWersja") {
        # Slad z innej wersji niz ta uruchomiona: aktualizacja sie nie
        # udala albo ktos podmienil plik recznie. Kasujemy, zeby ekran
        # nie wracal przy kazdym starcie.
        $u.poWersja = ''; $u.poZmiany = @(); Save-UstAkt $u
        return
    }

    $zmiany = @($u.poZmiany)
    $u.poWersja = ''; $u.poZmiany = @(); Save-UstAkt $u

    Add-Log "Zaktualizowano do wersji $AppWersja." 'ok'

    $okno = New-Object Windows.Window
    $okno.Title = 'Co nowego'
    $okno.Width = 480
    $okno.SizeToContent = 'Height'
    $okno.WindowStyle = 'None'
    $okno.AllowsTransparency = $true
    $okno.Background = [Windows.Media.Brushes]::Transparent
    $okno.ResizeMode = 'NoResize'
    $okno.ShowInTaskbar = $false
    try { $okno.Owner = $Window; $okno.WindowStartupLocation = 'CenterOwner' }
    catch { $okno.WindowStartupLocation = 'CenterScreen' }

    $ramka = New-Object Windows.Controls.Border
    $ramka.Background      = (Br '#111826')
    $ramka.BorderBrush     = (Br '#34D399')
    $ramka.BorderThickness = New-Object Windows.Thickness 1
    $ramka.CornerRadius    = New-Object Windows.CornerRadius 16
    $ramka.Padding         = New-Object Windows.Thickness 24,20,24,20
    $okno.Content = $ramka

    $stos = New-Object Windows.Controls.StackPanel
    $ramka.Child = $stos

    $tytul = New-Object Windows.Controls.TextBlock
    $tytul.Text = "Zaktualizowano do $AppWersja"
    $tytul.Foreground = (Br '#EAF2F8')
    $tytul.FontSize = 19
    $tytul.FontWeight = 'SemiBold'
    $stos.Children.Add($tytul) | Out-Null

    $pod = New-Object Windows.Controls.TextBlock
    $pod.Text = 'Poprzednia wersja została zachowana obok, jako plik .bak'
    $pod.Foreground = (Br '#9FB3C8')
    $pod.FontSize = 12
    $pod.TextWrapping = 'Wrap'
    $pod.Margin = New-Object Windows.Thickness 0,2,0,14
    $stos.Children.Add($pod) | Out-Null

    if ($zmiany.Count -gt 0) {
        foreach ($z in $zmiany) {
            $w = New-Object Windows.Controls.TextBlock
            $w.Text = "•  $z"
            $w.Foreground = (Br '#C7D6E6')
            $w.FontSize = 13
            $w.TextWrapping = 'Wrap'
            $w.Margin = New-Object Windows.Thickness 0,0,0,5
            $stos.Children.Add($w) | Out-Null
        }
    } else {
        $w = New-Object Windows.Controls.TextBlock
        $w.Text = 'Wydanie bez opisu zmian.'
        $w.Foreground = (Br '#7E8DA1')
        $w.FontSize = 12.5
        $stos.Children.Add($w) | Out-Null
    }

    $pasek = New-Object Windows.Controls.StackPanel
    $pasek.Orientation = 'Horizontal'
    $pasek.HorizontalAlignment = 'Right'
    $pasek.Margin = New-Object Windows.Thickness 0,18,0,0
    $stos.Children.Add($pasek) | Out-Null

    $bOk = Nowy-PrzyciskAkt 'Rozumiem' '#34D399' '#04121A' -Glowny
    $bOk.Margin = New-Object Windows.Thickness 0
    $pasek.Children.Add($bOk) | Out-Null
    $bOk.Add_Click({ $okno.Close() }.GetNewClosure())

    $okno.ShowDialog() | Out-Null
}

function Pokaz-Aktualizacje {
    param($Info)

    if (-not $Info) { return }

    Add-Log "Dostepna nowa wersja: $($Info.Wersja)" 'ok'

    $okno = New-Object Windows.Window
    $okno.Title = 'Aktualizacja'
    $okno.Width = 480
    $okno.SizeToContent = 'Height'
    $okno.WindowStyle = 'None'
    $okno.AllowsTransparency = $true
    $okno.Background = [Windows.Media.Brushes]::Transparent
    $okno.ResizeMode = 'NoResize'
    $okno.ShowInTaskbar = $false
    try { $okno.Owner = $Window; $okno.WindowStartupLocation = 'CenterOwner' }
    catch { $okno.WindowStartupLocation = 'CenterScreen' }

    $ramka = New-Object Windows.Controls.Border
    $ramka.Background      = (Br '#111826')
    $ramka.BorderBrush     = (Br '#22D3EE')
    $ramka.BorderThickness = New-Object Windows.Thickness 1
    $ramka.CornerRadius    = New-Object Windows.CornerRadius 16
    $ramka.Padding         = New-Object Windows.Thickness 24,20,24,20
    $okno.Content = $ramka

    $stos = New-Object Windows.Controls.StackPanel
    $ramka.Child = $stos

    $tytul = New-Object Windows.Controls.TextBlock
    $tytul.Text = "Dostępna wersja $($Info.Wersja)"
    $tytul.Foreground = (Br '#EAF2F8')
    $tytul.FontSize = 19
    $tytul.FontWeight = 'SemiBold'
    $stos.Children.Add($tytul) | Out-Null

    $pod = New-Object Windows.Controls.TextBlock
    $pod.Text = "Masz $AppWersja"
    $pod.Foreground = (Br '#9FB3C8')
    $pod.FontSize = 12
    $pod.Margin = New-Object Windows.Thickness 0,2,0,14
    $stos.Children.Add($pod) | Out-Null

    if ($Info.Zmiany.Count -gt 0) {
        foreach ($z in $Info.Zmiany) {
            $w = New-Object Windows.Controls.TextBlock
            $w.Text = "•  $z"
            $w.Foreground = (Br '#C7D6E6')
            $w.FontSize = 13
            $w.TextWrapping = 'Wrap'
            $w.Margin = New-Object Windows.Thickness 0,0,0,5
            $stos.Children.Add($w) | Out-Null
        }
    }

    if ($Info.PelnaWymag) {
        $u = New-Object Windows.Controls.TextBlock
        $u.Text = 'Ta wersja wymaga pełnej instalacji - pobierz instalator ze strony programu.'
        $u.Foreground = (Br '#FBBF24')
        $u.FontSize = 12
        $u.TextWrapping = 'Wrap'
        $u.Margin = New-Object Windows.Thickness 0,8,0,0
        $stos.Children.Add($u) | Out-Null
    }

    $stan = New-Object Windows.Controls.TextBlock
    $stan.Foreground = (Br '#9FB3C8')
    $stan.FontSize = 12
    $stan.TextWrapping = 'Wrap'
    $stan.Margin = New-Object Windows.Thickness 0,14,0,0
    $stan.Visibility = 'Collapsed'
    $stos.Children.Add($stan) | Out-Null

    $bar = New-Object Windows.Controls.ProgressBar
    $bar.Minimum = 0
    $bar.Maximum = 100
    $bar.Value   = 0
    $bar.Height  = 6
    $bar.Margin  = New-Object Windows.Thickness 0,10,0,0
    $bar.Visibility = 'Collapsed'
    $stos.Children.Add($bar) | Out-Null

    $pasek = New-Object Windows.Controls.StackPanel
    $pasek.Orientation = 'Horizontal'
    $pasek.HorizontalAlignment = 'Right'
    $pasek.Margin = New-Object Windows.Thickness 0,18,0,0
    $stos.Children.Add($pasek) | Out-Null

    $bAkt    = Nowy-PrzyciskAkt 'Aktualizuj teraz' '#22D3EE' '#04121A' -Glowny
    $bPomin  = Nowy-PrzyciskAkt 'Pomiń tę wersję'  '#151E2C' '#9FB3C8'
    $bPozniej= Nowy-PrzyciskAkt 'Później'          '#151E2C' '#9FB3C8'
    $bPozniej.Margin = New-Object Windows.Thickness 0
    $pasek.Children.Add($bAkt)     | Out-Null
    $pasek.Children.Add($bPomin)   | Out-Null
    $pasek.Children.Add($bPozniej) | Out-Null

    # Pobieranie idzie na watku okna, wiec bez wymuszenia przerysowania
    # komunikat "Pobieram..." nigdy by sie nie pokazal.
    $odswiez = {
        try { $okno.Dispatcher.Invoke([action]{}, [Windows.Threading.DispatcherPriority]::Render) } catch { }
    }.GetNewClosure()

    # Pokazanie bledu w jednym miejscu - trzy sciezki moga sie wywrocic
    # (start pobierania, samo pobieranie, dokonczenie), a kazda musi
    # oddac uzytkownikowi przyciski.
    $pokazBlad = {
        param($T)
        $bar.Visibility = 'Collapsed'
        $stan.Visibility = 'Visible'
        $stan.Foreground = (Br '#F43F5E')
        $stan.Text = "$T"
        Add-Log "Aktualizacja nieudana: $T" 'err'
        $bAkt.IsEnabled = $true
        $bPomin.IsEnabled = $true
        $bPozniej.IsEnabled = $true
    }.GetNewClosure()

    $bAkt.Add_Click({
        # UWAGA: GetNewClosure() przechwytuje wylacznie zmienne z biezacego
        # zakresu LOKALNEGO. $bar, $stan i $okno sa lokalne dla funkcji okna,
        # a nie dla tego uchwytu - wiec scriptblocki tworzone nizej ich NIE
        # przechwycily i przy wywolaniu trafialy w cokolwiek innego o tej
        # nazwie. Efekt: "The property 'IsIndeterminate' cannot be found on
        # this object", po cichu polkniete przez catch, i aktualizacja, ktora
        # pobierala plik, a potem nie robila nic. Kopie lokalne to naprawiaja.
        $lBar  = $bar
        $lStan = $stan
        $lOkno = $okno
        $lInfo = $Info

        $bAkt.IsEnabled = $false
        $bPomin.IsEnabled = $false
        $bPozniej.IsEnabled = $false
        $stan.Visibility = 'Visible'
        $stan.Foreground = (Br '#9FB3C8')
        $stan.Text = 'Przygotowuję...'
        $bar.Visibility = 'Visible'
        $bar.IsIndeterminate = $true
        $bar.Value = 0

        $tryb = Wybierz-DrogeAktualizacji $Info
        if ($Info.PelnaWymag -and $tryb -ne 'inno') {
            & $pokazBlad 'Ta wersja wymaga pełnej instalacji - pobierz instalator ze strony programu.'
            return
        }

        if ($tryb -eq 'inno') {
            $url = "$($Info.SetupUrl)"; $sha = "$($Info.SetupSha)"
            $roz = [int64]$Info.SetupRozm
            $cel = Plik-TymczasowySetup $Info; $etap = 'inno'
        } else {
            $url = "$($Info.Ps1Url)";   $sha = "$($Info.Ps1Sha)"
            $roz = [int64]$Info.Ps1Rozm
            $cel = Plik-TymczasowyPs1 $Info; $etap = 'ps1'
        }
        if (-not $url) { & $pokazBlad 'Manifest nie podaje pliku do pobrania.'; return }

        $stan.Text = 'Pobieram...'
        # Kazdy etap trafia do konsoli. Gdyby aktualizacja kiedys stanela,
        # ostatni wpis powie gdzie - zamiast zostawiac nas ze zgadywaniem.
        Add-Log "Aktualizacja $($Info.Wersja): pobieram $url" 'info'

        $postep = {
            param($Proc, $Ile, $Caly)
            if ($Proc -lt 0) {
                # Nie znamy postepu - pasek pracuje, ale nie klamie liczba.
                $lBar.IsIndeterminate = $true
                $lStan.Text = 'Pobieram plik aktualizacji...'
            } elseif ($Caly -gt 0) {
                $lBar.IsIndeterminate = $false
                $lBar.Value = $Proc
                $lStan.Text = ('Pobieram... {0}%   ({1:N0} z {2:N0} KB)' -f $Proc, ($Ile / 1KB), ($Caly / 1KB))
            } else {
                $lStan.Text = ('Pobieram... {0:N1} MB' -f ($Ile / 1MB))
            }
        }.GetNewClosure()

        $koniec = {
            param($Blad)
            if ($Blad) { & $pokazBlad "Nie udało się pobrać pliku: $Blad"; return }

            $lBar.IsIndeterminate = $false
            $lBar.Value = 100
            $lStan.Text = 'Sprawdzam sumę kontrolną...'
            Add-Log 'Aktualizacja: plik pobrany, sprawdzam sumę kontrolną.' 'info'

            if (-not (Sprawdz-Sume $cel $sha)) {
                Remove-Item -LiteralPath $cel -Force -ErrorAction SilentlyContinue
                & $pokazBlad 'Suma kontrolna się nie zgadza - plik odrzucony.'
                return
            }

            # Ta sama pulapka co wyzej, poziom glebiej: $lStan jest lokalne
            # dla uchwytu klikniecia, nie dla tego scriptblocka.
            $kStan = $lStan
            $raport = { param($T) $kStan.Text = "$T"; Add-Log "Aktualizacja: $T" 'info' }.GetNewClosure()
            if ($etap -eq 'inno') { $wynik = Zakoncz-Instalator  $lInfo $cel $raport }
            else                  { $wynik = Zakoncz-PodmianePs1 $lInfo $cel $raport }

            if (-not $wynik.Ok) { & $pokazBlad $wynik.Blad; return }

            Add-Log 'Aktualizacja: plik podmieniony, restartuję program.' 'ok'

            $lStan.Foreground = (Br '#34D399')
            $lStan.Text = 'Gotowe - program zamknie się i uruchomi ponownie.'

            # Chwila na przeczytanie komunikatu - bez zegara i bez usypiania
            # watku. Zegary w tym oknie modalnym juz raz nie zatykaly, a
            # Start-Sleep zatrzymalby rysowanie. Wiec pompujemy sami.
            for ($i = 0; $i -lt 9; $i++) {
                try { $lOkno.Dispatcher.Invoke([action]{}, [Windows.Threading.DispatcherPriority]::Background) } catch { }
                Start-Sleep -Milliseconds 120
            }

            try { $lOkno.Close() } catch { }
            if ($wynik.Zamknij) {
                Add-Log 'Aktualizacja: zamykam program, zaraz wstanie nowa wersja.' 'ok'
                try { $Window.Close() } catch { }
            }
        }.GetNewClosure()

        $r = Pobierz-ZPostepem $url $cel $roz $okno $postep $koniec
        if (-not $r.Ok) { & $pokazBlad $r.Blad }
    }.GetNewClosure())

    $bPomin.Add_Click({
        $u = Load-UstAkt
        $u.pomin = $Info.Wersja
        $u.czeka = ''
        Save-UstAkt $u
        $script:AktZnaleziona = $null
        Ukryj-PasekAkt
        Ustaw-PigulkeAkt 'neutral'
        Add-Log "Wersja $($Info.Wersja) pominięta - przypomnę przy następnej." 'info'
        $okno.Close()
    }.GetNewClosure())

    $bPozniej.Add_Click({ $okno.Close() }.GetNewClosure())

    $okno.ShowDialog() | Out-Null
}


$Window.Add_ContentRendered({
    if (-not $script:Mica) { Fade $Window 1 300 0 }
    Apply-Mica

    # Logo w pasku tytulu "wjezdza" z odbiciem, a za nim jeden gasnacy
    # pierscien - krotkie przedstawienie sie marki w chwili, gdy okno
    # dopiero sie pokazuje. Nigdzie indziej w programie to sie nie
    # powtarza, wiec zostaje ciekawostka, a nie tik.
    Pop-In    $UI.LogoMark 0.25 460 80
    Ping-Ring $UI.LogoRing 900 140

    # Pozycje menu wchodza jedna po drugiej - okno oglada sie wtedy jak
    # cos, co sie sklada, a nie jak obrazek, ktory po prostu jest.
    $i = 0
    foreach ($p in $Pages) {
        try {
            Fade  $p.Nav 1 220 0 (60 + $i * 22)
            Shift $p.Nav 0 -10 300 (60 + $i * 22)
        } catch { }
        $i++
    }

    Update-Hardware
    Start-Worker 'scan'

    # Aktualizacje na samym koncu i w osobnym watku: brak sieci ani
    # wolny serwer nie moga opoznic pokazania okna.
    # Najpierw ekran po aktualizacji, dopiero potem szukanie kolejnej -
    # inaczej oba okna potrafilyby wyskoczyc naraz.
    try { Pokaz-CoNowego } catch { }

    # Pigulka jest widoczna od startu, nawet gdy sprawdzenie nie idzie
    # (limit raz na dobe) - kliknieciem wymusza je natychmiast.
    if (Akt-Skonfigurowane) { Ustaw-PigulkeAkt 'neutral' }

    # Odczyt dziennika wydajnosci - w tle, bo przy duzym logu potrafi
    # zajac kilka sekund.
    Zbadaj-CzasStartu $Window { param($w) Pokaz-CzasStartu $w }

    Sprawdz-AktualizacjeWTle $Window { param($w) Odbierz-WynikAkt $w }
})

$Window.ShowDialog() | Out-Null
